anatomy.avatar", "descriptionFallback": "Avatar image (circular)."}, {"cls": "origam-bracket-competitor__name", "descriptionKey": "components.bracket_competitor.anatomy.name", "descriptionFallback": "Competitor name with overflow ellipsis."}, {"cls": "origam-bracket-competitor__advantage", "descriptionKey": "components.bracket_competitor.anatomy.advantage", "descriptionFallback": "Advantage pill badge (+N)."}, {"cls": "origam-bracket-competitor__score", "descriptionKey": "components.bracket_competitor.anatomy.score", "descriptionFallback": "Score value right-aligned."}, {"cls": "origam-bracket-competitor--winner", "descriptionKey": "components.bracket_competitor.anatomy.winner", "descriptionFallback": "Winner state: bolder text and intent-tinted background."}, {"cls": "origam-bracket-competitor--loser", "descriptionKey": "components.bracket_competitor.anatomy.loser", "descriptionFallback": "Loser state: reduced opacity."}, {"cls": "origam-bracket-competitor--tbd", "descriptionKey": "components.bracket_competitor.anatomy.tbd", "descriptionFallback": "TBD state: italic, reduced opacity."}, {"cls": "origam-bracket-competitor--interactive", "descriptionKey": "components.bracket_competitor.anatomy.interactive", "descriptionFallback": "Interactive state: cursor pointer, hover background, focus-visible outline."}], "svgDesc": "Schematic of the BracketCompetitor row with 5 numbered parts.", "svgTitle": "Anatomy of OrigamBracketCompetitor", "rootClass": "origam-bracket-competitor", "figcaption": "Anatomy of <code>&lt;origam-bracket-competitor&gt;</code> — 6 internal parts: root row, seed, avatar, name, advantage badge and score.", "svgViewBox": "0 0 640 160"}, "cssVars": [{"name": "--origam-bracket-competitor---height", "defaultValue": "36px", "descriptionKey": "components.bracket_competitor.css_vars.height", "descriptionFallback": "Minimum row height. compact: 28px, comfortable: 44px."}, {"name": "--origam-bracket-competitor---padding-block", "defaultValue": "4px", "descrip