nd__matches\">\n    <!-- #match slot × N -->\n    <origam-bracket-match class=\"origam-bracket-round__match\" />\n    <origam-bracket-match class=\"origam-bracket-round__match\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-bracket-round", "num": 1, "descriptionKey": "components.bracket_round.anatomy.root", "descriptionFallback": "Root flex column container. role=\"group\" with aria-labelledby pointing to the title. Direction modifier switches to row for vertical mode."}, {"cls": ".origam-bracket-round__title", "num": 2, "descriptionKey": "components.bracket_round.anatomy.title", "descriptionFallback": "Round title <h3>. Visible only when showRoundTitle=true. Gets a computed id for aria-labelledby."}, {"cls": ".origam-bracket-round__matches", "num": 3, "descriptionKey": "components.bracket_round.anatomy.matches", "descriptionFallback": "Flex column container for match cards. justify-content: space-around distributes matches evenly. Gap driven by --origam-bracket-round---match-gap."}], "classes": [{"cls": "origam-bracket-round", "descriptionKey": "components.bracket_round.anatomy.root", "descriptionFallback": "Root flex column container."}, {"cls": "origam-bracket-round__title", "descriptionKey": "components.bracket_round.anatomy.title", "descriptionFallback": "Round title heading <h3>."}, {"cls": "origam-bracket-round__matches", "descriptionKey": "components.bracket_round.anatomy.matches", "descriptionFallback": "Match cards container with space-around justification."}, {"cls": "origam-bracket-round__match", "descriptionKey": "components.bracket_round.anatomy.match", "descriptionFallback": "Applied to each OrigamBracketMatch inside the round."}, {"cls": "origam-bracket-round--final", "descriptionKey": "components.bracket_round.anatomy.final", "descriptionFallback": "Added to the last round (index === totalRounds - 1)."}, {"cls": "origam-bracket-round--direction-horizontal", "descriptionKey": "components.bracket_round.anatomy.horizontal", "descriptionFallback": "Flex column layout — matches stack vertically in a column."}, {"cls": "origam-bracket-round--direction-vertical", "descriptionKey": "components.bracket_round.anatomy.vertical", "descriptionFallback": "Flex row layout — matches stack horizontally in a row."}], "svgDesc": "Schematic of the BracketRound column with 3 numbered parts.", "svgTitle": "Anatomy of OrigamBracketRound", "rootClass": "origam-bracket-round", "figcaption": "Anatomy of <code>&lt;origam-bracket-round&gt;</code> — 3 parts: root column, round title heading and match list.", "svgViewBox": "0 0 480 220"}, "cssVars": [{"name": "--origam-bracket-round-title---margin-block-end", "defaultValue": "12px", "descriptionKey": "components.bracket_round.css_vars.title_margin_block_end", "descriptionFallback": "Bottom margin below the round title."}, {"name": "--origam-bracket-round-title---font-size", "defaultValue": "0.875rem", "descriptionKey": "components.bracket_round.css_vars.title_font_size", "descriptionFallback": "Font size of the round title."}, {"name": "--origam-bracket-round-title---font-weight", "defaultValue": "600", "descriptionKey": "components.bracket_round.css_vars.title_font_weight", "descriptionFallback": "Font weight of the round title."}, {"name": "--origam-bracket-round-title---letter-spacing", "defaultValue": "0.04em", "descriptionKey": "components.bracket_round.css_vars.title_letter_spacing", "descriptionFallback": "Letter spacing of the round title."}, {"name": "--origam-bracket-round-title---text-transform", "defaultValue": "uppercase", "descriptionKey": "components.bracket_round.css_vars.title_text_transform", "descriptionFallback": "Text transform of the round title. Default uppercase."}, {"name": "--origam-bracket-round---match-gap", "defaultValue": "24px", "descriptionKey": "components.bracket_round.css_vars.match_gap", "descriptionFallback": "Gap between match cards in the round."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => P