dered list ②, divider ③ and individual items ④. The last item is visually dimmed and aria-current=\"page\".", "svgViewBox": "0 0 700 100"}, "cssVars": [{"name": "--origam-breadcrumb---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.breadcrumb.css_vars.color", "descriptionFallback": "Default text color of the breadcrumb container."}, {"name": "--origam-breadcrumb---background", "defaultValue": "transparent", "descriptionKey": "components.breadcrumb.css_vars.background", "descriptionFallback": "Container background (transparent by default)."}, {"name": "--origam-breadcrumb---padding-block-start", "defaultValue": "{space.2}", "descriptionKey": "components.breadcrumb.css_vars.padding_block_start", "descriptionFallback": "Block-start padding (density-adjusted at render time)."}, {"name": "--origam-breadcrumb---padding-inline-start", "defaultValue": "{space.2}", "descriptionKey": "components.breadcrumb.css_vars.padding_inline_start", "descriptionFallback": "Inline-start padding."}, {"name": "--origam-breadcrumb---border-radius", "defaultValue": "0px", "descriptionKey": "components.breadcrumb.css_vars.border_radius", "descriptionFallback": "Container border-radius. Overridden by rounded prop."}, {"name": "--origam-breadcrumb---box-shadow", "defaultValue": "{shadow.none}", "descriptionKey": "components.breadcrumb.css_vars.box_shadow", "descriptionFallback": "Container box-shadow. Overridden by elevation."}, {"name": "--origam-breadcrumb-item---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.breadcrumb.css_vars.item_color", "descriptionFallback": "Default item text color."}, {"name": "--origam-breadcrumb-item---hover-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.breadcrumb.css_vars.item_hover_color", "descriptionFallback": "Item color on hover (link affordance)."}, {"name": "--origam-breadcrumb-item---active-color", "defaultValue": "{color.text.secondary}", "descriptionKey": "com