INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('cdbeb156-5cf6-43b3-9d00-932363068696', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'carousel', 'Carousel', 'Data Display', NULL, 'mdi-view-carousel', 'components.catalog.carousel.description', 'Sliding window component for cycling through a set of items, with pagination dots, optional progress bar, auto-play interval and keyboard navigation.', NULL, NULL, 'origam-carousel', NULL, 'packages/ds/src/components/Carousel/OrigamCarousel.vue', 'origam', NULL, NULL, '/stories/?story=components-carousel--design', '/docs/components/Carousel/OrigamCarousel.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.carousel.a11y.delimiter_label", "noteFallback": "Each pagination dot receives aria-label=\"Slide N of M\" via useLocale t() — screen readers announce position."}, {"noteKey": "components.carousel.a11y.reduced_motion", "noteFallback": "Auto-play is suppressed when prefers-reduced-motion: reduce is detected (prefersReducedMotion() check on mount)."}, {"noteKey": "components.carousel.a11y.pause_on_focus", "noteFallback": "The slide timer is cleared on unmount and restarted on modelValue change, but there is no explicit pause-on-focus — consider disabling cycle for keyboard-heavy contexts."}], "roles": ["region"], "keyboard": [{"key": "ArrowLeft / ArrowRight", "actionKey": "components.carousel.a11y.key_arrows", "actionFallback": "Navigates to the previous or next slide when focused on the carousel."}, {"key": "Tab", "actionKey": "components.carousel.a11y.key_tab", "actionFallback": "Moves focus through pagination dots and navigation arrows."}, {"k