ack": "Min and max labels at arc endpoints. Hidden when gaugeShowEndpoints=false."}], "svgDesc": "Schematic of the gauge chart component with numbered internal parts.", "svgTitle": "Anatomy of OrigamChartGauge", "rootClass": "origam-chart-gauge", "figcaption": "Anatomy of <code>&lt;origam-chart-gauge&gt;</code> — 6 internal parts.", "svgViewBox": "0 0 480 260"}, "cssVars": [{"name": "--origam-chart---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.chart_gauge.css_vars.background_color", "descriptionFallback": "Chart root background colour."}, {"name": "--origam-chart---padding", "defaultValue": "{space.3}", "descriptionKey": "components.chart_gauge.css_vars.padding", "descriptionFallback": "Inner padding of the chart root."}, {"name": "--origam-chart---animation-duration", "defaultValue": "600ms", "descriptionKey": "components.chart_gauge.css_vars.animation_duration", "descriptionFallback": "Duration of the fill arc animation."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.chart_gauge.playground.title", "defaultValue": "", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.chart_gauge.playground.subtitle", "defaultValue": "", "labelFallback": "Subtitle"}, {"kind": "switch", "prop": "gaugeShowEndpoints", "labelKey": "components.chart_gauge.playground.gauge_show_endpoints", "defaultValue": true, "labelFallback": "Gauge Show Endpoints"}, {"kind": "switch", "prop": "gaugeShowValue", "labelKey": "components.chart_gauge.playground.gauge_show_value", "defaultValue": true, "labelFallback": "Gauge Show Value"}, {"kind": "switch", "prop": "animated", "labelKey": "components.chart_gauge.playground.animated", "defaultValue": true, "labelFallback": "Animated"}, {"kind": "select", "prop": "colorScheme", "options": [{"label": "(default)", "value": ""}, {"label": "neutral", "value": "neutral"}, {"label": "primary", "value": "primary"}, {"label": "secondary", "