eight=\"16\" rx=\"2\" fill=\"var(--origam-color__surface---sunken, #f3f4f6)\" stroke=\"var(--origam-color__border---default, #e5e7eb)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"239\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #6b7280)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-chart-legend</text>\n", "code": "<div class=\"origam-chart-pictorial\">\n  <div class=\"origam-chart-pictorial__header\">\n    <slot name=\"title\" />\n  </div>\n  <div class=\"origam-chart-pictorial__body\">\n    <svg class=\"origam-chart-pictorial__svg origam-chart__svg\" role=\"img\">\n      <title /><desc />\n      <defs>\n        <symbol id=\"origam-chart-pictorial-icon\" viewBox=\"0 0 24 24\">\n          <path :d=\"icon\" />\n        </symbol>\n        <clipPath id=\"origam-chart-pictorial-clip-…\" />\n      </defs>\n      <g class=\"origam-chart__series\">\n        <g class=\"origam-chart-pictorial__column\" role=\"button\" tabindex=\"0\">\n          <use class=\"origam-chart-pictorial__icon origam-chart-pictorial__icon--empty\" />\n          <use class=\"origam-chart-pictorial__icon origam-chart-pictorial__icon--filled\" />\n          <text class=\"origam-chart-pictorial__value-label\" />\n        </g>\n      </g>\n      <g class=\"origam-chart-pictorial__axis\">\n        <text class=\"origam-chart-pictorial__axis-label\" />\n      </g>\n    </svg>\n    <origam-chart-tooltip />\n    <div class=\"origam-chart-pictorial__empty origam-chart__empty\">\n      <slot name=\"empty\" />\n    </div>\n  </div>\n  <origam-chart-legend />\n</div>", "legend": [{"cls": ".origam-chart-pictorial", "num": 1, "descriptionKey": "components.chart_pictorial.anatomy.root", "descriptionFallback": "Root wrapper. CSS grid: header / body / legend rows."}, {"cls": ".origam-chart-pictorial__header", "num": 2, "descriptionKey": "components.chart_pictorial.anatomy.header", "descriptionFallback": "Optional title + subtitle block."}, {"cls": ".origam-chart-pictorial__body", "num": 3, "descriptionKey": "components.chart_pictorial.anatomy.body", "descriptionFallback": "Plot area hosting the SVG and the empty slot."}, {"cls": ".origam-chart-pictorial__column", "num": 4, "descriptionKey": "components.chart_pictorial.anatomy.column", "descriptionFallback": "One column per data point. Keyboard-focusable (role=\"button\", tabindex=\"0\")."}, {"cls": ".origam-chart-pictorial__icon--empty", "num": 5, "descriptionKey": "components.chart_pictorial.anatomy.icon_empty", "descriptionFallback": "Background (unfilled) icon slots filled with emptyIconColor."}, {"cls": ".origam-chart-pictorial__icon--filled", "num": 6, "descriptionKey": "components.chart_pictorial.anatomy.icon_filled", "descriptionFallback": "Filled icon slots. In fill mode these use a <clipPath> for the thermometer effect."}, {"cls": ".origam-chart-pictorial__value-label", "num": 7, "descriptionKey": "components.chart_pictorial.anatomy.value_label", "descriptionFallback": "Formatted value text rendered adjacent to the column when showLabel=true."}], "classes": [{"cls": "origam-chart-pictorial", "descriptionKey": "components.chart_pictorial.anatomy.root", "descriptionFallback": "Root grid wrapper."}, {"cls": "origam-chart-pictorial__header", "descriptionKey": "components.chart_pictorial.anatomy.header", "descriptionFallback": "Title/subtitle block."}, {"cls": "origam-chart-pictorial__body", "descriptionKey": "components.chart_pictorial.anatomy.body", "descriptionFallback": "Plot area."}, {"cls": "origam-chart-pictorial__svg", "descriptionKey": "components.chart_pictorial.anatomy.svg", "descriptionFallback": "Responsive SVG."}, {"cls": "origam-chart-pictorial__column", "descriptionKey": "components.chart_pictorial.anatomy.column", "descriptionFallback": "One column group per data point."}, {"cls": "origam-chart-pictorial__icon", "descriptionKey": "components.chart_pictorial.anatomy.icon", "descriptionFallback": "Icon <use> element (base class)."}, {"cl