he root wrapper."}, {"name": "--origam-chart---gap", "defaultValue": "{space.3}", "descriptionKey": "components.chart_pictorial.css_vars.gap", "descriptionFallback": "Grid gap between header / body / legend rows."}, {"name": "--origam-chart---animation-duration", "defaultValue": "600ms", "descriptionKey": "components.chart_pictorial.css_vars.animation_duration", "descriptionFallback": "Icon animation duration. Set via animationDuration prop."}], "playground": {"controls": [{"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.chart_pictorial.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "text", "prop": "title", "labelKey": "components.chart_pictorial.playground.title", "defaultValue": "", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.chart_pictorial.playground.subtitle", "defaultValue": "", "labelFallback": "Subtitle"}, {"kind": "select", "prop": "iconColor", "options": [{"label": "(default)", "value": ""}, {"label": "neutral", "value": "neutral"}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "ghost", "value": "ghost"}, {"label": "success", "value": "success"}, {"label": "warning", "value": "warning"}, {"label": "danger", "value": "danger"}, {"label": "info", "value": "info"}], "labelKey": "components.chart_pictorial.playground.icon_color", "defaultValue": "", "labelFallback": "Icon Color"}, {"kind": "switch", "prop": "showLabel", "labelKey": "components.chart_pictorial.playground.show_label", "defaultValue": true, "labelFallback": "Show Label"}, {"kind": "switch", "prop": "showAxis", "labelKey": "components.chart_pictorial.playground.show_axis", "defaultValue": true, "labelFallback": "Show Axis"}, {"kind": "switch", "prop": "showLegend", "labelKey": "components.chart_pictorial.playground.show_legend", "defaultValue": true, "labelFallback": "Show Legend"}, {"kind": "switch", "prop": "showTooltip", "labelKey": "components.chart_pictorial.playground.show_tooltip", "defaultValue": true, "labelFallback": "Show Tooltip"}]}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('85b49e22-5568-4418-a78c-513edaa1c4b6', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'chart-polar', 'ChartPolar', 'Data Display', NULL, 'mdi-chart-pie', 'components.catalog.chart_polar.description', 'Polar chart (pie / donut) with animated slices, interactive legend, tooltip, and optional drilldown navigation.', NULL, NULL, 'origam-chart-polar', NULL, 'packages/ds/src/components/Chart/OrigamChartPolar.vue', 'origam', NULL, NULL, '/stories/?story=components-chart-polar--design', '/docs/components/Chart/OrigamChartPolar.html', 'chart', '{"a11y": {"notes": [{"noteKey": "components.chart_polar.a11y.svg_note", "noteFallback": "The SVG carries role=\"img\" with a <title> and <desc> generated from the series data. Screen readers announce the chart as a single image with a summary."}, {"noteKey": "components.chart_polar.a11y.slice_note", "noteFallback": "Each slice has tabindex=\"0\" and role=\"button\" with an aria-label formatted as \"{category}: {value}\"."}, {"noteKey": "components.chart_polar.a11y.reduced_motion_note", "noteFallback": "Slice animations are disabled under prefers-reduced-motion: reduce."}], "roles": ["figure", "img", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.chart_polar.a11y.key_tab", "actionFallback": "Moves focus across the interactive slices (each <path> has tabindex=\"0\")."}, {"key": "Enter / Space", "actionKey": "components.chart_polar.a11y.key_activate", "actionFallback": "Activates the focused slice (fires point-click or triggers drilldown)."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "