INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('bae19a55-b336-4c49-a219-a86456c06341', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'checkbox', 'Checkbox', 'Form & Input', NULL, 'mdi-checkbox-marked', 'components.catalog.checkbox.description', 'Form checkbox with label, hint, validation messages, indeterminate state, and full keyboard/accessibility support. Wraps OrigamInput and OrigamCheckboxBtn.', NULL, NULL, 'origam-checkbox', NULL, 'packages/ds/src/components/Checkbox/OrigamCheckbox.vue', 'origam', NULL, NULL, '/stories/?story=components-checkbox--design', '/docs/components/Checkbox/OrigamCheckbox.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.checkbox.a11y.aria_checked", "noteFallback": "The hidden native <input type=\"checkbox\"> carries aria-checked (including \"mixed\" for indeterminate). Screen readers announce state correctly."}, {"noteKey": "components.checkbox.a11y.aria_describedby", "noteFallback": "aria-describedby links the checkbox to the messages container (messagesId) so validation errors are announced."}, {"noteKey": "components.checkbox.a11y.disabled", "noteFallback": "When disabled=true, the native input is disabled and pointer events are removed. Screen readers announce \"dimmed\" state."}], "roles": ["checkbox"], "keyboard": [{"key": "Space", "actionKey": "components.checkbox.a11y.key_space", "actionFallback": "Toggles the checked state. Native <input type=\"checkbox\"> behaviour."}, {"key": "Tab", "actionKey": "components.checkbox.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"40\" width=\"660\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"50\" y=\"76\" width=\"40\" height=\"40\" rx=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <polyline points=\"58,97 68,108 82,84\" stroke=\"white\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\"/>\n  <rect x=\"110\" y=\"86\" width=\"220\" height=\"20\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"220\" y=\"100\" font-size=\"12\" fill=\"var(--origam-color__text---primary, #1a0f3c)\" text-anchor=\"middle\" font-family=\"sans-serif\">Checkbox label</text>\n  <rect x=\"20\" y=\"130\" width=\"660\" height=\"20\" rx=\"3\" fill=\"none\"/>\n  <text x=\"360\" y=\"143\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\">Hint / validation messages</text>\n  <circle cx=\"28\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"70\" cy=\"70\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"70\" y=\"74\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"220\" cy=\"80\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"220\" y=\"84\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"360\" cy=\"134\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"360\" y=\"138\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"68\" cy=\"96\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"68\" y=\"100\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"350\" y=\"185\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Checkbox wraps OrigamInput (frame) + OrigamCheckboxBtn (control)</text>\n", "code": "<origam-input class=\"origam-checkbox\">\n  <template #default=\"{ id, messagesId, isDisabled, isReadonly, isValid }\">\n    <origam-checkbox-btn\n      :id=\"id\"\n      :aria-describedby=\"messagesId\"\n      :disabled=\"isDisabled\"\n      :error=\"!isValid\"\n      :readonly=\"isReadonly\"\n    >\n      <!-- hidden native checkbox -->\n      <input type=\"checkbox\" class=\"origam-selection-control__input\" />\n      <!-- visual box + icon -->\n      <span class=\"origam-checkbox-btn__box\">\n        <origam-icon class=\"origam-checkbox-btn__icon\" />\n      </span>\n      <!-- label -->\n      <label class=\"origam-selection-control__label\" :for=\"id\" />\n    </origam-checkbox-btn>\n  </template>\n</origam-input>", "legend": [{"cls": ".origam-checkbox", "num": 1, "descriptionKey": "components.checkbox.anatomy.root", "descriptionFallback": "Root element extending OrigamInput. Holds the label, hint and messages frame."}, {"cls": ".origam-checkbox-btn", "num": 2, "descriptionKey": "components.checkbox.anatomy.btn", "descriptionFallback": "Visual checkbox control (OrigamCheckboxBtn). Contains the box and icon."}, {"cls": ".origam-selection-control__label", "num": 3, "descriptionKey": "components.checkbox.anatomy.label", "descriptionFallback": "Text label. Bound via htmlFor to the hidden native <input>."}, {"cls": ".origam-input__details", "num": 4, "descriptionKey": "components.checkbox.anatomy.details", "descriptionFallback": "Messages/hint area. Hidden when hideDetails=true."}, {"cls": ".origam-selection-control__input", "num": 5, "descriptionKey": "components.checkbox.anatomy.input", "descriptionFallback": "Hidden native <input type=\"checkbox\"> that carries the value for form submissions."}], "classes": [{"cls": "origam-checkbox", "descriptionKey": "components.checkbox.anatomy.root", "descriptionFallback": "Root element wrapping OrigamInput and OrigamCheckboxBtn."}, {"cls": "origam-checkbox-btn", "descriptionKey": "components.checkbox.anatomy.btn", "descriptionFallback": "Visual selection control (the styled square box + check icon)."}, {"cls": "origam-selection-control__label", "descriptionKey": "components.checkbox.anatomy.label", "descriptionFallback": "Label element rendered beside the box."}, {"cls": "origam-selection-control__input", "descriptionKey": "components.checkbox.anatomy.input", "descriptionFallback": "Hidden native checkbox for form semantics."}, {"cls": "origam-input__details", "descriptionKey": "components.checkbox.anatomy.details", "descriptionFallback": "Hint and validation messages container."}], "svgDesc": "Schematic of the Checkbox component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamCheckbox", "rootClass": "origam-checkbox", "figcaption": "Anatomy of <code>&lt;origam-checkbox&gt;</code> — 5 internal parts.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-checkbox---min-height", "defaultValue": "56px", "descriptionKey": "components.checkbox.css_vars.min_height", "descriptionFallback": "Minimum height of the checkbox input row, before density is applied."}, {"name": "--origam-checkbox__input---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.checkbox.css_vars.input_bg", "descriptionFallback": "Background of the checkbox visual box in unchecked state."}, {"name": "--origam-checkbox__input---background-color-checked", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.checkbox.css_vars.input_bg_ch