imary---bgSubtle, rgba(124,58,237,0.1))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"108\" y=\"104\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">icon</text>\n  <rect x=\"148\" y=\"80\" width=\"280\" height=\"40\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"288\" y=\"105\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Label / #default slot</text>\n  <circle cx=\"572\" cy=\"100\" r=\"24\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.1))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"572\" y=\"104\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">close</text>\n  <circle cx=\"68\" cy=\"68\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"68\" y=\"72.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"108\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"108\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"148\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"148\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"430\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"430\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"548\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"548\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"68\" cy=\"132\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"68\" y=\"136\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <circle cx=\"108\" cy=\"132\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"108\" y=\"136\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">7</text>\n  <text x=\"350\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">⑥ overlay + ⑦ underlay = absolute layers, opacity:0 at rest</text>\n", "code": "<span class=\"origam-chip origam-chip--size-default\">\n  <!-- interaction overlay (hover/focus/active) -->\n  <span class=\"origam-chip__overlay\" />\n  <span class=\"origam-chip__underlay\" />\n\n  <!-- filter icon (expand-x transition, visible when selected in group) -->\n  <div class=\"origam-chip__filter\">\n    <slot name=\"filter\" />\n  </div>\n\n  <!-- prepend slot: icon or avatar -->\n  <div class=\"origam-chip__prepend\">\n    <slot name=\"prepend\" />\n  </div>\n\n  <!-- main label / default slot -->\n  <div class=\"origam-chip__content\" data-no-activator=\"\">\n    <slot name=\"default\" />\n  </div>\n\n  <!-- append slot: icon or avatar -->\n  <div class=\"origam-chip__append\">\n    <slot name=\"append\" />\n  </div>\n\n  <!-- close button -->\n  <origam-btn class=\"origam-chip__close\" variant=\"text\" size=\"x-small\">\n    <slot name=\"close\" />\n  </origam-btn>\n</span>", "legend": [{"cls": ".origam-chip", "num": 1, "descriptionKey": "components.chip.anatomy.root", "descriptionFallback": "Root element. Renders as <code>&lt;span&gt;</code> by default; switches to <code>&lt;a&gt;</code> when a link prop is set. Pill shape by default (<code>border-radius: 9999px</code>)."}, {"cls": ".origam-chip__prepend", "num": 2, "descriptionKey": "components.chip.anatomy.prepend", "descriptionFallback": "Leading area. Renders <code>prependIcon</code> or <code>prependAvatar</code>, or the <code>#prepend</code> slot. Present only when <code>hasPrepend</code>."}, {"cls": ".origam-chip__content", "num": 3, "descriptionKey": "components.chip.anatomy.content", "descriptionFallback": "Label zone. Contains the <code>#default</code> slot text or the <code>text</code> prop. Has <code>data-no-activator</code> attribute."}, {"cls": ".origam-chip__filter", "num": 4, "descriptionKey": "components.chip.anatomy.filter", "descriptionFallback": "Filter check icon area. Visible only when <code>filter=true</code> and the chip is selected inside a ChipGroup. Uses <code>OrigamExpandX</code> transition."}, {"cls": ".origam-chip__close", "num": 5, "descriptionKey": "components.chip.anatomy.close", "descriptionFallback": "Close button (<code>OrigamBtn variant=\"text\"</code>). Present when <code>closable=true</code> or the <code>#close</code> slot is used."}, {"cls": ".origam-chip__overlay", "num": 6, "descriptionKey": "components.chip.anatomy.overlay", "descriptionFallback": "Interaction overlay. <code>opacity: 0</code> at rest → 0.24 on hover → 0.12 on focus. Present only when the chip is clickable."}, {"cls": ".origam-chip__underlay", "num": 7, "descriptionKey": "components.chip.anatomy.underlay", "descriptionFallback": "Reserved absolute underlay. <code>position: absolute</code>. Currently unpainted (no background)."}], "classes": [{"cls": "origam-chip", "descriptionKey": "components.chip.anatomy.root", "descriptionFallback": "Root element. Full-round pill by default."}, {"cls": "origam-chip__overlay", "descriptionKey": "components.chip.anatomy.overlay", "descriptionFallback": "Interaction overlay. Opacity animates on hover/focus/active."}, {"cls": "origam-chip__underlay", "descriptionKey": "components.chip.anatomy.underlay", "descriptionFallback": "Reserved absolute underlay layer."}, {"cls": "origam-chip__filter", "descriptionKey": "components.chip.anatomy.filter", "descriptionFallback": "Filter check icon container. Shown with ExpandX transition when selected in filter mode."}, {"cls": "origam-chip__prepend", "descriptionKey": "components.chip.anatomy.prepend", "descriptionFallback": "Leading icon or avatar container."}, {"cls": "origam-chip__content", "descriptionKey": "components.chip.anatomy.content", "descriptionFallback": "Label container."}, {"cls": "origam-chip__append", "descriptionKey": "components.chip.anatomy.append", "descriptionFallback": "Trailing icon or avatar container."}, {"cls": "origam-chip__close", "descriptionKey": "components.chip.anatomy.close", "descriptionFallback": "Close button rendered as an OrigamBtn with variant=\"text\"."}], "svgDesc": "Schematic of the Chip component with 7 numbered internal parts.", "svgTitle": "Anatomy of OrigamChip", "rootClass": "origam-chip", "figcaption": "Anatomy of <code>&lt;origam-chip&gt;</code> — 7 internal parts. The chip is a full-round pill by default. Absolute layers (overlay ⑥, underlay ⑦) handle interaction states.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-chip---background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.chip.css_vars.background_color", "descriptionFallback": "Default chip background color."}, {"name": "--origam-chip---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.chip.css_vars.color", "descriptionFallback": "Default chip foreground (text/icon) color."}, {"name": "--origam-chip---border-radius", "defaultValue": "{radius.full}", "descriptionKey": "components.chip.css_vars.border_radius", "descriptionFallback": "Border radius. Full pill by default. Overridden by the label modifier to radius.sm."}, {"name": "--origam-chip---font-weight", "defaultValue": "{font.weight.regular}", "descriptionKey": "components.chip.css_vars.font_weight", "descriptionFallback": "Chip label font weight."}, {"name": "--origam-chip---opacity-disabled", "defaultValue": "0.3", "descriptionKey": "components.chip.css_vars.opacity_disabled", "descriptionFallback": "Opacity applied when the chip is disabled."}, {"name": "--origam-chip---density", "defaultValue": "0px", "descriptionKey": "components.chip.css_vars.density", "descriptionFallback": "Density offset: 0 (default), -8px (compact)."}, {"name": "--origam-chip__overlay---opacity", "defaultValue": "0", "descriptionKey": "components.chip.css_vars.overlay_opacity", "descriptionFallback": "Overlay opacity at rest. Animates to 0.24 on hover and 0.12 on focus/active."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.chip.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.chip.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed chipStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.chip.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.chip.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.chip.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.chip.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success