INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('52b947fd-fc29-43ff-8a0a-69cf7dd8af5b', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'chip-group', 'ChipGroup', 'Data Display', NULL, 'mdi-label-multiple-outline', 'components.catalog.chip_group.description', 'Scrollable group of Chip elements with single or multi-select, filter support, and column layout option. Propagates color/bgColor tokens to descendant chips via OrigamDefaultsProvider.', NULL, NULL, 'origam-chip-group', NULL, 'packages/ds/src/components/Chip/OrigamChipGroup.vue', 'origam', NULL, NULL, '/stories/?story=components-chipgroup--design', '/docs/components/Chip/OrigamChipGroup.html', 'chip', '{"a11y": {"notes": [{"noteKey": "components.chip_group.a11y.group_role", "noteFallback": "The slide group container exposes a logical grouping of selectable chip controls. Each chip carries its own role and aria-selected."}, {"noteKey": "components.chip_group.a11y.defaults_propagation", "noteFallback": "Color tokens are propagated via OrigamDefaultsProvider — children that set their own color still take precedence over the group defaults."}], "roles": ["group"], "keyboard": [{"key": "Tab", "actionKey": "components.chip_group.a11y.key_tab", "actionFallback": "Moves focus between chips inside the group."}, {"key": "Enter / Space", "actionKey": "components.chip_group.a11y.key_activate", "actionFallback": "Selects or deselects the focused chip."}, {"key": "Arrow Left / Right", "actionKey": "components.chip_group.a11y.key_arrows", "actionFallback": "Scrolls the slide group when overflow is present (handled by OrigamSlideGroup)."}]}, "tokens": {