onent", "descriptionKey": "components.component_icon.anatomy.component", "descriptionFallback": "Strategy modifier. Signals the component-icon rendering path."}, {"cls": "origam-icon--size-{size}", "descriptionKey": "components.component_icon.anatomy.size", "descriptionFallback": "Size modifier when a named TSize token is passed."}], "svgDesc": "Schematic of ComponentIcon with 2 internal parts.", "svgTitle": "Anatomy of OrigamComponentIcon", "rootClass": "origam-icon", "figcaption": "Anatomy of <code>&lt;origam-component-icon&gt;</code> — 2 parts. The wrapper <code>div</code> hosts a dynamic <code>&lt;component :is=\"icon\"&gt;</code>.", "svgViewBox": "0 0 400 120"}, "cssVars": [{"name": "--origam-icon---font-size", "defaultValue": "24px", "descriptionKey": "components.component_icon.css_vars.font_size", "descriptionFallback": "Controls width and height of the component icon wrapper."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.component_icon.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.component_icon.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.component_icon.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.component_icon.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.component_icon.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.component_icon.exposed.is_loaded", "descriptionFallback": "True once the style she