ex centring."}], "svgDesc": "Schematic of Container with root wrapper and content slot.", "svgTitle": "Anatomy of OrigamContainer", "rootClass": "origam-container", "figcaption": "Anatomy of <code>&lt;origam-container&gt;</code> — 1 root element with responsive max-width and a default slot. The outer dashed rectangle represents the viewport.", "svgViewBox": "0 0 600 120"}, "cssVars": [{"name": "--origam-container---max-width", "defaultValue": "100%", "descriptionKey": "components.container.css_vars.max_width", "descriptionFallback": "Container max-width. Overridden per media breakpoint: 900px (md), 1200px (lg), 1800px (xl), 2400px (xxl)."}, {"name": "--origam-container---padding-inline-start", "defaultValue": "16px", "descriptionKey": "components.container.css_vars.padding_inline_start", "descriptionFallback": "Horizontal inner padding — start side."}, {"name": "--origam-container---padding-inline-end", "defaultValue": "16px", "descriptionKey": "components.container.css_vars.padding_inline_end", "descriptionFallback": "Horizontal inner padding — end side."}, {"name": "--origam-container---margin-inline-start", "defaultValue": "auto", "descriptionKey": "components.container.css_vars.margin_inline_start", "descriptionFallback": "Left auto margin (centres the container horizontally)."}, {"name": "--origam-container---margin-inline-end", "defaultValue": "auto", "descriptionKey": "components.container.css_vars.margin_inline_end", "descriptionFallback": "Right auto margin (centres the container horizontally)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.container.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.container.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.container.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.container.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.container.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.container.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "fluid", "labelKey": "components.container.playground.fluid", "defaultValue": false, "labelFallback": "Fluid"}, {"kind": "switch", "prop": "fullscreen", "labelKey": "components.container.playground.fullscreen", "defaultValue": false, "labelFallback": "Fullscreen"}], "defaultSlotContent": "Content"}, "previewVariants": [{"label": "default", "props": {}, "slotContent": "Container content"}, {"label": "fluid", "props": {"fluid": true}, "slotContent": "Fluid container"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e656586d-4858-4dd6-918e-6bb078d1911f', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'contextual-menu', 'ContextualMenu', 'Navigation', NULL, 'mdi-menu', 'components.catalog.contextual_menu.description', 'Right-click context menu that opens at the cursor position. Wraps OrigamMenu with openOnContextMenu + target="cursor" + activator="cursor" preconfigured.', NULL, NULL, 'origam-contextual-menu', NULL, 'packages/ds/src/components/ContextualMenu/OrigamContextualMenu.vue', 'origam', NULL, NULL, '/stories/?story=components-contextualmenu--design', '/docs/components/ContextualMenu/OrigamContextualMenu.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.contextual_menu.a11y.cursor_note", "noteFallback": "The menu panel is positioned at the exact cursor coordinates of the right-click event via target=\"cursor\". This matches the native browser context menu behaviour."}, {"noteKey": "components.contextual_menu.a11y.focus_note", "noteFallback": "On open, focus moves to the first enabled menu item. On close (Escape), focus returns to the element that received the right-click."}], "roles": ["menu", "menuitem"], "keyboard": [{"key": "Escape", "actionKey": "components.contextual_menu.a11y.key_escape", "actionFallback": "Closes the context menu and returns focus to the trigger element."}, {"key": "↑ / ↓", "actionKey": "components.contextual_menu.a11y.key_navigate", "actionFallback": "Navigate between menu items."}, {"key": "Enter / Space", "actionKey": "components.contextual_menu.a11y.key_select", "actionFallback": "Activates the focused menu item."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #f5f5f5)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"230\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fafafa)\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.1))\" stroke-width=\"1\" stroke-dasharray=\"6 3\"/>\n  <text x=\"350\" y=\"135\" font-size=\"13\" fill=\"var(--origam-color__text---disabled, #bbb)\" text-anchor=\"middle\" font-family=\"system-ui\">Right-click zone (#activator)</text>\n  <circle cx=\"36\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <rect x=\"200\" y=\"160\" width=\"220\" height=\"120\" rx=\"8\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.12))\" stroke-width=\"1.5\" filter=\"url(#shadow)\"/>\n  <circle cx=\"216\" cy=\"168\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"216\" y=\"172.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <rect x=\"208\" y=\"180\" width=\"204\" height=\"32\" rx=\"4\" fill=\"var(--origam-color__action--secondary---bg, rgba(124,58,237,0.08))\"/>\n  <text x=\"220\" y=\"200\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">Cut</text>\n  <rect x=\"208\" y=\"214\" width=\"204\" height=\"32\" rx=\"4\" fill=\"none\"/>\n  <text x=\"220\" y=\"234\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">Copy</text>\n  <rect x=\"208\" y=\"248\" width=\"204\" height=\"28\" rx=\"4\" fill=\"none\"/>\n  <text x=\"220\" y=\"266\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">Paste</text>\n  <circle cx=\"216\" cy=\"200\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"216\" y=\"204.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"350\" y=\"290\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b0b0b0)\" text-anchor=\"middle\" font-style=\"italic\">① = activator zone (v-bind=\"props\"). ② = menu panel (role=\"menu\"). ③ = menu items (#default slot).</text>\n", "code": "<!-- OrigamContextualMenu wraps OrigamMenu with preconfigured open-on-context-menu -->\n<!-- All OrigamMenu slots are forwarded transparently -->\n<origam-menu\n  open-on-context-menu\n  target=\"cursor\"\n  activator=\"cursor\"\n>\n  <!-- #default slot: your menu content -->\n  <origam-list>\n    <origam-list-item title=\"Cut\"   prepend-icon=\"mdi-content-cut\" />\n    <origam-list-item title=\"Copy\"  prepend-icon=\"mdi-content-copy\" />\n    <origam-list-item title=\"Paste\" prepend-icon=\"mdi-content-paste\" />\n  </origam-list>\n\n  <!-- #activator slot: the right-click zone -->\n  <template #activator=\"{ props }\">\n    <div v-bind=\"props\">Right-click zone</div>\n  </template>\n</origam-menu>", "legend": [{"cls": "activator zone", "num": 1, "descriptionKey": "components.contextual_menu.anatomy.activator", "descriptionFallback": "The element or region that captures the <code>contextmenu</code> event. Defined via the <code>#activator</code> slot or the parent element when no activator is provided."}, {"cls": ".origam-contextual-menu (OrigamMenu root)", "num": 2, "descriptionKey": "components.contextual_menu.anatomy.menu_panel", "descriptionFallback": "Floating menu panel positioned at the cursor via <code>target=\"cursor\"</code>. Background and box-shadow come from contextual-menu tokens. Position is <code>fixed</code> relative to the viewport."}, {"cls": "#default slot", "num": 3, "descriptionKey": "components.contextual_menu.anatomy.content", "descriptionFallback": "Menu content — typically an <code>&lt;origam-list&gt;</code> with <code>&lt;origam-list-item&gt;</code> elements. Max-width is constrained by <code>--origam-contextual-menu__content---max-width</code>."}], "classes": [{"cls": "origam-contextual-menu", "descriptionKey": "components.contextual_menu.anatomy.root", "descriptionFallback": "Root element — thin wrapper over OrigamMenu. Inherits all Menu BEM classes."}], "svgDesc": "Schematic of the ContextualMenu component with numbered regions.", "svgTitle": "Anatomy of OrigamContextualMenu", "rootClass": "origam-contextual-menu", "figcaption": "Anatomy of <code>&lt;origam-contextual-menu&gt;</code>. The component wraps <code>OrigamMenu</code> with <code>openOnContextMenu</code> + <code>target=\"cursor\"</code> pre-configured. Menu panel positions at the exact cursor coordinates of the right-click.", "svgViewBox": "0 0 700 300"}, "cssVars": [{"name": "--origam-contextual-menu---background", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.contextual_menu.css_vars.background", "descriptionFallback": "Background color of the menu panel."}, {"name": "--origam-contextual-menu---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.contextual_menu.css_vars.color", "descriptionFallback": "Foreground color of the menu panel."}, {"name": "--origam-contextual-menu---border-radius", "defaultValue": "{radius.md}", "descriptionKey": "components.contextual_menu.css_vars.border_radius", "descriptionFallback": "Border-radius of the menu panel."}, {"name": "--origam-contextual-menu---box-shadow", "defaultValue": "{shadow.lg}", "descriptionKey": "components.contextual_menu.css_vars.box_shadow", "descriptionFallback": "Box shadow (elevation) of the menu panel."}, {"name": "--origam-contextual-menu---z-index", "defaultValue": "{zIndex.dropdown} → 1000", "descriptionKey": "components.contextual_menu.css_vars.z_index", "descriptionFallback": "Z-index of the menu panel. Appears above content but below modal-level surfaces."}, {"name": "--origam-contextual-menu__content---max-width", "defaultValue": "320px", "descriptionKey": "components.contextual_menu.css_vars.content_max_width", "descriptionFallback": "Maximum width of the menu content area."}, {"name": "--origam-contextual-menu---transition-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.contextual_menu.css_vars.transition_duration", "descriptionFallback": "Open/close transition duration."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.contextual_menu.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to the underlying OrigamMenu."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.contextual_menu.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.contextual_menu.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.contextual_menu.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.contextual_menu.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.contextual_menu.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "modelValue", "labelKey": "components.contextual_menu.playground.model_value", "defaultValue": false, "labelFallback": "Open"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.contextual_menu.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(default)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}], "labelKey": "components.contextual_menu.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "select", "prop": "elevation", "options": [{"label": "(default)", "value": ""}, {"label": "none", "value": "none"}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}], "labelKey": "components.contextual_menu.playground.elevation", "defaultValue": "", "labelFallback": "Elevation"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('bc17dc29-255d-4e5a-9cab-862e133546ed', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'counter', 'Counter', 'Data Display', NULL, 'mdi-counter', 'components.catalog.counter.description', 'Animated character-count badge that shows current/max values. Used internally by TextField, Textarea and similar inputs.', NULL, NULL, 'origam-counter', NULL, 'packages/ds/src/components/Counter/OrigamCounter.vue', 'origam', NULL, NULL, '/stories/?story=components-counter--design', '/docs/components/Counter/OrigamCounter.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.counter.a11y.aria_note", "noteFallback": "OrigamCounter is a visual helper only. When embedded in a text field, the parent field should use aria-describedby pointing to the counter element so screen readers announce the character count."}, {"noteKey": "components.counter.a11y.live_note", "noteFallback": "For dynamic character-count announcements, add aria-live=\"polite\" to the counter element or its parent container."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-counter---color", "descriptionKey": "components.counter.tokens.color", "descriptionFallback": "Default text colour."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-counter---color-active", "descriptionKey": "components.counter.tokens.color_active", "descriptionFallback": "Text colour when field is active/focused."}, {"type": "color", "value": "var(--origam-color__feedback--danger---fgSubtle)", "tokenPath": "--origam-counter---color-error", "descriptionKey": "components.counter.tokens.color_error", "descriptionFallback": "Text colour when value exceeds max."}, {"type": "dimension", "value": "var(--origam-font__size---xs)", "tokenPath": "--origam-counter---font-size", "descriptionKey": "components.counter.tokens.font_size", "descriptionFallback": "Counter font size."}, {"type": "number", "value": "var(--origam-opacity---70)", "tokenPath": "--origam-counter---opacity", "descriptionKey": "components.counter.tokens.opacity", "descriptionFallback": "Default counter opacity."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fdf4ff)\" rx=\"4\"/>\n  <origam-transition name=\"origam-slide-y-transition\">\n    <rect x=\"280\" y=\"50\" width=\"140\" height=\"36\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(124,58,237,0.2))\" stroke-width=\"1.5\"/>\n  </origam-transition>\n  <text x=\"350\" y=\"73\" font-size=\"13\" fill=\"var(--origam-color__text---secondary, #666)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">12 / 50</text>\n  <circle cx=\"296\" cy=\"58\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"296\" y=\"62.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"350\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"350\" y=\"62.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"296\" y1=\"46\" x2=\"296\" y2=\"28\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.4))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"180\" y=\"26\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #7e5fb0)\" font-style=\"italic\" text-anchor=\"middle\">origam-counter (root tag)</text>\n  <line x1=\"350\" y1=\"46\" x2=\"350\" y2=\"28\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"510\" y=\"26\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #7e5fb0)\" font-style=\"italic\" text-anchor=\"middle\">#default slot — renders \"value / max\"</text>\n  <text x=\"350\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Wrapped in OrigamTransition (slide-y). --error modifier when value &gt; max.</text>\n", "code": "<!-- Wrapped in OrigamTransition for animated show/hide -->\n<origam-transition :transition=\"transition\">\n  <component\n    :is=\"tag\"\n    v-show=\"active\"\n    class=\"origam-counter\"\n    :class=\"{ ''origam-counter--error'': value > max && !disabled }\"\n  >\n    <!-- #default slot: { counter, max, value } -->\n    <slot :counter=\"counter\" :max=\"max\" :value=\"value\">\n      {{ counter }}\n    </slot>\n  </component>\n</origam-transition>", "legend": [{"cls": ".origam-counter", "num": 1, "descriptionKey": "components.counter.anatomy.root", "descriptionFallback": "Root element. Tag is controlled by the <code>tag</code> prop (default: <code>div</code>). Wrapped in <code>&lt;origam-transition&gt;</code> for animated show/hide. Modifier <code>--error</code> applied when <code>value &gt; max</code>."}, {"cls": "#default slot", "num": 2, "descriptionKey": "components.counter.anatomy.slot", "descriptionFallback": "Counter content. Default renderer produces \"<code>value / max</code>\" when max is set, or just \"<code>value</code>\" otherwise. Slot props: <code>{ counter, max, value }</code>."}], "classes": [{"cls": "origam-counter", "descriptionKey": "components.counter.anatomy.root", "descriptionFallback": "Root element. Transition-wrapped, v-show controlled by active prop."}, {"cls": "origam-counter--error", "descriptionKey": "components.counter.anatomy.error", "descriptionFallback": "Applied when value > max and disabled is false. Switches text colour to the danger token."}], "svgDesc": "Schematic of the Counter component with numbered parts.", "svgTitle": "Anatomy of OrigamCounter", "rootClass": "origam-counter", "figcaption": "Anatomy of <code>&lt;origam-counter&gt;</code>. A single root element (① tag) wraps the default slot (②) which renders the computed \"<code>value / max</code>\" string. The <code>--error</code> modifier is applied when <code>value &gt; max</code>.", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-counter---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.counter.css_vars.color", "descriptionFallback": "Default counter text colour."}, {"name": "--origam-counter---color-active", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.counter.css_vars.color_active", "descriptionFallback": "Counter text colour when the field is focused / active."}, {"name": "--origam-counter---color-error", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.counter.css_vars.color_error", "descriptionFallback": "Counter text colour when value exceeds max (--error modifier)."}, {"name": "--origam-counter---font-size", "defaultValue": "{font.size.xs}", "descriptionKey": "components.counter.css_vars.font_size", "descriptionFallback": "Counter font size."}, {"name": "--origam-counter---font-weight", "defaultValue": "{font.weight.regular}", "descriptionKey": "components.counter.css_vars.font_weight", "descriptionFallback": "Counter font weight."}, {"name": "--origam-counter---opacity", "defaultValue": "{opacity.70}", "descriptionKey": "components.counter.css_vars.opacity", "descriptionFallback": "Default opacity. Set to 1 when active/focused."}, {"name": "--origam-counter---transition-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.counter.css_vars.transition_duration", "descriptionFallback": "Transition duration for colour/opacity changes."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.counter.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.counter.exposed.css", "descriptionFallback": "Reactive CSS string for the injected style sheet."}, {"name": "id", "type": "string", "descriptionKey": "components.counter.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.counter.exposed.load", "descriptionFallback": "Injects the style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.counter.exposed.unload", "descriptionFallback": "Removes the style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.counter.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "number", "prop": "value", "labelKey": "components.counter.playground.value", "defaultValue": 12, "labelFallback": "Value"}, {"kind": "number", "prop": "max", "labelKey": "components.counter.playground.max", "defaultValue": 50, "labelFallback": "Max"}, {"kind": "switch", "prop": "active", "labelKey": "components.counter.playground.active", "defaultValue": true, "labelFallback": "Active (visible)"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.counter.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.counter.playground.color", "defaultValue": "", "labelFallback": "Color"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fa9e7610-a6bc-4107-8fda-0315ae9d1ed6', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'data-list', 'DataList', 'Data Display', NULL, 'mdi-format-list-bulleted', 'components.catalog.data_list.description', 'Semantic description list (<dl>) with two layout modes: avatar (icon + title/text stacked) and kv (key/value rows aligned side-by-side).', NULL, NULL, 'origam-data-list', NULL, 'packages/ds/src/components/DataList/OrigamDataList.vue', 'origam', NULL, NULL, '/stories/?story=components-datalist--design', '/docs/components/DataList/OrigamDataList.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.data_list.a11y.dl_note", "noteFallback": "Avatar mode renders a semantic <dl> with <dt> (term/title) and <dd> (definition/text) elements. This provides native screen-reader association between key and value without ARIA."}, {"noteKey": "components.data_list.a11y.kv_note", "noteFallback": "KV mode also uses <dl>/<dt>/<dd> structure, which is the recommended HTML pattern for key/value pairs. Do not use a <table> unless the data is truly tabular (multiple columns with a column header)."}], "roles": ["term", "definition"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-data-list---background-color", "descriptionKey": "components.data_list.tokens.background_color", "descriptionFallback": "Root list background."}, {"type": "fontWeight", "value": "var(--origam-font__weight---medium)", "tokenPath": "--origam-data-list__title---font-weight", "descriptionKey": "components.data_list.tokens.title_font_weight", "descriptionFallback": "Title row font weight."}, {"type": "dimension", "value": "160px", "tokenPath": "--origam-data-list__kv---key-width", "descriptionKey": "components.data_list.tokens.kv_key_width", "descriptionFallback": "Fixed width of the key column in kv mode."}, {"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-data-list__kv---row-divider", "descriptionKey": "components.data_list.tokens.kv_row_divider", "descriptionFallback": "Row bottom border colour in kv mode."}, {"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-data-list__item---hover-background-color", "descriptionKey": "components.data_list.tokens.item_hover_background_color", "descriptionFallback": "Item background on hover."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <text x=\"175\" y=\"22\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #555)\" text-anchor=\"middle\" font-weight=\"700\">mode=\"avatar\"</text>\n  <text x=\"525\" y=\"22\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #555)\" text-anchor=\"middle\" font-weight=\"700\">mode=\"kv\"</text>\n  <rect x=\"20\" y=\"30\" width=\"310\" height=\"250\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.1))\" stroke-width=\"1.5\"/>\n  <circle cx=\"36\" cy=\"38\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"42.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <rect x=\"28\" y=\"50\" width=\"294\" height=\"80\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.08))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <circle cx=\"52\" cy=\"75\" r=\"18\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.1))\"/>\n  <text x=\"52\" y=\"79\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #666)\" text-anchor=\"middle\">av.</text>\n  <circle cx=\"44\" cy=\"62\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"44\" y=\"66.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"96\" y=\"68\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\" font-weight=\"600\">Alice Martin</text>\n  <circle cx=\"80\" cy=\"62\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"80\" y=\"66.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"96\" y=\"86\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #666)\" font-family=\"system-ui\">alice@example.com</text>\n  <circle cx=\"80\" cy=\"82\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"80\" y=\"86.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <rect x=\"380\" y=\"30\" width=\"300\" height=\"250\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.1))\" stroke-width=\"1.5\"/>\n  <circle cx=\"396\" cy=\"38\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"396\" y=\"42.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"388\" y1=\"96\" x2=\"672\" y2=\"96\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.1))\" stroke-width=\"1\"/>\n  <text x=\"400\" y=\"74\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #888)\" font-family=\"system-ui\">Status</text>\n  <text x=\"540\" y=\"74\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">Active</text>\n  <circle cx=\"520\" cy=\"70\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"520\" y=\"74.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"396\" cy=\"70\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"396\" y=\"74.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n", "code": "<!-- mode=\"avatar\" — semantic <dl> layout -->\n<dl class=\"origam-data-list\">\n  <!-- per IDataItem -->\n  <div class=\"origam-data-list__item\">\n    <dt class=\"origam-data-list__title\">\n      <!-- OrigamDataTitle: avatar/icon + text -->\n    </dt>\n    <dd class=\"origam-data-list__text\">\n      <!-- OrigamDataText per text entry -->\n    </dd>\n  </div>\n</dl>\n\n<!-- mode=\"kv\" — key/value grid -->\n<dl class=\"origam-data-list origam-data-list--kv\">\n  <!-- per IDataListKVItem -->\n  <div class=\"origam-data-list__kv-row\">\n    <dt class=\"origam-data-list__kv-key\">Status</dt>\n    <dd class=\"origam-data-list__kv-value\">Active</dd>\n  </div>\n</dl>", "legend": [{"cls": ".origam-data-list", "num": 1, "descriptionKey": "components.data_list.anatomy.root", "descriptionFallback": "Root element. Renders as <code>&lt;dl&gt;</code> in avatar mode, <code>&lt;div&gt;</code> in kv mode. Background, padding and border-radius from tokens."}, {"cls": ".origam-data-list__title", "num": 2, "descriptionKey": "components.data_list.anatomy.title", "descriptionFallback": "<code>&lt;dt&gt;</code> element. Hosts the <code>OrigamDataTitle</code> with its prepend avatar/icon and text. Only in avatar mode."}, {"cls": ".origam-data-list__text (first)", "num": 3, "descriptionKey": "components.data_list.anatomy.text", "descriptionFallback": "<code>&lt;dd&gt;</code> elements. Each text row rendered by <code>OrigamDataText</code>. Stacked below the title in avatar mode."}, {"cls": ".origam-data-list__text (nth)", "num": 4, "descriptionKey": "components.data_list.anatomy.text_nth", "descriptionFallback": "Additional text rows. Multiple rows are stacked vertically within the item."}, {"cls": ".origam-data-list__kv-value", "num": 5, "descriptionKey": "components.data_list.anatomy.kv_value", "descriptionFallback": "<code>&lt;dd&gt;</code> element for the value in kv mode. Right-aligned. Accepts inline components (Chip, Avatar…)."}, {"cls": ".origam-data-list__kv-key", "num": 6, "descriptionKey": "components.data_list.anatomy.kv_key", "descriptionFallback": "<code>&lt;dt&gt;</code> element for the key in kv mode. Width fixed by <code>--origam-data-list__kv---key-width</code>. Muted colour."}], "classes": [{"cls": "origam-data-list", "descriptionKey": "components.data_list.anatomy.root", "descriptionFallback": "Root list element (dl in avatar mode)."}, {"cls": "origam-data-list--kv", "descriptionKey": "components.data_list.anatomy.kv_modifier", "descriptionFallback": "Applied when mode=\"kv\". Switches to key/value grid layout."}, {"cls": "origam-data-list__title", "descriptionKey": "components.data_list.anatomy.title", "descriptionFallback": "Title row (dt) in avatar mode."}, {"cls": "origam-data-list__text", "descriptionKey": "components.data_list.anatomy.text", "descriptionFallback": "Text row (dd) in avatar mode."}, {"cls": "origam-data-list__kv-key", "descriptionKey": "components.data_list.anatomy.kv_key", "descriptionFallback": "Key cell (dt) in kv mode."}, {"cls": "origam-data-list__kv-value", "descriptionKey": "components.data_list.anatomy.kv_value", "descriptionFallback": "Value cell (dd) in kv mode."}], "svgDesc": "Schematic of the DataList component in avatar mode and kv mode.", "svgTitle": "Anatomy of OrigamDataList", "rootClass": "origam-data-list", "figcaption": "Anatomy of <code>&lt;origam-data-list&gt;</code> in avatar mode (left) and kv mode (right). Avatar mode renders a <code>&lt;dl&gt;</code> with <code>&lt;dt&gt;</code> titles and <code>&lt;dd&gt;</code> text rows. KV mode renders a key/value grid layout.", "svgViewBox": "0 0 700 300"}, "cssVars": [{"name": "--origam-data-list---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.data_list.css_vars.background_color", "descriptionFallback": "Root list background colour."}, {"name": "--origam-data-list---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.data_list.css_vars.color", "descriptionFallback": "Root list foreground colour."}, {"name": "--origam-data-list---border-radius", "defaultValue": "{radius.none}", "descriptionKey": "components.data_list.css_vars.border_radius", "descriptionFallback": "List container border-radius."}, {"name": "--origam-data-list__title---font-size", "defaultValue": "{font.size.sm}", "descriptionKey": "components.data_list.css_vars.title_font_size", "descriptionFallback": "Font size of avatar-mode title rows."}, {"name": "--origam-data-list__title---font-weight", "defaultValue": "{font.weight.medium}", "descriptionKey": "components.data_list.css_vars.title_font_weight", "descriptionFallback": "Font weight of avatar-mode title rows."}, {"name": "--origam-data-list__title---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.data_list.css_vars.title_color", "descriptionFallback": "Text colour of avatar-mode title rows."}, {"name": "--origam-data-list__kv---key-width", "defaultValue": "160px", "descriptionKey": "components.data_list.css_vars.kv_key_width", "descriptionFallback": "Fixed width of the key column in kv mode."}, {"name": "--origam-data-list__kv---key-color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.data_list.css_vars.kv_key_color", "descriptionFallback": "Text colour of kv-mode keys."}, {"name": "--origam-data-list__kv---value-color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.data_list.css_vars.kv_value_color", "descriptionFallback": "Text colour of kv-mode values."}, {"name": "--origam-data-list__kv---row-divider", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.data_list.css_vars.kv_row_divider", "descriptionFallback": "Bottom border colour between kv rows."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.data_list.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.data_list.exposed.css", "descriptionFallback": "Reactive CSS string for the injected style sheet."}, {"name": "id", "type": "string", "descriptionKey": "components.data_list.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.data_list.exposed.load", "descriptionFallback": "Injects the style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.data_list.exposed.unload", "descriptionFallback": "Removes the style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.data_list.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "mode", "options": [{"label": "avatar", "value": "avatar"}, {"label": "kv", "value": "kv"}], "labelKey": "components.data_list.playground.mode", "defaultValue": "avatar", "labelFallback": "Mode"}, {"kind": "switch", "prop": "border", "labelKey": "components.data_list.playground.border", "defaultValue": false, "labelFallback": "Border"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}], "labelKey": "components.data_list.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "select", "prop": "density", "options": [{"label": "default", "value": "default"}, {"label": "comfortable", "value": "comfortable"}, {"label": "compact", "value": "compact"}], "labelKey": "components.data_list.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "select", "prop": "elevation", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}], "labelKey": "components.data_list.playground.elevation", "defaultValue": "", "labelFallback": "Elevation"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b5e4edac-c6d3-4b0c-997b-00266de840c3', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'data-table', 'DataTable', 'Data Display', NULL, 'mdi-table', 'components.catalog.data_table.description', 'Feature-rich data table with sorting, multi-sort, grouping, row selection, column pinning, virtual pagination and full slot customisation.', NULL, NULL, 'origam-data-table', NULL, 'packages/ds/src/components/DataTable/OrigamDataTable.vue', 'origam', NULL, NULL, '/stories/?story=components-datatable--design', '/docs/components/DataTable/OrigamDataTable.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.data_table.a11y.table_note", "noteFallback": "The table renders as a semantic <table> with proper <thead>, <tbody>, <tr>, <th> (scope=\"col\") and <td>. Screen readers can announce the table structure natively."}, {"noteKey": "components.data_table.a11y.sort_note", "noteFallback": "Sortable header cells use aria-sort=\"ascending\" | \"descending\" | \"none\". Sort direction changes are announced by screen readers without additional ARIA live regions."}, {"noteKey": "components.data_table.a11y.select_note", "noteFallback": "Row checkboxes have aria-label describing the row (e.g. \"Select row Alice Martin\"). The select-all checkbox uses aria-label=\"Select all\"."}], "roles": ["table", "rowheader", "columnheader", "row", "cell"], "keyboard": [{"key": "Tab", "actionKey": "components.data_table.a11y.key_tab", "actionFallback": "Move focus between header sort buttons, checkboxes and pagination controls."}, {"key": "Enter / Space", "actionKey": "components.data_table.a11y.key_sort", "actionFallback": "Activate a sortable column header to sort ascending, then descending."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-data-table---background-color", "descriptionKey": "components.data_table.tokens.background_color", "descriptionFallback": "Table root background."}, {"type": "color", "value": "var(--origam-color__surface---raised)", "tokenPath": "--origam-data-table__header---background-color", "descriptionKey": "components.data_table.tokens.header_background_color", "descriptionFallback": "Header row background."}, {"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-data-table__row---hover-background-color", "descriptionKey": "components.data_table.tokens.row_hover_background_color", "descriptionFallback": "Row hover background."}, {"type": "number", "value": "var(--origam-opacity---50)", "tokenPath": "--origam-data-table--loading---opacity", "descriptionKey": "components.data_table.tokens.loading_opacity", "descriptionFallback": "Opacity of data cells while loading."}, {"type": "number", "value": "var(--origam-opacity---0)", "tokenPath": "--origam-data-table__header---sort-icon-opacity", "descriptionKey": "components.data_table.tokens.sort_icon_opacity", "descriptionFallback": "Sort icon default opacity (hidden at rest, revealed on hover/active)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"260\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.1))\" stroke-width=\"1.5\"/>\n  <circle cx=\"36\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <rect x=\"20\" y=\"38\" width=\"660\" height=\"38\" rx=\"0\" fill=\"var(--origam-color__surface---raised, #1e1e2e)\" stroke=\"none\"/>\n  <circle cx=\"36\" cy=\"57\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"36\" y=\"61.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"80\" y=\"61\" font-size=\"10\" fill=\"#fff\" font-family=\"system-ui\" font-weight=\"600\">Name</text>\n  <text x=\"260\" y=\"61\" font-size=\"10\" fill=\"#fff\" font-family=\"system-ui\" font-weight=\"600\">Email</text>\n  <text x=\"500\" y=\"61\" font-size=\"10\" fill=\"#fff\" font-family=\"system-ui\" font-weight=\"600\">Role</text>\n  <rect x=\"20\" y=\"76\" width=\"660\" height=\"44\" rx=\"0\" fill=\"var(--origam-color__surface---raised, #f0f0f0)\"/>\n  <circle cx=\"36\" cy=\"98\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"102.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"80\" y=\"102\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">Alice Martin</text>\n  <text x=\"260\" y=\"102\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">alice@example.com</text>\n  <text x=\"500\" y=\"102\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">Admin</text>\n  <rect x=\"20\" y=\"120\" width=\"660\" height=\"44\" rx=\"0\" fill=\"none\"/>\n  <circle cx=\"36\" cy=\"142\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"146.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"80\" y=\"146\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">Bob Smith</text>\n  <line x1=\"20\" y1=\"164\" x2=\"680\" y2=\"164\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.08))\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"248\" width=\"660\" height=\"32\" rx=\"0\" fill=\"var(--origam-color__surface---default, #fafafa)\" stroke=\"none\"/>\n  <line x1=\"20\" y1=\"248\" x2=\"680\" y2=\"248\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.1))\" stroke-width=\"1\"/>\n  <circle cx=\"36\" cy=\"264\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"36\" y=\"268.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <text x=\"580\" y=\"268\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #555)\" font-family=\"system-ui\">1-10 of 52  &lt; 1 2 3 &gt;</text>\n", "code": "<div class=\"origam-data-table\">\n  <!-- slot: #top -->\n  <table class=\"origam-data-table__table\">\n    <thead>\n      <!-- OrigamDataTableHeaders -->\n      <tr>\n        <th class=\"origam-data-table-header-cell origam-data-table-header-cell--sortable\">\n          Name\n          <span class=\"origam-data-table-header-cell__sort-icon\" />\n        </th>\n        <!-- … more <th> … -->\n      </tr>\n    </thead>\n    <tbody>\n      <!-- OrigamDataTableRows → OrigamDataTableRow → OrigamDataTableColumnCell -->\n      <tr class=\"origam-data-table-row\">\n        <td class=\"origam-data-table-cell\">Alice Martin</td>\n        <!-- … more <td> … -->\n      </tr>\n    </tbody>\n  </table>\n  <!-- slot: #bottom → OrigamDataTableFooter -->\n  <div class=\"origam-data-table-footer\">…</div>\n</div>", "legend": [{"cls": ".origam-data-table", "num": 1, "descriptionKey": "components.data_table.anatomy.root", "descriptionFallback": "Root wrapper. Provides background, border-collapse, width=100%. Contains OrigamTable as the semantic <table>."}, {"cls": ".origam-data-table-header-cell (<th>)", "num": 2, "descriptionKey": "components.data_table.anatomy.header_cell", "descriptionFallback": "Column header cell (OrigamDataTableHeaderCell). Dark background from header.background-color token. Sortable headers show a sort icon (opacity-based reveal on hover/active)."}, {"cls": ".origam-data-table-row (<tr>)", "num": 3, "descriptionKey": "components.data_table.anatomy.row", "descriptionFallback": "Body row (OrigamDataTableRow). Alternating background for striped variant. Hover background from row.hover-background-color token. Selected rows use row.selected-background-color."}, {"cls": ".origam-data-table-footer", "num": 4, "descriptionKey": "components.data_table.anatomy.footer", "descriptionFallback": "Footer bar (OrigamDataTableFooter). Hosts items-per-page select, \"x-y of z\" info and pagination control. Fixed or inline depending on fixedFooter prop."}], "classes": [{"cls": "origam-data-table", "descriptionKey": "components.data_table.anatomy.root", "descriptionFallback": "Root wrapper."}, {"cls": "origam-data-table--show-select", "descriptionKey": "components.data_table.anatomy.show_select", "descriptionFallback": "Applied when showSelect=true. Adds checkbox column."}, {"cls": "origam-data-table--loading", "descriptionKey": "components.data_table.anatomy.loading", "descriptionFallback": "Applied when loading=true. Dims data cells to 50% opacity."}, {"cls": "origam-data-table-header-cell", "descriptionKey": "components.data_table.anatomy.header_cell", "descriptionFallback": "Column <th> element."}, {"cls": "origam-data-table-header-cell--sortable", "descriptionKey": "components.data_table.anatomy.header_cell_sortable", "descriptionFallback": "Applied to sortable column headers (cursor: pointer)."}, {"cls": "origam-data-table-row", "descriptionKey": "components.data_table.anatomy.row", "descriptionFallback": "Body <tr> element."}, {"cls": "origam-data-table-cell", "descriptionKey": "components.data_table.anatomy.cell", "descriptionFallback": "Body <td> element."}, {"cls": "origam-data-table-cell--fixed", "descriptionKey": "components.data_table.anatomy.cell_fixed", "descriptionFallback": 