INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b19c90e5-1c78-4b23-bee2-04a6ea5390f5', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'data-table-footer', 'DataTableFooter', 'Data Display', NULL, 'mdi-table-row', 'components.catalog.data_table_footer.description', 'Pagination and items-per-page footer bar rendered below the DataTable body.', NULL, NULL, 'origam-data-table-footer', NULL, 'packages/ds/src/components/DataTable/OrigamDataTableFooter.vue', 'origam', NULL, NULL, '/stories/?story=components-datatable--design', '/docs/components/DataTable/OrigamDataTable.html', 'data-table', '{"a11y": {"notes": [{"noteKey": "components.data_table_footer.a11y.pagination_note", "noteFallback": "The embedded OrigamPagination provides aria-label attributes on first/prev/next/last buttons via firstPageLabel, prevPageLabel, nextPageLabel and lastPageLabel props."}], "roles": ["contentinfo"], "keyboard": [{"key": "Tab", "actionKey": "components.data_table_footer.a11y.key_tab", "actionFallback": "Moves focus through the items-per-page select and pagination buttons."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"120\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"10\" y=\"20\" width=\"680\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---default, #fff)\" stroke=\"var(--origam-color__border---default, #e5d9f9)\" stroke-width=\"1.5\"/>\n  <rect x=\"30\" y=\"40\" width=\"160\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #f5f0ff)\" stroke=\"var(--origam-color__border---default, #c4b0f0)\" stroke-width=\"1\"/>\n  <text x=\"110\" y=\"64\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Items per page</text>\n  <rect x=\"220\" y=\"40\" width=\"160\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #f5f0ff)\" stroke=\"var(--origam-color__border---default, #c4b0f0)\" stroke-width=\"1\"/>\n  <text x=\"300\" y=\"64\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Page info</text>\n  <rect x=\"420\" y=\"40\" width=\"240\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #f5f0ff)\" stroke=\"var(--origam-color__border---default, #c4b0f0)\" stroke-width=\"1\"/>\n  <text x=\"540\" y=\"64\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Pagination</text>\n  <circle cx=\"20\" cy=\"28\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"20\" y=\"32\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"220\" cy=\"28\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"220\" y=\"32\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"420\" cy=\"28\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"420\" y=\"32\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div class=\"origam-data-table-footer\">\n  <origam-row>\n    <!-- #prepend slot -->\n    <div class=\"origam-data-table-footer__items-per-page\">\n      <span>Items per page</span>\n      <origam-select :items=\"itemsPerPageOptions\" />\n    </div>\n    <div class=\"origam-data-table-footer__info\">\n      <span>1–10 of 50</span>\n    </div>\n    <div class=\"origam-data-table-footer__pagination\">\n      <origam-pagination show-first-last-page rounded />\n    </div>\n    <!-- #append slot -->\n  </origam-row>\n</div>", "legend": [{"cls": ".origam-data-table-footer__items-per-page", "num": 1, "descriptionKey": "components.data_table_footer.anatomy.items_per_page", "descriptionFallback": "Items-per-page label + OrigamSelect dropdown. Fires setItemsPerPage() on change."}, {"cls": ".origam-data-table-footer__info", "num": 2, "descriptionKey": "components.data_table_footer.anatomy.info", "descriptionFallback": "Localised page range label: \"start–stop of total\". Driven by usePagination()."}, {"cls": ".origam-data-table-footer__pagination", "num": 3, "descriptionKey": "components.data_table_footer.anatomy.pagination", "descriptionFallback": "OrigamPagination with density=\"compact\", showFirstLastPage and rounded. Syncs currentPage with the shared pagination context."}], "classes": [{"cls": "origam-data-table-footer", "descriptionKey": "components.data_table_footer.anatomy.root", "descriptionFallback": "Root element — flex row, justify-content: flex-end."}, {"cls": "origam-data-table-footer__items-per-page", "descriptionKey": "components.data_table_footer.anatomy.items_per_page", "descriptionFallback": "Container for the items-per-page label and select control."}, {"cls": "origam-data-table-footer__info", "descriptionKey": "components.data_table_footer.anatomy.info", "descriptionFallback": "Page range information label (e.g. \"1–10 of 50\")."}, {"cls": "origam-data-table-footer__pagination", "descriptionKey": "components.data_table_footer.anatomy.pagination", "descriptionFallback": "Wrapper for the embedded OrigamPagination control."}], "svgDesc": "Schematic of the footer bar with items-per-page select, page info and pagination.", "svgTitle": "Anatomy of OrigamDataTableFooter", "rootClass": "origam-data-table-footer", "figcaption": "Anatomy of <code>&lt;origam-data-table-footer&gt;</code> — 3 internal parts: items-per-page, page info label and pagination.",