{"excerpt": [{"type": "dimension", "value": "40px", "tokenPath": "--origam-date-picker__day---size", "descriptionKey": "components.date_picker_month.tokens.day_size", "descriptionFallback": "Day cell size (height and width)."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-date-picker__day---background-color-selected", "descriptionKey": "components.date_picker_month.tokens.day_selected_bg", "descriptionFallback": "Selected day background colour."}, {"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-date-picker__day---background-color-in-range", "descriptionKey": "components.date_picker_month.tokens.day_in_range_bg", "descriptionFallback": "Background of cells within a date-range selection."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"280\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <!-- root -->\n  <rect x=\"40\" y=\"20\" width=\"620\" height=\"240\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- week numbers column -->\n  <rect x=\"40\" y=\"20\" width=\"52\" height=\"240\" rx=\"6\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.05))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"66\" y=\"50\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Wk</text>\n  <text x=\"66\" y=\"80\"  font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">22</text>\n  <text x=\"66\" y=\"110\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">23</text>\n  <text x=\"66\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">24</text>\n  <text x=\"66\" y=\"170\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">25</text>\n  <text x=\"66\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">26</text>\n  <!-- days grid -->\n  <rect x=\"96\" y=\"20\" width=\"564\" height=\"240\" rx=\"0\" fill=\"none\"/>\n  <!-- weekday header row -->\n  <rect x=\"96\" y=\"20\" width=\"564\" height=\"36\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\"/>\n  <text x=\"378\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Lu  Ma  Me  Je  Ve  Sa  Di</text>\n  <!-- day cells sample -->\n  <text x=\"378\" y=\"76\"  font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\"> 1   2   3   4   5   6   7</text>\n  <text x=\"378\" y=\"106\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\"> 8   9  10  11  12  13  14</text>\n  <!-- selected day -->\n  <circle cx=\"312\" cy=\"135\" r=\"14\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"312\" y=\"139\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\">15</text>\n  <text x=\"386\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">16  17  18  19  20  21</text>\n  <text x=\"378\" y=\"170\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">22  23  24  25  26  27  28</text>\n  <text x=\"346\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">29  30</text>\n  <!-- adjacent days faded -->\n  <text x=\"430\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #aaa)\" text-anchor=\"middle\" font-family=\"system-ui\" opacity=\"0.5\"> 1   2   3   4</text>\n  <!-- markers -->\n  <circle cx=\"48\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"104\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"104\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"104\" cy=\"56\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"104\" y=\"60.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"312\" cy=\"118\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"312\" y=\"122.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<div class=\"origam-date-picker-month\">\n  <!-- optional week numbers column (showWeek=true) -->\n  <div class=\"origam-date-picker-month__weeks\">\n    <div class=\"origam-date-picker-month__day\">&nbsp;</div>\n    <div class=\"origam-date-picker-month__day origam-date-picker-month__day--adjacent\">\n      <span>22</span>\n    </div>\n    <!-- … -->\n  </div>\n\n  <!-- animated day grid (OrigamTransition wraps the inner div) -->\n  <div class=\"origam-date-picker-month__days\">\n    <!-- weekday headers (hidden when hideWeekdays=true) -->\n    <div class=\"origam-date-picker-month__day origam-date-picker-month__weekday\">\n      <span>Lu</span>\n    </div>\n    <!-- … -->\n\n    <!-- day cell -->\n    <div class=\"origam-date-picker-month__day origam-date-picker-month__day--selected\">\n      <origam-btn\n        class=\"origam-date-picker-month__day-btn\"\n        :active=\"item.isSelected\"\n        :border=\"item.isToday\"\n        icon\n        :text=\"item.localized\"\n      />\n    </div>\n  </div>\n</div>", "legend": [{"cls": ".origam-date-picker-month", "num": 1, "descriptionKey": "components.date_picker_month.anatomy.root", "descriptionFallback": "Root flex container. Display: flex, padding: 0 12px 8px. Hosts the weeks column and the days grid side by side."}, {"cls": ".origam-date-picker-month__weeks", "num": 2, "descriptionKey": "components.date_picker_month.anatomy.weeks", "descriptionFallback": "Optional week-numbers column. Visible when showWeek=true. Uses grid-template-rows: repeat(7, 1fr)."}, {"cls": ".origam-date-picker-month__weekday", "num": 3, "descriptionKey": "components.date_picker_month.anatomy.weekday", "descriptionFallback": "Weekday label cell (Mon, Tue…). Font-size 0.85rem. Hidden when hideWeekdays=true."}, {"cls": ".origam-date-picker-month__day", "num": 4, "descriptionKey": "components.date_picker_month.anatomy.day", "descriptionFallback": "Day cell. 40×40px. Contains the day button. Modifiers: --selected, --today, --adjacent, --hide-adjacent, --week-start, --week-end."}], "classes": [{"cls": "origam-date-picker-month", "descriptionKey": "components.date_picker_month.anatomy.root", "descriptionFallback": "Root flex container."}, {"cls": "origam-date-picker-month__weeks", "descriptionKey": "components.date_picker_month.anatomy.weeks", "descriptionFallback": "Week-numbers column (showWeek=true)."}, {"cls": "origam-date-picker-month__days", "descriptionKey": "components.date_picker_month.anatomy.days", "descriptionFallback": "Day grid — 7-column CSS grid."}, {"cls": "origam-date-picker-month__weekday", "descriptionKey": "components.date_picker_month.anatomy.weekday", "descriptionFallback": "Weekday label header cell."}, {"cls": "origam-date-picker-month__day", "descriptionKey": "components.date_picker_month.anatomy.day", "descriptionFallback": "Day wrapper cell. 40×40px."}, {"cls": "origam-date-picker-month__day--selected", "descriptionKey": "components.date_picker_month.anatomy.day_selected", "descriptionFallback": "Applied when the day is part of the current selection."}, {"cls": "origam-date-picker-month__day--today", "descriptionKey": "components.date_picker_month.anatomy.day_today", "descriptionFallback": "Applied when the day is today. The inner button receives border=true."}, {"cls": "origam-date-picker-month__day--adjacent", "descriptionKey": "components.date_picker_month.anatomy.day_adjacent", "descriptionFallback": "Days from the previous or next month. Opacity 0.5."}, {"cls": "origam-date-picker-month__day--hide-adjacent", "descriptionKey": "components.date_picker_month.anatomy.day_hide_adjacent", "descriptionFallback": "Adjacent days rendered invisible (opacity 0) when showAdjacentMonths=false."}, {"cls": "origam-date-picker-month__day-btn", "descriptionKey": "components.date_picker_month.anatomy.day_btn", "descriptionFallback": "Inner OrigamBtn inside each day cell. Height 24px, font-size 0.85rem."}], "svgDesc": "Schematic of the DatePickerMonth component showing weekday labels, day cells and week numbers column.", "svgTitle": "Anatomy of OrigamDatePickerMonth", "rootClass": "origam-date-picker-month", "figcaption": "Anatomy of <code>&lt;origam-date-picker-month&gt;</code> — 4 parts: ① root wrapper, ② week-numbers column (showWeek), ③ weekday header row, ④ day button cells.", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-date-picker-month-day-diff", "defaultValue": "4px", "descriptionKey": "components.date_picker_month.css_vars.day_diff", "descriptionFallback": "Gap used to offset the range-selection pseudo-element (::before/::after) on selected day cells."}, {"name": "--origam-btn---height", "defaultValue": "24px", "descriptionKey": "components.date_picker_month.css_vars.btn_height", "descriptionFallback": "Height of the inner day button (overridden from the default btn height via :deep selector)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.date_picker_month.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.date_picker_month.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.date_picker_month.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.date_picker_month.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.date_picker_month.exposed.unload", "descriptionFallback": "Removes the injected style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.date_picker_month.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.date_picker_month.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "switch", "prop": "hideWeekdays", "labelKey": "components.date_picker_month.playground.hide_weekdays", "defaultValue": false, "labe