INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e275fdcc-dc97-461c-b1ef-20cad7ae58fb', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'date-picker', 'DatePicker', 'Form & Input', NULL, 'mdi-calendar', 'components.catalog.date_picker.description', 'Calendar popup to select a single date, multiple dates or a range. Supports month and year navigation with animated view transitions.', NULL, NULL, 'origam-date-picker', NULL, 'packages/ds/src/components/DatePicker/OrigamDatePicker.vue', 'origam', NULL, NULL, '/stories/?story=components-datepicker--design', '/docs/components/DatePicker/OrigamDatePicker.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.date_picker.a11y.grid_note", "noteFallback": "The day grid uses role=\"grid\" with role=\"gridcell\" for each day. Disabled days have aria-disabled=\"true\" and are skipped in keyboard navigation."}, {"noteKey": "components.date_picker.a11y.label_note", "noteFallback": "Each day button has an aria-label with the full date string (e.g. \"15 juin 2026\") for screen reader users."}, {"noteKey": "components.date_picker.a11y.reduced_motion_note", "noteFallback": "View-change transitions (OrigamFade) are disabled under prefers-reduced-motion: reduce."}], "roles": ["dialog", "grid", "gridcell", "button"], "keyboard": [{"key": "← / → / ↑ / ↓", "actionKey": "components.date_picker.a11y.key_navigate_days", "actionFallback": "Navigate between day cells within the grid."}, {"key": "Enter / Space", "actionKey": "components.date_picker.a11y.key_select", "actionFallback": "Select the focused day, month or year."}, {"key": "PageUp / PageDown", "actionKey": "components.date_picker.a11y.key_month_nav", "actionFallback": "Move to the previous / next month without leaving the day grid."}, {"key": "Home / End", "actionKey": "components.date_picker.a11y.key_week_edges", "actionFallback": "Jump to the first / last day of the current week row."}, {"key": "Escape", "actionKey": "components.date_picker.a11y.key_close", "actionFallback": "Close the picker (when used inside DatePickerField)."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "40px", "tokenPath": "--origam-date-picker__day---size", "descriptionKey": "components.date_picker.tokens.day_size", "descriptionFallback": "Day button size (width and height)."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-date-picker__day---background-color-selected", "descriptionKey": "components.date_picker.tokens.day_background_color_selected", "descriptionFallback": "Selected day button background."}, {"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-date-picker__day---background-color-in-range", "descriptionKey": "components.date_picker.tokens.day_background_color_in_range", "descriptionFallback": "Days in range background (range mode)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"360\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <rect x=\"200\" y=\"20\" width=\"300\" height=\"320\" rx=\"10\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.1))\" stroke-width=\"1.5\"/>\n  <circle cx=\"216\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"216\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <rect x=\"200\" y=\"20\" width=\"300\" height=\"64\" rx=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <rec