rcle cx=\"282\" cy=\"212\" r=\"14\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"283\" y=\"216\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\">15</text>\n  <text x=\"222\" y=\"215\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">16  17  18  19  20  21</text>\n  <text x=\"219\" y=\"236\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">22  23  24  25  26  27  28</text>\n  <text x=\"219\" y=\"258\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">29  30</text>\n  <rect x=\"200\" y=\"300\" width=\"300\" height=\"40\" rx=\"0\" fill=\"var(--origam-color__surface---sunken, #f9f9f9)\" stroke=\"none\"/>\n  <line x1=\"200\" y1=\"300\" x2=\"500\" y2=\"300\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.1))\" stroke-width=\"1\"/>\n  <circle cx=\"216\" cy=\"320\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"216\" y=\"324.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"420\" y=\"324\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #666)\" font-family=\"system-ui\">Cancel</text>\n  <text x=\"468\" y=\"324\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-family=\"system-ui\" font-weight=\"700\">OK</text>\n", "code": "<origam-picker class=\"origam-date-picker origam-date-picker--month\">\n  <!-- slot: #title -->\n\n  <!-- slot: #header → OrigamDatePickerHeader -->\n  <template #header>\n    <origam-date-picker-header :header=\"selectedDateLabel\" />\n  </template>\n\n  <!-- default slot: controls + animated grid -->\n  <origam-date-picker-controls @click:prev=\"prev\" @click:next=\"next\" @click:month=\"viewMonths\" />\n\n  <origam-fade>\n    <!-- view: month grid -->\n    <origam-date-picker-month v-model:date=\"model\" v-model:month=\"month\" v-model:year=\"year\" />\n\n    <!-- OR view: months -->\n    <origam-date-picker-months v-model:month=\"month\" :year=\"year\" />\n\n    <!-- OR view: years -->\n    <origam-date-picker-years v-model:year=\"year\" />\n  </origam-fade>\n\n  <!-- slot: #actions -->\n  <template #actions>\n    <origam-btn text=\"Cancel\" variant=\"text\" />\n    <origam-btn text=\"OK\" color=\"primary\" />\n  </template>\n</origam-picker>", "legend": [{"cls": ".origam-date-picker", "num": 1, "descriptionKey": "components.date_picker.anatomy.root", "descriptionFallback": "Root element. Fixed width 328px (368px with showWeek). Built on OrigamPicker with overflow:hidden. Modifier --year / --months applied while switching view."}, {"cls": "OrigamDatePickerHeader", "num": 2, "descriptionKey": "components.date_picker.anatomy.header", "descriptionFallback": "Coloured header strip (background from header.background-color token = color.action.primary.bg). Shows the selected date. Hidden via hideHeader prop. Replaced by the #header slot."}, {"cls": "OrigamDatePickerControls", "num": 3, "descriptionKey": "components.date_picker.anatomy.controls", "descriptionFallback": "Navigation bar with prev/next arrow buttons and a text button that toggles between month, months and year views."}, {"cls": "OrigamDatePickerMonth", "num": 4, "descriptionKey": "components.date_picker.anatomy.month", "descriptionFallback": "Day-grid view. Weekday labels row + 6 rows of day buttons. Day cells use day.size (40px) and day.border-radius (full). Animated via OrigamFade when switching views."}, {"cls": "#actions slot", "num": 5, "descriptionKey": "components.date_picker.anatomy.actions", "descriptionFallback": "Optional action buttons row. Use for Cancel / OK confirmation pattern. Only rendered when the #actions slot is provided."}], "classes": [{"cls": "origam-date-picker", "descriptionKey": "components.date_picker.anatomy.root", "descriptionFallback": "Root picker element."}, {"cls": "origam-date-picker--month", "descriptionKey": "components.date_picker.anatomy.month_modifier", "descriptionFallback": "Applied when viewMode=\"month\". Modifier drives CSS transitions on sub-components."}, {"cls": "origam-date-picker--show-week", "descriptionKey": "components.date_picker.anatomy.show_week_modifier", "descriptionFallback": "Applied when showWeek=true. Widens the picker to 368px."}], "svgDesc": "Schematic of the DatePicker component with numbered internal regions.", "svgTitle": "Anatomy of OrigamDatePicker", "rootClass": "origam-date-picker", "figcaption": "Anatomy of <code>&lt;origam-date-picker&gt;</code> — 5 regions: root ①, header strip ②, navigation controls ③, day grid ④, and optional actions ⑤.", "svgViewBox": "0 0 700 360"}, "cssVars": [{"name": "--origam-date-picker---background-color", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.date_picker.css_vars.background_color", "descriptionFallback": "Picker surface background colour."}, {"name": "--origam-date-picker---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.date_picker.css_vars.color", "descriptionFallback": "Picker surface foreground colour."}, {"name": "--origam-date-picker---border-radius", "defaultValue": "{radius.md}", "descriptionKey": "components.date_picker.css_vars.border_radius", "descriptionFallback": "Picker surface border-radius."}, {"name": "--origam-date-picker__header---background-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.date_picker.css_vars.header_background_color", "descriptionFallback": "Header strip background (selected-date display area)."}, {"name": "--origam-date-picker__header---color", "defaultValue": "{color.action.primary.fg}", "descriptionKey": "components.date_picker.css_vars.header_color", "descriptionFallback": "Header strip text colour."}, {"name": "--origam-date-picker__day---size", "defaultValue": "40px", "descriptionKey": "components.date_picker.css_vars.day_size", "descriptionFallback": "Size (width and height) of day buttons in the day grid."}, {"name": "--origam-date-picker__day---border-radius", "defaultValue": "{radius.full}", "descriptionKey": "components.date_picker.css_vars.day_border_radius", "descriptionFallback": "Border-radius of day buttons (full circle by default)."}, {"name": "--origam-date-picker__day---background-color-selected", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.date_picker.css_vars.day_background_color_selected", "descriptionFallback": "Background of the selected day button."}, {"name": "--origam-date-picker__day---background-color-in-range", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.date_picker.css_vars.day_background_color_in_range", "descriptionFallback": "Background of days within a selected date range."}, {"name": "--origam-date-picker__day---color-out-of-month", "defaultValue": "{color.text.disabled}", "descriptionKey": "components.date_picker.css_vars.day_color_out_of_month", "descriptionFallback": "Text colour of days outside the current month."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.date_picker.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.date_picker.exposed.css", "descriptionFallback": "Reactive CSS string for the injected style sheet."}, {"name": "id", "type": "string", "descriptionKey": "components.date_picker.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.date_picker.exposed.load", "descriptionFallback": "Injects the style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.date_picker.exposed.unload", "descriptionFallback": "Removes the style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.date_picker.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.date_picker.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "switch", "prop": "multiple", "labelKey": "components.date_picker.playground.multiple", "defaultValue": false, "labelFallback": "Multiple"}, {"kind": "switch", "prop": "range", "labelKey": "components.date_picker.playground.range", "defaultValue": false, "labelFallback": "Range"}, {"kind": "switch", "prop": "hideHeader", "labelKey": "components.date_picker.playground.hide_header", "defaultValue": false, "labelFallback": "Hide header"}, {"kind": "switch", "prop": "showWeek", "labelKey": "components.date_picker.playground.show_week", "defaultValue": false, "labelFallback": "Show week numbers"}, {"kind": "switch", "prop": "landscape", "labelKey": "components.date_picker.playground.landscape", "defaultValue": false, "labelFallback": "Landscape"}]}, "previewVariants": [{"label": "default", "props": {"color": "primary"}}, {"label": "range", "props": {"color": "primary", "range": true}}, {"label": "no header", "props": {"color": "primary", "hideHeader": true}}, {"label": "landscape", "props": {"color": "primary", "landscape": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4671d982-724c-4ccc-9dfd-6cc4c4f1c75f', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'date-picker-controls', 'DatePickerControls', 'Form & Input', NULL, 'mdi-calendar-arrow-left', 'components.catalog.date_picker_controls.description', 'Navigation toolbar for the DatePicker. Renders a month/year label button, a mode-toggle icon button, and prev/next navigation buttons. Emits discrete click events for each control.', NULL, NULL, 'origam-date-picker-controls', NULL, 'packages/ds/src/components/DatePicker/OrigamDatePickerControls.vue', 'origam', NULL, NULL, NULL, NULL, 'date-picker', '{"a11y": {"notes": [{"noteKey": "components.date_picker_controls.a11y.disabled", "noteFallback": "Disabled controls receive tabindex=\"-1\" via OrigamBtn and are not reachable by keyboard."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.date_picker_controls.a11y.key_tab", "actionFallback": "Moves focus between the five control buttons."}, {"key": "Enter / Space", "actionKey": "components.date_picker_controls.a11y.key_activate", "actionFallback": "Activates the focused button."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f8f5ff)\"/>\n  <rect x=\"8\" y=\"16\" width=\"544\" height=\"48\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.2))\" stroke-width=\"1\"/>\n  <rect x=\"16\" y=\"24\" width=\"160\" height=\"32\" rx=\"2\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.07))\"/>\n  <rect x=\"420\" y=\"24\" width=\"120\" height=\"32\" rx=\"2\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.07))\"/>\n  <circle cx=\"16\" cy=\"16\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"16\" y=\"20\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"80\" cy=\"24\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"80\" y=\"28\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"456\" cy=\"24\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"456\" y=\"28\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div class=\"origam-date-picker-controls\">\n  <!-- left: month label + mode toggle -->\n  <origam-btn-group>\n    <origam-btn class=\"origam-date-picker-controls__month-btn\" />\n    <origam-btn class=\"origam-date-picker-controls__mode-btn\" />\n  </origam-btn-group>\n  <origam-spacer />\n  <!-- right: prev / next -->\n  <div class=\"origam-date-picker-controls__month\">\n    <origam-btn-group>\n      <origam-btn /><!-- prev -->\n      <origam-btn /><!-- next -->\n    </origam-btn-group>\n  </div>\n</div>", "legend": [{"cls": ".origam-date-picker-controls", "num": 1, "descriptionKey": "components.date_picker_controls.anatomy.root", "descriptionFallback": "Root flex container."}, {"cls": ".origam-date-picker-controls__month-btn / .origam-date-picker-controls__mode-btn", "num": 2, "descriptionKey": "components.date_picker_controls.anatomy.left_group", "descriptionFallback": "Left button group: month label button and mode-toggle icon button."}, {"cls": ".origam-date-picker-controls__month", "num": 3, "descriptionKey": "components.date_picker_controls.anatomy.right_group", "descriptionFallback": "Right flex container holding the prev/next navigation button group."}], "classes": [{"cls": "origam-date-picker-controls", "descriptionKey": "components.date_picker_controls.anatomy.root", "descriptionFallback": "Root flex container."}, {"cls": "origam-date-picker-controls__month-btn", "descriptionKey": "components.date_picker_controls.anatomy.month_btn", "descriptionFallback": "Month label text button."}, {"cls": "origam-date-picker-controls__mode-btn", "descriptionKey": "components.date_picker_controls.anatomy.mode_btn", "descriptionFallback": "Mode-toggle icon button."}, {"cls": "origam-date-picker-controls__month", "descriptionKey": "components.date_picker_controls.anatomy.nav_group", "descriptionFallback": "Navigation buttons container."}], "svgDesc": "A flex row with a button group on the left and navigation buttons on the right.", "svgTitle": "Anatomy of OrigamDatePickerControls", "rootClass": "origam-date-picker-controls", "figcaption": "Anatomy of <code>&lt;origam-date-picker-controls&gt;</code> — root flex row ①, left button group (month label + mode toggle) ②, right navigation button group (prev + next) ③.", "svgViewBox": "0 0 560 80"}, "cssVars": [{"name": "--origam-date-picker---controls-color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.date_picker_controls.css_vars.color", "descriptionFallback": "Default text colour of the controls."}, {"name": "--origam-date-picker---controls-color-hover", "defaultValue": "{color.text.primary}", "descriptionKey": "components.date_picker_controls.css_vars.color_hover", "descriptionFallback": "Text colour on hover."}, {"name": "--origam-date-picker---controls-color-disabled", "defaultValue": "{color.text.disabled}", "descriptionKey": "components.date_picker_controls.css_vars.color_disabled", "descriptionFallback": "Text colour when disabled."}], "exposed": [{"name": "filterProps", "type": "(props: IDatePickerControlsProps, exclude?: string[]) => Partial<IDatePickerControlsProps>", "descriptionKey": "components.date_picker_controls.exposed.filter_props", "descriptionFallback": "Filters component props for forwarding."}, {"name": "css", "type": "ComputedRef<string>", "descriptionKey": "components.date_picker_controls.exposed.css", "descriptionFallback": "Serialised scoped CSS string."}, {"name": "id", "type": "string", "descriptionKey": "components.date_picker_controls.exposed.id", "descriptionFallback": "Unique style scope identifier."}, {"name": "load", "type": "() => void", "descriptionKey": "components.date_picker_controls.exposed.load", "descriptionFallback": "Mounts the scoped style sheet."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.date_picker_controls.exposed.unload", "descriptionFallback": "Unmounts the scoped style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.date_picker_controls.exposed.is_loaded", "descriptionFallback": "Whether the scoped style sheet is currently mounted."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.date_picker_controls.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "text", "prop": "text", "labelKey": "components.date_picker_controls.playground.text", "defaultValue": "", "labelFallback": "Text"}, {"kind": "select", "prop": "viewMode", "options": [{"label": "(default)", "value": ""}, {"label": "month", "value": "month"}, {"label": "DATE_MODE.MONTH", "value": "DATE_MODE.MONTH"}, {"label": "months", "value": "months"}, {"label": "DATE_MODE.MONTHS", "value": "DATE_MODE.MONTHS"}, {"label": "years", "value": "years"}, {"label": "DATE_MODE.YEARS", "value": "DATE_MODE.YEARS"}], "labelKey": "components.date_picker_controls.playground.view_mode", "defaultValue": "", "labelFallback": "View Mode"}, {"kind": "select", "prop": "nextIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-check", "value": "mdi-check"}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-close", "value": "mdi-close"}], "labelKey": "components.date_picker_controls.playground.next_icon", "defaultValue": "", "labelFallback": "Next Icon"}, {"kind": "select", "prop": "prevIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-check", "value": "mdi-check"}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-close", "value": "mdi-close"}], "labelKey": "components.date_picker_controls.playground.prev_icon", "defaultValue": "", "labelFallback": "Prev Icon"}, {"kind": "select", "prop": "modeIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-check", "value": "mdi-check"}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-close", "value": "mdi-close"}], "labelKey": "components.date_picker_controls.playground.mode_icon", "defaultValue": "", "labelFallback": "Mode Icon"}, {"kind": "switch", "prop": "disabledMonth", "labelKey": "components.date_picker_controls.playground.disabled_month", "defaultValue": false, "labelFallback": "Disabled Month"}, {"kind": "switch", "prop": "disabledYear", "labelKey": "components.date_picker_controls.playground.disabled_year", "defaultValue": false, "labelFallback": "Disabled Year"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('199ee0f3-7687-44b8-9f12-8e16c5811c4e', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'date-picker-field', 'DatePickerField', 'Form & Input', NULL, 'mdi-calendar-edit', 'components.catalog.date_picker_field.description', 'Text field with a built-in calendar dropdown. Combines OrigamTextField and OrigamDatePicker into a single form control with chip display for multiple/range selections.', NULL, NULL, 'origam-date-picker-field', NULL, 'packages/ds/src/components/DatePickerField/OrigamDatePickerField.vue', 'origam', NULL, NULL, '/stories/?story=components-datepickerfield--design', '/docs/components/DatePickerField/OrigamDatePickerField.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.date_picker_field.a11y.aria_haspopup_note", "noteFallback": "The field sets aria-haspopup=\"datepickerbox\" on the inner input to signal that activating it opens a date picker. The calendar dropdown uses role=\"dialog\" with aria-modal=\"true\" when open."}, {"noteKey": "components.date_picker_field.a11y.label_note", "noteFallback": "The field must have a label (via the label prop or an external aria-label). Without a label, the calendar toggle icon is not accessible."}, {"noteKey": "components.date_picker_field.a11y.chip_note", "noteFallback": "In multiple/range mode, each chip has aria-label with the formatted date. Closable chips have an aria-label on the close button (\"Remove date X\")."}], "roles": ["combobox", "dialog"], "keyboard": [{"key": "Enter / Space (on field)", "actionKey": "components.date_picker_field.a11y.key_open", "actionFallback": "Opens the calendar dropdown."}, {"key": "Escape", "actionKey": "components.date_picker_field.a11y.key_close", "actionFallback": "Closes the calendar dropdown and returns focus to the field."}, {"key": "Tab", "actionKey": "components.date_picker_field.a11y.key_tab", "actionFallback": "Moves focus between the field, calendar navigation and days."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"240\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <rect x=\"60\" y=\"30\" width=\"580\" height=\"54\" rx=\"8\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(0,0,0,0.3))\" stroke-width=\"1.5\"/>\n  <circle cx=\"76\" cy=\"38\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"76\" y=\"42.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <text x=\"78\" y=\"54\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-date-picker-field</text>\n  <text x=\"80\" y=\"66\" font-size=\"12\" fill=\"var(--origam-color__text---disabled, #aaa)\" font-family=\"system-ui\">DD / MM / YYYY</text>\n  <circle cx=\"620\" cy=\"57\" r=\"14\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"none\"/>\n  <text x=\"620\" y=\"61\" font-size=\"16\" fill=\"var(--origam-color__text---secondary, #888)\" text-anchor=\"middle\">📅</text>\n  <circle cx=\"636\" cy=\"42\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"636\" y=\"46.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <rect x=\"60\" y=\"100\" width=\"580\" height=\"130\" rx=\"10\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.1))\" stroke-width=\"1.5\"/>\n  <circle cx=\"76\" cy=\"108\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"76\" y=\"112.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"350\" y=\"145\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #888)\" text-anchor=\"middle\" font-family=\"system-ui\">OrigamDatePicker</text>\n  <text x=\"350\" y=\"168\" font-size=\"10\" fill=\"var(--origam-color__text---disabled, #bbb)\" text-anchor=\"middle\" font-family=\"system-ui\">(calendar grid)</text>\n  <text x=\"350\" y=\"220\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b0b0b0)\" text-anchor=\"middle\" font-style=\"italic\">① = text-field chrome. ② = appendInner calendar icon. ③ = DatePicker dropdown (OrigamMenu).</text>\n", "code": "<!-- DatePickerField = TextField chrome + Menu + DatePicker -->\n<origam-text-field class=\"origam-date-picker-field\" :aria-label=\"label\">\n\n  <!-- #prepend, #prependInner, #label, #prefix slots passthrough -->\n\n  <!-- selected dates as text or chips -->\n  <span class=\"origam-date-picker-field__selection-text\">\n    {{ formattedDates }}\n  </span>\n  <!-- OR chips in multiple/range mode -->\n  <origam-chip\n    v-for=\"date in selectedDates\"\n    :closable=\"closableChips\"\n    v-bind=\"chipProps\"\n  />\n\n  <!-- #suffix, #clear slots passthrough -->\n\n  <!-- calendar toggle icon -->\n  <template #appendInner>\n    <origam-icon icon=\"mdi-calendar\" />\n  </template>\n\n  <!-- #append slot passthrough -->\n\n  <!-- floating DatePicker -->\n  <origam-menu\n    v-model=\"menu\"\n    content-class=\"origam-date-picker-field__content\"\n  >\n    <origam-date-picker v-model=\"model\" />\n  </origam-menu>\n</origam-text-field>", "legend": [{"cls": ".origam-date-picker-field (TextField root)", "num": 1, "descriptionKey": "components.date_picker_field.anatomy.field", "descriptionFallback": "TextField chrome — label, border, density, variant. The selected date(s) appear as formatted text or chips inside the control area. Extends all ITextFieldProps."}, {"cls": "appendInner — calendar toggle icon", "num": 2, "descriptionKey": "components.date_picker_field.anatomy.toggle_icon", "descriptionFallback": "Calendar icon rendered in the appendInner slot by default (mdi-calendar). Clicking it toggles the menu open/closed. aria-label comes from openText/closeText props."}, {"cls": "OrigamMenu + OrigamDatePicker", "num": 3, "descriptionKey": "components.date_picker_field.anatomy.menu", "descriptionFallback": "Floating menu (OrigamMenu) containing the full OrigamDatePicker. Positioned below the field with an offset from --origam-date-picker-field---menu-offset. Content class: origam-date-picker-field__content."}], "classes": [{"cls": "origam-date-picker-field", "descriptionKey": "components.date_picker_field.anatomy.root", "descriptionFallback": "Root — extends TextField BEM classes."}, {"cls": "origam-date-picker-field__selection-text", "descriptionKey": "components.date_picker_field.anatomy.selection_text", "descriptionFallback": "Formatted date text displayed in the field when mode is single."}, {"cls": "origam-date-picker-field__selection-chips", "descriptionKey": "components.date_picker_field.anatomy.selection_chips", "descriptionFallback": "Chip container in multiple/range mode."}, {"cls": "origam-date-picker-field__content", "descriptionKey": "components.date_picker_field.anatomy.content", "descriptionFallback": "Menu content class applied to the OrigamMenu teleport target."}], "svgDesc": "Schematic of the DatePickerField component with numbered internal parts.", "svgTitle": "Anatomy of OrigamDatePickerField", "rootClass": "origam-date-picker-field", "figcaption": "Anatomy of <code>&lt;origam-date-picker-field&gt;</code>. The component combines an <code>OrigamTextField</code> chrome ① with a calendar toggle icon ② that opens an <code>OrigamMenu</code> containing <code>OrigamDatePicker</code> ③.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-date-picker-field---min-width", "defaultValue": "200px", "descriptionKey": "components.date_picker_field.css_vars.min_width", "descriptionFallback": "Minimum field width."}, {"name": "--origam-date-picker-field---max-width", "defaultValue": "320px", "descriptionKey": "components.date_picker_field.css_vars.max_width", "descriptionFallback": "Maximum field width."}, {"name": "--origam-date-picker-field---menu-offset", "defaultValue": "{space.1}", "descriptionKey": "components.date_picker_field.css_vars.menu_offset", "descriptionFallback": "Vertical gap between the field bottom and the calendar dropdown."}, {"name": "--origam-date-picker-field__icon---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.date_picker_field.css_vars.icon_color", "descriptionFallback": "Default colour of the calendar toggle icon."}, {"name": "--origam-date-picker-field__icon---color-hover", "defaultValue": "{color.text.primary}", "descriptionKey": "components.date_picker_field.css_vars.icon_color_hover", "descriptionFallback": "Icon colour on hover."}, {"name": "--origam-date-picker-field__icon---color-error", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.date_picker_field.css_vars.icon_color_error", "descriptionFallback": "Icon colour in error state."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.date_picker_field.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "isFocused", "type": "Ref<boolean>", "descriptionKey": "components.date_picker_field.exposed.is_focused", "descriptionFallback": "Whether the field is currently focused."}, {"name": "menu", "type": "Ref<boolean>", "descriptionKey": "components.date_picker_field.exposed.menu", "descriptionFallback": "Whether the calendar dropdown is currently open."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.date_picker_field.exposed.css", "descriptionFallback": "Reactive CSS string for the injected style sheet."}, {"name": "id", "type": "string", "descriptionKey": "components.date_picker_field.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.date_picker_field.exposed.load", "descriptionFallback": "Injects the style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.date_picker_field.exposed.unload", "descriptionFallback": "Removes the style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.date_picker_field.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "variant", "options": [{"label": "outlined", "value": "outlined"}, {"label": "filled", "value": "filled"}, {"label": "underlined", "value": "underlined"}, {"label": "solo", "value": "solo"}, {"label": "solo-filled", "value": "solo-filled"}], "labelKey": "components.date_picker_field.playground.variant", "defaultValue": "outlined", "labelFallback": "Variant"}, {"kind": "select", "prop": "color", "options": [{"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.date_picker_field.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "select", "prop": "density", "options": [{"label": "default", "value": "default"}, {"label": "comfortable", "value": "comfortable"}, {"label": "compact", "value": "compact"}], "labelKey": "components.date_picker_field.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "switch", "prop": "range", "labelKey": "components.date_picker_field.playground.range", "defaultValue": false, "labelFallback": "Range mode"}, {"kind": "switch", "prop": "multiple", 