INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('59622e01-1293-47a6-b46a-3165aff7fbfe', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'expansion-panel-header', 'ExpansionPanelHeader', 'Layout & Structure', NULL, 'mdi-chevron-down-box', 'components.catalog.expansion_panel_header.description', 'Clickable header button with expand/collapse icon, prepend/append slots and ripple support. Carries aria-expanded and aria-controls.', NULL, NULL, 'origam-expansion-panel-header', NULL, 'packages/ds/src/components/ExpansionPanel/OrigamExpansionPanelHeader.vue', 'origam', NULL, NULL, '/stories/?story=components-expansionpanel--design', '/docs/components/ExpansionPanel/OrigamExpansionPanel.html', 'expansion-panel', '{"a11y": {"notes": [{"noteKey": "components.expansion_panel_header.a11y.aria_expanded", "noteFallback": "The header button carries aria-expanded=\"true|false\" reflecting the current panel selection state."}, {"noteKey": "components.expansion_panel_header.a11y.aria_controls", "noteFallback": "The header button carries aria-controls pointing to the content region ID (expansion-panel-content-{id})."}, {"noteKey": "components.expansion_panel_header.a11y.disabled", "noteFallback": "Disabled panels apply tabindex=\"-1\" and the disabled HTML attribute to the header button. Pointer events are removed."}, {"noteKey": "components.expansion_panel_header.a11y.readonly", "noteFallback": "When readonly is true, clicks are intercepted but not propagated — the button remains focusable and receives keyboard events without toggling."}, {"noteKey": "components.expansion_panel_header.a11y.ripple", "noteFallback": "The ripple directive provides a visual affordance for click interactions that supplements focus-visible styling."}], "roles": ["button"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.expansion_panel_header.a11y.key_activate", "actionFallback": "Toggles the parent panel expanded/collapsed when focus is on the header button."}, {"key": "Tab", "actionKey": "components.expansion_panel_header.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "0.9375rem", "tokenPath": "--origam-expansion-panel__header---font-size", "descriptionKey": "components.expansion_panel_header.tokens.font_size", "descriptionFallback": "Header title font size (15px)."}, {"type": "dimension", "value": "48px", "tokenPath": "--origam-expansion-panel__header---min-height", "descriptionKey": "components.expansion_panel_header.tokens.min_height", "descriptionFallback": "Header minimum height at rest."}, {"type": "dimension", "value": "64px", "tokenPath": "--origam-expansion-panel__header---min-height-active", "descriptionKey": "components.expansion_panel_header.tokens.min_height_active", "descriptionFallback": "Header minimum height when panel is expanded."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-expansion-panel__header__wrapper---padding-block", "descriptionKey": "components.expansion_panel_header.tokens.wrapper_padding_block", "descriptionFallback": "Top and bottom padding of the wrapper row (16px)."}, {"type": "dimension", "value": "var(--origam-space---6)", "tokenPath": "--origam-expansion-panel__header__wrapper---padding-inline", "descriptionKey": "components.expansion_panel_header.tokens.wrapper_padding_inline", "descriptionFallback": "Leading and trailing padding of the wrapper row (24px)."}, {"type": "number", "value": "var(--origam-opacity---0)", "tokenPath": "--origam-expansion-panel__header---hover-overlay-opacity", "descriptionKey": "components.expansion_panel_header.tokens.hover_overlay_opacity", "descriptionFallback": "Base overlay opacity on hover (resolved via scoped style to 0.04)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"16\" width=\"644\" height=\"148\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"50\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">.origam-expansion-panel-header (button)</text>\n  <rect x=\"40\" y=\"20\" width=\"640\" height=\"140\" rx=\"3\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"68\" y=\"108\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">__overlay</text>\n  <rect x=\"56\" y=\"72\" width=\"80\" height=\"64\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"68\" y=\"112\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">__prepend</text>\n  <rect x=\"148\" y=\"72\" width=\"300\" height=\"64\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"250\" y=\"108\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__title (__wrapper)