r\">\n    <span class=\"origam-expansion-panel-header__prepend\"><!-- prepend slot / icon --></span>\n    <span class=\"origam-expansion-panel-header__title\"><!-- default slot / title --></span>\n    <span class=\"origam-expansion-panel-header__append\">\n      <!-- append slot / icon -->\n      <!-- expand / collapse icon -->\n    </span>\n  </div>\n</button>", "legend": [{"cls": ".origam-expansion-panel-header", "num": 1, "descriptionKey": "components.expansion_panel_header.anatomy.root", "descriptionFallback": "Root button element. Carries aria-expanded, aria-controls, tabindex and the ripple directive."}, {"cls": ".origam-expansion-panel-header__overlay", "num": 2, "descriptionKey": "components.expansion_panel_header.anatomy.overlay", "descriptionFallback": "Absolutely positioned overlay for hover/focus state painting. Opacity is 0 at rest, increases on hover and focus-visible."}, {"cls": ".origam-expansion-panel-header__prepend", "num": 3, "descriptionKey": "components.expansion_panel_header.anatomy.prepend", "descriptionFallback": "Leading area hosting prependAvatar or prependIcon. Emits click:prepend when clicked."}, {"cls": ".origam-expansion-panel-header__title", "num": 4, "descriptionKey": "components.expansion_panel_header.anatomy.title", "descriptionFallback": "Title text span. Hosts the default slot or the title prop value."}, {"cls": ".origam-expansion-panel-header__append", "num": 5, "descriptionKey": "components.expansion_panel_header.anatomy.append", "descriptionFallback": "Trailing area hosting appendAvatar, appendIcon, and the expand/collapse icon. Emits click:append when clicked."}], "classes": [{"cls": "origam-expansion-panel-header", "descriptionKey": "components.expansion_panel_header.anatomy.root", "descriptionFallback": "Root button element."}, {"cls": "origam-expansion-panel-header--active", "descriptionKey": "components.expansion_panel_header.anatomy.active", "descriptionFallback": "Applied when the parent panel is expanded."}, {"cls": "origam-expansion-panel-header--focusable", "descriptionKey": "components.expansion_panel_header.anatomy.focusable", "descriptionFallback": "Applied when focusable=true. Enhances overlay opacity when active and focused."}, {"cls": "origam-expansion-panel-header--static", "descriptionKey": "components.expansion_panel_header.anatomy.static", "descriptionFallback": "Applied when static=true. Header is rendered without toggle behaviour."}, {"cls": "origam-expansion-panel-header__overlay", "descriptionKey": "components.expansion_panel_header.anatomy.overlay", "descriptionFallback": "Absolutely positioned state overlay."}, {"cls": "origam-expansion-panel-header__wrapper", "descriptionKey": "components.expansion_panel_header.anatomy.wrapper", "descriptionFallback": "Inner flex row containing prepend, title and append."}, {"cls": "origam-expansion-panel-header__prepend", "descriptionKey": "components.expansion_panel_header.anatomy.prepend", "descriptionFallback": "Leading slot area."}, {"cls": "origam-expansion-panel-header__title", "descriptionKey": "components.expansion_panel_header.anatomy.title", "descriptionFallback": "Title text span."}, {"cls": "origam-expansion-panel-header__append", "descriptionKey": "components.expansion_panel_header.anatomy.append", "descriptionFallback": "Trailing slot area with expand/collapse icon."}], "svgDesc": "Schematic of the ExpansionPanelHeader component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamExpansionPanelHeader", "rootClass": "origam-expansion-panel-header", "figcaption": "Anatomy of <code>&lt;origam-expansion-panel-header&gt;</code> — 5 internal parts. Root ① is rendered as a <code>&lt;button&gt;</code> with <code>aria-expanded</code> and <code>aria-controls</code>. The overlay ② covers the entire button for hover/focus state painting.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-expansion-panel__header---font-size", "defaultValue": "0.9375rem", "descriptionKey": "components.expansion_panel_header.css_vars.font_size", "descriptionFallback": "Font size of the header title text (15px)."}, {"name": "--origam-expansion-panel__header---font-weight", "defaultValue": "{font.weight.regular}", "descriptionKey": "components.expansion_panel_header.css_vars.font_weight", "descriptionFallback": "Font weight of the header title text."}, {"name": "--origam-expansion-panel__header---line-height", "defaultValue": "1", "descriptionKey": "components.expansion_panel_header.css_vars.line_height", "descriptionFallback": "Line height of the header button."}, {"name": "--origam-expansion-panel__header---min-height", "defaultValue": "48px", "descriptionKey": "components.expansion_panel_header.css_vars.min_height", "descriptionFallback": "Minimum height of the header at rest."}, {"name": "--origam-expansion-panel__header---border-radius", "defaultValue": "inherit", "descriptionKey": "components.expansion_panel_header.css_vars.border_radius", "descriptionFallback": "Border-radius inherited from the parent panel."}, {"name": "--origam-expansion-panel__header__wrapper---padding-block", "defaultValue": "16px ({space.4})", "descriptionKey": "components.expansion_panel_header.css_vars.wrapper_padding_block", "descriptionFallback": "Top and bottom padding of the inner wrapper row."}, {"name": "--origam-expansion-panel__header__wrapper---padding-inline", "defaultValue": "24px ({space.6})", "descriptionKey": "components.expansion_panel_header.css_vars.wrapper_padding_inline", "descriptionFallback": "Leading and trailing padding of the inner wrapper row."}, {"name": "--origam-expansion-panel__header__overlay---opacity", "defaultValue": "0", "descriptionKey": "components.expansion_panel_header.css_vars.overlay_opacity", "descriptionFallback": "Base opacity of the state overlay. Increases to ~0.04 on hover and ~0.12 on focus-visible."}, {"name": "--origam-expansion-panel__header---focus-overlay-opacity", "defaultValue": "calc(0.12 * 1)", "descriptionKey": "components.expansion_panel_header.css_vars.focus_overlay_opacity", "descriptionFallback": "Overlay opacity when the header is focused (focus-visible)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.expansion_panel_header.exposed.filter_props", "descriptionFallback": "Filters and forwards a subset of props to sub-components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.expansion_panel_header.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.expansion_panel_header.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.expansion_panel_header.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.expansion_panel_header.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.expansion_panel_header.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.expansion_panel_header.playground.title", "defaultValue": "Panel header", "labelFallback": "Title"}, {"kind": "select", "prop": "expandIcon", "options": [{"label": "chevron-down", "value": "mdi-chevron-down"}, {"label": "plus", "value": "mdi-plus"}, {"label": "arrow-down", "value": "mdi-arrow-down"}], "labelKey": "components.expansion_panel_header.playground.expand_icon", "defaultValue": "mdi-chevron-down", "labelFallback": "Expand icon"}, {"kind": "switch", "prop": "hideActions", "labelKey": "components.expansion_panel_header.playground.hide_actions", "defaultValue": false, "labelFallback": "Hide actions"}, {"kind": "switc