ack": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "lines", "options": [{"label": "one", "value": "one"}, {"label": "two", "value": "two"}, {"label": "three", "value": "three"}], "labelKey": "components.list.playground.lines", "defaultValue": "one", "labelFallback": "Lines"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}], "labelKey": "components.list.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "switch", "prop": "nav", "labelKey": "components.list.playground.nav", "defaultValue": false, "labelFallback": "Nav mode"}, {"kind": "switch", "prop": "slim", "labelKey": "components.list.playground.slim", "defaultValue": false, "labelFallback": "Slim"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.list.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "select", "prop": "density", "options": [{"label": "default", "value": "default"}, {"label": "compact", "value": "compact"}], "labelKey": "components.list.playground.density", "defaultValue": "default", "labelFallback": "Density"}], "defaultSlotContent": ""}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('05ef7360-a2f9-41d4-8792-20c192a6aba6', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'expansion-panels', 'ExpansionPanels', 'Layout & Structure', NULL, 'mdi-view-list-outline', 'components.catalog.expansion_panels.description', 'Container managing a group of ExpansionPanel items. Supports accordion, flat, popout and inset display modes. Props cascade to all child panels via DefaultsProvider.', NULL, NULL, 'origam-expansion-panels', NULL, 'packages/ds/src/components/ExpansionPanel/OrigamExpansionPanels.vue', 'origam', NULL, NULL, '/stories/?story=components-expansionpanel--design', '/docs/components/ExpansionPanel/OrigamExpansionPanel.html', 'expansion-panel', '{"a11y": {"notes": [{"noteKey": "components.expansion_panels.a11y.group_management", "noteFallback": "The container manages group selection state and propagates it to child panels via inject/provide. Each panel header receives aria-expanded and aria-controls independently."}, {"noteKey": "components.expansion_panels.a11y.cascade", "noteFallback": "Visual props (density, color, bgColor, rounded, border) are cascaded via OrigamDefaultsProvider so all child panels share the same visual treatment without per-panel repetition."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.expansion_panels.a11y.key_tab", "actionFallback": "Moves focus between panel headers in sequence."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "calc(100% - 32px)", "tokenPath": "--origam-expansion-panel__popout---max-width", "descriptionKey": "components.expansion_panels.tokens.popout_max_width", "descriptionFallback": "Inactive panel width in popout mode."}, {"type": "dimension", "value": "calc(100% + 16px)", "tokenPath": "--origam-expansion-panel__popout---max-width-active", "descriptionKey": "components.expansion_panels.tokens.popout_max_width_active", "descriptionFallback": "Active panel width in popout mode."}, {"type": "dimension", "value": "calc(100% - 32px)", "tokenPath": "--origam-expansion-panel__inset---max-width-active", "descriptionKey": "components.expansion_panels.tokens.inset_max_width_active", "descriptionFallback": "Active panel width in inset mode."}, {"type": "duration", "value": "var(--origam-motion__duration---slow)", "tokenPath": "--origam-expansion-panel__accordion---header-overlay-transition", "descriptionKey": "components.expansion_panels.tokens.accordion_header_overlay_transition", "descriptionFallback": "Transition duration for border-radius animation in accordion header overlay."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"16\" y=\"16\" width=\"668\" height=\"188\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"44\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">.origam-expansion-panels</text>\n  <rect x=\"32\" y=\"56\" width=\"636\" height=\"60\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"90\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-expansion-panel ① (slot item 0)</text>\n  <rect x=\"32\" y=\"128\" width=\"636\" height=\"60\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"162\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-expansion-panel ② (slot item 1)</text>\n  <circle cx=\"24\" cy=\"24\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"24\" y=\"28\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"40\" cy=\"64\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"40\" y=\"68\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<div class=\"origam-expansion-panels origam-expansion-panels--accordion\">\n  <!-- DefaultsProvider cascades density, color, bgColor, rounded, border -->\n  <origam-expansion-panel title=\"Section 1\">...</origam-expansion-panel>\n  <origam-expansion-panel title=\"Section 2\">...</origam-expansion-panel>\n</div>", "legend": [{"cls": ".origam-expansion-panels", "num": 1, "descriptionKey": "components.expansion_panels.anatomy.root", "descriptionFallback": "Root flex container. Wraps all panels. Mode modifier classes (--accordion, --flat, --popout, --inset) control layout and border-radius of children."}, {"cls": ".origam-expansion-panel (child)", "num": 2, "descriptionKey": "components.expansion_panels.anatomy.panel_child", "descriptionFallback": "Each OrigamExpansionPanel child. Border-radius is managed by the parent''s CSS selectors (:first-child, :last-child) for mode-specific shapes."}], "classes": [{"cls": "origam-expansion-panels", "descriptionKey": "components.expansion_panels.anatomy.root", "descriptionFallback": "Root container element."}, {"cls": "origam-expansion-panels--accordion", "descriptionKey": "components.expansion_panels.anatomy.accordion", "descriptionFallback": "Accordion mode: panels are flush, one open at a time."}, {"cls": "origam-expansion-panels--flat", "descriptionKey": "components.expansion_panels.anatomy.flat", "descriptionFallback": "Flat mode: no shadow, no border separator."}, {"cls": "origam-expansion-panels--popout", "descriptionKey": "components.expansion_panels.anatomy.popout", "descriptionFallback": "Popout mode: active panel extends beyond container width."}, {"cls": "origam-expansion-panels--inset", "descriptionKey": "components.expansion_panels.anatomy.inset", "descriptionFallback": "Inset mode: active panel shrinks inside container width."}], "svgDesc": "Schematic of the ExpansionPanels container with 3 numbered internal parts.", "svgTitle": "Anatomy of OrigamExpansionPanels", "rootClass": "origam-expansion-panels", "figcaption": "Anatomy of <code>&lt;origam-expansion-panels&gt;</code>. The root ① is a flex container wrapping all child panels ②. Mode modifiers (accordion, flat, popout, inset) are applied as root class modifiers.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-expansion-panel__popout---max-width", "defaultValue": "calc(100% - 32px)", "descriptionKey": "components.expansion_panels.css_vars.popout_max_width", "descriptionFallback": "Width of inactive panels in popout mode."}, {"name": "--origam-expansion-panel__popout---max-width-active", "defaultValue": "calc(100% + 16px)", "descriptionKey": "components.expansion_panels.css_vars.popout_max_width_active", "descriptionFallback": "Width of the active panel in popout mode."}, {"name": "--origam-expansion-panel__inset---max-width", "defaultValue": "100%", "descriptionKey": "components.expansion_panels.css_vars.inset_max_width", "descriptionFallback": "Width of inactive panels in inset mode."}, {"name": "--origam-expansion-panel__inset---max-width-active", "defaultValue": "calc(100% - 32px)", "descriptionKey": "components.expansion_panels.css_vars.inset_max_width_active", "descriptionFallback": "Width of the active panel in inset mode."}, {"name": "--origam-expansion-panel__accordion---header-overlay-transition", "defaultValue": "{motion.duration.slow} (0.3s)", "descriptionKey": "components.expansion_panels.css_vars.accordion_header_overlay_transition", "descriptionFallback": "Transition duration for the header overlay border-radius animation in accordion mode."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.expansion_panels.exposed.filter_props", "descriptionFallback": "Filters and forwards a subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.expansion_panels.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.expansion_panels.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.expansion_panels.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.expansion_panels.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.expansion_panels.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "switch", "prop": "accordion", "labelKey": "components.expansion_panels.playground.accordion", "defaultValue": false, "labelFallback": "Accordion"}, {"kind": "switch", "prop": "flat", "labelKey": "components.expansion_panels.playground.flat", "defaultValue": false, "labelFallback": "Flat"}, {"kind": "switch", "prop": "popout", "labelKey": "components.expansion_panels.playground.popout", "defaultValue": false, "labelFallback": "Popout"}, {"kind": "switch", "prop": "inset", "labelKey": "components.expansion_panels.playground.inset", "defaultValue": false, "labelFallback": "Inset"}, {"kind": "switch", "prop": "multiple", "labelKey": "components.expansion_panels.playground.multiple", "defaultValue": false, "labelFallback": "Multiple"}, {"kind": "select", "prop": "color", "options": [{"label": "(default)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}], "labelKey": "components.expansion_panels.playground.color", "defaultValue": "", "labelFallback": "Color"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('06697339-167e-45b9-a904-386037672102', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'fade', 'Fade', 'Utilities & Providers', NULL, 'mdi-transition', 'components.catalog.fade.description', 'Opacity-only enter/leave CSS transition. A thin wrapper around the generic Transition that sets name="origam-transition--fade".', NULL, NULL, 'origam-fade', NULL, 'packages/ds/src/components/Transition/OrigamFade.vue', 'origam', NULL, NULL, '/stories/?story=components-transition--design', '/docs/components/Transition/OrigamTransition.html', 'transition', '{"a11y": {"notes": [{"noteKey": "components.fade.a11y.reduced_motion", "noteFallback": "useCssTransition automatically sets disabled=true when prefers-reduced-motion: reduce is detected. Content appears/disappears instantly with no opacity animation."}, {"noteKey": "components.fade.a11y.transparent", "noteFallback": "The transition wrapper adds no elements to the DOM — it is transparent to the accessibility tree. Only the slotted content is announced by screen readers."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"40\" width=\"260\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"170\" y=\"75\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">enter-active</text>\n  <text x=\"170\" y=\"91\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">opacity: 0 → 1</text>\n  <rect x=\"400\" y=\"40\" width=\"260\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"5 3\" opacity=\"0.45\"/>\n  <text x=\"530\" y=\"75\" font-size=\"11\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">leave-active</text>\n  <text x=\"530\" y=\"91\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">opacity: 1 → 0</text>\n  <circle cx=\"48\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"408\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"408\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"80\" font-size=\"20\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">→</text>\n", "code": "<component :is=\"tag\" :name=\"name\" v-bind=\"transitionProps\">\n  <slot name=\"default\" />\n</component>", "legend": [{"cls": ".origam-transition--fade-enter-active", "num": 1, "descriptionKey": "components.fade.anatomy.enter", "descriptionFallback": "Applied to the entering element. Sets transition-property: opacity, duration: 0.3s, easing: cubic-bezier(0.4, 0, 0.2, 1)."}, {"cls": ".origam-transition--fade-leave-active", "num": 2, "descriptionKey": "components.fade.anatomy.leave", "descriptionFallback": "Applied to the leaving element. Same duration and easing. Opacity animates from 1 to 0 via .origam-transition--fade-leave-to."}], "classes": [{"cls": "origam-transition--fade", "descriptionKey": "components.fade.anatomy.cls_root", "descriptionFallback": "Transition name used as the CSS class prefix for enter/leave phases."}, {"cls": "origam-transition--fade-enter-active", "descriptionKey": "components.fade.anatomy.cls_enter_active", "descriptionFallback": "Active entering phase: transition-property: opacity; duration: 0.3s."}, {"cls": "origam-transition--fade-leave-active", "descriptionKey": "components.fade.anatomy.cls_leave_active", "descriptionFallback": "Active leaving phase: same timing as enter."}, {"cls": "origam-transition--fade-enter-from", "descriptionKey": "components.fade.anatomy.cls_enter_from", "descriptionFallback": "Initial state of the entering element: opacity: 0."}, {"cls": "origam-transition--fade-leave-to", "descriptionKey": "components.fade.anatomy.cls_leave_to", "descriptionFallback": "Final state of the leaving element: opacity: 0."}, {"cls": "origam-transition--fade-move", "descriptionKey": "components.fade.anatomy.cls_move", "descriptionFallback": "Applied to sibling elements that shift position when group=true. Animates transform over 0.5s."}], "svgDesc": "Schematic showing the fade transition: an entering element at full opacity and a leaving element at opacity 0.", "svgTitle": "Anatomy of OrigamFade", "rootClass": "origam-transition--fade", "figcaption": "Anatomy of <code>&lt;origam-fade&gt;</code> — wraps a single child. During the transition, the entering element ① fades from <code>opacity: 0</code> to <code>1</code> while the leaving element ② fades from <code>1</code> to <code>0</code> over 300 ms.", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-transition---default-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.fade.css_vars.duration", "descriptionFallback": "Fade enter/leave duration (300 ms). Hardcoded in the SCSS block as 0.3s; override via the token rebuild."}, {"name": "--origam-transition---default-easing", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.fade.css_vars.easing", "descriptionFallback": "Easing function for both enter and leave phases: cubic-bezier(0.4, 0, 0.2, 1)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.fade.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to the underlying transition element."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.fade.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "select", "prop": "mode", "options": [{"label": "(default)", "value": ""}, {"label": "TRANSITION_MODE.IN_OUT", "value": "TRANSITION_MODE.IN_OUT"}, {"label": "in-out", "value": "in-out"}, {"label": "TRANSITION_MODE.OUT_IN", "value": "TRANSITION_MODE.OUT_IN"}, {"label": "out-in", "value": "out-in"}, {"label": "TRANSITION_MODE.DEFAULT", "value": "TRANSITION_MODE.DEFAULT"}, {"label": "default", "value": "default"}], "labelKey": "components.fade.playground.mode", "defaultValue": "", "labelFallback": "Mode"}, {"kind": "switch", "prop": "group", "labelKey": "components.fade.playground.group", "defaultValue": false, "labelFallback": "Group"}, {"kind": "switch", "prop": "hideOnLeave", "labelKey": "components.fade.playground.hide_on_leave", "defaultValue": false, "labelFallback": "Hide On Leave"}, {"kind": "switch", "prop": "leaveAbsolute", "labelKey": "components.fade.playground.leave_absolute", "defaultValue": false, "labelFallback": "Leave Absolute"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('5a8c5db0-85cf-4e18-b150-52b4e10c2420', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'field', 'Field', 'Form & Input', NULL, 'mdi-form-textbox', 'components.catalog.field.description', 'Shared form-field shell used by all input components (TextField, NumberField, PasswordField…). Provides the label, prefix/suffix, prepend/append-inner zones, loader, outline/underline rendering and error state. Not intended for direct use — consume through a specific input component.', NULL, NULL, 'origam-field', NULL, 'packages/ds/src/components/Field/OrigamField.vue', 'origam', NULL, NULL, '/stories/?story=components-field--design', '/docs/components/Field/OrigamField.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.field.a11y.label_for", "noteFallback": "The floating label is wired to the input via the id passed through the default slot props. Consumers must bind the id from slotProps to their <input> id attribute."}, {"noteKey": "components.field.a11y.aria_describedby", "noteFallback": "The aria-describedby attribute is provided through the default slot props and must be forwarded to the native <input> so screen readers read associated messages."}, {"noteKey": "components.field.a11y.error_state", "noteFallback": "When error is truthy, the --error modifier class is applied. Consumers are responsible for adding aria-invalid=\"true\" to the native input."}, {"noteKey": "components.field.a11y.required", "noteFallback": "The required prop appends * to the label. The native required attribute must be added to the <input> element directly by the consuming component."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.field.a11y.key_tab", "actionFallback": "Moves focus to the embedded input element (passed via #default slot)."}, {"key": "Escape", "actionKey": "components.field.a11y.key_escape", "actionFallback": "Clears the field when clearable=true and focus is inside the field."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-field---border-radius", "descriptionKey": "components.field.tokens.border_radius", "descriptionFallback": "Field corner radius (4px)."}, {"type": "color", "value": "var(--origam-color__border---default)", "tokenPath": "--origam-field---border-color", "descriptionKey": "components.field.tokens.border_color", "descriptionFallback": "Default border colour."}, {"type": "number", "value": "0.38", "tokenPath": "--origam-field---border-opacity", "descriptionKey": "components.field.tokens.border_opacity", "descriptionFallback": "Border opacity at rest (translucent on inactive state)."}, {"type": "dimension", "value": "16px", "tokenPath": "--origam-field---font-size", "descriptionKey": "components.field.tokens.font_size", "descriptionFallback": "Base input font size."}, {"type": "dimension", "value": "6px", "tokenPath": "--origam-field__input---padding-block-md", "descriptionKey": "components.field.tokens.input_padding_block_md", "descriptionFallback": "Block padding for size=default (36px control). Centres input text vertically."}, {"type": "color", "value": "var(--origam-color__feedback--danger---border)", "tokenPath": "--origam-field--error---border-color", "descriptionKey": "components.field.tokens.error_border_color", "descriptionFallback": "Border colour in error state."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"60\" width=\"644\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"40\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__label (floating)</text>\n  <rect x=\"28\" y=\"56\" width=\"200\" height=\"16\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.1))\"/>\n  <rect x=\"28\" y=\"134\" width=\"644\" height=\"2\" rx=\"1\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.3))\"/>\n  <text x=\"350\" y=\"150\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">loader (OrigamProgress)</text>\n  <rect x=\"48\" y=\"72\" width=\"60\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"78\" y=\"104\" font-size=\"7.5\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">prepend</text>\n  <rect x=\"116\" y=\"72\" width=\"40\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"136\" y=\"104\" font-size=\"7\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">prefix</text>\n  <rect x=\"164\" y=\"72\" width=\"300\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"314\" y=\"104\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">__input (#default slot)</text>\n  <rect x=\"472\" y=\"72\" width=\"40\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"492\" y=\"104\" font-size=\"7\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">suffix</text>\n  <rect x=\"520\" y=\"72\" width=\"40\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"540\" y=\"104\" font-size=\"7.5\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">clear</text>\n  <rect x=\"568\" y=\"72\" width=\"84\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"610\" y=\"104\" font-size=\"7.5\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">append</text>\n  <circle cx=\"36\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"72\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n", "code": "<div class=\"origam-field origam-field--variant-outlined\">\n  <!-- interaction overlay -->\n  <div class=\"origam-field__overlay\" />\n\n  <!-- loader (OrigamProgress) — v-if hasLoader -->\n  <div class=\"origam-field__loader\"><origam-progress /></div>\n\n  <!-- prepend inner icon / avatar -->\n  <div class=\"origam-field__prepend-inner\">\n    <slot name=\"prependInner\" />\n  </div>\n\n  <!-- input area: label + prefix + #default + suffix -->\n  <div class=\"origam-field__field\">\n    <label class=\"origam-field__label\">{{ label }}</label>\n    <span class=\"origam-field__prefix\">{{ prefix }}</span>\n    <slot name=\"default\" v-bind=\"slotProps\" />\n    <span class=\"origam-field__suffix\">{{ suffix }}</span>\n  </div>\n\n  <!-- clearable button — v-if showClear -->\n  <div class=\"origam-field__clearable\">\n    <origam-icon :icon=\"clearIcon\" />\n  </div>\n\n  <!-- append inner icon / avatar -->\n  <div class=\"origam-field__append-inner\">\n    <slot name=\"appendInner\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-field", "num": 1, "descriptionKey": "components.field.anatomy.root", "descriptionFallback": "Root grid container. display: grid; grid-template-areas: \"prepend-inner field clear append-inner\"."}, {"cls": ".origam-field__overlay", "num": 2, "descriptionKey": "components.field.anatomy.overlay", "descriptionFallback": "Interaction scrim (hover/focus ripple). pointer-events: none."}, {"cls": ".origam-field__prepend-inner", "num": 3, "descriptionKey": "components.field.anatomy.prepend_inner", "descriptionFallback": "Leading icon/avatar zone inside the field border."}, {"cls": ".origam-field__field", "num": 4, "descriptionKey": "components.field.anatomy.field", "descriptionFallback": "Input area containing label, prefix, #default slot and suffix."}, {"cls": ".origam-field__clearable", "num": 5, "descriptionKey": "components.field.anatomy.clearable", "descriptionFallback": "Clear icon button. Shown when clearable=true and field is dirty/focused."}, {"cls": ".origam-field__append-inner", "num": 6, "descriptionKey": "components.field.anatomy.append_inner", "descriptionFallback": "Trailing icon/avatar zone inside the field border."}, {"cls": ".origam-field__loader", "num": 7, "descriptionKey": "components.field.anatomy.loader", "descriptionFallback": "Progress bar at the bottom of the field. Rendered when loading is active and kind !== skeleton."}], "classes": [{"cls": "origam-field", "descriptionKey": "components.field.anatomy.root", "descriptionFallback": "Root grid container."}, {"cls": "origam-field--variant-outlined", "descriptionKey": "components.field.anatomy.variant_outlined", "descriptionFallback": "Variant modifier. One of: outlined, underlined, filled, solo, solo-filled, solo-inverted, plain."}, {"cls": "origam-field--focused", "descriptionKey": "components.field.anatomy.focused", "descriptionFallback": "Applied when the embedded input has focus."}, {"cls": "origam-field--error", "descriptionKey": "components.field.anatomy.error", "descriptionFallback": "Applied when the error prop is truthy. Changes border and label colour to the danger semantic."}, {"cls": "origam-field__overlay", "descriptionKey": "components.field.anatomy.overlay", "descriptionFallback": "Interaction scrim layer."}, {"cls": "origam-field__field", "descriptionKey": "components.field.anatomy.field", "descriptionFallback": "Core input region containing label, prefix, slot and suffix."}, {"cls": "origam-field__prepend-inner", "descriptionKey": "components.field.anatomy.prepend_inner", "descriptionFallback": "Leading inner icon/avatar zone."}, {"cls": "origam-field__append-inner", "descriptionKey": "components.field.anatomy.append_inner", "descriptionFallback": "Trailing inner icon/avatar zone."}, {"cls": "origam-field__clearable", "descriptionKey": "components.field.anatomy.clearable", "descriptionFallback": "Clear button zone."}, {"cls": "origam-field__loader", "descriptionKey": "components.field.anatomy.loader", "descriptionFallback": "Progress loader zone at the bottom."}], "svgDesc": "Schematic of the Field component with 7 numbered internal parts.", "svgTitle": "Anatomy of OrigamField", "rootClass": "origam-field", "figcaption": "Anatomy of <code>&lt;origam-field&gt;</code> — 7 internal zones. The field is a CSS Grid with columns: prepend-inner / input / clear / append-inner. Label floats above the top edge when active.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-field---border-radius", "defaultValue": "{radius.sm} (4px)", "descriptionKey": "components.field.css_vars.border_radius", "descriptionFallback": "Field corner radius. Overridden by the rounded prop."}, {"name": "--origam-field---border-color", "defaultValue": "{color.border.default}", "descriptionKey": "components.field.css_vars.border_color", "descriptionFallback": "Default outline/underline colour."}, {"name": "--origam-field---border-width", "defaultValue": "{border.width.thin}", "descriptionKey": "components.field.css_vars.border_width", "descriptionFallback": "Border width for outlined/underlined variants."}, {"name": "--origam-field---border-opacity", "defaultValue": "0.38", "descriptionKey": "components.field.css_vars.border_opacity", "descriptionFallback": "Border opacity at rest. Transitions to 1 on focus."}, {"name": "--origam-field---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.field.css_vars.color", "descriptionFallback": "Field text colour inherited by the input."}, {"name": "--origam-field---font-size", "defaultValue": "16px", "descriptionKey": "components.field.css_vars.font_size", "descriptionFallback": "Input font size."}, {"name": "--origam-field---opacity-disabled", "defaultValue": "0.5", "descriptionKey": "components.field.css_vars.opacity_disabled", "descriptionFallback": "Opacity when disabled."}, {"name": "--origam-field---transition-duration", "defaultValue": "{motion.duration.normal}", "descriptionKey": "components.field.css_vars.transition_duration", "descriptionFallback": "Duration for label float, border and opacity transitions."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.field.exposed.filter_props", "descriptionFallback": "Filters and forwards a subset of props to the embedded input element."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.field.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.field.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.field.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.field.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.field.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}, {"name": "styleId", "type": "string", "descriptionKey": "components.field.exposed.style_id", "descriptionFallback": "Secondary style ID used for variant-level scoped styles."}], "playground": {"controls": [{"kind": "select", "prop": "variant", "options": [{"label": "(default)", "value": ""}, {"label": "VARIANT.TEXT", "value": "VARIANT.TEXT"}, {"label": "text", "value": "text"}, {"label": "flat", "value": "flat"}, {"label": "VARIANT.FLAT", "value": "VARIANT.FLAT"}, {"label": "VARIANT.ELEVATED", "value": "VARIANT.ELEVATED"}, {"label": "elevated", "value": "elevated"}, {"label": "tonal", "value": "tonal"}, {"label": "VARIANT.TONAL", "value": "VARIANT.TONAL"}, {"label": "VARIANT.OUTLINED", "value": "VARIANT.OUTLINED"}, {"label": "outlined", "value": "outlined"}, {"label": "plain", "value": "plain"}, {"label": "VARIANT.PLAIN", "value": "VARIANT.PLAIN"}, {"label": "ghost", "value": "ghost"}, {"label": "VARIANT.GHOST", "value": "VARIANT.GHOST"}], "labelKey": "components.field.playground.variant", "defaultValue": "", "labelFallback": "Variant"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.field.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.field.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "select", "prop": "size", "options": [{"label": "(default)", "value": ""}, {"label": "x-small", "value": "x-small"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "large", "value": "large"}, {"label": "x-large", "value": "x-large"}], "labelKey": "components.field.playground.size", "defaultValue": "", "labelFallback": "Size"}, {"kind": "select", "prop": "density", "options": [{"label": "(default)", "value": ""}, {"label": "default", "value": "default"}, {"label": "DENSITY.DEFAULT", "value": "DENSITY.DEFAULT"}, {"label": "compact", "value": "compact"}, {"label": "DENSITY.COMPACT", "value": "DENSITY.COMPACT"}, {"label": "DENSITY.COMFORTABLE", "value": "DENSITY.COMFORTABLE"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.field.playground.density", "defaultValue": "", "labelFallback": "Density"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(default)", "value": ""}, {"label": "ROUNDED.X_SMALL", "value": "ROUNDED.X_SMALL"}, {"label": "x-small", "value": "x-small"}, {"label": "ROUNDED.SMALL", "value": "ROUNDED.SMALL"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "ROUNDED.DEFAULT", "value": "ROUNDED.DEFAULT"}, {"label": "ROUNDED.MEDIUM", "value": "ROUNDED.MEDIUM"}, {"label": "medium", "value": "medium"}, {"label": "large", "value": "large"}, {"label": "ROUNDED.LARGE", "value": "ROUNDED.LARGE"}, {"label": "x-large", "value": "x-large"}, {"label": "ROUNDED.X_LARGE", "value": "ROUNDED.X_LARGE"}, {"label": "shaped", "value": "shaped"}, {"label": "ROUNDED.SHAPED", "value": "ROUNDED.SHAPED"}, {"label": "shaped-invert", "value": "shaped-invert"}, {"label": "ROUNDED.SHAPED_INVERT", "value": "ROUNDED.SHAPED_INVERT"}], "labelKey": "components.field.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.field.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "flat", "labelKey": "components.field.playground.flat", "defaultValue": false, "labelFallback": "Flat"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('86c16d40-ccda-42d6-a00c-92fb47cee5ed', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'file-field', 'FileField', 'Form & Input', NULL, 'mdi-file-upload-outline', 'components.catalog.file_field.description', 'File upload input with three display modes (list, chips, counter), an optional drag-and-drop dropzone, file size validation, progress tracking and per-item download/remove actions.', NULL, NULL, 'origam-file-field', NULL, 'packages/ds/src/components/FileField/OrigamFileField.vue', 'origam', NULL, NULL, '/stories/?story=components-filefield--design', '/docs/components/FileField/OrigamFileField.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.file_field.a11y.label", "noteFallback": "The dropzone is a <label> element pointing to the hidden <input type=\"file\">. Clicking anywhere on the label opens the native file picker."}, {"noteKey": "components.file_field.a11y.drag_events", "noteFallback": "Drag events (dragenter, dragover, dragleave, drop) are handled on the <label>. The --dragging modifier class provides visual feedback during dragover."}, {"noteKey": "components.file_field.a11y.disabled", "noteFallback": "When disabled=true, the hidden input is disabled and cursor changes to not-allowed. The dropzone opacity drops to 0.6."}, {"noteKey": "components.file_field.a11y.error", "noteFallback": "When error is truthy, the dropzone border changes to the danger semantic colour. The error message (if a string) is displayed inside the dropzone area."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.file_field.a11y.key_tab", "actionFallback": "Moves focus to the file input or dropzone label."}, {"key": "Enter / Space", "actionKey": "components.file_field.a11y.key_activate", "actionFallback": "Opens the native file picker when the dropzone label has focus."}]}, "tokens": {"excerpt": [{"type": "color", "value": "rgba(0, 0, 0, 0)", "tokenPath": "--origam-file-field__dropzone---background-color", "descriptionKey": "components.file_field.tokens.dropzone_bg", "descriptionFallback": "Default dropzone background."}, {"type": "color", "value": "var(--origam-color__border---default)", "tokenPath": "--origam-file-field__dropzone---color", "descriptionKey": "components.file_field.tokens.dropzone_color", "descriptionFallback": "Dropzone dashed border and text colour."}, {"type": "dimension", "value": "var(--origam-radius---md)", "tokenPath": "--origam-file-field__dropzone---border-radius", "descriptionKey": "components.file_field.tokens.dropzone_border_radius", "descriptionFallback": "Dropzone corner radius (8px)."}, {"type": "dimension", "value": "140px", "tokenPath": "--origam-file-field__dropzone---min-height", "descriptionKey": "components.file_field.tokens.dropzone_min_height", "descriptionFallback": "Minimum height of the empty dropzone."}, {"type": "color", "value": "var(--origam-color__feedback--info---bgSubtle)", "tokenPath": "--origam-file-field__dropzone--dragging---background-color", "descriptionKey": "components.file_field.tokens.dropzone_dragging_bg", "descriptionFallback": "Dropzone background during dragover."}, {"type": "color", "value": "var(--origam-color__feedback--danger---bg)", "tokenPath": "--origam-file-field__dropzone--error---border-color", "descriptionKey": "components.file_field.tokens.dropzone_error_border", "descriptionFallback": "Dropzone border in error state."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"16\" width=\"644\" height=\"100\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"70\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">OrigamInput → OrigamField (label, prepend/append, clearable)</text>\n  <rect x=\"48\" y=\"128\" width=\"604\" height=\"76\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"170\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__dragndrop / file list (display mode: list | chips | counter)</text>\n  <circle cx=\"36\" cy=\"24\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"28.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"56\" cy=\"136\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<origam-input class=\"origam-file-field\">\n  <!-- OrigamField handles label, prepend/append inner, clearable -->\n\n  <!-- hidden native file input -->\n  <input type=\"file\" :multiple=\"multiple\" style=\"opacity:0;position:absolute;\" />\n\n  <!-- dropzone mode -->\n  <div v-if=\"isDropzoneMode\" class=\"origam-file-field__dragndrop\">\n    <label class=\"origam-file-field__dropzone\">\n      <!-- icon + title + subtitle / single-file DnD item -->\n      <origam-file-field-drag-n-drop-item v-if=\"!multiple && hasFiles\" />\n      <template v-else>\n        <origam-icon class=\"origam-file-field__dropzone-icon\" />\n        <div class=\"origam-file-field__dropzone-title\" />\n        <div class=\"origam-file-field__dropzone-subtitle\" />\n      </template>\n    </label>\n\n    <!-- multi-file list below dropzone -->\n    <div v-if=\"multiple && hasFiles\" class=\"origam-file-field__list\">\n      <origam-file-field-list-item v-for=\"(file, i) in model\" :key=\"i\" />\n    </div>\n  </div>\n</origam-input>", "legend": [{"cls": ".origam-file-field", "num": 1, "descriptionKey": "components.file_field.anatomy.root", "descriptionFallback": "Root element. Extends OrigamInput which itself renders an OrigamField with label, prepend/append zones, and clearable."}, {"cls": ".origam-file-field__dragndrop", "num": 2, "descriptionKey": "components.file_field.anatomy.dragndrop", "descriptionFallback": "Drag-and-drop wrapper rendered when dropzone/dragndrop=true. Houses the <label> dropzone area and the file list below it."}, {"cls": ".origam-file-field__dropzone", "num": 3, "descriptionKey": "components.file_field.anatomy.dropzone", "descriptionFallback": "<label> element acting as the drop target. Accepts drag events, triggers the hidden file input on click. Has --dragging modifier on dragover."}, {"cls": ".origam-file-field__list", "num": 4, "descriptionKey": "components.file_field.anatomy.list", "descriptionFallback": "Vertical list of OrigamFileFieldListItem cards shown below the field in list display mode."}, {"cls": ".origam-file-field__dropzone-icon / __dropzone-title / __dropzone-subtitle", "num": 5, "descriptionKey": "components.file_field.anatomy.dropzone_content", "descriptionFallback": "Inner dropzone content zones: upload icon, primary title text, and secondary subtitle text."}], "classes": [{"cls": "origam-file-field", "descriptionKey": "components.file_field.anatomy.root", "descriptionFallback": "Root element wrapping OrigamInput."}, {"cls": "origam-file-field__dragndrop", "descriptionKey": "components.file_field.anatomy.dragndrop", "descriptionFallback": "Drag-and-drop container (dropzone + list below)."}, {"cls": "origam-file-field__dropzone", "descriptionKey": "components.file_field.anatomy.dropzone", "descriptionFallback": "<label> drop target. Adds --dragging modifier on dragover."}, {"cls": "origam-file-field__dropzone-icon", "descriptionKey": "components.file_field.anatomy.dropzone_icon", "descriptionFallback": "Upload icon glyph inside the dropzone."}, {"cls": "origam-file-field__dropzone-title", "descriptionKey": "components.file_field.anatomy.dropzone_title", "descriptionFallback": "Primary text area inside the dropzone."}, {"cls": "origam-file-field__dropzone-subtitle", "descriptionKey": "components.file_field.anatomy.dropzone_subtitle", "descriptionFallback": "Secondary text area inside the dropzone."}, {"cls": "origam-file-field__list", "descriptionKey": "components.file_field.anatomy.list", "descriptionFallback": "Vertical file card list below the field (list display mode)."}], "svgDesc": "Schematic of the FileField component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamFileField", "rootClass": "origam-file-field", "figcaption": "Anatomy of <code>&lt;origam-file-field&gt;</code>. The root ① extends OrigamInput → OrigamField (label, icons, clearable). Below the field ②, the display zone renders in one of three modes: list (card stack), chips (closable chips row), or counter (\"{n} files\").", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-file-field---gap", "defaultValue": "{space.2} (8px)", "descriptionKey": "components.file_field.css_vars.gap", "descriptionFallback": "Gap between the dropzone wrapper sections (dropzone + list)."}, {"name": "--origam-file-field---list-gap", "defaultValue": "{space.2} (8px)", "descriptionKey": "components.file_field.css_vars.list_gap", "descriptionFallback": "Gap between file-field list items."}, {"name": "--origam-file-field__dropzone---background-color", "defaultValue": "transparent", "descriptionKey": "components.file_field.css_vars.dropzone_background_color", "descriptionFallback": "Default dropzone background colour."}, {"name": "--origam-file-field__dropzone---color", "defaultValue": "{color.border.default}", "descriptionKey": "components.file_field.css_vars.dropzone_color", "descriptionFallback": "Dropzone dashed border colour and text colour fallback."}, {"name": "--origam-file-field__dropzone---border-radius", "defaultValue": "{radius.md} (8px)", "descriptionKey": "components.file_field.css_vars.dropzone_border_radius", "descriptionFallback": "Dropzone corner radius."}, {"name": "--origam-file-field__dropzone---min-height", "defaultValue": "140px", "descriptionKey": "components.file_field.css_vars.dropzone_min_height", "descriptionFallback": "Minimum height of the empty dropzone area."}, {"name": "--origam-file-field__dropzone--dragging---background-color", "defaultValue": "{color.feedback.info.bgSubtle}", "descriptionKey": "components.file_field.css_vars.dropzone_dragging_bg", "descriptionFallback": "Dropzone background during dragover."}, {"name": "--origam-file-field__dropzone--dragging---border-color", "defaultValue": "{color.feedback.info.bg}", "descriptionKey": "components.file_field.css_vars.dropzone_dragging_border", "descriptionFallback": "Dropzone border colour during dragover."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.file_field.exposed.filter_props", "descriptionFallback": "Filters and forwards a subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.file_field.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.file_field.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.file_field.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.file_field.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.file_field.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "text", "prop": "label", "labelKey": "components.file_field.playground.label", "defaultValue": "Upload a file", "labelFallback": "Label"}, {"kind": "select", "prop": "variant", "options": [{"label": "outlined", "value": "outlined"}, {"label": "underlined", "value": "underlined"}, {"label": "filled", "value": "filled"}, {"label": "solo", "value": "solo"}], "labelKey": "components.file_field.playground.variant", "defaultValue": "outlined", "labelFallback": "Variant"}, {"kind": "switch", "prop": "multiple", "labelKey": "components.file_field.playground.multiple", "defaultValue": false, "labelFallback": "Multiple"}, {"kind": "switch", "prop": "dropzone", "labelKey": "components.file_field.playground.dropzone", "defaultValue": false, "labelFallback": "Dropzone mode"}, {"kind": "switch", "prop": "chips", "labelKey": "components.file_field.playground.chips", "defaultValue": false, "labelFallback": "Chips display"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.file_field.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": [{"label": "default", "props": {"label": "Upload a file", "variant": "outlined"}}, {"label": "dropzone", "props": {"label": "Drop files", "dropzone": true, "multiple": true}}, {"label": "chips", "props": {"chips": true, "label": "Attachments", "multiple": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('ff4fd17b-0405-4a0d-9245-0934fb8caa6b', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'file-field-drag-n-drop-item', 'FileFieldDragNDropItem', 'Form & Input', NULL, 'mdi-file-upload-outline', 'components.catalog.file_field_drag_n_drop_item.description', 'File card rendered inside a drag-and-drop dropzone. Displays the file icon, name, human-readable size, an optional progress bar, and a remove button.', NULL, NULL, 'origam-file-field-drag-n-drop-item', NULL, 'packages/ds/src/components/FileField/OrigamFileFieldDragNDropItem.vue', 'origam', NULL, NULL, '/stories/?story=components-filefield--design', '/docs/components/FileField/OrigamFileField.html', 'file-field', '{"a11y": {"notes": [{"noteKey": "components.file_field_drag_n_drop_item.a11y.remove_btn", "noteFallback": "The remove button is a native <button> (via OrigamBtn). It is disabled when disabled=true or readonly=true — pointer events and keyboard activation are suppressed."}], "roles": [], "keyboard": [{"key": "Enter / Space", "actionKey": "components.file_field_drag_n_drop_item.a11y.key_remove", "actionFallback": "Activates the remove button when focused — native <button> behaviour."}, {"key": "Tab", "actionKey": "components.file_field_drag_n_drop_item.a11y.key_tab", "actionFallback": "Moves focus to the remove button and then to the next interactive element."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-file-field-dragndrop-item---gap", "descriptionKey": "components.file_field_drag_n_drop_item.tokens.gap", "descriptionFallba