\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"56\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <rect x=\"116\" y=\"44\" width=\"450\" height=\"72\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f9f5ff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"210\" y=\"64\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" font-weight=\"600\" font-family=\"''JetBrains Mono'',monospace\">document.docx</text>\n  <text x=\"210\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">320 kB</text>\n  <rect x=\"136\" y=\"90\" width=\"410\" height=\"6\" rx=\"3\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.12))\"/>\n  <rect x=\"136\" y=\"90\" width=\"267\" height=\"6\" rx=\"3\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"124\" cy=\"52\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"124\" y=\"56\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"340\" cy=\"95\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"340\" y=\"99\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <rect x=\"580\" y=\"44\" width=\"72\" height=\"72\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f3eeff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"616\" y=\"83\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">remove</text>\n  <circle cx=\"588\" cy=\"52\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"588\" y=\"56\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<li class=\"origam-file-field-list-item\">\n  <slot>\n    <origam-icon class=\"origam-file-field-list-item__icon\" />\n    <div class=\"origam-file-field-list-item__content\">\n      <div class=\"origam-file-field-list-item__name\">document.docx</div>\n      <div class=\"origam-file-field-list-item__meta\">320 kB</div>\n      <origam-progress class=\"origam-file-field-list-item__progress\" />\n    </div>\n    <div class=\"origam-file-field-list-item__actions\">\n      <origam-btn :icon=\"removeIcon\" flat size=\"small\" @click.stop=\"handleRemove\" />\n    </div>\n  </slot>\n</li>", "legend": [{"cls": ".origam-file-field-list-item", "num": 1, "descriptionKey": "components.file_field_list_item.anatomy.root", "descriptionFallback": "Root <li> element. display: flex; align-items: center. Has background-color, border (1px solid), border-radius and padding from design tokens."}, {"cls": ".origam-file-field-list-item__icon", "num": 2, "descriptionKey": "components.file_field_list_item.anatomy.icon", "descriptionFallback": "OrigamIcon rendered from the fileIcon prop. flex-shrink: 0; color from --origam-file-field-list-item__icon---color."}, {"cls": ".origam-file-field-list-item__content", "num": 3, "descriptionKey": "components.file_field_list_item.anatomy.content", "descriptionFallback": "Flex column: stacks __name, __meta and optional __progress. flex-grow: 1; min-width: 0 for truncation support."}, {"cls": ".origam-file-field-list-item__progress", "num": 4, "descriptionKey": "components.file_field_list_item.anatomy.progress", "descriptionFallback": "OrigamProgress bar. Rendered only when the progress prop is a number. height: 4px; rounded; has margin-top from token."}, {"cls": ".origam-file-field-list-item__actions", "num": 5, "descriptionKey": "components.file_field_list_item.anatomy.actions", "descriptionFallback": "Flex row of action buttons. flex-shrink: 0. Contains the remove OrigamBtn (flat, size=\"small\")."}], "classes": [{"cls": "origam-file-field-list-item", "descriptionKey": "components.file_field_list_item.anatomy.root", "descriptionFallback": "Root <li> flex container with background, border, border-radius and padding tokens."}, {"cls": "origam-file-field-list-item__icon", "descriptionKey": "components.file_field_list_item.anatomy.icon", "descriptionFallback": "File type icon (flex-shrink: 0)."}, {"cls": "origam-file-field-list-item__content", "descriptionKey": "components.file_field_list_item.anatomy.content", "descriptionFallback": "Column container for name, meta and progress."}, {"cls": "origam-file-field-list-item__name", "descriptionKey": "components.file_field_list_item.anatomy.name", "descriptionFallback": "File name text. Truncated with text-overflow: ellipsis."}, {"cls": "origam-file-field-list-item__meta", "descriptionKey": "components.file_field_list_item.anatomy.meta", "descriptionFallback": "Human-readable file size text."}, {"cls": "origam-file-field-list-item__progress", "descriptionKey": "components.file_field_list_item.anatomy.progress", "descriptionFallback": "Upload progress bar (conditional on progress prop)."}, {"cls": "origam-file-field-list-item__actions", "descriptionKey": "components.file_field_list_item.anatomy.actions", "descriptionFallback": "Action buttons zone (remove button)."}], "svgDesc": "Schematic of the list file item with 5 numbered parts: root <li>, icon, content column, progress bar, actions.", "svgTitle": "Anatomy of OrigamFileFieldListItem", "rootClass": "origam-file-field-list-item", "figcaption": "Anatomy of <code>&lt;origam-file-field-list-item&gt;</code> — renders as a semantic <code>&lt;li&gt;</code>. 5 internal parts: root card ①, file icon ②, content column ③ (name + meta + optional progress ④), and the actions zone ⑤ with the remove button.", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-file-field-list-item---background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.file_field_list_item.css_vars.background_color", "descriptionFallback": "Card background color."}, {"name": "--origam-file-field-list-item---border-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.file_field_list_item.css_vars.border_color", "descriptionFallback": "Card border color."}, {"name": "--origam-file-field-list-item---border-width", "defaultValue": "1px", "descriptionKey": "components.file_field_list_item.css_vars.border_width", "descriptionFallback": "Card border width."}, {"name": "--origam-file-field-list-item---border-style", "defaultValue": "solid", "descriptionKey": "components.file_field_list_item.css_vars.border_style", "descriptionFallback": "Card border style."}, {"name": "--origam-file-field-list-item---border-radius", "defaultValue": "{radius.sm} (6px)", "descriptionKey": "components.file_field_list_item.css_vars.border_radius", "descriptionFallback": "Card corner radius (6px as fallback in the .vue; closest token is radius.sm = 4px)."}, {"name": "--origam-file-field-list-item---gap", "defaultValue": "{space.3} (12px)", "descriptionKey": "components.file_field_list_item.css_vars.gap", "descriptionFallback": "Gap between the icon, content column and actions zone."}, {"name": "--origam-file-field-list-item---padding-block", "defaultValue": "{space.2} (10px)", "descriptionKey": "components.file_field_list_item.css_vars.padding_block", "descriptionFallback": "Block (top/bottom) padding of the card."}, {"name": "--origam-file-field-list-item---padding-inline", "defaultValue": "{space.3} (12px)", "descriptionKey": "components.file_field_list_item.css_vars.padding_inline", "descriptionFallback": "Inline (left/right) padding of the card."}, {"name": "--origam-file-field-list-item__icon---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.file_field_list_item.css_vars.icon_color", "descriptionFallback": "Color of the file type icon glyph."}, {"name": "--origam-file-field-list-item__name---font-size", "defaultValue": "{font.size.md} (0.875rem)", "descriptionKey": "components.file_field_list_item.css_vars.name_font_size", "descriptionFallback": "Font size for the file name label."}, {"name": "--origam-file-field-list-item__name---font-weight", "defaultValue": "{font.weight.medium} (500)", "descriptionKey": "components.file_field_list_item.css_vars.name_font_weight", "descriptionFallback": "Font weight for the file name label."}, {"name": "--origam-file-field-list-item__meta---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.file_field_list_item.css_vars.meta_color", "descriptionFallback": "Color of the file size / meta text."}, {"name": "--origam-file-field-list-item__meta---font-size", "defaultValue": "{font.size.sm} (0.75rem)", "descriptionKey": "components.file_field_list_item.css_vars.meta_font_size", "descriptionFallback": "Font size for the file size / meta text."}, {"name": "--origam-file-field-list-item__progress---margin-top", "defaultValue": "{space.1} (4px)", "descriptionKey": "components.file_field_list_item.css_vars.progress_margin_top", "descriptionFallback": "Top margin of the progress bar inside the content column."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.file_field_list_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.file_field_list_item.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed root styles."}, {"name": "id", "type": "string", "descriptionKey": "components.file_field_list_item.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.file_field_list_item.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document.