INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f8dc7890-67de-4cdc-84f1-34eabead58af', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'kbd', 'Kbd', 'Typography', NULL, 'mdi-keyboard-outline', 'components.catalog.kbd.description', 'Keyboard shortcut renderer using semantic <kbd> elements with filled, outlined and tonal variants.', NULL, NULL, 'origam-kbd', NULL, 'packages/ds/src/components/Kbd/OrigamKbd.vue', 'origam', NULL, NULL, '/stories/?story=components-kbd--design', '/docs/components/Kbd/OrigamKbd.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.kbd.a11y.semantic_note", "noteFallback": "Uses native <kbd> HTML elements — screen readers announce these as keyboard input, requiring no ARIA role override."}, {"noteKey": "components.kbd.a11y.separator_note", "noteFallback": "The separator span in combination mode carries aria-hidden=\"true\" so screen readers skip the \"+\" character and only read the key names."}, {"noteKey": "components.kbd.a11y.contrast_note", "noteFallback": "The v-contrast directive automatically adjusts the text color to ensure WCAG contrast requirements are met against the background."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-kbd---background-color", "descriptionKey": "components.kbd.tokens.background_color", "descriptionFallback": "Default key background."}, {"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-kbd---border-radius", "descriptionKey": "components.kbd.tokens.border_radius", "descriptionFallback": "Default key border radius (4px)."}, {"type": "fontFamily", "value": "var(--origam-font__family---mono)", "tokenPath": "--origam-kbd---font-family", "descriptionKey": "components.kbd.tokens.font_family", "descriptionFallback": "Monospace font stack for key labels."}, {"type": "fontWeight", "value": "var(--origam-font__weight---medium)", "tokenPath": "--origam-kbd---font-weight", "descriptionKey": "components.kbd.tokens.font_weight", "descriptionFallback": "Key label font weight."}, {"type": "shadow", "value": "var(--origam-shadow---xs)", "tokenPath": "--origam-kbd---box-shadow", "descriptionKey": "components.kbd.tokens.box_shadow", "descriptionFallback": "Key shadow for the 3D depth effect."}, {"type": "dimension", "value": "var(--origam-space---1)", "tokenPath": "--origam-kbd---gap", "descriptionKey": "components.kbd.tokens.gap", "descriptionFallback": "Gap between keys in combination mode."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <text x=\"350\" y=\"35\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">SINGLE KEY</text>\n  <rect x=\"270\" y=\"45\" width=\"160\" height=\"50\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, #d4d4d4)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"76\" font-size=\"14\" fill=\"var(--origam-color__text---primary, #171717)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"500\">Ctrl</text>\n  <circle cx=\"278\" cy=\"53\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"278\" y=\"57.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <text x=\"350\" y=\"125\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">COMBINATION</text>\n  <rect x=\"170\" y=\"140\" width=\"80\" height=\"40\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, #d4d4d4)\" stroke-width=\"1.5\"/>\n  <text x=\"210\" y=\"166\" font-size=\"13\" fill=\"var(--origam-color__text---primary, #171717)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"500\">Ctrl</text>\n  <text x=\"270\" y=\"163\" font-size=\"14\" fill=\"var(--origam-color__text---secondary, rgba(0,0,0,0.55))\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">+</text>\n  <rect x=\"290\" y=\"140\" width=\"50\" height=\"40\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, #d4d4d4)\" stroke-width=\"1.5\"/>\n  <text x=\"315\" y=\"166\" font-size=\"13\" fill=\"var(--origam-color__text---primary, #171717)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"500\">S</text>\n  <circle cx=\"178\" cy=\"148\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"178\" y=\"152.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"270\" cy=\"148\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"270\" y=\"152.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"350\" y=\"195\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Renders native &lt;kbd&gt; HTML elements — always semantic</text>\n", "code": "<!-- Single key -->\n<kbd class=\"origam-kbd origam-kbd--variant-outlined\">Ctrl</kbd>\n\n<!-- Combination -->\n<kbd class=\"origam-kbd origam-kbd--combination origam-kbd--variant-outlined\">\n  <kbd class=\"origam-kbd__key\">Ctrl</kbd>\n  <span class=\"origam-kbd__separator\" aria-hidden=\"true\">+</span>\n  <kbd class=\"origam-kbd__key\">S</kbd>\n</kbd>", "legend": [{"cls": ".origam-kbd", "num": 1, "descriptionKey": "components.kbd.anatomy.root", "descriptionFallback": "Root <code>&lt;kbd&gt;</code> element. In single-key mode, renders the key directly. The <code>v-contrast</code> directive auto-adjusts text color for accessibility."}, {"cls": ".origam-kbd__key", "num": 2, "descriptionKey": "components.kbd.anatomy.key", "descriptionFallback": "Individual key element in combination mode. Each item in the <code>combination</code> array renders as a nested <code>&lt;kbd class=\"origam-kbd__key\"&gt;</code>."}, {"cls": ".origam-kbd__separator", "num": 3, "descriptionKey": "components.kbd.anatomy.separator", "descriptionFallback": "Character rendered between keys in combination mode. <code>aria-hidden=\"true\"</code> so screen readers skip it. Default: \"+\"."}], "classes": [{"cls": "origam-kbd", "descriptionKey": "components.kbd.anatomy.root", "descriptionFallback": "Root <kbd> element. Shared key-surface styles via @mixin key-surface."}, {"cls": "origam-kbd--variant-outlined", "descriptionKey": "components.kbd.anatomy.variant_outlined", "descriptionFallback": "Outlined variant: border + bottom shadow for 3D key effect."}, {"cls": "origam-kbd--variant-filled", "descriptionKey": "components.kbd.anatomy.variant_filled", "descriptionFallback": "Filled variant: surface-overlay background with stronger shadow."}, {"cls": "origam-kbd--variant-tonal", "descriptionKey": "components.kbd.anatomy.variant_tonal", "descriptionFallback": "Tonal variant: tinted background, no border, no shadow."}, {"cls": "origam-kbd--combination", "descriptionKey": "components.kbd.anatomy.combination", "descriptionFallback": "Applied when combination prop is set. Makes the root transparent; each __key inherits key-surface styles."}, {"cls": "origam-kbd__key", "descriptionKey": "components.kbd.anatomy.key", "descriptionFallback": "Individual nested key in combination mode. Inherits key-surface styles."}, {"cls": "origam-kbd__separator", "descriptionKey": "components.kbd.anatomy.separator", "descriptionFallback": "Separator text between keys. aria-hidden=\"true\"."}], "svgDesc": "Schematic of the Kbd component with 3 numbered parts: root key, combination wrapper, and separator.", "svgTitle": "Anatomy of OrigamKbd", "rootClass": "origam-kbd", "figcaption": "Anatomy of <code>&lt;origam-kbd&gt;</code>. Single-key mode ① renders one <code>&lt;kbd&gt;</code>; combination mode ② wraps individual keys in nested <code>&lt;kbd&gt;</code> elements separated by a ③ span.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-kbd---background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.kbd.css_vars.background_color", "descriptionFallback": "Key background color. Overridden per variant."}, {"name": "--origam-kbd---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.kbd.css_vars.color", "descriptionFallback": "Key foreground color. Auto-adjusted by v-contrast directive."}, {"name": "--origam-kbd---border-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.kbd.css_vars.border_color", "descriptionFallback": "Key border color."}, {"name": "--origam-kbd---border-width", "defaultValue": "1px", "descriptionKey": "components.kbd.css_vars.border_width", "descriptionFallback": "Border width. Set to 0 for tonal variant."}, {"name": "--origam-kbd---border-radius", "defaultValue": "4px", "descriptionKey": "components.kbd.css_vars.border_radius", "descriptionFallback": "Key border radius. Overridden by the rounded prop."}, {"name": "--origam-kbd---font-family", "defaultValue": "{font.family.mono}", "descriptionKey": "components.kbd.css_vars.font_family", "descriptionFallback": "Monospace font family for the key label."}, {"name": "--origam-kbd---font-weight", "defaultValue": "{font.weight.medium}", "descriptionKey": "components.kbd.css_vars.font_weight", "descriptionFallback": "Key label font weight."}, {"name": "--origam-kbd---box-shadow", "defaultValue": "0 1px 0 0 color-mix(…), inset 0 1px 0 0 color-mix(…)", "descriptionKey": "components.kbd.css_vars.box_shadow", "descriptionFallback": "3D key shadow. Composed of a bottom border-like shadow and an inset highlight. Cleared for tonal/combination variants."}, {"name": "--origam-kbd---gap", "defaultValue": "4px", "descriptionKey": "components.kbd.css_vars.gap", "descriptionFallback": "Gap between keys in combination mode."}, {"name": "--origam-kbd__separator---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.kbd.css_vars.separator_color", "descriptionFallback": "Color of the separator character between keys."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.kbd.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.kbd.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed kbdStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.kbd.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.kbd.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.kbd.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.kbd.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "text", "labelKey": "components.kbd.playground.text", "defaultValue": "⌘", "labelFallback": "Key text"}, {"kind": "select", "prop": "variant", "options": [{"label": "outlined", "value": "outlined"}, {"label": "filled", "value": "filled"}, {"label": "tonal", "value": "tonal"}], "labelKey": "components.kbd.playground.variant", "defaultValue": "outlined", "labelFallback": "Variant"}, {"kind": "select", "prop": "size", "options": [{"label": "x-small", "value": "x-small"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "large", "value": "large"}, {"label": "x-large", "value": "x-large"}], "labelKey": "components.kbd.playground.size", "defaultValue": "default", "labelFallback": "Size"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8acc5c62-217c-49d1-91cb-0b02cec5d793', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'label', 'Label', 'Feedback & Status', NULL, 'mdi-tag-outline', 'components.catalog.label.description', 'Form field label with required indicator and floating state support.', NULL, NULL, 'origam-label', NULL, 'packages/ds/src/components/Label/OrigamLabel.vue', 'origam', NULL, NULL, '/stories/?story=components-label--design', '/docs/components/Label/OrigamLabel.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.label.a11y.association_note", "noteFallback": "Use the for= attribute (via id matching) or wrap the input inside the label to associate them. The component does not auto-generate the for= relationship."}, {"noteKey": "components.label.a11y.required_note", "noteFallback": "The <sup>*</sup> required indicator is a visual cue only. Screen readers may not announce it. Pair with aria-required=\"true\" on the input for complete accessibility."}], "roles": ["label (native HTML)"], "keyboard": [{"key": "click on label", "actionKey": "components.label.a11y.key_click", "actionFallback": "Clicking the label focuses its associated input (native <label> for= binding)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-label---color", "descriptionKey": "components.label.tokens.color", "descriptionFallback": "Default label text color."}, {"type": "dimension", "value": "var(--origam-font__size---md)", "tokenPath": "--origam-label---font-size", "descriptionKey": "components.label.tokens.font_size", "descriptionFallback": "Default font size."}, {"type": "fontWeight", "value": "var(--origam-font__weight---regular)", "tokenPath": "--origam-label---font-weight", "descriptionKey": "components.label.tokens.font_weight", "descriptionFallback": "Label font weight."}, {"type": "duration", "value": "var(--origam-motion__duration---normal)", "tokenPath": "--origam-label---transition-duration", "descriptionKey": "components.label.tokens.transition_duration", "descriptionFallback": "Duration of float animation transitions."}, {"type": "color", "value": "var(--origam-color__feedback--danger---fgSubtle)", "tokenPath": "--origam-label---required-indicator-color", "descriptionKey": "components.label.tokens.required_indicator_color", "descriptionFallback": "Color of the asterisk required indicator."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"500\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"300\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"120\" y=\"76\" font-size=\"13\" fill=\"var(--origam-color__text---primary, #1a1a2e)\" font-family=\"''JetBrains Mono'',monospace\">Label text</text>\n  <text x=\"240\" y=\"70\" font-size=\"10\" fill=\"var(--origam-color__feedback--danger---bg, #ef4444)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">*</text>\n  <circle cx=\"36\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"248\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"248\" y=\"64.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"46\" y1=\"40\" x2=\"80\" y2=\"22\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"22\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-label</text>\n  <line x1=\"248\" y1=\"69\" x2=\"248\" y2=\"118\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"180\" y=\"132\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">sup · visible when required=true</text>\n", "code": "<!-- root: <label> by default -->\n<component :is=\"tag\" class=\"origam-label\" @click=\"handleClick\">\n  <!-- default slot or text prop -->\n  <slot>\n    <span>{{ text }}</span>\n    <!-- required indicator -->\n    <sup v-if=\"required\">*</sup>\n  </slot>\n</component>", "legend": [{"cls": ".origam-label", "num": 1, "descriptionKey": "components.label.anatomy.root", "descriptionFallback": "Root element. Renders as <code>&lt;label&gt;</code> by default. Accepts <code>tag</code> override."}, {"cls": ".origam-label sup", "num": 2, "descriptionKey": "components.label.anatomy.required", "descriptionFallback": "Required indicator <code>&lt;sup&gt;*&lt;/sup&gt;</code>. Only rendered when <code>required=true</code>. Color driven by <code>--origam-label---required-indicator-color</code>."}], "classes": [{"cls": "origam-label", "descriptionKey": "components.label.anatomy.root", "descriptionFallback": "Root element. Renders as <label> by default."}, {"cls": "origam-label--floating", "descriptionKey": "components.label.anatomy.floating", "descriptionFallback": "Applied when floating=true. Reduces font-size and hides the label until field activation."}], "svgDesc": "Schematic of the Label component with 2 numbered internal parts.", "svgTitle": "Anatomy of OrigamLabel", "rootClass": "origam-label", "figcaption": "Anatomy of <code>&lt;origam-label&gt;</code> — 2 internal parts. The required indicator ② is a <code>&lt;sup&gt;*&lt;/sup&gt;</code> appended when <code>required=true</code>.", "svgViewBox": "0 0 500 160"}, "cssVars": [{"name": "--origam-label---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.label.css_vars.color", "descriptionFallback": "Default label text color."}, {"name": "--origam-label---font-size", "defaultValue": "{font.size.md}", "descriptionKey": "components.label.css_vars.font_size", "descriptionFallback": "Default font size. Overridden to 1em when used inside OrigamField."}, {"name": "--origam-label---font-weight", "defaultValue": "{font.weight.regular}", "descriptionKey": "components.label.css_vars.font_weight", "descriptionFallback": "Label font weight."}, {"name": "--origam-label---line-height", "defaultValue": "{font.lineHeight.normal}", "descriptionKey": "components.label.css_vars.line_height", "descriptionFallback": "Label line height."}, {"name": "--origam-label---letter-spacing", "defaultValue": "{font.letterSpacing.normal}", "descriptionKey": "components.label.css_vars.letter_spacing", "descriptionFallback": "Label letter spacing."}, {"name": "--origam-label---pointer-events", "defaultValue": "none", "descriptionKey": "components.label.css_vars.pointer_events", "descriptionFallback": "Labels do not capture pointer events (positioned on top of input)."}, {"name": "--origam-label---transition-duration", "defaultValue": "{motion.duration.normal}", "descriptionKey": "components.label.css_vars.transition_duration", "descriptionFallback": "Duration of opacity/transform transitions for the float animation."}, {"name": "--origam-label---required-indicator-color", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.label.css_vars.required_indicator_color", "descriptionFallback": "Color of the asterisk required indicator <sup>*</sup>."}, {"name": "--origam-label__floating---font-size", "defaultValue": "0.75em", "descriptionKey": "components.label.css_vars.floating_font_size", "descriptionFallback": "Font size of the floating variant (clone shown in the field notch)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.label.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.label.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.label.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.label.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.label.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.label.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "required", "labelKey": "components.label.playground.required", "defaultValue": false, "labelFallback": "Required"}, {"kind": "switch", "prop": "floating", "labelKey": "components.label.playground.floating", "defaultValue": false, "labelFallback": "Floating"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}], "labelKey": "components.label.playground.color", "defaultValue": "", "labelFallback": "Color"}, {"kind": "select", "prop": "tag", "options": [{"label": "label", "value": "label"}, {"label": "span", "value": "span"}, {"label": "legend", "value": "legend"}], "labelKey": "components.label.playground.tag", "defaultValue": "label", "labelFallback": "Tag"}], "defaultSlotContent": "Email address"}, "previewVariants": [{"label": "default", "props": {}, "slotContent": "Email address"}, {"label": "required", "props": {"required": true}, "slotContent": "Password"}, {"label": "primary", "props": {"color": "primary"}, "slotContent": "Username"}, {"label": "danger", "props": {"color": "danger", "required": true}, "slotContent": "Error field"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('cb29bfe8-cf94-4f1d-879e-1d699a9ce9e1', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'layout', 'Layout', 'Layout & Structure', NULL, 'mdi-page-layout-body', 'components.catalog.layout.description', 'Root layout container that coordinates space-reservation for registered layout items (Drawer, AppBar, BottomNav, SystemBar). Pushes content automatically via CSS custom properties.', NULL, NULL, 'origam-layout', NULL, 'packages/ds/src/components/Layout/OrigamLayout.vue', 'origam', NULL, NULL, '/stories/?story=components-layout--design', '/docs/components/Layout/OrigamLayout.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.layout.a11y.landmark_note", "noteFallback": "OrigamLayout renders as a plain <div> — no ARIA landmark role. Use <origam-main> (renders as <main>) and <origam-system-bar> to provide landmark semantics for assistive technologies."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.layout.a11y.key_tab", "actionFallback": "Tab navigation flows through the interactive children inside the layout (drawer toggles, nav items, main content)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-layout---background-color", "descriptionKey": "components.layout.tokens.background_color", "descriptionFallback": "Default background color for the layout root."}, {"type": "other", "value": "flex", "tokenPath": "--origam-layout---display", "descriptionKey": "components.layout.tokens.display", "descriptionFallback": "Layout display mode (flex, column)."}, {"type": "other", "value": "100vw", "tokenPath": "--origam-layout__wrapper---width", "descriptionKey": "components.layout.tokens.wrapper_width", "descriptionFallback": "Wrapper width in full-height mode."}, {"type": "other", "value": "100vh", "tokenPath": "--origam-layout__wrapper---height", "descriptionKey": "components.layout.tokens.wrapper_height", "descriptionFallback": "Wrapper height in full-height mode."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"240\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"24\" y=\"24\" width=\"652\" height=\"192\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"24\" y=\"24\" width=\"652\" height=\"32\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"44\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">SystemBar / AppBar (layout item)</text>\n  <rect x=\"24\" y=\"56\" width=\"160\" height=\"160\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"104\" y=\"140\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Drawer</text>\n  <text x=\"104\" y=\"154\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">(layout item)</text>\n  <rect x=\"184\" y=\"56\" width=\"492\" height=\"160\" rx=\"0\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"430\" y=\"128\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-layout__wrapper</text>\n  <text x=\"430\" y=\"145\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">→ origam-main + slot content</text>\n  <circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"32\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"192\" cy=\"64\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"192\" y=\"68\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<div :id=\"layoutId\" ref=\"origamLayoutRef\" class=\"origam-layout\">\n  <div :id=\"`${layoutId}-wrapper`\" class=\"origam-layout__wrapper\">\n    <slot name=\"default\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-layout", "num": 1, "descriptionKey": "components.layout.anatomy.root", "descriptionFallback": "Root <code>&lt;div&gt;</code>. Emits <code>--origam-layout---position-{top,right,bottom,left}</code> CSS vars reflecting each registered item''s reserved space."}, {"cls": ".origam-layout__wrapper", "num": 2, "descriptionKey": "components.layout.anatomy.wrapper", "descriptionFallback": "Inner wrapper — <code>width: 100%; height: 100%</code>. In <code>full-height</code> mode switches to <code>100vw / 100vh</code>."}], "classes": [{"cls": "origam-layout", "descriptionKey": "components.layout.anatomy.root", "descriptionFallback": "Root element. position: relative; width: 100%; height: 100%."}, {"cls": "origam-layout__wrapper", "descriptionKey": "components.layout.anatomy.wrapper", "descriptionFallback": "Inner wrapper. width: 100%; height: 100%; max-height: 100%; max-width: 100%."}, {"cls": "origam-layout--full-height", "descriptionKey": "components.layout.anatomy.full_height", "descriptionFallback": "Applied when fullHeight=true. Switches wrapper to 100vw / 100vh."}], "svgDesc": "Schematic of the Layout component with its wrapper child and registered layout items.", "svgTitle": "Anatomy of OrigamLayout", "rootClass": "origam-layout", "figcaption": "Anatomy of <code>&lt;origam-layout&gt;</code> — root wrapper (①) + inner <code>__wrapper</code> (②) that receives the content. Layout items (Drawer, AppBar…) register themselves and carve space via CSS vars.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-layout---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.layout.css_vars.background_color", "descriptionFallback": "Layout background color."}, {"name": "--origam-layout---position-top", "defaultValue": "0px", "descriptionKey": "components.layout.css_vars.position_top", "descriptionFallback": "Space reserved at the top by registered layout items (e.g. AppBar height). Consumed by OrigamMain as padding-block-start."}, {"name": "--origam-layout---position-bottom", "defaultValue": "0px", "descriptionKey": "components.layout.css_vars.position_bottom", "descriptionFallback": "Space reserved at the bottom (e.g. BottomNav height). Consumed by OrigamMain as padding-block-end."}, {"name": "--origam-layout---position-left", "defaultValue": "0px", "descriptionKey": "components.layout.css_vars.position_left", "descriptionFallback": "Space reserved on the left (e.g. Drawer width). Consumed by OrigamMain as padding-inline-start."}, {"name": "--origam-layout---position-right", "defaultValue": "0px", "descriptionKey": "components.layout.css_vars.position_right", "descriptionFallback": "Space reserved on the right (e.g. rail nav width). Consumed by OrigamMain as padding-inline-end."}], "exposed": [{"name": "getLayoutItem", "type": "(id: string) => ILayerItem | undefined", "descriptionKey": "components.layout.exposed.get_layout_item", "descriptionFallback": "Returns the layout metadata (position, size, id) of a registered item by its string ID."}, {"name": "items", "type": "Ref<Array<ILayerItem>>", "descriptionKey": "components.layout.exposed.items", "descriptionFallback": "Reactive array of all registered layout items with their current positions and sizes."}, {"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.layout.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.layout.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.layout.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.layout.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.layout.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.layout.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "fullHeight", "labelKey": "components.layout.playground.full_height", "defaultValue": false, "labelFallback": "Full height (100vw/100vh)"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(default)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "surface", "value": "surface"}], "labelKey": "components.layout.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "select", "prop": "elevation", "options": [{"label": "(none)", "value": ""}, {"label": "1", "value": "1"}, {"label": "2", "value": "2"}, {"label": "4", "value": "4"}], "labelKey": "components.layout.playground.elevation", "defaultValue": "", "labelFallback": "Elevation"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('bef66f68-56fb-4e3b-ae44-decf77a6fe96', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'lazy', 'Lazy', 'Layout & Structure', NULL, 'mdi-image-filter-none', 'components.catalog.lazy.description', 'Defers the mounting of its children until the placeholder enters the viewport. Uses IntersectionObserver (v-intersect directive) with an optional fade-in transition.', NULL, NULL, 'origam-lazy', NULL, 'packages/ds/src/components/Lazy/OrigamLazy.vue', 'origam', NULL, NULL, '/stories/?story=components-lazy--design', '/docs/components/Lazy/OrigamLazy.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.lazy.a11y.aria_busy_note", "noteFallback": "While the content is not yet revealed, the root element carries <code>aria-busy=\"true\"</code>. This signals to assistive technologies that the region is still loading."}, {"noteKey": "components.lazy.a11y.intersection_note", "noteFallback": "OrigamLazy relies on IntersectionObserver. Ensure placeholder dimensions are set (min-height / height) so the browser can observe a non-zero element. A zero-size element may never intersect and the content would never mount."}, {"noteKey": "components.lazy.a11y.reduced_motion_note", "noteFallback": "The default OrigamFade transition respects prefers-reduced-motion: reduce — pass transition=\"null\" to fully disable animation."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"24\" y=\"24\" width=\"300\" height=\"152\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <text x=\"174\" y=\"96\" font-size=\"11\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">placeholder</text>\n  <text x=\"174\" y=\"112\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">(min-height applied, children not mounted)</text>\n  <rect x=\"376\" y=\"24\" width=\"300\" height=\"152\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"526\" y=\"88\" font-size=\"11\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">revealed</text>\n  <text x=\"526\" y=\"104\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">(children mounted + fade transition)</text>\n  <circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\"/>\n  <text x=\"32\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"384\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"384\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<component :is=\"tag\" v-intersect=\"intersect\" :aria-busy=\"!isActive || undefined\" class=\"origam-lazy\">\n  <!-- children rendered only when isActive=true -->\n  <template v-if=\"isActive\">\n    <origam-transition :transition=\"transition\" appear>\n      <slot name=\"default\" />\n    </origam-transition>\n  </template>\n</component>", "legend": [{"cls": ".origam-lazy (placeholder)", "num": 1, "descriptionKey": "components.lazy.anatomy.placeholder", "descriptionFallback": "While <code>isActive=false</code>, the root element is an empty block with the configured dimensions. The <code>v-intersect</code> directive watches it."}, {"cls": ".origam-lazy (revealed)", "num": 2, "descriptionKey": "components.lazy.anatomy.revealed", "descriptionFallback": "Once <code>isActive=true</code>, the default slot is rendered inside an <code>&lt;origam-transition&gt;</code> (OrigamFade by default). The element is never hidden again."}], "classes": [{"cls": "origam-lazy", "descriptionKey": "components.lazy.anatomy.root", "descriptionFallback": "Root element. Carries dimension styles and the v-intersect watcher."}], "svgDesc": "Schematic of the Lazy component in its two states: placeholder and revealed.", "svgTitle": "Anatomy of OrigamLazy", "rootClass": "origam-lazy", "figcaption": "Anatomy of <code>&lt;origam-lazy&gt;</code> — ① placeholder state (children unmounted, min-height reserves space for IntersectionObserver) → ② revealed state (children mounted with transition).", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-lazy---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.lazy.css_vars.transition_duration", "descriptionFallback": "Duration of the reveal transition (OrigamFade)."}, {"name": "--origam-lazy---transition-timing-function", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.lazy.css_vars.transition_timing_function", "descriptionFallback": "Easing of the reveal transition."}, {"name": "--origam-lazy---placeholder-min-height", "defaultValue": "{space.10}", "descriptionKey": "components.lazy.css_vars.placeholder_min_height", "descriptionFallback": "Minimum height of the placeholder zone so the IntersectionObserver has something to detect."}, {"name": "--origam-lazy---placeholder-background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.lazy.css_vars.placeholder_background_color", "descriptionFallback": "Background color of the placeholder zone (visible only before reveal)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.lazy.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.lazy.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.lazy.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.lazy.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.lazy.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.lazy.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "modelValue", "labelKey": "components.lazy.playground.model_value", "defaultValue": false, "labelFallback": "Revealed (modelValue)"}, {"kind": "text", "prop": "height", "labelKey": "components.lazy.playground.height", "defaultValue": "200", "labelFallback": "Height (placeholder)"}, {"kind": "select", "prop": "tag", "options": [{"label": "div", "value": "div"}, {"label": "section", "value": "section"}, {"label": "article", "value": "article"}], "labelKey": "components.lazy.playground.tag", "defaultValue": "div", "labelFallback": "Tag"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
