, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-check", "value": "mdi-check"}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-close", "value": "mdi-close"}], "labelKey": "components.ligature_icon.playground.icon", "defaultValue": "", "labelFallback": "Icon"}]}, "previewVariants": [{"label": "home", "props": {"icon": "home", "size": "large"}}, {"label": "primary", "props": {"icon": "favorite", "size": "large", "color": "primary"}}, {"label": "danger", "props": {"icon": "close", "size": "large", "color": "danger"}}, {"label": "x-large", "props": {"icon": "star", "size": "x-large"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
