INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8299d4db-046c-45fa-9d57-04eaa1dde5ac', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'parallax-element', 'ParallaxElement', 'Media', NULL, 'mdi-layers-outline', 'components.catalog.parallax_element.description', 'Individually moving element inside a Parallax container. Driven by mouse position, scroll or audio data. Uses translate, rotate, scale or opacity transforms.', NULL, NULL, 'origam-parallax-element', NULL, 'packages/ds/src/components/Parallax/OrigamParallaxElement.vue', 'origam', NULL, NULL, '/stories/?story=components-parallax--design', '/docs/components/Parallax/OrigamParallax.html', 'parallax', '{"a11y": {"notes": [{"noteKey": "components.parallax_element.a11y.reduced_motion", "noteFallback": "The transform transition is inherited from the host Parallax. Under prefers-reduced-motion: reduce, the host disables transitions, so all element movements stop automatically."}, {"noteKey": "components.parallax_element.a11y.no_role", "noteFallback": "ParallaxElement is a presentational wrapper — it carries no ARIA role. Accessible text must come from the slotted content."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "other", "value": "1000px", "tokenPath": "--origam-parallax---perspective", "descriptionKey": "components.parallax_element.tokens.perspective", "descriptionFallback": "CSS perspective value set on the host Parallax container."}, {"type": "other", "value": "center center", "tokenPath": "--origam-parallax---transform-origin", "descriptionKey": "components.parallax_element.tokens.transform_origin", "descriptionFallback": "Default transform-origin for the host container. Elements can override via the transformOrigin prop."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"30\" y=\"30\" width=\"540\" height=\"160\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <text x=\"300\" y=\"20\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"600\">origam-parallax (host)</text>\n  <rect x=\"80\" y=\"60\" width=\"440\" height=\"110\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__action--primary---bgHover, #a855f7)\" stroke-width=\"1.5\"/>\n  <text x=\"300\" y=\"90\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-parallax-element</text>\n  <rect x=\"140\" y=\"100\" width=\"320\" height=\"50\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"300\" y=\"130\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot — user content</text>\n  <circle cx=\"38\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"42\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"88\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"88\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"148\" cy=\"108\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"148\" y=\"112\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"300\" y=\"198\" font-size=\"8\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Transform driven by mouse position / scroll / audio via inject(ORIGAM_PARALLAX_KEY)</text>\n", "code": "<!-- Must be nested inside origam-parallax -->\n<origam-parallax event=\"move\" direction=\"both\" :height=\"400\">\n  <!-- root receives computed transform + transition styles -->\n  <component :is=\"tag\" class=\"origam-parallax-element\" :style=\"parallaxElementStyles\">\n    <slot name=\"default\" />\n  </component>\n</origam-parallax>", "legend": [{"cls": ".origam-parallax (host)", "num": 1, "descriptionKey": "components.parallax_element.anatomy.host", "descriptionFallback": "Parent OrigamParallax required as the injection context. Provides movement data via provide(ORIGAM_PARALLAX_KEY)."}, {"cls": ".origam-parallax-element", "num": 2, "descriptionKey": "components.parallax_element.anatomy.root", "descriptionFallback": "Root element. Receives the computed CSS transform (translate/rotate/scale/opacity) and transition parameters on each animation frame."}, {"cls": "#default slot", "num": 3, "descriptionKey": "components.parallax_element.anatomy.slot", "descriptionFallback": "User content rendered inside the animated root. Any markup is valid."}], "classes": [{"cls": "origam-parallax-element", "descriptionKey": "components.parallax_element.anatomy.root", "descriptionFallback": "Root block element. Renders as the tag prop value (default: div). Carries all transform and border/rounded/elevation classes."}], "svgDesc": "Schematic of the ParallaxElement component with 3 numbered internal parts.", "svgTitle": "Anatomy of OrigamParallaxElement", "rootClass": "origam-parallax-element", "figcaption": "Anatomy of <code>&lt;origam-parallax-element&gt;</code> — 3 parts: ① host container, ② root element (receives transform style), ③ default slot content.", "svgViewBox": "0 0 600 220"}, "cssVars": [{"name": "--origam-parallax---perspective", "defaultValue": "1000px", "descriptionKey": "components.parallax_element.css_vars.perspective", "descriptionFallback": "CSS perspective depth inherited from the host Parallax. Applied on the parent container, not the element itself."}, {"name": "--origam-parallax__element---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.parallax_element.css_vars.transition_duration", "descriptionFallback": "Transition duration for the transform applied to each element. Sourced from parallax.element.transition-duration token."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.parallax_element.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.parallax_element.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed parallaxElementStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.parallax_element.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.parallax_element.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.parallax_element.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.parallax_element.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "rounded", "options": [{"label": "(default)", "value": ""}, {"label": "ROUNDED.X_SMALL", "value": "ROUNDED.X_SMALL"}, {"label": "x-small", "value": "x-small"}, {"label": "ROUNDED.SMALL", "value": "ROUNDED.SMALL"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "ROUNDED.DEFAULT", "value": "ROUNDED.DEFAULT"}, {"label": "ROUNDED.MEDIUM", "value": "ROUNDED.MEDIUM"}, {"label": "medium", "value": "medium"}, {"label": "large", "value": "large"}, {"label": "ROUNDED.LARGE", "value": "ROUNDED.LARGE"}, {"label": "x-large", "value": "x-large"}, {"label": "ROUNDED.X_LARGE", "value": "ROUNDED.X_LARGE"}, {"label": "shaped", "value": "shaped"}, {"label": "ROUNDED.SHAPED", "value": "ROUNDED.SHAPED"}, {"label": "shaped-invert", "value": "shaped-invert"}, {"label": "ROUNDED.SHAPED_INVERT", "value": "ROUNDED.SHAPED_INVERT"}], "labelKey": "components.parallax_element.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "select", "prop": "axis", "options": [{"label": "(default)", "value": ""}, {"label": "x", "value": "x"}, {"label": "y", "value": "y"}], "labelKey": "components.parallax_element.playground.axis", "defaultValue": "", "labelFallback": "Axis"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c23f70d0-5cbf-463d-b7de-6b20cf527f97', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'password-field', 'PasswordField', 'Form & Input', NULL, 'mdi-lock-outline', 'components.catalog.password_field.description', 'Secure password input with show/hide toggle, 4-segment strength bar, and a requirements checklist (list or tile layout). Automatically injects validation rules for enabled requirements.', NULL, NULL, 'origam-password-field', NULL, 'packages/ds/src/components/PasswordField/OrigamPasswordField.vue', 'origam', NULL, NULL, '/stories/?story=components-passwordfield--design', '/docs/components/PasswordField/OrigamPasswordField.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.password_field.a11y.toggle_note", "noteFallback": "The show/hide toggle is a button element with aria-label that changes between \"Show password\" and \"Hide password\" depending on state."}, {"noteKey": "components.password_field.a11y.requirements_note", "noteFallback": "The requirements popup opens with aria-haspopup=\"listbox\" on the input. Each requirement item announces its state via a visually-hidden text or the icon''s aria-hidden."}, {"noteKey": "components.password_field.a11y.strength_note", "noteFallback": "The strength bar is visual only (aria-hidden). Strength feedback is conveyed via the requirements checklist and the update:strength emit, which the parent can use to show a text label."}], "roles": ["textbox"], "keyboard": [{"key": "Tab", "actionKey": "components.password_field.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element (input → toggle icon)."}, {"key": "Enter / Space (on toggle icon)", "actionKey": "components.password_field.a11y.key_toggle", "actionFallback": "Reveals or hides the password."}]}, "tokens": {"excerpt": [{"type": "number", "value": "0.2", "tokenPath": "--origam-password-field__item-icon---opacity", "descriptionKey": "components.password_field.tokens.item_icon_opacity", "descriptionFallback": "Default icon opacity (unmet requirement)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"260\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"30\" y=\"20\" width=\"640\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.4))\" stroke-width=\"1.5\"/>\n  <text x=\"60\" y=\"38\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #7c3aed)\" font-family=\"''JetBrains Mono'',monospace\">Password</text>\n  <rect x=\"60\" y=\"44\" width=\"540\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\"/>\n  <text x=\"80\" y=\"60\" font-size=\"12\" fill=\"var(--origam-color__text---primary, #444)\" letter-spacing=\"4\">••••••••</text>\n  <rect x=\"620\" y=\"44\" width=\"36\" height=\"24\" rx=\"3\" fill=\"transparent\"/>\n  <text x=\"638\" y=\"60\" font-size=\"14\" fill=\"var(--origam-color__text---secondary, #7c3aed)\" text-anchor=\"middle\">👁</text>\n  <rect x=\"30\" y=\"86\" width=\"640\" height=\"8\" rx=\"4\" fill=\"var(--origam-color__surface---disabled, rgba(124,58,237,0.15))\"/>\n  <rect x=\"30\" y=\"86\" width=\"160\" height=\"8\" rx=\"4\" fill=\"var(--origam-color__feedback--danger---bg, rgba(239,68,68,0.7))\"/>\n  <rect x=\"192\" y=\"86\" width=\"160\" height=\"8\" rx=\"4\" fill=\"var(--origam-color__feedback--warning---bg, rgba(245,158,11,0.7))\"/>\n  <rect x=\"354\" y=\"86\" width=\"160\" height=\"8\" rx=\"4\" fill=\"var(--origam-color__surface---disabled, rgba(124,58,237,0.15))\"/>\n  <rect x=\"516\" y=\"86\" width=\"154\" height=\"8\" rx=\"4\" fill=\"var(--origam-color__surface---disabled, rgba(124,58,237,0.15))\"/>\n  <rect x=\"30\" y=\"106\" width=\"640\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.2))\" stroke-width=\"1\"/>\n  <rect x=\"50\" y=\"118\" width=\"580\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\"/>\n  <text x=\"70\" y=\"134\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #7c3aed)\" font-family=\"''JetBrains Mono'',monospace\">origam-password-field__item  — \"8+ characters\"  ✓</text>\n  <rect x=\"50\" y=\"148\" width=\"580\" height=\"24\" rx=\"3\" fill=\"transparent\"/>\n  <text x=\"70\" y=\"164\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" font-family=\"''JetBrains Mono'',monospace\">origam-password-field__item  — \"Uppercase letter\"  ○</text>\n  <rect x=\"50\" y=\"178\" width=\"580\" height=\"24\" rx=\"3\" fill=\"transparent\"/>\n  <text x=\"70\" y=\"194\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" font-family=\"''JetBrains Mono'',monospace\">origam-password-field__item  — \"Number\"  ○</text>\n  <circle cx=\"26\" cy=\"24\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"26\" y=\"28\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"616\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"616\" y=\"52\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"26\" cy=\"90\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"26\" y=\"94\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"26\" cy=\"110\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"26\" y=\"114\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"44\" cy=\"122\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"44\" y=\"126\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"44\" cy=\"152\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"44\" y=\"156\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <circle cx=\"44\" cy=\"182\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"44\" y=\"186\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">7</text>\n", "code": "<origam-text-field class=\"origam-password-field\">\n  <!-- #default slot: the input with appended toggle -->\n  <template #default>\n    <input :type=\"isVisible ? ''text'' : ''password''\" />\n\n    <!-- show/hide toggle -->\n    <span class=\"origam-password-field__toggle-icon\">\n      <origam-icon :icon=\"isVisible ? offIcon : onIcon\" />\n    </span>\n\n    <!-- requirements popup (menu) -->\n    <origam-menu content-class=\"origam-password-field__info\">\n      <slot name=\"info\">\n        <div class=\"origam-password-field__item\"\n          v-for=\"rule in requirementRules\">\n          <div class=\"origam-password-field__validate\">\n            <origam-icon class=\"origam-password-field__icon\" />\n          </div>\n        </div>\n      </slot>\n    </origam-menu>\n  </template>\n\n  <!-- details slot: strength bar + inline requirements -->\n  <template #details>\n    <div class=\"origam-password-field__inline-footer\">\n      <div class=\"origam-password-field__strength\">\n        <span\n          v-for=\"i in 4\"\n          class=\"origam-password-field__strength-segment\"\n        />\n      </div>\n\n      <!-- list layout -->\n      <ul class=\"origam-password-field__requirements origam-password-field__requirements--list\">\n        <li\n          v-for=\"rule in requirementRules\"\n          class=\"origam-password-field__item\"\n        >\n          <span class=\"origam-password-field__requirement-icon\" />\n          <span class=\"origam-password-field__requirement-label\">{{ rule.label }}</span>\n        </li>\n      </ul>\n    </div>\n  </template>\n</origam-text-field>", "legend": [{"cls": ".origam-password-field", "num": 1, "descriptionKey": "components.password_field.anatomy.root", "descriptionFallback": "Root OrigamTextField wrapper with type=\"password\" wiring."}, {"cls": ".origam-password-field__toggle-icon", "num": 2, "descriptionKey": "components.password_field.anatomy.toggle_icon", "descriptionFallback": "Show/hide toggle button in the appendInner slot. Icon swaps between onIcon and offIcon."}, {"cls": ".origam-password-field__strength", "num": 3, "descriptionKey": "components.password_field.anatomy.strength", "descriptionFallback": "4-segment strength bar. Visible when strengthBar=true. Segments fill based on computed level."}, {"cls": ".origam-password-field__inline-footer", "num": 4, "descriptionKey": "components.password_field.anatomy.inline_footer", "descriptionFallback": "Container rendered in the details slot, hosting the strength bar and requirements list."}, {"cls": ".origam-password-field__requirements", "num": 5, "descriptionKey": "components.password_field.anatomy.requirements", "descriptionFallback": "Requirements list container. Modifier --list or --tiles controls the layout."}, {"cls": ".origam-password-field__item", "num": 6, "descriptionKey": "components.password_field.anatomy.item", "descriptionFallback": "Individual requirement row or tile. Gets --valid modifier when the predicate passes."}, {"cls": ".origam-password-field__requirement-icon", "num": 7, "descriptionKey": "components.password_field.anatomy.requirement_icon", "descriptionFallback": "Check or cross icon for each requirement. Opacity: 0.2 (unmet) → 1 (met)."}], "classes": [{"cls": "origam-password-field", "descriptionKey": "components.password_field.anatomy.root", "descriptionFallback": "Root field container."}, {"cls": "origam-password-field__toggle-icon", "descriptionKey": "components.password_field.anatomy.toggle_icon", "descriptionFallback": "Show/hide toggle icon wrapper in the appendInner slot."}, {"cls": "origam-password-field__info", "descriptionKey": "components.password_field.anatomy.info", "descriptionFallback": "Requirements popup content class applied to the OrigamMenu."}, {"cls": "origam-password-field__item", "descriptionKey": "components.password_field.anatomy.item", "descriptionFallback": "Individual requirement row. Gets --valid modifier when test() returns true."}, {"cls": "origam-password-field__item--valid", "descriptionKey": "components.password_field.anatomy.item_valid", "descriptionFallback": "BEM modifier applied when the requirement predicate is satisfied."}, {"cls": "origam-password-field__validate", "descriptionKey": "components.password_field.anatomy.validate", "descriptionFallback": "Absolute-positioned checkmark badge on the tile corner."}, {"cls": "origam-password-field__icon", "descriptionKey": "components.password_field.anatomy.icon", "descriptionFallback": "Glyph icon (45px, bold). Opacity 0.2 unmet → 1 met."}, {"cls": "origam-password-field__inline-footer", "descriptionKey": "components.password_field.anatomy.inline_footer", "descriptionFallback": "Details slot container for strength bar + inline requirements list."}, {"cls": "origam-password-field__strength", "descriptionKey": "components.password_field.anatomy.strength", "descriptionFallback": "Strength bar wrapper containing 4 __strength-segment spans."}, {"cls": "origam-password-field__strength-segment", "descriptionKey": "components.password_field.anatomy.strength_segment", "descriptionFallback": "One segment of the 4-part strength ba