INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b6760e25-ca06-49ac-b665-f66a0067021c', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'picker', 'Picker', 'Overlay & Surface', NULL, 'mdi-calendar-blank-outline', 'components.catalog.picker.description', 'Base picker chrome shared by DatePicker and ColorPicker. Provides a card panel with title, optional header, body slot, and actions footer. Supports landscape orientation and full token customisation.', NULL, NULL, 'origam-picker', NULL, 'packages/ds/src/components/Picker/OrigamPicker.vue', 'origam', NULL, NULL, '/stories/?story=components-datepicker--design', '/docs/components/Picker/OrigamPicker.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.picker.a11y.role_note", "noteFallback": "When used standalone, OrigamPicker has no implicit ARIA role. When opened inside a Dialog or Overlay, it inherits role=\"dialog\" from the container."}, {"noteKey": "components.picker.a11y.title_note", "noteFallback": "The title prop / #title slot provides a visible label. The parent overlay should reference it via aria-labelledby for screen reader context."}], "roles": ["dialog"], "keyboard": [{"key": "Escape", "actionKey": "components.picker.a11y.key_close", "actionFallback": "Closes the picker when used inside an overlay (DatePickerField, ColorPickerField)."}, {"key": "Tab", "actionKey": "components.picker.a11y.key_tab", "actionFallback": "Moves focus through the picker controls in order."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---raised)", "tokenPath": "--origam-picker---background-color", "descriptionKey": 