INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a370d01a-0ef8-4ea8-bd3a-d29294a01b6f', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'scale-rotate', 'ScaleRotate', 'Utilities & Providers', NULL, 'mdi-rotate-3d-variant', 'components.catalog.transition_scale_rotate.description', 'CSS-driven Vue transition that combines scale(0) + rotate(−45deg) + opacity on enter, with a symmetric leave. Sub-component of the Transition family.', NULL, NULL, 'origam-scale-rotate', NULL, 'packages/ds/src/components/Transition/OrigamScaleRotate.vue', 'origam', NULL, NULL, '/stories/?story=components-transition--design', '/docs/components/Transition/OrigamTransition.html', 'transition', '{"a11y": {"notes": [{"noteKey": "components.scale_rotate.a11y.reduced_motion", "noteFallback": "The transition is disabled automatically when prefers-reduced-motion: reduce is detected (disabled prop becomes true via useCssTransition)."}, {"noteKey": "components.scale_rotate.a11y.no_role", "noteFallback": "The wrapper is transparent to the accessibility tree. Only the slotted child is announced by screen readers."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"40\" width=\"260\" height=\"100\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"170\" y=\"86\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">enter-active</text>\n  <text x=\"170\" y=\"102\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">scale(0) rotate(−45deg) → full</text>\n  <rect x=\"400\" y=\"40\" width=\"260\" height=\"100\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"5 3\" opacity=\"0.5\"/>\n  <text x=\"530\" y=\"86\" font-size=\"11\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">leave-active</text>\n  <text x=\"530\" y=\"102\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">full → opacity 0</text>\n  <circle cx=\"48\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"408\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"408\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"95\" font-size=\"22\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">→</text>\n", "code": "<!-- wraps <transition> or <transition-group> via useCssTransition -->\n<component :is=\"tag\" :name=\"name\" v-bind=\"transitionProps\">\n  <slot name=\"default\" />\n</component>\n\n<!-- CSS keyframes (global, not scoped) -->\n<!-- .origam-transition--scale-rotate-enter-from { opacity: 0; transform: scale(0) rotate(-45deg); }\n     .origam-transition--scale-rotate-enter-active,\n     .origam-transition--scale-rotate-leave-active { transition-property: transform, opacity; transition-duration: 0.3s; } -->", "legend": [{"cls": ".origam-transition--scale-rotate-enter-active", "num": 1, "descriptionKey": "components.scale_rotate.anatomy.enter", "descriptionFallback": "Enter phase. Child animates from scale(0) rotate(−45deg) opacity:0 to identity. Duration: 0.3 s, easing: cubic-bezier(0.4,0,0.2,1)."}, {"cls": ".origam-transition--scale-rotate-leave-active", "num": 2, "descriptionKey": "components.scale_rotate.anatomy.leave", "descriptionFallback": "Leave phase. Child transitions opacity and transform out over 0.3 s."}], "classes": [{"cls": "origam-transition--scale-rotate", "descriptionKey": "components.scale_rotate.anatomy.class_root", "descriptionFallback": "CSS transition class prefix applied by Vue."}, {"cls": "origam-transition--scale-rotate-enter-from", "descriptionKey": "components.scale_rotate.anatomy.class_enter_from", "descriptionFallback": "Starting state: opacity:0, transform: scale(0) rotate(−45deg)."}, {"cls": "origam-transition--scale-rotate-enter-active", "descriptionKey": "components.scale_rotate.anatomy.class_enter_active", "descriptionFallback": "Transition active state for enter (0.3 s, standard easing)."}, {"cls": "origam-transition--scale-rotate-leave-active", "descriptionKey": "components.scale_rotate.anatomy.class_leave_active", "descriptionFallback": "Transition active state for leave (0.3 s)."}, {"cls": "origam-transition--scale-rotate-move", "descriptionKey": "components.scale_rotate.anatomy.class_move", "descriptionFallback": "Move transition applied in group mode (0.5 s, transform-only)."}], "svgDesc": "Schematic of the scale-rotate transition with entering and leaving elements.", "svgTitle": "Anatomy of OrigamScaleRotate", "rootClass": "origam-transition--scale-rotate", "figcaption": "Anatomy of <code>&lt;origam-scale-rotate&gt;</code> — wraps one child element. The enter ① animates from scale(0) + rotate(−45deg) + opacity:0 to full. The leave ② transitions opacity out over 0.3 s.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-transition---default-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.scale_rotate.css_vars.duration", "descriptionFallback": "Default transition duration for the scale-rotate animation (0.3 s hardcoded in the CSS class, token reference for override)."}, {"name": "--origam-transition---default-easing", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.scale_rotate.css_vars.easing", "descriptionFallback": "Easing function: cubic-bezier(0.4, 0, 0.2, 1)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.scale_rotate.exposed.filter_props", "descriptionFallback": "Forwards a filtered subset of props to the underlying transition."}], "playground": {"controls": [{"kind": "select", "prop": "mode", "options": [{"label": "(none)", "value": ""}, {"label": "in-out", "value": "in-out"}, {"label": "out-in", "value": "out-in"}], "labelKey": "components.scale_rotate.playground.mode", "defaultValue": "", "labelFallback": "Mode"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.scale_rotate.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "group", "labelKey": "components.scale_rotate.playground.group", "defaultValue": false, "labelFallback": "Group mode"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d33b8498-30ad-4e0b-bfb8-8b85c7d2a6f1', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'select', 'Select', 'Form & Input', NULL, 'mdi-form-select', 'components.catalog.select.description', 'Dropdown selection control with single/multiple mode, chip display, search/autocomplete, and full TextField chrome (label, prefix, suffix, clearable).', NULL, NULL, 'origam-select', NULL, 'packages/ds/src/components/Select/OrigamSelect.vue', 'origam', NULL, NULL, '/stories/?story=components-select--design', '/docs/components/Select/OrigamSelect.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.select.a11y.combobox_note", "noteFallback": "The field uses role=\"combobox\" with aria-expanded reflecting the menu state and aria-haspopup=\"listbox\". The dropdown list has role=\"listbox\" and each item has role=\"option\"."}, {"noteKey": "components.select.a11y.aria_label_note", "noteFallback": "The label prop is used as aria-label on the internal text field. When using a placeholder-only UI, also provide an explicit aria-label for screen readers."}, {"noteKey": "components.select.a11y.multiple_note", "noteFallback": "In multiple mode, aria-multiselectable=\"true\" is set on the listbox. Each selected option has aria-selected=\"true\"."}], "roles": ["combobox", "listbox", "option"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.select.a11y.key_enter", "actionFallback": "Opens the dropdown or confirms the highlighted option."}, {"key": "Escape", "actionKey": "components.select.a11y.key_escape", "actionFallback": "Closes the dropdown without changing the selection."}, {"key": "Arrow Down / Up", "actionKey": "components.select.a11y.key_arrows", "actionFallback": "Navigates between items in the open dropdown list."}, {"key": "Tab", "actionKey": "components.select.a11y.key_tab", "actionFallback": "Closes the dropdown and moves focus to the next element."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"520\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"40\" y=\"43\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">Framework</text>\n  <text x=\"40\" y=\"64\" font-size=\"12\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">Vue 3</text>\n  <text x=\"510\" y=\"56\" font-size=\"18\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">▾</text>\n  <rect x=\"20\" y=\"100\" width=\"520\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"46\" y=\"122\" font-size=\"11\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-family=\"''JetBrains Mono'',monospace\">Vue 3</text>\n  <text x=\"46\" y=\"146\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">React</text>\n  <text x=\"46\" y=\"166\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">Svelte</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"48\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"48\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"120\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"120\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"510\" cy=\"40\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"510\" y=\"44\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"28\" cy=\"108\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"112\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"46\" cy=\"122\" r=\"7\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"46\" y=\"126\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n", "code": "<!-- extends TextField chrome -->\n<origam-text-field class=\"origam-select origam-select--single\">\n  <!-- dropdown via OrigamMenu -->\n  <origam-menu content-class=\"origam-select__content\">\n    <origam-list class=\"origam-select__menu-list\">\n      <origam-list-item>\n        <!-- item text with optional search highlight -->\n        <span class=\"origam-select__text\">Vue 3</span>\n      </origam-list-item>\n    </origam-list>\n  </origam-menu>\n\n  <!-- selected value display -->\n  <span class=\"origam-select__selection-text\">Vue 3</span>\n\n  <!-- menu toggle chevron (appendInner) -->\n  <origam-icon class=\"origam-select__menu-icon\" />\n</origam-text-field>", "legend": [{"cls": ".origam-select", "num": 1, "descriptionKey": "components.select.anatomy.root", "descriptionFallback": "Root element extending OrigamTextField. Carries BEM modifiers for single/multiple, chips, autocomplete and open states."}, {"cls": "origam-select (label via TextField)", "num": 2, "descriptionKey": "components.select.anatomy.label", "descriptionFallback": "Floating label managed by the inner TextField field slot."}, {"cls": ".origam-select__selection-text", "num": 3, "descriptionKey": "components.select.anatomy.selection_text", "descriptionFallback": "Selected value text displayed inside the field when not in chip mode."}, {"cls": ".origam-select__menu-icon", "num": 4, "descriptionKey": "components.select.anatomy.menu_icon", "descriptionFallback": "Chevron icon toggling the dropdown. Rotates 180° when the menu is open."}, {"cls": ".origam-select__content (inside OrigamMenu)", "num": 5, "descriptionKey": "components.select.anatomy.content", "descriptionFallback": "Dropdown container rendered by OrigamMenu. Contains the OrigamList of items."}, {"cls": ".origam-select__text / .origam-select__mask", "num": 6, "descriptionKey": "components.select.anatomy.text", "descriptionFallback": "Per-item text label. Includes .origam-select__mask and .origam-select__unmask for the search-highlight animation."}], "classes": [{"cls": "origam-select", "descriptionKey": "components.select.anatomy.root", "descriptionFallback": "Root block."}, {"cls": "origam-select--single", "descriptionKey": "components.select.anatomy.modifier_single", "descriptionFallback": "Applied when multiple=false."}, {"cls": "origam-select--multiple", "descriptionKey": "components.select.anatomy.modifier_multiple", "descriptionFallback": "Applied when multiple=true."}, {"cls": "origam-select--chips", "descriptionKey": "components.select.anatomy.modifier_chips", "descriptionFallback": "Applied when chips=true."}, {"cls": "origam-select--active-menu", "descriptionKey": "components.select.anatomy.modifier_active_menu", "descriptionFallback": "Applied while the dropdown is open."}, {"cls": "origam-select--autocomplete", "descriptionKey": "comp