INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('cea1617b-2d17-4d79-8ea0-bb09bc3f964f', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'selection-control', 'SelectionControl', 'Form & Input', NULL, 'mdi-checkbox-marked-circle-outline', 'components.catalog.selection_control.description', 'Base selection-control primitive used by Checkbox, Radio, Switch and similar inputs. Renders a ripple zone, a native input and a label with full ARIA support.', NULL, NULL, 'origam-selection-control', NULL, 'packages/ds/src/components/SelectionControl/OrigamSelectionControl.vue', 'origam', NULL, NULL, '/stories/?story=components-selection-control--design', '/docs/components/SelectionControl/OrigamSelectionControl.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.selection_control.a11y.native_note", "noteFallback": "A native <input type=\"checkbox|radio\"> is always rendered (even when the input slot is customised). This ensures browser-native focus, keyboard handling and form participation."}, {"noteKey": "components.selection_control.a11y.aria_checked_note", "noteFallback": "aria-checked is set automatically by the native input. For type=\"checkbox\", aria-checked is forwarded explicitly via the :aria-checked binding."}, {"noteKey": "components.selection_control.a11y.label_note", "noteFallback": "The label is wired to the input via for/id. Clicking the label toggles the control and fires click:label."}, {"noteKey": "components.selection_control.a11y.error_note", "noteFallback": "When error=true, the label and icon adopt --origam-selection-control---color-error for visual feedback. No aria-invalid is set at this layer — use OrigamInput / form-level components for validation semantics."}], "roles": ["checkbox", "radio"], "keyboard": [{"key": "Space", "actionKey": "components.selection_control.a11y.key_space", "actionFallback": "Toggles the checkbox or selects the radio option."}, {"key": "Tab", "actionKey": "components.selection_control.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---primary)", "tokenPath": "--origam-selection-control---color", "descriptionKey": "components.selection_control.tokens.color", "descriptionFallback": "Default control color."}, {"type": "color", "value": "var(--origam-color__text---disabled)", "tokenPath": "--origam-selection-control---color-disabled", "descriptionKey": "components.selection_control.tokens.color_disabled", "descriptionFallback": "Color when disabled."}, {"type": "number", "value": "var(--origam-opacity---50)", "tokenPath": "--origam-selection-control---opacity-disabled", "descriptionKey": "components.selection_control.tokens.opacity_disabled", "descriptionFallback": "Opacity when disabled."}, {"type": "dimension", "value": "40px", "tokenPath": "--origam-selection-control__wrapper---width", "descriptionKey": "components.selection_control.tokens.wrapper_width", "descriptionFallback": "Base width of the ripple wrapper (before density offset)."}, {"type": "dimension", "value": "40px", "tokenPath": "--origam-selection-control__wrapper---height", "descriptionKey": "components.selection_control.tokens.wrapper_height", "descriptionFallback": "Base height of the ripple wrapper."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-selection-control---transition-duration", "descriptionKey": "components.selection_control.tokens.transition_duration", "descriptionFallback": "Transition duration for icon/color animations."}], "sourceFile": "packages/ds/src/assets/css/tokens/li