 cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"130\" y=\"64\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<div class=\"origam-selection-control origam-selection-control--dirty\">\n  <!-- wrapper: ripple target + background color -->\n  <div class=\"origam-selection-control__wrapper\">\n    <!-- input zone with v-ripple -->\n    <div class=\"origam-selection-control__input\">\n      <!-- icon (true/false icon) -->\n      <origam-icon :icon=\"icon\" :color=\"bgColor\" />\n      <!-- visually hidden native input -->\n      <input type=\"checkbox\" :id :name :value :checked :disabled />\n    </div>\n  </div>\n\n  <!-- label -->\n  <div class=\"origam-selection-control__label\">\n    <origam-label :for=\"id\" :text=\"label\" :color=\"color\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-selection-control", "num": 1, "descriptionKey": "components.selection_control.anatomy.root", "descriptionFallback": "Root element. Flex-row, aligns wrapper and label. Carries state modifiers (dirty, disabled, error, focused, inline)."}, {"cls": ".origam-selection-control__wrapper", "num": 2, "descriptionKey": "components.selection_control.anatomy.wrapper", "descriptionFallback": "Square wrapper (40px + density). Hosts the ripple zone and the background color layer."}, {"cls": ".origam-selection-control__input", "num": 3, "descriptionKey": "components.selection_control.anatomy.input", "descriptionFallback": "Circular ripple zone (v-ripple). Contains the OrigamIcon (true/falseIcon) and the native input."}, {"cls": "input[type=\"checkbox|radio\"] (native)", "num": 4, "descriptionKey": "components.selection_control.anatomy.native_input", "descriptionFallback": "Visually hidden native input. Manages browser check state, form submission, and screen-reader focus."}, {"cls": ".origam-selection-control__label", "num": 5, "descriptionKey": "components.selection_control.anatomy.label", "descriptionFallback": "Label container. Renders OrigamLabel with for/id wiring."}], "classes": [{"cls": "origam-selection-control", "descriptionKey": "components.selection_control.anatomy.root", "descriptionFallback": "Root block."}, {"cls": "origam-selection-control--dirty", "descriptionKey": "components.selection_control.anatomy.modifier_dirty", "descriptionFallback": "Applied when modelValue is truthy (checked state)."}, {"cls": "origam-selection-control--disabled", "descriptionKey": "components.selection_control.anatomy.modifier_disabled", "descriptionFallback": "Applied when disabled=true."}, {"cls": "origam-selection-control--error", "descriptionKey": "components.selection_control.anatomy.modifier_error", "descriptionFallback": "Applied when error=true. Changes icon and label color."}, {"cls": "origam-selection-control--focused", "descriptionKey": "components.selection_control.anatomy.modifier_focused", "descriptionFallback": "Applied when the native input is focused."}, {"cls": "origam-selection-control--focus-visible", "descriptionKey": "components.selection_control.anatomy.modifier_focus_visible", "descriptionFallback": "Applied on keyboard focus for the visible outline."}, {"cls": "origam-selection-control--inline", "descriptionKey": "components.selection_control.anatomy.modifier_inline", "descriptionFallback": "Applied when inline=true."}, {"cls": "origam-selection-control__wrapper", "descriptionKey": "components.selection_control.anatomy.wrapper", "descriptionFallback": "Inner wrapper hosting ripple and background."}, {"cls": "origam-selection-control__input", "descriptionKey": "components.selection_control.anatomy.input", "descriptionFallback": "Ripple zone with icon and native input."}, {"cls": "origam-selection-control__label", "descriptionKey": "components.selection_control.anatomy.label", "descriptionFallback": "Label container."}], "svgDesc": "Schematic of the SelectionControl component with 5 numbered parts.", "svgTitle": "Anatomy of OrigamSelectionControl",