INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8fa7674c-6161-4fd7-adf2-5dfb4aab3592', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'selection-control-group', 'SelectionControlGroup', 'Form & Input', NULL, 'mdi-format-list-checks', 'components.catalog.selection_control_group.description', 'Groups multiple SelectionControl instances under a shared v-model with inline layout support and a typed item-slot API.', NULL, NULL, 'origam-selection-control-group', NULL, 'packages/ds/src/components/SelectionControl/OrigamSelectionControlGroup.vue', 'origam', NULL, NULL, '/stories/?story=components-selection-control--design', '/docs/components/SelectionControl/OrigamSelectionControl.html', 'selection-control', '{"a11y": {"notes": [{"noteKey": "components.selection_control_group.a11y.role_group", "noteFallback": "The root element carries role=\"group\" and is identified by the computed name/id attribute. Screen readers announce the group boundary."}, {"noteKey": "components.selection_control_group.a11y.defaults_provider", "noteFallback": "OrigamDefaultsProvider forwards type, name, density, color, disabled, readonly and error to every descendant SelectionControl. Child overrides still win."}], "roles": ["group"], "keyboard": [{"key": "Tab", "actionKey": "components.selection_control_group.a11y.key_tab", "actionFallback": "Moves focus through each child SelectionControl."}, {"key": "Space", "actionKey": "components.selection_control_group.a11y.key_space", "actionFallback": "Toggles the focused child control."}]}, "tokens": {"excerpt": [{"type": "other", "value": "flex", "tokenPath": "--origam-selection-control-group---display", "descriptionKey": "components.selection_control_group.tokens.display", "descriptionFallback": "Display mode for the group container."}, {"type": "other", "value": "column", "tokenPath": "--origam-selection-control-group---flex-direction", "descriptionKey": "components.selection_control_group.tokens.flex_direction", "descriptionFallback": "Default stack direction (column). Row when inline."}, {"type": "dimension", "value": "var(--origam-space---2)", "tokenPath": "--origam-selection-control-group---gap", "descriptionKey": "components.selection_control_group.tokens.gap", "descriptionFallback": "Gap between child controls."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"520\" height=\"160\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <rect x=\"40\" y=\"50\" width=\"440\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"260\" y=\"73\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-selection-control (item 1)</text>\n  <rect x=\"40\" y=\"96\" width=\"440\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"260\" y=\"119\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-selection-control (item 2)</text>\n  <rect x=\"40\" y=\"142\" width=\"440\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #eee)\" opacity=\"0.4\"/>\n  <text x=\"260\" y=\"158\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">slot: item / item.{index}</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"50\" cy=\"56\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"50\" y=\"60\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"50\" cy=\"148\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"50\" y=\"152\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div role=\"group\" :id=\"name\" class=\"origam-selection-control-group\">\n  <!-- OrigamDefaultsProvider pushes density/color/type/disabled/… to children -->\n  <origam-defaults-provider :defaults=\"slotDefaults\">\n    <slot name=\"default\" v-bind=\"{ items }\">\n      <!-- fallback: iterate items via item slot -->\n      <template v-for=\"(item, index) in items\" :key=\"index\">\n        <slot :name=\"`item.${index}`\" v-bind=\"{ item }\">\n          <slot name=\"item\" v-bind=\"{ item, index }\" />\n        </slot>\n      </template>\n    </slot>\n  </origam-defaults-provider>\n</div>", "legend": [{"cls": ".origam-selection-control-group", "num": 1, "descriptionKey": "components.selection_control_group.anatomy.root", "descriptionFallback": "Root div with role=\"group\". Receives the group id as the ARIA id attribute. Applies --inline modifier when inline=true."}, {"cls": ".origam-selection-control-group--inline", "num": 2, "descriptionKey": "components.selection_control_group.anatomy.inline", "descriptionFallback": "Modifier applied when 