ionKey": "components.sheet.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.sheet.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}, {"label": "2xl", "value": "2xl"}], "labelKey": "components.sheet.playground.rounded", "defaultValue": "md", "labelFallback": "Rounded"}, {"kind": "select", "prop": "elevation", "options": [{"label": "(none)", "value": ""}, {"label": "1", "value": "1"}, {"label": "2", "value": "2"}, {"label": "4", "value": "4"}, {"label": "8", "value": "8"}], "labelKey": "components.sheet.playground.elevation", "defaultValue": "", "labelFallback": "Elevation"}, {"kind": "switch", "prop": "border", "labelKey": "components.sheet.playground.border", "defaultValue": false, "labelFallback": "Border"}, {"kind": "select", "prop": "color", "options": [{"label": "(default)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.sheet.playground.color", "defaultValue": "", "labelFallback": "Color"}], "defaultSlotContent": "Sheet content"}, "previewVariants": [{"label": "default", "props": {"bgColor": "surface", "rounded": "md", "elevation": "2"}, "slotContent": "Sheet surface"}, {"label": "colored", "props": {"color": "white", "bgColor": "primary", "rounded": "lg"}, "slotContent": "Colored sheet"}, {"label": "outlined", "props": {"border": true, "rounded": "lg"}, "slotContent": "Outlined"}, {"label": "elevated", "props": {"rounded": "xl", "elevation": "8"}, "slotContent": "Elevated"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('640031cc-a25f-488d-8438-d36317ac108c', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'skeleton', 'Skeleton', 'Feedback & Status', NULL, 'mdi-shimmer', 'components.catalog.skeleton.description', 'Loading placeholder with animated pulse shimmer. Supports text, rectangular, circular, card and list-item variants. Renders real content via the default slot when loading=false.', NULL, NULL, 'origam-skeleton', NULL, 'packages/ds/src/components/Skeleton/OrigamSkeleton.vue', 'origam', NULL, NULL, '/stories/?story=components-skeleton--design', '/docs/components/Skeleton/OrigamSkeleton.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.skeleton.a11y.role_note", "noteFallback": "Each skeleton block has role=\"status\", aria-busy=\"true\" and aria-label=\"Loading\". This ensures screen readers announce the loading state without repeating a full description."}, {"noteKey": "components.skeleton.a11y.reduced_motion_note", "noteFallback": "The pulse animation is disabled under prefers-reduced-motion: reduce. The skeleton remains visible as a static placeholder."}, {"noteKey": "components.skeleton.a11y.content_note", "noteFallback": "When loading=false, the skeleton is replaced by real content via the default slot. Ensure the revealed content is semantically correct (headings, alt text, etc.)."}], "roles": ["status"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-skeleton---background-color", "descriptionKey": "components.skeleton.tokens.background_color", "descriptionFallback": "Base placeholder background color."}, {"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-skeleton---border-radius", "descriptionKey": "components.skeleton.tokens.border_radius", "descriptionFallback": "Border-radius for text and rectangular variants."}, {"type": "dimension", "value": "var(--origam-radius---full)", "tokenPath": "--origam-skeleton---border-radius-circular", "descriptionKey": "components.skeleton.tokens.border_radius_circular", "descriptionFallback": "Border-radius for circular variant."}, {"type": "duration", "value": "var(--origam-motion__duration---xslow)", "tokenPath": "--origam-skeleton---animation-duration", "descriptionKey": "components.skeleton.tokens.animation_duration", "descriptionFallback": "Pulse animation duration."}, {"type": "dimension", "value": "1.2em", "tokenPath": "--origam-skeleton---text-height", "descriptionKey": "components.skeleton.tokens.text_height", "descriptionFallback": "Text variant line height."}, {"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-skeleton---gap", "descriptionKey": "components.skeleton.tokens.gap", "descriptionFallback": "Gap in list-item composite layout."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <text x=\"30\" y=\"30\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\" font-style=\"italic\">list-item variant</text>\n  <rect x=\"20\" y=\"44\" width=\"520\" height=\"96\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <circle cx=\"68\" cy=\"92\" r=\"32\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.15))\"/>\n  <rect x=\"120\" y=\"72\" width=\"260\" height=\"16\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.18))\"/>\n  <rect x=\"120\" y=\"98\" width=\"180\" height=\"12\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.12))\" opacity=\"0.7\"/>\n  <text x=\"30\" y=\"165\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\" font-style=\"italic\">rectangular variant (standalone)</text>\n  <rect x=\"20\" y=\"172\" width=\"520\" height=\"20\" rx=\"2\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.18))\"/>\n  <circle cx=\"28\" cy=\"52\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"56\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"50\" cy=\"70\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"50\" y=\"74\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"130\" cy=\"70\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"130\" y=\"74\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"28\" cy=\"180\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"184\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<!-- loading=false → render real content -->\n<template v-if=\"!loading\">\n  <slot />\n</template>\n\n<!-- list-item composite -->\n<div\n  v-else-if=\"variant === ''list-item''\"\n  class=\"origam-skeleton-wrapper origam-skeleton-wrapper--list-item\"\n  role=\"status\"\n  aria-busy=\"true\"\n  aria-label=\"Loading\"\n>\n  <div class=\"origam-skeleton origam-skeleton--circular origam-skeleton--pulse\" />\n  <div class=\"origam-skeleton__lines\">\n    <div class=\"origam-skeleton origam-skeleton--text origam-skeleton--pulse\" />\n    <div class=\"origam-skeleton origam-skeleton--text origam-skeleton--pulse\" />\n  </div>\n</div>\n\n<!-- standalone block (rectangular / text / circular) -->\n<div\n  v-else\n  class=\"origam-skeleton origam-skeleton--rectangular origam-skeleton--pulse\"\n  role=\"status\"\n  aria-busy=\"true\"\n  aria-label=\"Loading\"\n/>", "legend": [{"cls": ".origam-skeleton-wrapper", "num": 1, "descriptionKey": "components.skeleton.anatomy.wrapper", "descriptionFallback": "Composite variant container rendered for card and list-item variants. Carries the variant modifier class (e.g. origam-skeleton-wrapper--list-item)."}, {"cls": ".origam-skeleton--circular", "num": 2, "descriptionKey": "components.skeleton.anatomy.circular", "descriptionFallback": "Circular avatar placeholder inside the list-item wrapper. Has the spin animation when pulse=true."}, {"cls": ".origam-skeleton--text (inside __lines)", "num": 3, "descriptionKey": "components.skeleton.anatomy.text_lines", "descriptionFallback": "Text line placeholders. The first line is 60% width, the second 40% with reduced opacity."}, {"cls": ".origam-skeleton--rectangular / --text (standalone)", "num": 4, "descriptionKey": "components.skeleton.anatomy.standalone", "descriptionFallback": "The single-block element rendered for rectangular, text and circular variants (no composite wrapper)."}], "classes": [{"cls": "origam-skeleton", "descriptionKey": "components.skeleton.anatomy.block", "descriptionFallback": "Core skeleton block. Carries the shimmer background and animation."}, {"cls": "origam-skeleton--text", "descriptionKey": "components.skeleton.anatomy.modifier_text", "descriptionFallback": "Text-height variant (1.2em tall, 100% wide by default)."}, {"cls": "origam-skeleton--rectangular", "descriptionKey": "components.skeleton.anatomy.modifier_rectangular", "descriptionFallback": "Full-height rectangular block."}, {"cls": "origam-skeleton--circular", "descriptionKey": "components.skeleton.anatomy.modifier_circular", "descriptionFallback": "Circular block. Height mirrors width."}, {"cls": "origam-skeleton--pulse", "descriptionKey": "components.skeleton.anatomy.modifier_pulse", "descriptionFallback": "Activates wave shimmer (text/rectangular) or spin (circular) animation."}, {"cls": "origam-skeleton-wrapper", "descriptionKey": "components.skeleton.anatomy.wrapper_class", "descriptionFallback": "Container for composite variants (card, list-item)."}, {"cls": "origam-skeleton-wrapper--list-item", "descriptionKey": "components.skeleton.anatomy.wrapper_list_item", "descriptionFallback": "List-item composite layout (avatar + text lines)."}, {"cls": "origam-skeleton-wrapper--card", "descriptionKey": "components.skeleton.anatomy.wrapper_card", "descriptionFallback": "Card composite layout (image block + text lines)."}, {"cls": "origam-skeleton__lines", "descriptionKey": "components.skeleton.anatomy.lines", "descriptionFallback": "Text lines column inside list-item wrapper."}], "svgDesc": "Schematic of the Skeleton component with 4 numbered parts for the list-item variant.", "svgTitle": "Anatomy of OrigamSkeleton", "rootClass": "origam-skeleton", "figcaption": "Anatomy of <code>&lt;origam-skeleton&gt;</code> — 4 parts: composite wrapper ①, circular avatar block ②, text lines ③, and the standalone rectangular/text block ④.", "svgViewBox": "0 0 560 200"}, "cssVars": [{"name": "--origam-skeleton---background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.skeleton.css_vars.background_color", "descriptionFallback": "Base background color of the skeleton block."}, {"name": "--origam-skeleton---border-radius", "defaultValue": "{radius.sm}", "descriptionKey": "components.skeleton.css_vars.border_radius", "descriptionFallback": "Border-radius for text and rectangular variants."}, {"name": "--origam-skeleton---border-radius-circular", "defaultValue": "{radius.full}", "descriptionKey": "components.skeleton.css_vars.border_radius_circular", "descriptionFallback": "Border-radius for circular variant (50% = full circle)."}, {"name": "--origam-skeleton---animation-duration", "defaultValue": "{motion.duration.xslow}", "descriptionKey": "components.skeleton.css_vars.animation_duration", "descriptionFallback": "Duration of the shimmer / spin animation."}, {"name": "--origam-skeleton---text-height", "defaultValue": "1.2em", "descriptionKey": "components.skeleton.css_vars.text_height", "descriptionFallback": "Height of the text variant block."}, {"name": "--origam-skeleton---gap", "defaultValue": "{space.3}", "descriptionKey": "components.skeleton.css_vars.gap", "descriptionFallback": "Gap between avatar and text lines in list-item variant."}, {"name": "--origam-skeleton---wave-color", "defaultValue": "color-mix(in srgb, {skeleton.background-color} 50%, white)", "descriptionKey": "components.skeleton.css_vars.wave_color", "descriptionFallback": "Highlight color of the shimmer wave. Derived from background-color by default."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.skeleton.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.skeleton.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.skeleton.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.skeleton.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.skeleton.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.skeleton.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "variant", "options": [{"label": "text", "value": "text"}, {"label": "rectangular", "value": "rectangular"}, {"label": "circular", "value": "circular"}, {"label": "card", "value": "card"}, {"label": "list-item", "value": "list-item"}], "labelKey": "components.skeleton.playground.variant", "defaultValue": "rectangular", "labelFallback": "Variant"}, {"kind": "switch", "prop": "pulse", "labelKey": "components.skeleton.playground.pulse", "defaultValue": true, "labelFallback": "Pulse animation"}, {"kind": "switch", "prop": "loading", "labelKey": "components.skeleton.playground.loading", "defaultValue": true, "labelFallback": "Loading"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(default)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "pill", "value": "pill"}], "labelKey": "components.skeleton.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}]}, "previewVariants": [{"label": "text", "props": {"width": 200, "variant": "text"}}, {"label": "rectangular", "props": {"width": 200, "height": 80, "variant": "rectangular"}}, {"label": "circular", "props": {"width": 48, "variant": "circular"}}, {"label": "card", "props": {"width": 200, "variant": "card"}}, {"label": "list-item", "props": {"width": 260, "variant": "list-item"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
