of the stack container."}, {"name": "--origam-snackbar-group---z-index", "defaultValue": "var(--origam-z-index-toast, 1060)", "descriptionKey": "components.snackbar_group.css_vars.z_index", "descriptionFallback": "Z-index of the teleported stack root."}, {"name": "--origam-snackbar-group---position-top", "defaultValue": "16px", "descriptionKey": "components.snackbar_group.css_vars.position_top", "descriptionFallback": "Distance from the viewport top edge for top-* locations."}, {"name": "--origam-snackbar-group---position-bottom", "defaultValue": "16px", "descriptionKey": "components.snackbar_group.css_vars.position_bottom", "descriptionFallback": "Distance from the viewport bottom edge for bottom-* locations."}, {"name": "--origam-snackbar-group---position-left", "defaultValue": "16px", "descriptionKey": "components.snackbar_group.css_vars.position_left", "descriptionFallback": "Distance from the viewport left edge for *-left locations."}, {"name": "--origam-snackbar-group---position-right", "defaultValue": "16px", "descriptionKey": "components.snackbar_group.css_vars.position_right", "descriptionFallback": "Distance from the viewport right edge for *-right locations."}, {"name": "--origam-snackbar-group---transition-duration", "defaultValue": "180ms", "descriptionKey": "components.snackbar_group.css_vars.transition_duration", "descriptionFallback": "Duration of the slide-up / slide-down enter and leave transitions."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.snackbar_group.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "visibleItems", "type": "ComputedRef<ReadonlyArray<ISnackbarGroupItem>>", "descriptionKey": "components.snackbar_group.exposed.visible_items", "descriptionFallback": "Computed slice of items currently rendered (capped to max, ordered per direction)."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.snackbar_group.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed stack styles."}, {"name": "id", "type": "string", "descriptionKey": "components.snackbar_group.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.snackbar_group.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.snackbar_group.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.snackbar_group.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "location", "options": [{"label": "(default)", "value": ""}, {"label": "top-left", "value": "top-left"}, {"label": "top-right", "value": "top-right"}, {"label": "top-center", "value": "top-center"}, {"label": "bottom-left", "value": "bottom-left"}, {"label": "bottom-right", "value": "bottom-right"}, {"label": "bottom-center", "value": "bottom-center"}, {"label": "top", "value": "top"}, {"label": "bottom", "value": "bottom"}], "labelKey": "components.snackbar_group.playground.location", "defaultValue": "", "labelFallback": "Location"}, {"kind": "select", "prop": "direction", "options": [{"label": "(default)", "value": ""}, {"label": "top-down", "value": "top-down"}, {"label": "bottom-up", "value": "bottom-up"}], "labelKey": "components.snackbar_group.playground.direction", "defaultValue": "", "labelFallback": "Direction"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('6f549312-ab6a-4b5f-a90a-50f84a7fd949', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'snackbar-item', 'SnackbarItem', 'Feedback & Status', NULL, 'mdi-message-badge-outline', 'components.catalog.snackbar_item.description', 'Pure visual layer for a single toast notification. Handles intent theming, icon, title, message, action buttons and the dismiss control.', NULL, NULL, 'origam-snackbar-item', NULL, 'packages/ds/src/components/Snackbar/OrigamSnackbarItem.vue', 'origam', NULL, NULL, '/stories/?story=components-snackbar--design', '/docs/components/Snackbar/OrigamSnackbar.html', 'snackbar', '{"a11y": {"notes": [{"noteKey": "components.snackbar_item.a11y.live_note", "noteFallback": "aria-live is set to \"assertive\" for warning and danger intents, \"polite\" for others. The value can be overridden via the ariaLive prop."}, {"noteKey": "components.snackbar_item.a11y.atomic_note", "noteFallback": "aria-atomic=\"true\" ensures screen readers read the entire item when it is updated."}, {"noteKey": "components.snackbar_item.a11y.dismiss_note", "noteFallback": "The dismiss button carries aria-label=\"Dismiss notification\" (or the dismissLabel prop value). It is keyboard-focusable and activated via Enter/Space."}, {"noteKey": "components.snackbar_item.a11y.contrast_note", "noteFallback": "The v-contrast directive ensures foreground and background token combinations meet WCAG AA contrast ratios for each intent."}], "roles": ["status", "alert"], "keyboard": [{"key": "Tab", "actionKey": "components.snackbar_item.a11y.key_tab", "actionFallback": "Moves focus to the dismiss button or action buttons."}, {"key": "Enter / Space", "actionKey": "components.snackbar_item.a11y.key_activate", "actionFallback": "Activates the focused dismiss or action button."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-snackbar-group__item---background-color", "descriptionKey": "components.snackbar_item.tokens.background_color", "descriptionFallback": "Default background color. Intent variants reference feedback tokens."}, {"type": "dimension", "value": "var(--origam-radius---md)", "tokenPath": "--origam-snackbar-group__item---border-radius", "descriptionKey": "components.snackbar_item.tokens.border_radius", "descriptionFallback": "Corner radius of the item card."}, {"type": "shadow", "value": "var(--origam-shadow---md)", "tokenPath": "--origam-snackbar-group__item---box-shadow", "descriptionKey": "components.snackbar_item.tokens.box_shadow", "descriptionFallback": "Elevation shadow applied to the card."}, {"type": "fontWeight", "value": "var(--origam-font__weight---semibold)", "tokenPath": "--origam-snackbar-group__item---title-font-weight", "descriptionKey": "components.snackbar_item.tokens.title_font_weight", "descriptionFallback": "Font weight of the title text."}, {"type": "number", "value": "0.85", "tokenPath": "--origam-snackbar-group__item---message-opacity", "descriptionKey": "components.snackbar_item.tokens.message_opacity", "descriptionFallback": "Opacity of the message text."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #f8f5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"24\" width=\"660\" height=\"172\" rx=\"8\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"36\" y=\"40\" width=\"600\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.03))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"5 3\"/>\n  <text x=\"48\" y=\"58\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">__content</text>\n  <rect x=\"48\" y=\"65\" width=\"48\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"72\" y=\"108\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">icon</text>\n  <rect x=\"108\" y=\"65\" width=\"300\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.03))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"120\" y=\"83\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">__text</text>\n  <rect x=\"120\" y=\"88\" width=\"280\" height=\"20\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"260\" y=\"102\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__title</text>\n  <rect x=\"120\" y=\"115\" width=\"280\" height=\"16\" rx=\"2\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.03))\"/>\n  <text x=\"260\" y=\"127\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__message</text>\n  <rect x=\"420\" y=\"65\" width=\"120\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.05))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"480\" y=\"108\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__actions</text>\n  <rect x=\"616\" y=\"65\" width=\"28\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"630\" y=\"108\" font-size=\"7\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">✕</text>\n  <circle cx=\"28\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"36\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"44\" cy=\"55\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"44\" y=\"59\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"56\" cy=\"73\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"77\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"116\" cy=\"73\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"116\" y=\"77\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"116\" cy=\"107\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"116\" y=\"111\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"428\" cy=\"73\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"428\" y=\"77\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <circle cx=\"624\" cy=\"73\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"624\" y=\"77\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">7</text>\n", "code": "<div class=\"origam-snackbar-item origam-snackbar-item--intent-success\">\n  <div class=\"origam-snackbar-item__content\">\n    <div class=\"origam-snackbar-item__prepend\">\n      <slot name=\"prepend\"><origam-icon :icon=\"resolvedIcon\" :size=\"24\" /></slot>\n    </div>\n    <div class=\"origam-snackbar-item__text\">\n      <div class=\"origam-snackbar-item__title\">\n        <slot name=\"title\">{{ title }}</slot>\n      </div>\n      <div class=\"origam-snackbar-item__message\">\n        <slot name=\"message\">{{ message }}</slot>\n      </div>\n      <slot/>\n    </div>\n  </div>\n  <div class=\"origam-snackbar-item__actions\">\n    <slot name=\"actions\">\n      <origam-btn v-for=\"action in actions\" variant=\"text\" />\n    </slot>\n  </div>\n  <origam-btn class=\"origam-snackbar-item__dismiss\" :icon=\"MDI_ICONS.CLOSE\" size=\"x-small\" variant=\"text\" />\n</div>", "legend": [{"cls": ".origam-snackbar-item", "num": 1, "descriptionKey": "components.snackbar_item.anatomy.root", "descriptionFallback": "Root element. Carries the intent modifier class (e.g. <code>--intent-success</code>) and the role / aria-live / aria-atomic attributes."}, {"cls": ".origam-snackbar-item__content", "num": 2, "descriptionKey": "components.snackbar_item.anatomy.content", "descriptionFallback": "Flex row hosting the prepend icon and the text block."}, {"cls": ".origam-snackbar-item__prepend", "num": 3, "descriptionKey": "components.snackbar_item.anatomy.prepend", "descriptionFallback": "Leading icon area. Defaults to the per-intent MDI icon; replaced by the <code>#prepend</code> slot or hidden when <code>icon=false</code>."}, {"cls": ".origam-snackbar-item__title", "num": 4, "descriptionKey": "components.snackbar_item.anatomy.title", "descriptionFallback": "Bold first-line label. Rendered only when the <code>title</code> prop is set."}, {"cls": ".origam-snackbar-item__message", "num": 5, "descriptionKey": "components.snackbar_item.anatomy.message", "descriptionFallback": "Body text. Rendered when the <code>message</code> prop or the <code>#message</code> slot is provided."}, {"cls": ".origam-snackbar-item__actions", "num": 6, "descriptionKey": "components.snackbar_item.anatomy.actions", "descriptionFallback": "Action buttons row. Rendered only when <code>actions</code> is non-empty or the <code>#actions</code> slot is used."}, {"cls": ".origam-snackbar-item__dismiss", "num": 7, "descriptionKey": "components.snackbar_item.anatomy.dismiss", "descriptionFallback": "Close button (OrigamBtn icon x-small). Hidden when <code>dismissible=false</code>."}], "classes": [{"cls": "origam-snackbar-item", "descriptionKey": "components.snackbar_item.anatomy.root", "descriptionFallback": "Root element with intent modifier and ARIA attributes."}, {"cls": "origam-snackbar-item__content", "descriptionKey": "components.snackbar_item.anatomy.content", "descriptionFallback": "Flex row: prepend icon + text block."}, {"cls": "origam-snackbar-item__prepend", "descriptionKey": "components.snackbar_item.anatomy.prepend", "descriptionFallback": "Leading icon area."}, {"cls": "origam-snackbar-item__text", "descriptionKey": "components.snackbar_item.anatomy.text", "descriptionFallback": "Column: title + message + default slot."}, {"cls": "origam-snackbar-item__title", "descriptionKey": "components.snackbar_item.anatomy.title", "descriptionFallback": "Bold title text."}, {"cls": "origam-snackbar-item__message", "descriptionKey": "components.snackbar_item.anatomy.message", "descriptionFallback": "Body message text."}, {"cls": "origam-snackbar-item__actions", "descriptionKey": "components.snackbar_item.anatomy.actions", "descriptionFallback": "Action buttons row."}, {"cls": "origam-snackbar-item__dismiss", "descriptionKey": "components.snackbar_item.anatomy.dismiss", "descriptionFallback": "Close/dismiss button."}], "svgDesc": "Schematic of the SnackbarItem component with 7 numbered internal parts.", "svgTitle": "Anatomy of OrigamSnackbarItem", "rootClass": "origam-snackbar-item", "figcaption": "Anatomy of <code>&lt;origam-snackbar-item&gt;</code> — 7 internal parts. The <code>__content</code> row holds the prepend icon and the text block; <code>__actions</code> and <code>__dismiss</code> are appended when present.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-snackbar-item---gap", "defaultValue": "12px", "descriptionKey": "components.snackbar_item.css_vars.gap", "descriptionFallback": "Gap between the prepend area and the text+actions block."}, {"name": "--origam-snackbar-item---min-width", "defaultValue": "288px", "descriptionKey": "components.snackbar_item.css_vars.min_width", "descriptionFallback": "Minimum width of the item."}, {"name": "--origam-snackbar-item---max-width", "defaultValue": "420px", "descriptionKey": "components.snackbar_item.css_vars.max_width", "descriptionFallback": "Maximum width of the item."}, {"name": "--origam-snackbar-item---padding", "defaultValue": "12px 14px", "descriptionKey": "components.snackbar_item.css_vars.padding", "descriptionFallback": "Inner padding of the item."}, {"name": "--origam-snackbar-item---border-radius", "defaultValue": "8px", "descriptionKey": "components.snackbar_item.css_vars.border_radius", "descriptionFallback": "Corner radius of the item card."}, {"name": "--origam-snackbar-item---background-color", "defaultValue": "var(--origam-color__surface---default)", "descriptionKey": "components.snackbar_item.css_vars.background_color", "descriptionFallback": "Default background. Intent variants override this via feedback tokens."}, {"name": "--origam-snackbar-item---border-color", "defaultValue": "var(--origam-color__border---subtle)", "descriptionKey": "components.snackbar_item.css_vars.border_color", "descriptionFallback": "Default border colour. Intent variants override this via feedback tokens."}, {"name": "--origam-snackbar-item---box-shadow", "defaultValue": "0 4px 12px rgba(0,0,0,0.12)", "descriptionKey": "components.snackbar_item.css_vars.box_shadow", "descriptionFallback": "Elevation shadow for the item card."}, {"name": "--origam-snackbar-item__title---font-weight", "defaultValue": "600", "descriptionKey": "components.snackbar_item.css_vars.title_font_weight", "descriptionFallback": "Font weight of the title line."}, {"name": "--origam-snackbar-item__message---opacity", "defaultValue": "0.85", "descriptionKey": "components.snackbar_item.css_vars.message_opacity", "descriptionFallback": "Opacity of the message text, giving the title visual priority."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.snackbar_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.snackbar_item.playground.title", "defaultValue": "", "labelFallback": "Title"}, {"kind": "select", "prop": "intent", "options": [{"label": "(default)", "value": ""}, {"label": "neutral", "value": "neutral"}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "ghost", "value": "ghost"}, {"label": "success", "value": "success"}, {"label": "warning", "value": "warning"}, {"label": "danger", "value": "danger"}, {"label": "info", "value": "info"}], "labelKey": "components.snackbar_item.playground.intent", "defaultValue": "", "labelFallback": "Intent"}, {"kind": "select", "prop": "icon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-check", "value": "mdi-check"}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-close", "value": "mdi-close"}], "labelKey": "components.snackbar_item.playground.icon", "defaultValue": "", "labelFallback": "Icon"}, {"kind": "switch", "prop": "dismissible", "labelKey": "components.snackbar_item.playground.dismissible", "defaultValue": true, "labelFallback": "Dismissible"}, {"kind": "select", "prop": "ariaLive", "options": [{"label": "(default)", "value": ""}, {"label": "polite", "value": "polite"}, {"label": "assertive", "value": "assertive"}], "labelKey": "components.snackbar_item.playground.aria_live", "defaultValue": "", "labelFallback": "Aria Live"}], "defaultSlotContent": "Content"}, "previewVariants": [{"label": "info", "props": {"title": "Info", "intent": "info", "message": "This is an informational message."}}, {"label": "success", "props": {"title": "Success", "intent": "success", "message": "Operation completed successfully."}}, {"label": "warning", "props": {"intent": "warning", "message": "Something might need your attention."}}, {"label": "danger", "props": {"title": "Error", "intent": "danger", "message": "An error has occurred."}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('facae1ec-5f2c-437b-aef1-b22b7349c550', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'spacer', 'Spacer', 'Layout & Structure', NULL, 'mdi-arrow-expand-horizontal', 'components.catalog.spacer.description', 'Flex spacer that grows to fill available space inside a flex row or column, pushing siblings apart.', NULL, NULL, 'origam-spacer', NULL, 'packages/ds/src/components/Grids/OrigamSpacer.vue', 'origam', NULL, NULL, '/stories/?story=components-spacer--design', '/docs/components/Spacer/OrigamSpacer.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.spacer.a11y.presentational_note", "noteFallback": "Spacer is a purely presentational layout element with no semantic role. Screen readers skip it entirely. No ARIA attributes are needed."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"120\" fill=\"var(--origam-color__surface---sunken, #f8f5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.4))\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <text x=\"32\" y=\"38\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">flex container (e.g. origam-toolbar / origam-row)</text>\n  <rect x=\"32\" y=\"48\" width=\"80\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"72\" y=\"70\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">sibling</text>\n  <rect x=\"124\" y=\"48\" width=\"432\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"5 3\"/>\n  <text x=\"340\" y=\"70\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-spacer  (flex-grow: 1)</text>\n  <rect x=\"568\" y=\"48\" width=\"80\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"608\" y=\"70\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">sibling</text>\n  <circle cx=\"132\" cy=\"56\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"132\" y=\"60\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n", "code": "<div class=\"origam-spacer\">\n  <slot />\n</div>", "legend": [{"cls": ".origam-spacer", "num": 1, "descriptionKey": "components.spacer.anatomy.root", "descriptionFallback": "Root element. <code>flex-grow: 1</code> (driven by <code>--origam-spacer---flex-grow</code>). No visual surface by default — purely a layout utility."}], "classes": [{"cls": "origam-spacer", "descriptionKey": "components.spacer.anatomy.root", "descriptionFallback": "Root element. flex-grow: 1 via --origam-spacer---flex-grow."}], "svgDesc": "Schematic of the Spacer component with 1 numbered part inside a flex container.", "svgTitle": "Anatomy of OrigamSpacer", "rootClass": "origam-spacer", "figcaption": "Anatomy of <code>&lt;origam-spacer&gt;</code> — a single element that grows to fill all remaining space in a flex container.", "svgViewBox": "0 0 700 120"}, "cssVars": [{"name": "--origam-spacer---flex-grow", "defaultValue": "1", "descriptionKey": "components.spacer.css_vars.flex_grow", "descriptionFallback": "Controls how greedily the spacer grows inside a flex container. Default is 1 (fill all remaining space)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.spacer.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.spacer.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.spacer.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.spacer.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.spacer.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.spacer.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
