scriptionFallback": "Width of the standard track."}, {"type": "dimension", "value": "24px", "tokenPath": "--origam-switch__track---height", "descriptionKey": "components.switch_track.tokens.height", "descriptionFallback": "Height of the standard track."}, {"type": "dimension", "value": "var(--origam-radius---full)", "tokenPath": "--origam-switch__track---border-radius", "descriptionKey": "components.switch_track.tokens.border_radius", "descriptionFallback": "Pill border-radius of the track."}, {"type": "color", "value": "color-mix(in srgb, var(--origam-color__text---primary) 60%, var(--origam-color__surface---default))", "tokenPath": "--origam-switch__track---background-color", "descriptionKey": "components.switch_track.tokens.background_color", "descriptionFallback": "Track background in OFF state."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-switch__track---background-color-checked", "descriptionKey": "components.switch_track.tokens.background_color_checked", "descriptionFallback": "Track background in ON state."}, {"type": "color", "value": "var(--origam-color__feedback--danger---bg)", "tokenPath": "--origam-switch__track---background-color-error", "descriptionKey": "components.switch_track.tokens.background_color_error", "descriptionFallback": "Track background in error state."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #f8f5ff)\" rx=\"4\"/>\n  <rect x=\"190\" y=\"40\" width=\"320\" height=\"100\" rx=\"50\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"88\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-switch-track--dirty</text>\n  <rect x=\"202\" y=\"52\" width=\"80\" height=\"76\" rx=\"38\" fill=\"var(--origam-color__surface---overlay, rgba(255,255,255,0.15))\" stroke=\"none\"/>\n  <text x=\"242\" y=\"92\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">true</text>\n  <rect x=\"418\" y=\"52\" width=\"80\" height=\"76\" rx=\"38\" fill=\"var(--origam-color__surface---overlay, rgba(0,0,0,0.08))\" stroke=\"none\"/>\n  <text x=\"458\" y=\"92\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">false</text>\n  <circle cx=\"462\" cy=\"90\" r=\"42\" fill=\"var(--origam-color__surface---default, #fff)\" stroke=\"none\"/>\n  <circle cx=\"198\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"198\" y=\"52\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"210\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"210\" y=\"64\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"426\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"426\" y=\"64\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"470\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"470\" y=\"64\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<div class=\"origam-switch-track origam-switch-track--dirty\">\n  <!-- left content: visible when ON -->\n  <div class=\"origam-switch-track__true\">\n    <slot name=\"track.true\" v-bind=\"{ model: modelValue, isValid }\" />\n  </div>\n  <!-- right content: visible when OFF -->\n  <div class=\"origam-switch-track__false\">\n    <slot name=\"track.false\" v-bind=\"{ model: modelValue, isValid }\" />\n  </div>\n  <!-- free overlay layer -->\n  <slot name=\"overlay\" v-bind=\"{ model: modelValue, isValid }\" />\n</div>", "legend": [{"cls": ".origam-switch-track", "num": 1, "descriptionKey": "components.switch_track.anatomy.root", "descriptionFallback": "Root element. Pill-shaped rail with <code>border-radius: 9999px</code>. Carries state modifiers: <code>--dirty</code> (ON), <code>--disabled</code>, <code>--readonly</code>, <code>--error</code>, <code>--inset</code>."}, {"cls": ".origam-switch-track__true", "num": 2, "descriptionKey": "components.switch_track.anatomy.true", "descriptionFallback": "Left half — hosts the <code>#track.true</code> slot. Visible (opacity: 1) when <code>modelValue</code> is true, hidden (opacity: 0) when false. Uses <code>margin-inline-end: auto</code> to push to the left."}, {"cls": ".origam-switch-track__false", "num": 3, "descriptionKey": "components.switch_track.anatomy.false", "descriptionFallback": "Right half — hosts the <code>#track.false</code> slot. Visible when <code>modelValue</code> is false, hidden when true. Uses <code>margin-inline-start: auto</code> to push to the right."}, {"cls": "(overlay slot)", "num": 4, "descriptionKey": "components.switch_track.anatomy.overlay", "descriptionFallback": "<code>#overlay</code> slot host rendered after the half-labels. Positioned freely inside the track (absolute positioning is the consumer''s responsibility)."}], "classes": [{"cls": "origam-switch-track", "descriptionKey": "components.switch_track.anatomy.root", "descriptionFallback": "Root pill-shaped rail element with state modifiers."}, {"cls": "origam-switch-track__true", "descriptionKey": "components.switch_track.anatomy.true", "descriptionFallback": "Left (ON-side) content wrapper. Opacity-toggled by --dirty."}, {"cls": "origam-switch-track__false", "descriptionKey": "components.switch_track.anatomy.false", "descriptionFallback": "Right (OFF-side) content wrapper. Opacity-toggled by --dirty."}], "svgDesc": "Schematic of the SwitchTrack component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamSwitchTrack", "rootClass": "origam-switch-track", "figcaption": "Anatomy of <code>&lt;origam-switch-track&gt;</code> — 4 internal parts. The pill-shaped rail paints the background; the <code>__true</code> / <code>__false</code> halves reveal or hide on each side; the <code>overlay</code> slot sits on top.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-switch__track---background-color", "defaultValue": "rgb(163, 163, 163)", "descriptionKey": "components.switch_track.css_vars.background_color", "descriptionFallback": "Rail background colour in OFF state. Overridden by bgColor prop when set."}, {"name": "--origam-switch__track---border-radius", "defaultValue": "9999px", "descriptionKey": "components.switch_track.css_vars.border_radius", "descriptionFallback": "Corner radius of the track rail (pill shape)."}, {"name": "--origam-switch__track---height", "defaultValue": "14px", "descriptionKey": "components.switch_track.css_vars.height", "descriptionFallback": "Height of the standard (non-inset) track."}, {"name": "--origam-switch__track---width", "defaultValue": "36px", "descriptionKey": "components.switch_track.css_vars.width", "descriptionFallback": "Minimum width of the standard (non-inset) track."}, {"name": "--origam-switch__track--inset---height", "defaultValue": "32px", "descriptionKey": "components.switch_track.css_vars.inset_height", "descriptionFallback": "Height of the track in inset variant."}, {"name": "--origam-switch__track--inset---width", "defaultValue": "52px", "descriptionKey": "components.switch_track.css_vars.inset_width", "descriptionFallback": "Minimum width of the track in inset variant."}, {"name": "--origam-switch__track---background-color-disabled", "defaultValue": "rgb(163, 163, 163)", "descriptionKey": "components.switch_track.css_vars.background_color_disabled", "descriptionFallback": "Rail background in disabled ON state."}, {"name": "--origam-switch---opacity-disabled", "defaultValue": "0.32", "descriptionKey": "components.switch_track.css_vars.opacity_disabled", "descriptionFallback": "Opacity applied to the entire track in disabled state."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.switch_track.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.switch_track.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed track styles."}, {"name": "id", "type": "string", "descriptionKey": "components.switch_track.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.switch_track.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.switch_track.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.switch_track.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.switch_track.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.switch_track.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.switch_track.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.switch_track.playground.readonly", "defaultValue": false, "labelFallback": "Read-only"}, {"kind": "switch", "prop": "modelValue", "labelKey": "components.switch_track.playground.model_value", "defaultValue": false, "labelFallback": "Value"}, {"kind": "switch", "prop": "error", "labelKey": "components.switch_track.playground.error", "defaultValue": false, "labelFallback": "Error"}, {"kind": "switch", "prop": "inset", "labelKey": "components.switch_track.playground.inset", "defaultValue": false, "labelFallback": "Inset"}]}, "previewVariants": [{"label": "off", "props": {"modelValue": false}}, {"label": "on", "props": {"modelValue": true}}, {"label": "inset off", "props": {"inset": true, "modelValue": false}}, {"label": "inset on", "props": {"inset": true, "modelValue": true}}, {"label": "disabled", "props": {"disabled": true, "modelValue": false}}, {"label": "error", "props": {"error": true, "modelValue": false}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3665639f-8cba-429e-a8c6-d932acda9137', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'system-bar', 'SystemBar', 'Layout & Structure', NULL, 'mdi-dock-top', 'components.catalog.system_bar.description', 'Thin bar anchored to the top of an app layout — typically used to display status icons, time or network info in a narrow stripe.', NULL, NULL, 'origam-system-bar', NULL, 'packages/ds/src/components/SystemBar/OrigamSystemBar.vue', 'origam', NULL, NULL, '/stories/?story=components-system-bar--design', '/docs/components/SystemBar/OrigamSystemBar.html', NULL, '{"playground": {"controls": [{"kind": "switch", "prop": "window", "labelKey": "components.system_bar.playground.window", "defaultValue": false, "labelFallback": "Window"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e9cf9371-b432-4a01-b231-85e87e76ae9e', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'tab', 'Tab', 'Navigation', NULL, 'mdi-tab', 'components.catalog.tab.description', 'Single registered tab inside an OrigamTabs tablist — renders the label text and optional leading/trailing icons.', NULL, NULL, 'origam-tab', NULL, 'packages/ds/src/components/Tabs/OrigamTab.vue', 'origam', NULL, NULL, '/stories/?story=components-tabs--design', '/docs/components/Tabs/OrigamTabs.html', 'tabs', '{"a11y": {"notes": [{"noteKey": "components.tab.a11y.aria_note", "noteFallback": "OrigamTab wires role=\"tab\", aria-selected, aria-controls (pointing to the matching panel id) and aria-disabled automatically — no manual ARIA needed on the consumer side."}, {"noteKey": "components.tab.a11y.disabled_note", "noteFallback": "When disabled=true the tab gets aria-disabled=\"true\" and tabindex=-1; click events are swallowed via handleClick guard."}, {"noteKey": "components.tab.a11y.focus_note", "noteFallback": "Focus-visible outline is applied via :focus-visible pseudo-class (2px solid currentColor, outline-offset: -2px). Never shown on mouse click."}, {"noteKey": "components.tab.a11y.reduced_motion_note", "noteFallback": "The indicator transform transition should be disabled under prefers-reduced-motion: reduce via the consuming theme."}], "roles": ["tab"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.tab.a11y.key_activate", "actionFallback": "Activates the tab (selects it in the group)."}, {"key": "ArrowLeft / ArrowRight", "actionKey": "components.tab.a11y.key_arrows", "actionFallback": "Moves focus to the previous / next tab in the tablist (roving tabindex managed by OrigamTabs)."}, {"key": "Tab", "actionKey": "components.tab.a11y.key_tab", "actionFallback": "Moves focus outside the tablist to the next focusable element (tabpanel)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-tabs__item---color", "descriptionKey": "components.tab.tokens.item_color", "descriptionFallback": "Resting label color."}, {"type": "dimension", "value": "var(--origam-space---12)", "tokenPath": "--origam-tabs__item---height", "descriptionKey": "components.tab.tokens.item_height", "descriptionFallback": "Minimum tab height."}, {"type": "fontWeight", "value": "var(--origam-font__weight---medium)", "tokenPath": "--origam-tabs__item---font-weight", "descriptionKey": "components.tab.tokens.item_font_weight", "descriptionFallback": "Resting label font weight."}, {"type": "duration", "value": "var(--origam-motion__duration---fast)", "tokenPath": "--origam-tabs__item---transition-duration", "descriptionKey": "components.tab.tokens.item_transition_duration", "descriptionFallback": "Transition duration for color and background changes."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-tabs__indicator---color", "descriptionKey": "components.tab.tokens.indicator_color", "descriptionFallback": "Underline indicator color for variant=\"underline\"."}, {"type": "dimension", "value": "var(--origam-border__width---2)", "tokenPath": "--origam-tabs__indicator---height", "descriptionKey": "components.tab.tokens.indicator_height", "descriptionFallback": "Thickness of the underline indicator."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"52\" width=\"520\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"60\" y=\"66\" width=\"80\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"100\" y=\"95\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">icon</text>\n  <rect x=\"152\" y=\"66\" width=\"256\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"280\" y=\"95\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Label / #default slot</text>\n  <rect x=\"420\" y=\"66\" width=\"80\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"460\" y=\"95\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">append icon</text>\n  <rect x=\"40\" y=\"128\" width=\"520\" height=\"4\" rx=\"0\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"50\" cy=\"60\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"50\" y=\"64.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"88\" cy=\"74\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"88\" y=\"78\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"280\" cy=\"74\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"280\" y=\"78\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"448\" cy=\"74\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"448\" y=\"78\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"280\" cy=\"133\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"280\" y=\"137\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <line x1=\"50\" y1=\"48\" x2=\"80\" y2=\"28\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"26\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-tab</text>\n  <text x=\"300\" y=\"175\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">② prepend · ③ label · ④ append — flex row; ⑤ indicator — abs bottom</text>\n", "code": "<!-- root button: role=\"tab\", aria-selected, aria-controls, tabindex -->\n<button class=\"origam-tab\" role=\"tab\">\n  <!-- leading icon (v-if=\"icon\") -->\n  <span class=\"origam-tab__prepend\">\n    <origam-icon :icon=\"icon\" />\n  </span>\n\n  <!-- label / #default slot -->\n  <span class=\"origam-tab__label\">\n    <slot name=\"default\">{{ text }}</slot>\n  </span>\n\n  <!-- trailing icon (v-if=\"appendIcon\") -->\n  <span class=\"origam-tab__append\">\n    <origam-icon :icon=\"appendIcon\" />\n  </span>\n\n  <!-- underline indicator (v-if=\"variant === ''underline''\") -->\n  <span class=\"origam-tab__indicator\" aria-hidden=\"true\" />\n</button>", "legend": [{"cls": ".origam-tab", "num": 1, "descriptionKey": "components.tab.anatomy.root", "descriptionFallback": "Root element. Renders as <code>&lt;button&gt;</code> by default. Carries <code>role=\"tab\"</code>, <code>aria-selected</code>, <code>aria-controls</code> and managed <code>tabindex</code>."}, {"cls": ".origam-tab__prepend", "num": 2, "descriptionKey": "components.tab.anatomy.prepend", "descriptionFallback": "Leading icon area. Rendered with <code>v-if=\"icon\"</code>. Wraps an <code>&lt;OrigamIcon&gt;</code>."}, {"cls": ".origam-tab__label", "num": 3, "descriptionKey": "components.tab.anatomy.label", "descriptionFallback": "Label zone. Contains the default slot (falls back to the <code>text</code> prop)."}, {"cls": ".origam-tab__append", "num": 4, "descriptionKey": "components.tab.anatomy.append", "descriptionFallback": "Trailing icon area. Rendered with <code>v-if=\"appendIcon\"</code>."}, {"cls": ".origam-tab__indicator", "num": 5, "descriptionKey": "components.tab.anatomy.indicator", "descriptionFallback": "Absolute underline indicator. Visible only when <code>variant=\"underline\"</code>. Scales from 0 → 1 on <code>--active</code> via CSS transform."}], "classes": [{"cls": "origam-tab", "descriptionKey": "components.tab.anatomy.root", "descriptionFallback": "Root element. Carries role=\"tab\", aria-selected, aria-controls, and tabindex."}, {"cls": "origam-tab--active", "descriptionKey": "components.tab.anatomy.active", "descriptionFallback": "Applied when this tab is the selected item in the tablist."}, {"cls": "origam-tab--disabled", "descriptionKey": "components.tab.anatomy.disabled", "descriptionFallback": "Applied when disabled=true. Sets cursor: not-allowed; pointer-events: none."}, {"cls": "origam-tab--with-prepend", "descriptionKey": "components.tab.anatomy.with_prepend", "descriptionFallback": "Applied when the icon prop is set (leading icon present)."}, {"cls": "origam-tab--with-append", "descriptionKey": "components.tab.anatomy.with_append", "descriptionFallback": "Applied when the appendIcon prop is set (trailing icon present)."}, {"cls": "origam-tab__prepend", "descriptionKey": "components.tab.anatomy.prepend", "descriptionFallback": "Leading icon wrapper. Only rendered when icon prop is provided."}, {"cls": "origam-tab__label", "descriptionKey": "components.tab.anatomy.label", "descriptionFallback": "Label zone containing the default slot content or text prop."}, {"cls": "origam-tab__append", "descriptionKey": "components.tab.anatomy.append", "descriptionFallback": "Trailing icon wrapper. Only rendered when appendIcon prop is provided."}, {"cls": "origam-tab__indicator", "descriptionKey": "components.tab.anatomy.indicator", "descriptionFallback": "Bottom indicator bar. Visible only in underline variant; scales on activation."}], "svgDesc": "Schematic of the Tab component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamTab", "rootClass": "origam-tab", "figcaption": "Anatomy of <code>&lt;origam-tab&gt;</code> — 5 internal parts. The indicator (⑤) is absolute-positioned at the block-end and scales on activation.", "svgViewBox": "0 0 600 200"}, "cssVars": [{"name": "--origam-tabs__item---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.tab.css_vars.color", "descriptionFallback": "Tab label color in resting state."}, {"name": "--origam-tabs__item---background-color", "defaultValue": "transparent", "descriptionKey": "components.tab.css_vars.background_color", "descriptionFallback": "Tab background in resting state."}, {"name": "--origam-tabs__item---height", "defaultValue": "48px", "descriptionKey": "components.tab.css_vars.height", "descriptionFallback": "Minimum tab height."}, {"name": "--origam-tabs__item---padding-inline", "defaultValue": "16px", "descriptionKey": "components.tab.css_vars.padding_inline", "descriptionFallback": "Horizontal padding of each tab."}, {"name": "--origam-tabs__item---padding-block", "defaultValue": "0", "descriptionKey": "components.tab.css_vars.padding_block", "descriptionFallback": "Vertical padding of each tab."}, {"name": "--origam-tabs__item---gap", "defaultValue": "8px", "descriptionKey": "components.tab.css_vars.gap", "descriptionFallback": "Gap between icon and label."}, {"name": "--origam-tabs__item---font-size", "defaultValue": "0.875rem", "descriptionKey": "components.tab.css_vars.font_size", "descriptionFallback": "Tab label font size."}, {"name": "--origam-tabs__item---font-weight", "defaultValue": "500", "descriptionKey": "components.tab.css_vars.font_weight", "descriptionFallback": "Tab label font weight."}, {"name": "--origam-tabs__item---letter-spacing", "defaultValue": "0.03125em", "descriptionKey": "components.tab.css_vars.letter_spacing", "descriptionFallback": "Tab label letter spacing."}, {"name": "--origam-tabs__item---border-radius", "defaultValue": "0", "descriptionKey": "components.tab.css_vars.border_radius", "descriptionFallback": "Tab border radius. Set to radius.full for pills variant."}, {"name": "--origam-tabs__item---transition-duration", "defaultValue": "0.2s", "descriptionKey": "components.tab.css_vars.transition_duration", "descriptionFallback": "Transition duration for color, background-color, border-color and transform."}, {"name": "--origam-tabs__item--active---color", "defaultValue": "currentColor", "descriptionKey": "components.tab.css_vars.active_color", "descriptionFallback": "Tab label color when active."}, {"name": "--origam-tabs__item--active---font-weight", "defaultValue": "600", "descriptionKey": "components.tab.css_vars.active_font_weight", "descriptionFallback": "Font weight applied to the active tab."}, {"name": "--origam-tabs__indicator---color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.tab.css_vars.indicator_color", "descriptionFallback": "Color of the underline indicator bar (variant=\"underline\")."}, {"name": "--origam-tabs__indicator---height", "defaultValue": "2px", "descriptionKey": "components.tab.css_vars.indicator_height", "descriptionFallback": "Thickness of the underline indicator bar."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.tab.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "toggle", "type": "() => void", "descriptionKey": "components.tab.exposed.toggle", "descriptionFallback": "Toggles the selected state of this tab in the group."}, {"name": "select", "type": "(value: boolean) => void", "descriptionKey": "components.tab.exposed.select", "descriptionFallback": "Programmatically selects (true) or deselects (false) this tab."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.tab.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed tab styles."}, {"name": "id", "type": "string", "descriptionKey": "components.tab.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.tab.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.tab.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.tab.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "text", "labelKey": "components.tab.playground.text", "defaultValue": "Tab label", "labelFallback": "Label text"}, {"kind": "select", "prop": "icon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-magnify", "value": "mdi-magnify"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-star", "value": "mdi-star"}], "labelKey": "components.tab.playground.icon", "defaultValue": "", "labelFallback": "Leading icon"}, {"kind": "select", "prop": "appendIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-close", "value": "mdi-close"}, {"label": "mdi-chevron-right", "value": "mdi-chevron-right"}, {"label": "mdi-bell", "value": "mdi-bell"}], "labelKey": "components.tab.playground.append_icon", "defaultValue": "", "labelFallback": "Trailing icon"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.tab.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}], "defaultSlotContent": ""}, "previewVariants": [{"label": "default", "props": {"text": "Tab", "value": "a"}}, {"label": "with icon", "props": {"icon": "mdi-magnify", "text": "Search", "value": "b"}}, {"label": "disabled", "props": {"text": "Disabled", "value": "c", "disabled": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c686f811-31c0-45ae-871b-002c42fe2172', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'tab-panel', 'TabPanel', 'Navigation', NULL, 'mdi-tab', 'components.catalog.tab_panel.description', 'A single tab content panel — lazy-mounted by default until first activated, then kept alive via v-show.', NULL, NULL, 'origam-tab-panel', NULL, 'packages/ds/src/components/Tabs/OrigamTabPanel.vue', 'origam', NULL, NULL, '/stories/?story=components-tabs--design', '/docs/components/Tabs/OrigamTabs.html', 'tabs', '{"a11y": {"notes": [{"noteKey": "components.tab_panel.a11y.aria_note", "noteFallback": "OrigamTabPanel sets role=\"tabpanel\" and aria-labelledby pointing to the sibling tab DOM id automatically. No manual ARIA needed."}, {"noteKey": "components.tab_panel.a11y.lazy_note", "noteFallback": "Content is not in the DOM until the panel is first activated (unless eager=true). Screen readers only perceive the content after it is mounted."}, {"noteKey": "components.tab_panel.a11y.vshow_note", "noteFallback": "Inactive panels use v-show (not v-if) after first mount, so content remains in the DOM. Assistive technologies may still reach it via search — the v-show=\"false\" (display: none) does hide it from AT per ARIA spec."}], "roles": ["tabpanel"], "keyboard": [{"key": "Tab", "actionKey": "components.tab_panel.a11y.key_tab", "actionFallback": "Moves focus into the panel content from the tablist."}, {"key": "Shift + Tab", "actionKey": "components.tab_panel.a11y.key_shift_tab", "actionFallback": "Returns focus to the active tab in the tablist."}]}, "tokens": {"excerpt": [{"type": "duration", "value": "var(--origam-motion__duration---fast)", "tokenPath": "--origam-tabs__panel---transition-duration", "descriptionKey": "components.tab_panel.tokens.transition_duration", "descriptionFallback": "Duration of the fade transition when switching panels."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"40\" width=\"480\" height=\"100\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"60\" y=\"60\" width=\"440\" height=\"60\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"280\" y=\"94\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot content</text>\n  <circle cx=\"52\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"52\" y=\"52.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"72\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"72\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"52\" y1=\"36\" x2=\"80\" y2=\"18\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"16\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-tab-panel</text>\n  <text x=\"280\" y=\"160\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">① = role=\"tabpanel\" · tabindex=0 · aria-labelledby; ② = lazy #default slot</text>\n", "code": "<!-- root: role=\"tabpanel\", tabindex=0, aria-labelledby -->\n<Transition name=\"fade\" mode=\"out-in\">\n  <div\n    v-show=\"isShown\"\n    class=\"origam-tab-panel\"\n    role=\"tabpanel\"\n    tabindex=\"0\"\n    :aria-labelledby=\"tabLabelledBy\"\n  >\n    <!-- lazy slot: only renders after first activation -->\n    <slot v-if=\"hasContent\" name=\"default\" />\n  </div>\n</Transition>", "legend": [{"cls": ".origam-tab-panel", "num": 1, "descriptionKey": "components.tab_panel.anatomy.root", "descriptionFallback": "Root element. Carries <code>role=\"tabpanel\"</code>, <code>tabindex=\"0\"</code> and <code>aria-labelledby</code> pointing to the matching tab id. Hidden via <code>v-show</code> when inactive."}, {"cls": "#default slot", "num": 2, "descriptionKey": "components.tab_panel.anatomy.slot", "descriptionFallback": "Slot content area. Lazy-mounted on first activation via <code>useLazy</code> — renders only after the panel becomes selected for the first time."}], "classes": [{"cls": "origam-tab-panel", "descriptionKey": "components.tab_panel.anatomy.root", "descriptionFallback": "Root element. role=\"tabpanel\", tabindex=0, aria-labelledby, hidden via v-show when inactive."}, {"cls": "origam-tab-panel--active", "descriptionKey": "components.tab_panel.anatomy.active", "descriptionFallback": "Applied when this panel is the selected item in the panels group."}], "svgDesc": "Schematic of the TabPanel component with 2 numbered internal parts.", "svgTitle": "Anatomy of OrigamTabPanel", "rootClass": "origam-tab-panel", "figcaption": "Anatomy of <code>&lt;origam-tab-panel&gt;</code> — 2 parts. The root carries <code>role=\"tabpanel\"</code> and <code>aria-labelledby</code> pointing to the sibling tab; the slot content is lazy-mounted on first activation.", "svgViewBox": "0 0 560 180"}, "cssVars": [{"name": "--origam-tab-panels__panel---padding-block", "defaultValue": "16px", "descriptionKey": "components.tab_panel.css_vars.padding_block", "descriptionFallback": "Vertical padding applied to each tab panel via the parent OrigamTabPanels."}, {"name": "--origam-tab-panels__panel---padding-inline", "defaultValue": "0", "descriptionKey": "components.tab_panel.css_vars.padding_inline", "descriptionFallback": "Horizontal padding applied to each tab panel via the parent OrigamTabPanels."}, {"name": "--origam-tab-panels__panel---transition-duration", "defaultValue": "0.18s", "descriptionKey": "components.tab_panel.css_vars.transition_duration", "descriptionFallback": "Duration of the fade transition when switching panels."}, {"name": "--origam-tab-panels__panel--focus---outline-color", "defaultValue": "currentColor", "descriptionKey": "components.tab_panel.css_vars.focus_outline_color", "descriptionFallback": "Outline color shown on focus-visible for the panel container."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.tab_panel.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.tab_panel.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed panel styles."}, {"name": "id", "type": "string", "descriptionKey": "components.tab_panel.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.tab_panel.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.tab_panel.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.tab_panel.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "eager", "labelKey": "components.tab_panel.playground.eager", "defaultValue": false, "labelFallback": "Eager mount"}], "defaultSlotContent": ""}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b8ece23a-2315-4c19-b2e6-53db076249d6', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'tab-panels', 'TabPanels', 'Navigation', NULL, 'mdi-tab', 'components.catalog.tab_panels.description', 'Content container that mirrors the tablist selection — orchestrates OrigamTabPanel children with optional fade transition and swipe support.', NULL, NULL, 'origam-tab-panels', NULL, 'packages/ds/src/components/Tabs/OrigamTabPanels.vue', 'origam', NULL, NULL, '/stories/?story=components-tabs--design', '/docs/components/Tabs/OrigamTabs.html', 'tabs', '{"a11y": {"notes": [{"noteKey": "components.tab_panels.a11y.sync_note", "noteFallback": "OrigamTabPanels has no ARIA role of its own — it is a layout orchestrator. ARIA semantics live on each child OrigamTabPanel (role=\"tabpanel\")."}, {"noteKey": "components.tab_panels.a11y.sync_model_note", "noteFallback": "Keep the v-model in sync with the sibling OrigamTabs v-model. Desynchronised models break the aria-controls / aria-labelledby wiring between tabs and panels."}], "roles": [], "keyboard": [{"key": "Swipe left / right", "actionKey": "components.tab_panels.a11y.swipe", "actionFallback": "When swipeable=true, horizontal swipe navigates to the next/previous panel."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-tab-panels__panel---padding-block", "descriptionKey": "components.tab_panels.tokens.padding_block", "descriptionFallback": "Default vertical padding for panel content."}, {"type": "dimension", "value": "var(--origam-space---0)", "tokenPath": "--origam-tab-panels__panel---padding-inline", "descriptionKey": "components.tab_panels.tokens.padding_inline", "descriptionFallback": "Default horizontal padding for panel content."}, {"type": "duration", "value": "var(--origam-motion__duration---fast)", "tokenPath": "--origam-tabs__panel---transition-duration", "descriptionKey": "components.tab_panels.tokens.transition_duration", "descriptionFallback": "Duration of the fade transition between panels."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"30\" y=\"36\" width=\"540\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"50\" y=\"56\" width=\"500\" height=\"100\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <rect x=\"70\" y=\"76\" width=\"460\" height=\"60\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"300\" y=\"110\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-tab-panel (active)</text>\n  <circle cx=\"42\" cy=\"44\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"42\" y=\"48.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"62\" cy=\"64\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"62\" y=\"68\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"82\" cy=\"84\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"82\" y=\"88\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <line x1=\"42\" y1=\"32\" x2=\"70\" y2=\"14\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"74\" y=\"12\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-tab-panels</text>\n  <text x=\"300\" y=\"180\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">① root · ② defaults-provider · ③ active origam-tab-panel</text>\n", "code": "<!-- root: manages group + provides transition context -->\n<div class=\"origam-tab-panels\" v-touch=\"touchOptions\">\n  <!-- internal defaults provider forwards transition to all child panels -->\n  <origam-defaults-provider :defaults=\"slotDefaults\">\n    <!-- #default slot: place origam-tab-panel children here -->\n    <slot name=\"default\" v-bind=\"slotProps\" />\n  </origam-defaults-provider>\n</div>", "legend": [{"cls": ".origam-tab-panels", "num": 1, "descriptionKey": "components.tab_panels.anatomy.root", "descriptionFallback": "Root element. Manages the panel group via <code>useGroup</code> and provides transition context via <code>ORIGAM_TAB_PANELS_CTX_KEY</code>."}, {"cls": "OrigamDefaultsProvider (internal)", "num": 2, "descriptionKey": "components.tab_panels.anatomy.defaults_provider", "descriptionFallback": "Internal <code>&lt;OrigamDefaultsProvider&gt;</code> that injects the <code>transition</code> prop into child <code>&lt;OrigamTabPanel&gt;</code> elements without requiring explicit prop drilling."}, {"cls": ".origam-tab-panel--active", "num": 3, "descriptionKey": "components.tab_panels.anatomy.active_panel", "descriptionFallback": "The currently visible panel. Inactive panels remain in the DOM via <code>v-show</code> after first mount."}], "classes": [{"cls": "origam-tab-panels", "descriptionKey": "components.tab_panels.anatomy.root", "descriptionFallback": "Root element. display: block; position: relative. Provides transition context to child panels."}, {"cls": "origam-tab-panels--direction-vertical", "descriptionKey": "components.tab_panels.anatomy.vertical", "descriptionFallback": "Applied when direction=\"vertical\". Switches to display: flex; flex-direction: row."}, {"cls": "origam-tab-panels--swipeable", "descriptionKey": "components.tab_panels.anatomy.swipeable", "descriptionFallback": "Applied when swipeable=true. Adds overflow: hidden and touch-action: pan-y."}], "svgDesc": "Schematic of the TabPanels container with 3 numbered parts.", "svgTitle": "Anatomy of OrigamTabPanels", "rootClass": "origam-tab-panels", "figcaption": "Anatomy of <code>&lt;origam-tab-panels&gt;</code> — 3 layers. The root wraps an <code>&lt;OrigamDefaultsProvider&gt;</code> that forwards the <code>transition</code> prop to child panels. Only the active panel is shown; others are <code>v-show</code>-hidden.", "svgViewBox": "0 0 600 200"}, "cssVars": [{"name": "--origam-tab-panels__panel---padding-block", "defaultValue": "16px", "descriptionKey": "components.tab_panels.css_vars.padding_block", "descriptionFallback": "Vertical padding applied inside the tab panels container."}, {"name": "--origam-tab-panels__panel---padding-inline", "defaultValue": "0", "descriptionKey": "components.tab_panels.css_vars.padding_inline", "descriptionFallback": "Horizontal padding applied inside the tab panels container."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.tab_panels.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "next", "type": "() => void", "descriptionKey": "components.tab_panels.exposed.next", "descriptionFallback": "Programmatically selects the next panel in registration order."}, {"name": "prev", "type": "() => void", "descriptionKey": "components.tab_panels.exposed.prev", "descriptionFallback": "Programmatically selects the previous panel in registration order."}, {"name": "select", "type": "(value: any, selected: boolean) => void", "descriptionKey": "components.tab_panels.exposed.select", "descriptionFallback": "Programmatically selects a panel by its registered value."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.tab_panels.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.tab_panels.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.tab_panels.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.tab_panels.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.tab_panels.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "transition", "options": [{"label": "fade (default)", "value": "fade"}, {"label": "(none)", "value": ""}], "labelKey": "components.tab_panels.playground.transition", "defaultValue": "fade", "labelFallback": "Transition"}, {"kind": "switch", "prop": "swipeable", "labelKey": "components.tab_panels.playground.swipeable", "defaultValue": false, "labelFallback": "Swipeable"}, {"kind": "select", "prop": "direction", "options": [{"label": "horizontal", "value": "horizontal"}, {"label": "vertical", "value": "vertical"}], "labelKey": "components.tab_panels.playground.direction", "defaultValue": "horizontal", "labelFallback": "Direction"}], "defaultSlotContent": ""}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
