INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('66a79428-3598-474e-bf7c-1d129ab0e315', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'text-mask', 'TextMask', 'Data Display', NULL, 'mdi-format-color-text', 'components.catalog.text_mask.description', 'Renders text with a gradient or image as a transparent fill via background-clip: text. Supports animated gradients (pan, rotate, pulse, zoom).', NULL, NULL, 'origam-text-mask', NULL, 'packages/ds/src/components/TextMask/OrigamTextMask.vue', 'origam', NULL, NULL, '/stories/?story=components-textmask--design', '/docs/components/TextMask/OrigamTextMask.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.text_mask.a11y.dom_text_note", "noteFallback": "The text content is preserved in the DOM as plain text (or semantic slot content). The background-clip:text transform is purely CSS — screen readers and search engines read the real text."}, {"noteKey": "components.text_mask.a11y.reduced_motion_note", "noteFallback": "All CSS animations are disabled under prefers-reduced-motion: reduce. The background-size reverts to cover so the gradient is still visible."}, {"noteKey": "components.text_mask.a11y.contrast_note", "noteFallback": "Gradient backgrounds may produce low-contrast regions. Verify WCAG AA contrast ratios for the minimum-contrast point of the gradient. Add a fallback color for browsers that do not support background-clip:text."}], "roles": ["(none — inline text)"], "keyboard": []}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-font__size---5xl)", "tokenPath": "--origam-text-mask---font-size-default", "descriptionKey": "components.text_mask.tokens.font_size_default", "descriptionFallback": "Reference display font size used in the DS story defaults."}, {"type": "fontWeight", "value": "var(--origam-font__weight---bold)", "tokenPath": "--origam-text-mask---font-weight-default", "descriptionKey": "components.text_mask.tokens.font_weight_default", "descriptionFallback": "Reference font weight used in the DS story defaults."}, {"type": "number", "value": "var(--origam-font__lineHeight---tight)", "tokenPath": "--origam-text-mask---line-height-default", "descriptionKey": "components.text_mask.tokens.line_height_default", "descriptionFallback": "Tight line-height suited to large display text."}, {"type": "duration", "value": "3s", "tokenPath": "--origam-text-mask__animation---duration-default", "descriptionKey": "components.text_mask.tokens.animation_duration", "descriptionFallback": "Default animation cycle duration."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"544\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <defs>\n    <linearGradient id=\"tmGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" style=\"stop-color:#7c3aed\"/>\n      <stop offset=\"50%\" style=\"stop-color:#a855f7\"/>\n      <stop offset=\"100%\" style=\"stop-color:#06b6d4\"/>\n    </linearGradient>\n  </defs>\n  <text x=\"300\" y=\"92\" font-size=\"32\" fill=\"url(#tmGrad)\" font-weight=\"900\" text-anchor=\"middle\" font-family=\"sans-serif\">Hello World</text>\n  <circle cx=\"36\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"46\" y1=\"40\" x2=\"80\" y2=\"22\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"22\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-text-mask</text>\n  <text x=\"300\" y=\"148\" font-size=\"8\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">background-clip: text · -webkit-text-fill-color: transparent</text>\n", "code": "<!-- root: inline-block with background-clip: text -->\n<component\n  :is=\"tag\"\n  class=\"origam-text-mask\"\n  :class=\"[\n    `origam-text-mask--align-${align}`,\n    `origam-text-mask--${animationType}`,\n    { ''origam-text-mask--animated'': animated }\n  ]\"\n  :style=\"{\n    ''--origam-text-mask---bg'': resolvedBackground,\n    ''--origam-text-mask---font-size'': ...,\n    ''--origam-text-mask---font-weight'': ...,\n  }\"\n>\n  <!-- slot content (wins over text prop) -->\n  <slot v-if=\"hasSlot\"/>\n  <template v-else>{{ text }}</template>\n</component>", "legend": [{"cls": ".origam-text-mask", "num": 1, "descriptionKey": "components.text_mask.anatomy.root", "descriptionFallback": "Root element (span by default). Sets background-image, background-clip:text and -webkit-text-fill-color:transparent. Animation classes are added when animated=true."}], "classes": [{"cls": "origam-text-mask", "descriptionKey": "components.text_mask.anatomy.root", "descriptionFallback": "Root element. display:inline-block with background-clip:text."}, {"cls": "origam-text-mask--align-left", "descriptionKey": "components.text_mask.anatomy.align_left", "descriptionFallback": "text-align: left (default)."}, {"cls": "origam-text-mask--align-center", "descriptionKey": "components.text_mask.anatomy.align_center", "descriptionFallback": "text-align: center."}, {"cls": "origam-text-mask--align-right", "descriptionKey": "components.text_mask.anatomy.align_right", "descriptionFallback": "text-align: right."}, {"cls": "origam-text-mask--animated", "descriptionKey": "components.text_mask.anatomy.animated", "descriptionFallback": "Added when animated=true. Enables the keyframe animation selected by --{animationType}."}, {"cls": "origam-text-mask--pan", "descriptionKey": "components.text_mask.anatomy.pan", "descriptionFallback": "Horizontal pan animation (background-position 0% → 100%)."}, {"cls": "origam-text-mask--rotate", "descriptionKey": "components.text_mask.anatomy.rotate", "descriptionFallback": "Hue-rotate animation (filter: hue-rotate 0 → 360deg)."}, {"cls": "origam-text-mask--pulse", "descriptionKey": "components.text_mask.anatomy.pulse", "descriptionFallback": "Size pulse animation (background-size oscillates)."}, {"cls": "origam-text-mask--zoom", "descriptionKey": "components.text_mask.anatomy.zoom", "descriptionFallback": "Zoom animation (background-size 100% → 220%)."}], "svgDesc": "Schematic of the TextMask component — root with inline background-clip style.", "svgTitle": "Anatomy of OrigamTextMask", "rootClass": "origam-text-mask", "figcaption": "Anatomy of <code>&lt;origam-text-mask&gt;</code> — single root element with <code>background-clip: text</code>. The text content is preserved in the DOM; the gradient/image visual is CSS-only.", "svgViewBox": "0 0 600 160"}, "cssVars": [{"name": "--origam-text-mask---bg", "defaultValue": "undefined", "descriptionKey": "components.text_mask.css_vars.bg", "descriptionFallback": "Resolved background-image value (gradient or url()). Set from the background prop."}, {"name": "--origam-text-mask---duration", "defaultValue": "3s", "descriptionKey": "components.text_mask.css_vars.duration", "descriptionFallback": "Animation cycle duration. Maps to animationDuration prop."}, {"name": "--origam-text-mask---font-size", "defaultValue": "inherit", "descriptionKey": "components.text_mask.css_vars.font_size", "descriptionFallback": "Font size of the masked text."}, {"name": "--origam-text-mask---font-weight", "defaultValue": "inherit", "descriptionKey": "components.text_mask.css_vars.font_weight", "descriptionFallback": "Font weight of the masked text."}, {"name": "--origam-text-mask---font-family", "defaultValue": "inherit", "descriptionKey": "components.text_mask.css_vars.font_family", "descriptionFallback": "Font family of the masked text."}, {"name": "--origam-text-mask---line-height", "defaultValue": "1.1", "descriptionKey": "components.text_mask.css_vars.line_height", "descriptionFallback": "Line height of the masked text."}, {"name": "--origam-text-mask---letter-spacing", "defaultValue": "normal", "descriptionKey": "components.text_mask.css_vars.letter_spacing", "descriptionFallback": "Letter spacing of the masked text."}], "exposed": [{"name": "resolvedBackground", "type": "ComputedRef<string>", "descriptionKey": "components.text_mask.exposed.resolved_background", "descriptionFallback": "The resolved background-image CSS value (gradient or url()). Derived from the background prop after resolveGradient() processing."}, {"name": "hasSlot", "type": "ComputedRef<boolean>", "descriptionKey": "components.text_mask.exposed.has_slot", "descriptionFallback": "True when the default slot is provided. When false, the text prop is rendered."}], "playground": {"controls": [{"kind": "select", "prop": "background", "options": [{"label": "Violet → Cyan", "value": "linear-gradient(90deg, #7c3aed, #a855f7, #06b6d4)"}, {"label": "Sunset", "value": "linear-gradient(135deg, #f59e0b, #ef4444, #a855f7)"}, {"label": "Ocean", "value": "linear-gradient(135deg, #06b6d4, #3b82f6, #6366f1)"}, {"label": "Forest", "value": "linear-gradient(135deg, #10b981, #059669, #3b82f6)"}], "labelKey": "components.text_mask.playground.background", "defaultValue": "linear-gradient(90deg, #7c3aed, #a855f7, #06b6d4)", "labelFallback": "Background"}, {"kind": "switch", "prop": "animated", "labelKey": "components.text_mask.playground.animated", "defaultValue": false, "labelFallback": "Animated"}, {"kind": "select", "prop": "animationType", "options": [{"label": "pan", "value": "pan"}, {"label": "rotate", "value": "rotate"}, {"label": "pulse", "value": "pulse"}, {"label": "zoom", "value": "zoom"}], "labelKey": "components.text_mask.playground.animation_type", "defaultValue": "pan", "labelFallback": "Animation type"}, {"kind": "number", "prop": "fontSize", "labelKey": "components.text_mask.playground.font_size", "defaultValue": 48, "labelFallback": "Font size (px)"}, {"kind": "select", "prop": "fontWeight", "options": [{"label": "400", "value": 400}, {"label": "600", "value": 600}, {"label": "700", "value": 700}, {"label": "800", "value": 800}, {"label": "900", "value": 900}], "labelKey": "components.text_mask.playground.font_weight", "defaultValue": 800, "labelFallback": "Font weight"}, {"kind": "select", "prop": "align", "options": [{"label": "left", "value": "left"}, {"label": "center", "value": "center"}, {"label": "right", "value": "right"}], "labelKey": "components.text_mask.playground.align", "defaultValue": "left", "labelFallback": "Align"}], "defaultSlotContent": "Origam DS"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
