INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e9f3fbde-f533-4589-84b8-68c689f428f9', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'title', 'Title', 'Data Display', NULL, 'mdi-format-header-1', 'components.catalog.title.description', 'Polymorphic heading with configurable tag (h1–h6 or any block element) and density-driven typography tokens.', NULL, NULL, 'origam-title', NULL, 'packages/ds/src/components/Title/OrigamTitle.vue', 'origam', NULL, NULL, '/stories/?story=components-title--design', '/docs/components/Title/OrigamTitle.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.title.a11y.heading_level_note", "noteFallback": "Always choose a tag value that fits the document heading hierarchy (h1 for the page title, h2 for sections, etc.). Skipping heading levels (h1 → h3) impairs screen reader navigation."}, {"noteKey": "components.title.a11y.vcontrast_note", "noteFallback": "The vContrast directive automatically adjusts the text color for sufficient contrast against the background. Do not suppress it without verifying WCAG AA compliance manually."}, {"noteKey": "components.title.a11y.color_note", "noteFallback": "When setting color or bgColor, verify that the contrast ratio meets WCAG 2.1 AA (≥ 4.5:1 for normal text). The vContrast directive assists but does not guarantee compliance for every color combination."}], "roles": ["heading (native HTML)"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---primary)", "tokenPath": "--origam-title---color", "descriptionKey": "components.title.tokens.color", "descriptionFallback": "Default heading text color."}, {"type": "fontFamily", "value": "var(--origam-font__family---sans)", "tokenPath": "--origam-title---font-family", "descriptionKey": "components.title.tokens.font_family", "descriptionFallback": "Heading font family."}, {"type": "fontWeight", "value": "var(--origam-font__weight---semibold)", "tokenPath": "--origam-title---font-weight", "descriptionKey": "components.title.tokens.font_weight", "descriptionFallback": "Heading font weight."}, {"type": "dimension", "value": "var(--origam-font__size---xl)", "tokenPath": "--origam-title---font-size-md", "descriptionKey": "components.title.tokens.font_size_md", "descriptionFallback": "Font size for density=default."}, {"type": "dimension", "value": "var(--origam-font__size---3xl)", "tokenPath": "--origam-title---font-size-xl", "descriptionKey": "components.title.tokens.font_size_xl", "descriptionFallback": "Font size for density=comfortable."}, {"type": "dimension", "value": "var(--origam-font__size---md)", "tokenPath": "--origam-title---font-size-xs", "descriptionKey": "components.title.tokens.font_size_xs", "descriptionFallback": "Font size for density=compact."}, {"type": "dimension", "value": "var(--origam-font__letterSpacing---tight)", "tokenPath": "--origam-title---letter-spacing", "descriptionKey": "components.title.tokens.letter_spacing", "descriptionFallback": "Heading letter-spacing."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"544\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"52\" y=\"90\" font-size=\"28\" fill=\"var(--origam-color__text---primary, #1a1a2e)\" font-weight=\"700\" font-family=\"sans-serif\">Page Title</text>\n  <circle cx=\"36\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"46\" y1=\"40\" x2=\"80\" y2=\"22\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"22\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-title (tag=h1 default)</text>\n  <text x=\"300\" y=\"140\" font-size=\"8\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">density: compact → xs · default → md · comfortable → xl</text>\n", "code": "<!-- root: polymorphic heading, h1 by default -->\n<component\n  :is=\"tag\"\n  :id=\"id\"\n  v-contrast\n  class=\"origam-title\"\n  :class=\"[densityClasses, colorClasses, borderClasses, paddingClasses, marginClasses]\"\n  :style=\"[colorStyles, borderStyles, paddingStyles, marginStyles]\"\n>\n  <slot v-if=\"hasContent\" name=\"default\">{{ text }}</slot>\n</component>", "legend": [{"cls": ".origam-title", "num": 1, "descriptionKey": "components.title.anatomy.root", "descriptionFallback": "Root element. Renders as <h1> by default (overridable via tag prop). Uses vContrast directive for automatic text color contrast. Three density modifier classes control font size: --density-compact, --density-default, --density-comfortable."}], "classes": [{"cls": "origam-title", "descriptionKey": "components.title.anatomy.root", "descriptionFallback": "Root element. font-family, font-weight, letter-spacing, line-height come from tokens."}, {"cls": "origam-title--density-compact", "descriptionKey": "components.title.anatomy.density_compact", "descriptionFallback": "Applied when density=\"compact\". font-size: var(--origam-title---font-size-xs)."}, {"cls": "origam-title--density-default", "descriptionKey": "com