INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2ae4ae49-495c-4e27-b25c-03a8c0563f3f', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'treeview', 'Treeview', 'Data Display', NULL, 'mdi-file-tree', 'components.catalog.treeview.description', 'Hierarchical tree structure with expand/collapse, single/multi selection and optional guide lines. Items are defined via a typed ITreeviewNode list.', NULL, NULL, 'origam-treeview', NULL, 'packages/ds/src/components/Treeview/OrigamTreeview.vue', 'origam', NULL, NULL, '/stories/?story=components-treeview--design', '/docs/components/Treeview/OrigamTreeview.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.treeview.a11y.aria_roles", "noteFallback": "Root element has role=\"tree\"; each node has role=\"treeitem\". aria-selected, aria-expanded and aria-disabled are set reactively."}, {"noteKey": "components.treeview.a11y.multiselect", "noteFallback": "aria-multiselectable is set to true on the tree root when selectMode=\"multiple\"."}], "roles": ["tree", "treeitem"], "keyboard": [{"key": "ArrowRight", "actionKey": "components.treeview.a11y.key_expand", "actionFallback": "Expands a collapsed node, or moves focus to the first child of an already-expanded node."}, {"key": "ArrowLeft", "actionKey": "components.treeview.a11y.key_collapse", "actionFallback": "Collapses an expanded node, or moves focus to the parent node."}, {"key": "ArrowDown / ArrowUp", "actionKey": "components.treeview.a11y.key_vertical", "actionFallback": "Moves focus to the next/previous visible node in the tree."}, {"key": "Enter / Space", "actionKey": "components.treeview.a11y.key_select", "actionFallback": "Selects the focused node (when selectMode is not none)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-treeview---background-color", "descriptionKey": "components.treeview.tokens.background_color", "descriptionFallback": "Tree background."}, {"type": "color", "value": "var(--origam-color__action--primary---bgSubtle)", "tokenPath": "--origam-treeview---row-bg-selected", "descriptionKey": "components.treeview.tokens.row_bg_selected", "descriptionFallback": "Row background when selected."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-treeview---indent-size", "descriptionKey": "components.treeview.tokens.indent_size", "descriptionFallback": "Indentation per depth level."}, {"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-treeview---guide-color", "descriptionKey": "components.treeview.tokens.guide_color", "descriptionFallback": "Guide line color."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"380\" height=\"180\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <line x1=\"50\" y1=\"60\" x2=\"50\" y2=\"160\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.3))\" stroke-width=\"1.5\"/>\n  <rect x=\"30\" y=\"50\" width=\"350\" height=\"36\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"70\" y=\"71\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" font-family=\"''JetBrains Mono'',monospace\">src/</text>\n  <text x=\"40\" y=\"71\" font-size=\"14\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\">›</text>\n  <rect x=\"50\" y=\"100\" width=\"320\" height=\"32\" rx=\"4\" fill=\"transparent\"/>\n  <text x=\"80\" y=\"121\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" font-family=\"''JetBrains Mono'',monospace\">main.ts</text>\n  <rect x=\"50\" y=\"140\" width=\"320\" height=\"32\" rx=\"4\" fill=\"transparent\"/>\n  <text x=\"80\" y=\"161\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" font-family=\"''JetBrains Mono'',monospace\">App.vue</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"38\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"62\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"50\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"50\" y=\"62\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"50\" cy=\"110\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"50\" y=\"114\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<div role=\"tree\" class=\"origam-treeview\" aria-label=\"File tree\">\n  <origam-treeview-node\n    v-for=\"node in items\"\n    :key=\"node.id\"\n    :node=\"node\"\n    :depth=\"0\"\n  />\n</div>", "legend": [{"cls": ".origam-treeview", "num": 1, "descriptionKey": "components.treeview.anatomy.root", "descriptionFallback": "Root element. role=\"tree\", aria-multiselectable when selectMode=\"multiple\"."}, {"cls": ".origam-treeview-node", "num": 2, "descriptionKey": "components.treeview.anatomy.node", "descriptionFallback": "Each node row. role=\"treeitem\". aria-selected, aria-expanded, aria-disabled are set dynamically."}, {"cls": ".origam-treeview-node__chevron", "num": 3, "descriptionKey": "components.treeview.anatomy.chevron", "descriptionFallback": "Expand/collapse indicator. Rotated 90° when the node is expanded."}, {"cls": ".origam-treeview-node__children", "num": 4, "descriptionKey": "components.treeview.anatomy.children", "descriptionFallback": "Container for child nodes. Indented by indent-size per depth level."}], "classes": [{"cls": "origam-treeview", "descriptionKey": "components.treeview.anatomy.root", "descriptionFallback": "Root tree container."}, {"cls": "origam-treeview-node", "descriptionKey": "components.treeview.anatomy.node", "descriptionFallback": "Individual node wrapper."}, {"cls": "origam-treeview-node__chevron", "descriptionKey": "components.treeview.anatomy.chevron", "descriptionFallback": "Expand icon."}, {"cls": "origam-treeview-node__label", "descriptionKey": "components.treeview.anatomy.label", "descriptionFallback": "Node label text."}, {"cls": "origam-treeview-node__children", "descriptionKey": "components.treeview.anatomy.children", "descriptionFallback": "Children container (indented)."}], "svgDesc": "Schematic showing the Treeview root and one TreeviewNode with its parts.", "svgTitle": "Anatomy of OrigamTreeview", "rootClass": "origam-treeview", "figcaption": "Anatomy of <code>&lt;origam-treeview&gt;</code> — the root ① is a <code>role=\"tree\"</code> container; each node ② is a <code>role=\"treeitem\"</code> with a chevron ③ and recursive children ④.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-treeview---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.treeview.css_vars.background_color", "descriptionFallback": "Treeview background color."}, {"name": "--origam-treeview---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.treeview.css_vars.color", "descriptionFallback": "Default node text color."}, {"name": "--origam-treeview---indent-size", "defaultValue": "{space.4}", "descriptionKey": "components.treeview.css_vars.indent_size", "descriptionFallback": "Per-depth indentation size."}, {"name": "--origam-treeview---row-height", "defaultValue": "{space.8}", "descriptionKey": "components.treeview.css_vars.row_height", "descriptionFallback": "Height of each tree row."}, {"name": "--origam-treeview---row-bg-hover", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.treeview.css_vars.row_bg_hover", "descriptionFallback": "Row background on hover."}, {"name": "--origam-treeview---row-bg-selected", "defaultValue": "{color.action.primary.bgSubtle}", "descriptionKey": "components.treeview.css_vars.row_bg_selected", "descriptionFallback": "Row background when selected."}, {"name": "--origam-treeview---guide-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.treeview.css_vars.guide_color", "descriptionFallback": "Color of the vertical guide lines (show-lines)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.treeview.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "isExpanded", "type": "(id: string) => boolean", "descriptionKey": "components.treeview.exposed.is_expanded", "descriptionFallback": "Returns true if the given node id is currently expanded."}, {"name": "isSelected", "type": "(id: string) => boolean", "descriptionKey": "components.treeview.exposed.is_selected", "descriptionFallback": "Returns true if the given node id is in the selected set."}, {"name": "toggleExpanded", "type": "(id: string) => void", "descriptionKey": "components.treeview.exposed.toggle_expanded", "descriptionFallback": "Programmatically expand or collapse a node by id."}, {"name": "toggleSelected", "type": "(id: string) => void", "descriptionKey": "components.treeview.exposed.toggle_selected", "descriptionFallback": "Programmatically select or deselect a node by id."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.treeview.exposed.css", "descriptionFallback": "Reactive CSS string for computed styles."}, {"name": "id", "type": "string", "descriptionKey": "components.treeview.exposed.id", "descriptionFallback": "Unique style-sheet ID."}, {"name": "load", "type": "() => void", "descriptionKey": "components.treeview.exposed.load", "descriptionFallback": "Injects the style sheet on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.treeview.exposed.unload", "descriptionFallback": "Removes the style sheet on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.treeview.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "selectMode", "options": [{"label": "none", "value": "none"}, {"label": "single", "value": "single"}, {"label": "multiple", "value": "multiple"}], "labelKey": "components.treeview.playground.select_mode", "defaultValue": "none", "labelFallback": "Select mode"}, {"kind": "select", "prop": "selectableNodes", "options": [{"label": "leaf", "value": "leaf"}, {"label": "branch", "value": "branch"}, {"label": "all", "value": "all"}], "labelKey": "components.treeview.playground.selectable_nodes", "defaultValue": "leaf", "labelFallback": "Selectable nodes"}, {"kind": "switch", "prop": "showLines", "labelKey": "components.treeview.playground.show_lines", "defaultValue": true, "labelFallback": "Show guide lines"}, {"kind": "switch", "prop": "expandOnClick", "labelKey": "components.treeview.playground.expand_on_click", "defaultValue": false, "labelFallback": "Expand on row click"}, {"kind": "select", "prop": "color", "options": [{"label": "primary", "value": "primary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.treeview.playground.color", "defaultValue": "primary", "labelFallback": "Selection color"}]}, "previewVariants": [{"label": "default tree", "props": {"showLines": true, "selectMode": "none", "expandOnClick": false}}, {"label": "single select", "props": {"showLines": true, "selectMode": "single", "expandOnClick": true}}, {"label": "no lines", "props": {"showLines": false, "selectMode": "none"}}, {"label": "colored selection", "props": {"color": "primary", "showLines": true, "selectMode": "single"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('32b1a18f-7060-423c-bc6a-4a151186e45c', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'treeview-node', 'TreeviewNode', 'Data Display', NULL, 'mdi-file-tree', 'components.catalog.treeview_node.description', 'Single node in a Treeview — renders chevron, icon, label and size badge; recursively renders children when expanded. Handles its own expand/select keyboard interactions.', NULL, NULL, 'origam-treeview-node', NULL, 'packages/ds/src/components/Treeview/OrigamTreeviewNode.vue', 'origam', NULL, NULL, '/stories/?story=components-treeview--design', '/docs/components/Treeview/OrigamTreeview.html', 'treeview', '{"a11y": {"notes": [{"noteKey": "components.treeview_node.a11y.role_note", "noteFallback": "OrigamTreeviewNode uses a wrapper with role=\"none\" and an inner interactive div with role=\"treeitem\". ARIA attributes (aria-expanded, aria-selected, aria-disabled, aria-label) are applied to the inner row only."}, {"noteKey": "components.treeview_node.a11y.group_note", "noteFallback": "The children container uses role=\"group\" with aria-label=\"{node.label} contents\" as required by the ARIA tree pattern."}, {"noteKey": "components.treeview_node.a11y.focus_note", "noteFallback": "Focus-visible outline is applied on the row via :focus-visible (2px solid, outline-offset: -2px)."}, {"noteKey": "components.treeview_node.a11y.decorative_note", "noteFallback": "Guide lines, chevron and icon are all aria-hidden=\"true\". Only the label contributes to the accessible name (supplemented by aria-label=\"node.label\" on the treeitem)."}], "roles": ["treeitem"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.treeview_node.a11y.key_activate", "actionFallback": "Selects the node (if selectable) or toggles expansion (if it has children and is not selectable)."}, {"key": "ArrowRight", "actionKey": "components.treeview_node.a11y.key_arrow_right", "actionFallback": "If collapsed and has children: expands. If expanded and has children: moves focus to first child."}, {"key": "ArrowLeft", "actionKey": "components.treeview_node.a11y.key_arrow_left", "actionFallback": "If expanded: collapses the node. If collapsed: moves focus to the parent treeitem."}, {"key": "Tab", "actionKey": "components.treeview_node.a11y.key_tab", "actionFallback": "Moves focus out of the tree to the next focusable element in the page."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-treeview---indent-size", "descriptionKey": "components.treeview_node.tokens.indent_size", "descriptionFallback": "Indent per depth level."}, {"type": "dimension", "value": "var(--origam-space---8)", "tokenPath": "--origam-treeview---row-height", "descriptionKey": "components.treeview_node.tokens.row_height", "descriptionFallback": "Minimum row height."}, {"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-treeview---row-bg-hover", "descriptionKey": "components.treeview_node.tokens.row_bg_hover", "descriptionFallback": "Row background on hover."}, {"type": "color", "value": "var(--origam-color__action--primary---bgSubtle)", "tokenPath": "--origam-treeview---row-bg-selected", "descriptionKey": "components.treeview_node.tokens.row_bg_selected", "descriptionFallback": "Row background when selected."}, {"type": "dimension", "value": "var(--origam-font__size---sm)", "tokenPath": "--origam-treeview---label-font-size", "descriptionKey": "components.treeview_node.tokens.label_font_size", "descriptionFallback": "Font size of the node label."}, {"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-treeview---guide-color", "descriptionKey": "components.treeview_node.tokens.guide_color", "descriptionFallback": "Color of the vertical guide lines."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"640\" height=\"280\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- node wrapper -->\n  <rect x=\"20\" y=\"30\" width=\"600\" height=\"230\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- row -->\n  <rect x=\"36\" y=\"46\" width=\"568\" height=\"48\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\"/>\n  <!-- guide lines (2 levels) -->\n  <rect x=\"48\" y=\"46\" width=\"2\" height=\"48\" fill=\"var(--origam-color__border---subtle, rgba(168,85,247,0.3))\"/>\n  <rect x=\"64\" y=\"46\" width=\"2\" height=\"48\" fill=\"var(--origam-color__border---subtle, rgba(168,85,247,0.2))\"/>\n  <!-- chevron -->\n  <rect x=\"72\" y=\"58\" width=\"20\" height=\"24\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"82\" y=\"74\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\">›</text>\n  <!-- icon -->\n  <rect x=\"98\" y=\"58\" width=\"24\" height=\"24\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"110\" y=\"74\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #1a1035)\" text-anchor=\"middle\">📁</text>\n  <!-- label -->\n  <rect x=\"130\" y=\"58\" width=\"300\" height=\"24\" rx=\"2\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <text x=\"240\" y=\"74\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #1a1035)\" font-family=\"''JetBrains Mono'',monospace\">node.label</text>\n  <!-- size -->\n  <rect x=\"438\" y=\"58\" width=\"60\" height=\"24\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\"/>\n  <text x=\"468\" y=\"74\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">size</text>\n  <!-- slot node -->\n  <rect x=\"36\" y=\"106\" width=\"568\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.20))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"320\" y=\"128\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#node slot</text>\n  <!-- children group -->\n  <rect x=\"36\" y=\"154\" width=\"568\" height=\"88\" rx=\"3\" fill=\"var(--origam-color__surface---sunken, #f9f5ff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.20))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"320\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-treeview-node (recursive children)</text>\n  <!-- numbers -->\n  <circle cx=\"30\" cy=\"38\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"30\" y=\"42.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"44\" cy=\"54\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"44\" y=\"58\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"48\" cy=\"70\" r=\"7\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"48\" y=\"74\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"82\" cy=\"54\" r=\"7\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"82\" y=\"58\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"110\" cy=\"54\" r=\"7\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"110\" y=\"58\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"240\" cy=\"54\" r=\"7\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"240\" y=\"58\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <circle cx=\"468\" cy=\"54\" r=\"7\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"468\" y=\"58\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">7</text>\n  <circle cx=\"320\" cy=\"162\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"320\" y=\"166\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">8</text>\n  <line x1=\"30\" y1=\"26\" x2=\"60\" y2=\"10\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"64\" y=\"8\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-treeview-node</text>\n  <text x=\"320\" y=\"260\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">③ guide lines · ④ chevron · ⑤ icon · ⑥ label · ⑦ size — inside ② row; ⑧ = recursive children</text>\n", "code": "<!-- root: role=\"none\" (ARIA on inner row) -->\n<div class=\"origam-treeview-node\" role=\"none\">\n  <!-- interactive row: role=\"treeitem\" -->\n  <div\n    class=\"origam-treeview-node__row\"\n    role=\"treeitem\"\n    :aria-expanded=\"hasChildren ? isNodeExpanded : undefined\"\n    :aria-selected=\"isSelectable ? isNodeSelected : undefined\"\n    :aria-disabled=\"node.disabled || undefined\"\n    :aria-label=\"node.label\"\n    tabindex=\"0\"\n  >\n    <!-- guide lines (once per depth, v-for + v-if) -->\n    <span class=\"origam-treeview-node__guide\" aria-hidden=\"true\" />\n\n    <!-- chevron: rotates on expand, hidden on leaves -->\n    <span class=\"origam-treeview-node__chevron\" aria-hidden=\"true\">\n      &#8250;\n    </span>\n\n    <!-- icon: custom, folder, or leaf -->\n    <span class=\"origam-treeview-node__icon\" aria-hidden=\"true\" />\n\n    <!-- label text -->\n    <span class=\"origam-treeview-node__label\">{{ node.label }}</span>\n\n    <!-- optional size badge -->\n    <span class=\"origam-treeview-node__size\">{{ node.size }}</span>\n  </div>\n\n  <!-- custom #node slot (after the row) -->\n  <slot name=\"node\" :node=\"node\" :depth=\"depth\" :is-expanded=\"isNodeExpanded\" :is-selected=\"isNodeSelected\" />\n\n  <!-- recursive children (v-if=\"isNodeExpanded && hasChildren\") -->\n  <div class=\"origam-treeview-node__children\" role=\"group\">\n    <origam-treeview-node v-for=\"child in node.children\" :key=\"child.id\" :node=\"child\" :depth=\"depth + 1\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-treeview-node", "num": 1, "descriptionKey": "components.treeview_node.anatomy.root", "descriptionFallback": "Root wrapper, <code>role=\"none\"</code>. Flex column, no ARIA role — ARIA is on the inner row."}, {"cls": ".origam-treeview-node__row", "num": 2, "descriptionKey": "components.treeview_node.anatomy.row", "descriptionFallback": "Interactive row. <code>role=\"treeitem\"</code>, <code>aria-expanded</code>, <code>aria-selected</code>, <code>aria-disabled</code>, <code>tabindex</code>. Handles click and keyboard events."}, {"cls": ".origam-treeview-node__guide", "num": 3, "descriptionKey": "components.treeview_node.anatomy.guide", "descriptionFallback": "Vertical guide line repeated once per depth level (depth > 0 and showLines=true). <code>aria-hidden=\"true\"</code>."}, {"cls": ".origam-treeview-node__chevron", "num": 4, "descriptionKey": "components.treeview_node.anatomy.chevron", "descriptionFallback": "Expand/collapse indicator. Rotates 90° when expanded. Invisible (<code>visibility: hidden</code>) on leaf nodes."}, {"cls": ".origam-treeview-node__icon", "num": 5, "descriptionKey": "components.treeview_node.anatomy.icon", "descriptionFallback": "Node icon — custom <code>node.icon</code>, or a folder emoji (expanded/collapsed), or a document emoji for leaves. <code>aria-hidden=\"true\"</code>."}, {"cls": ".origam-treeview-node__label", "num": 6, "descriptionKey": "components.treeview_node.anatomy.label", "descriptionFallback": "Node label text. <code>flex: 1</code>, truncated with ellipsis. Uses the <code>node.label</code> value."}, {"cls": ".origam-treeview-node__size", "num": 7, "descriptionKey": "components.treeview_node.anatomy.size", "descriptionFallback": "Optional size badge. Only rendered when <code>node.size</code> is provided."}, {"cls": ".origam-treeview-node__children", "num": 8, "descriptionKey": "components.treeview_node.anatomy.children", "descriptionFallback": "Children container, <code>role=\"group\"</code>, <code>aria-label=\"{node.label} contents\"</code>. Shown only when expanded. Recursively renders <code>&lt;OrigamTreeviewNode&gt;</code> for each child."}], "classes": [{"cls": "origam-treeview-node", "descriptionKey": "components.treeview_node.anatomy.root", "descriptionFallback": "Root wrapper. role=\"none\", flex column."}, {"cls": "origam-treeview-node--expanded", "descriptionKey": "components.treeview_node.anatomy.expanded", "descriptionFallback": "Applied when the node is in expanded state."}, {"cls": "origam-treeview-node--selected", "descriptionKey": "components.treeview_node.anatomy.selected", "descriptionFallback": "Applied when the node is in selected state."}, {"cls": "origam-treeview-node--disabled", "descriptionKey": "components.treeview_node.anatomy.disabled", "descriptionFallback": "Applied when node.disabled=true."}, {"cls": "origam-treeview-node__row", "descriptionKey": "components.treeview_node.anatomy.row", "descriptionFallback": "Interactive row element. Carries role=\"treeitem\" and all ARIA attributes."}, {"cls": "origam-treeview-node__row--selected", "descriptionKey": "components.treeview_node.anatomy.row_selected", "descriptionFallback": "Applied to the row when selected."}, {"cls": "origam-treeview-node__row--disabled", "descriptionKey": "components.treeview_node.anatomy.row_disabled", "descriptionFallback": "Applied to the row when disabled."}, {"cls": "origam-treeview-node__row--selectable", "descriptionKey": "components.treeview_node.anatomy.row_selectable", "descriptionFallback": "Applied to the row when the node can be selected."}, {"cls": "origam-treeview-node__guide", "descriptionKey": "components.treeview_node.anatomy.guide", "descriptionFallback": "Vertical guide line. Rendered once per depth level when showLines is active."}, {"cls": "origam-treeview-node__chevron", "descriptionKey": "components.treeview_node.anatomy.chevron", "descriptionFallback": "Expand indicator. Rotates on expand, hidden on leaf nodes."}, {"cls": "origam-treeview-node__chevron--expanded", "descriptionKey": "components.treeview_node.anatomy.chevron_expanded", "descriptionFallback": "Applied when node is expanded. Rotates chevron 90°."}, {"cls": "origam-treeview-node__chevron--hidden", "descriptionKey": "components.treeview_node.anatomy.chevron_hidden", "descriptionFallback": "Applied on leaf nodes (visibility: hidden, space preserved)."}, {"cls": "origam-treeview-node__icon", "descriptionKey": "components.treeview_node.anatomy.icon", "descriptionFallback": "Node icon element. aria-hidden=\"true\"."}, {"cls": "origam-treeview-node__label", "descriptionKey": "components.treeview_node.anatomy.label", "descriptionFallback": "Node label. flex: 1, truncated with ellipsis."}, {"cls": "origam-treeview-node__size", "descriptionKey": "components.treeview_node.anatomy.size", "descriptionFallback": "Size badge. Only rendered when node.size is provided."}, {"cls": "origam-treeview-node__children", "descriptionKey": "components.treeview_node.anatomy.children", "descriptionFallback": "Children container. role=\"group\", shown only when expanded."}], "svgDesc": "Schematic of the TreeviewNode component with 8 numbered internal parts.", "svgTitle": "Anatomy of OrigamTreeviewNode", "rootClass": "origam-treeview-node", "figcaption": "Anatomy of <code>&lt;origam-treeview-node&gt;</code> — 8 parts. The root wrapper holds the interactive row (with guide lines, chevron, icon, label and size) followed by the optional node slot and the recursive children group.", "svgViewBox": "0 0 640 280"}, "cssVars": [{"name": "--origam-treeview---indent-size", "defaultValue": "16px", "descriptionKey": "components.treeview_node.css_vars.indent_size", "descriptionFallback": "Indent per depth level. Applied via CSS calc on the row padding-inline-start."}, {"name": "--origam-treeview---row-height", "defaultValue": "32px", "descriptionKey": "components.treeview_node.css_vars.row_height", "descriptionFallback": "Minimum row height."}, {"name": "--origam-treeview---row-padding-inline", "defaultValue": "8px", "descriptionKey": "components.treeview_node.css_vars.row_padding_inline", "descriptionFallback": "Horizontal padding added to the base indent on the row."}, {"name": "--origam-treeview---row-bg-hover", "defaultValue": "var(--origam-color__surface---overlay)", "descriptionKey": "components.treeview_node.css_vars.row_bg_hover", "descriptionFallback": "Row background on hover."}, {"name": "--origam-treeview---row-bg-selected", "defaultValue": "var(--origam-color__action--primary---bgS