INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('9e04d16b-a840-4aa3-9196-610ab52bc1f6', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'component', 'video', 'Video', 'Media', NULL, 'mdi-video', 'components.catalog.video.description', 'Full-featured HTML5 video player with custom controls, picture-in-picture, fullscreen, captions, playback rate, cast/AirPlay and double-tap-to-skip. All browser native events are surfaced as Vue emits.', NULL, NULL, 'origam-video', NULL, 'packages/ds/src/components/Video/OrigamVideo.vue', 'origam', NULL, NULL, '/stories/?story=components-video--design', '/docs/components/Video/OrigamVideo.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.video.a11y.captions", "noteFallback": "Subtitles/captions are provided via the tracks prop using WebVTT format. The captions button in the toolbar toggles the active track."}, {"noteKey": "components.video.a11y.autoplay", "noteFallback": "Autoplay is suppressed when prefers-reduced-motion: reduce is active, respecting the user preference."}, {"noteKey": "components.video.a11y.aria", "noteFallback": "The controls bar uses aria-label for icon-only buttons (play, mute, fullscreen). The scrubber is a range input with aria-label, aria-valuemin, aria-valuemax and aria-valuenow."}], "roles": ["region"], "keyboard": [{"key": "Space / K", "actionKey": "components.video.a11y.key_play_pause", "actionFallback": "Toggle play/pause (when focus is on the player or controls)."}, {"key": "ArrowRight / ArrowLeft", "actionKey": "components.video.a11y.key_seek", "actionFallback": "Seek forward/backward by 5 seconds."}, {"key": "ArrowUp / ArrowDown", "ac