INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('dcdf873a-6f83-4b36-b571-df2158c4d8ff', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-calendar', 'useCalendar', NULL, 'Calendar', 'mdi-calendar', '', 'Stateless calendar engine powering <OrigamCalendar>. Computes the visible date range for month/week/day/agenda views, expands recurring events (RRULE), and provides pure grid-builder functions for month, week, and day layouts. Navigation mutates the current date via optional callbacks so the composable can be driven from props, a store, or a local ref without re-instantiation.', NULL, 'function useCalendar(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2d2acc23-7252-45a1-840a-c15504a4690c', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-cell', 'useCell', NULL, 'DataTable', 'mdi-table-column', '', 'Resolve the padding for a DataTable cell based on the column definition. Special columns (data-table-select and data-table-expand) receive a fixed narrow padding; user-defined columns honour the column''s own padding setting; all others receive the default undefined (letting CSS tokens drive the spacing).', NULL, 'function useCell(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('48cd93b2-fc80-48f3-b7ed-e364be2db51f', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-chart', 'useChart', NULL, 'Chart', 'mdi-chart-line', '', 'Stateless SVG chart engine powering <OrigamChart>. Computes every render-time descriptor needed for cartesian, polar, pie/donut, radar, bar, scatter, and stacked variants: viewBox, pixel-mapping scales, gridline ticks, per-series path/rect/circle descriptors, resolved legend entries, and an interactive hover state. Driven entirely by thunk options so it reacts to props, stores, or computed refs without re-instantiation.', NULL, 'function useChart(options: IUseChartOptions): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('ca671e59-201d-4882-8115-16028983a562', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-chart-animation', 'useChartAnimationStyle', 'Chart', 'Chart', NULL, NULL, NULL, NULL, 'function useChartAnimationStyle(props: Pick<IChartBaseProps, ''animationDuration''>): ComputedRef<Record<string, string>>', NULL, NULL, 'packages/ds/src/composables/Chart/chart-animation.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fb60babb-37ff-43bf-8bfa-97f61d3376d6', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-chart-gauge', 'useChartGauge', NULL, 'Chart', 'mdi-gauge', '', 'Solid-gauge geometry engine for <OrigamChartGauge>. Given a value clamped between min and max, computes the SVG arc paths for the track (full arc background) and the indicator (partial arc proportional to the value), plus centre coordinates and radius values for the value label. Designed to mirror a speedometer-style gauge with a configurable sweep angle and thickness.', NULL, 'function useChartGauge(options: IUseChartGaugeOptions): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('84479b52-15d0-488d-994a-a25fb2a33079', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-chart-header-typography', 'useChartHeaderTypography', 'Chart', 'Chart', NULL, NULL, NULL, NULL, 'function useChartHeaderTypography(props: ITypographyProps): { headerTypographyStyles: ComputedRef<StyleValue>; }', NULL, NULL, 'packages/ds/src/composables/Chart/chart-header-typography.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('dfa4afbe-9824-4167-a85d-f0be2125bb87', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-chart-zoom', 'useChartZoom', NULL, 'Chart', 'mdi-magnify-plus-outline', '', 'Manages interactive zoom and pan state for OrigamChartCartesian. The zoom window is expressed as a closed [zoomStart, zoomEnd] range of category indices. Provides scroll-wheel zoom, drag-to-select zoom, and programmatic pan, all with clamping invariants.', NULL, 'function useChartZoom(options: { dataLength: () => number }): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0f389d48-f9bf-47da-96ff-82bb891a31dc', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-clipboard', 'useClipboard', NULL, 'Clipboard', 'mdi-clipboard-outline', '', 'Headless clipboard composable. Wraps the modern navigator.clipboard.writeText API with a legacy execCommand fallback. Exposes a self-resetting copied flag so consumers do not need to wire the reset timeout themselves. Never throws — callers branch on the returned boolean.', NULL, 'function useClipboard(options?: IUseClipboardOptions): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('88b210c8-4e8e-48af-b49b-af989e8bc03f', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-code', 'useCode', NULL, 'Code', 'mdi-code-tags', '', 'Singleton shiki-powered syntax highlighter. Lazily loads shiki on the first highlight() call to keep the initial bundle small. Bundles only the curated origam language subset and dual light/dark themes so token colours switch via CSS variables without re-tokenising. Caches results in a tiny LRU keyed by (code, lang).', NULL, 'function useCode(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3e3b2bc2-925b-4b47-814e-d9189bd1b464', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-css-support', 'useCssSupport', NULL, 'CssSupport', 'mdi-code-braces', '', 'The single CSS feature-detection layer in Origam. Provides a reactive flag map for the monitored feature matrix, plus free-form supports() / supportsAny() / supportsAll() helpers with per-query caching. Never call CSS.supports() directly in a component.', NULL, 'function useCssSupport(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('21d1caa8-f4a6-4079-b8b3-8ad320001fbe', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-css-support-client', 'useCssSupportClient', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useCssSupportClient(feature: TCssFeatureName | string, options?: IUseCssSupportClientOptions = {}): Ref<boolean>', NULL, NULL, 'packages/ds/src/composables/Commons/cssSupportClient.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
