INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3e09615c-0ff9-48ed-9bf8-1c616f1545ba', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-date', 'useDate', NULL, 'Commons', 'mdi-calendar-blank', '', 'Injects the configured date adapter instance. Reads the date options provided by createOrigam() (or a parent OrigamDateProvider) and returns a ready-to-use adapter that abstracts all date arithmetic. Throws if called outside an app context where date options are not provided.', NULL, 'function useDate(): DateAdapter', NULL, NULL, 'packages/ds/src/composables/Commons/date.composable.ts', NULL, NULL, 'useDate() must be called inside a component tree where date options have been registered (via createOrigam({ date: { adapter: DateAdapter } }) or a parent OrigamDateProvider). It throws with a clear message if the injection key is missing.', NULL, NULL, NULL, '{"consumedInterfaces": ["IDateOptions", "ILocaleInstance"]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7925d457-de26-403d-8e9a-5c96ca644986', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-date-picker-calendar', 'useDatePickerCalendar', NULL, 'Commons', 'mdi-calendar-month', '', 'Calendar computation layer for OrigamDatePicker. Derives all calendar display values (weeks, days, day metadata) from ICalendarProps in a reactive computed graph. Handles adjacent-month days, disabled states, selected ranges, week numbers and the static/dynamic weeks-in-month modes.', NULL, 'function useDatePickerCalendar(props: ICalendarProps): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0290e382-4430-4f8c-9fd4-bd55d8b85a4a', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-defaults', 'useDefaults', NULL, 'Commons', 'mdi-tune-variant', '', 'Component-side hook for the OrigamDefaultsProvider system. Returns a Proxy over the component''s own props that resolves each value through a four-level chain: explicitly passed prop → component-specific defaults from the closest provider → global defaults from the closest provider → withDefaults() value.', NULL, 'function useDefaults<T extends Record<string, any>>(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c922c053-13de-420c-a35d-dc3cb14db12f', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-delay', 'useDelay', NULL, 'Commons', 'mdi-timer-outline', '', 'Manages open/close delay timing for overlay components. Reads openDelay and closeDelay from IDelayProps and exposes runOpenDelay / runCloseDelay helpers that debounce state transitions. Each new call cancels any in-flight delay, preventing race conditions when hover enters and leaves quickly.', NULL, 'function useDelay(
