INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d725b320-879b-4335-9b63-3baea49b0ed8', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-parallax', 'useParallaxRuntime', NULL, 'Parallax', 'mdi-layers-triple-outline', '', 'Headless parallax engine used by OrigamParallax. Maintains a registry of layers, tracks scroll progress via IntersectionObserver, and drives per-frame transforms via requestAnimationFrame. Branches automatically to a CSS scroll-driven animation path (Chrome 115+) when the easing is linear and the browser supports animation-timeline: scroll(). Respects prefers-reduced-motion at OS level.', NULL, 'function useParallaxRuntime(options: IUseParallaxRuntimeOptions): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('cd5be94e-e38f-42d5-9ab3-cfca370fb2e7', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-parallax-transform', 'useParallaxTransform', NULL, 'Parallax', 'mdi-layers-triple-outline', '', 'Computes CSS transform strings for parallax layer elements based on normalised mouse-position coordinates. Supports five transform types: translate, rotate, depth (3-D tilt), depth-inv (inverted tilt), scale, scale-x, and scale-y. Consumed by OrigamParallax to animate child layers.', NULL, 'function useParallaxTransform(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('eca78d03-aff6-42f2-a673-c4c6a3ee869b', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-passed-props', 'usePassedProps', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function usePassedProps(_props: T, instanceLabel?: string = ''usePassedProps''): (key: Extract<keyof T, string> | string) => boolean', NULL, NULL, 'packages/ds/src/composables/Commons/passedProps.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('269d2e8b-0b90-431c-8b69-2434055c83f2', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-password-strength', 'computeStrength', NULL, 'PasswordField', 'mdi-shield-lock-outline', '', 'Pure function (no Vue reactivity needed) that scores a password string on a 0-4 scale based on length, digit presence, case diversity, and special characters. Returns a numeric score and a semantic level (weak / fair / good / strong). Used internally by OrigamPasswordField to drive the strength bar colour and label. No third-party dependencies.', NULL, 'function computeStrength(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b1bad861-8db8-460e-9b0d-365fcdab4b74', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-position', 'usePosition', NULL, 'Commons', 'mdi-map-marker-outline', '', 'Derives CSS positioning classes and inline style declarations from IPositionProps. Emits a BEM modifier class for the position variant (absolute, fixed, sticky, relative, static) and inline top/bottom/left/right properties for any offset props that are set.', NULL, 'function usePosition(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('bc0d0c43-d575-441a-b3f7-3bc791e1cacd', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-progress', 'useProgress', NULL, 'Progress', 'mdi-progress-clock', '', 'Computes all state needed to render a progress bar or circular progress indicator: a normalised 0-100 value from modelValue and max, thickness as a number, a visibility flag tied to IntersectionObserver, and BEM class/style arrays that handle indeterminate, striped, active, and absolute modes. Used by OrigamProgressLinear and OrigamProgressCircular.', NULL, 'function useProgress(props: IProgressTypeProps): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('930043be-10c7-4f2b-b77b-e324377bcafc', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-props', 'useProps', NULL, 'Commons', 'mdi-tune-variant', '', 'Returns a filterProps utility that picks only the keys declared on a component interface from an arbitrary props object, stripping undefined values so that Vue 3 boolean-prop coercion does not silently override withDefaults in child components. Used by composite components (DataTable, List, Select…) to forward a safe subset of their own props to child Origam components.', NULL, 'function useProps<T extends Record<string, any>>(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2ff2708b-083f-4cf6-a137-3bd9e0eb4a8b', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-qr-code', 'useQrCode', NULL, 'QrCode', 'mdi-qrcode', '', 'Headless QR-code composable. Encodes a string payload using qrcode-generator (Reed-Solomon + matrix masking) and returns a reactive SVG string, the raw module matrix, and the matrix size. The encoder is LRU-cached at module level to avoid rebuilding identical matrices on re-renders. Fully SSR-safe — no DOM API is touched.', NULL, 'function useQrCode(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('9cdd66db-4f08-4afb-9b15-bdac70ea8f49', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-refs', 'useRefs', NULL, 'Commons', 'mdi-link-variant', '', 'Manages a dynamic array of template refs that is reset before each update cycle. Provides an updateRef(el, i) callback designed for use with :ref in v-for loops, where Vue replaces individual refs by index. The refs array is always fresh (cleared in onBeforeUpdate) so stale elements from a previous render do not leak.', NULL, 'function useRefs<T extends object>(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('49ee0381-b474-4751-a019-c7df20fea992', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-resize-observer', 'useResizeObserver', NULL, 'Commons', 'mdi-resize', '', 'Wraps the native ResizeObserver API with a reactive template ref. Returns a resizeRef to attach to any element and a readonly contentRect that updates on every resize. Automatically disconnects the observer on component unmount. Supports both content-box (default) and border-box measurement.', NULL, 'function useResizeObserver(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('27e5cfd6-c33b-446d-9089-3ed6501c091a', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-rounded', 'useRounded', NULL, 'Commons', 'mdi-rounded-corner', '', 'Resolves the `rounded` prop to border-radius classes and inline styles. Supports the modern utility taxonomy (xs/sm/md/lg/xl/none/full), the legacy named variants (x-small/small/default/medium/large/x-large/shaped), numbers and free-form CSS values.', NULL, 'function useRounded(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c9d6fc15-582e-4a8a-a552-84f4d7f6d114', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-route', 'useRoute', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useRoute(): Ref<RouteLocationNormalizedLoaded | undefined>', NULL, NULL, 'packages/ds/src/composables/Commons/route.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('9a400903-6c06-4af2-8ba9-37ddb478ed7d', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-router', 'useRouter', NULL, 'Commons', 'mdi-routes', '', 'Thin wrappers around Vue Router that expose the current route and router instance from the Vue component instance rather than via direct vue-router import. Also provides useLink (a link-resolution helper used by all clickable Origam components) and useBackButton (navigation guard for hardware/browser back button interception).', NULL, '// Returns the active route as a reactive ref
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4c3ceca5-50e0-48e9-bcb9-b8811ab4e1d1', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-rtl', 'useRtl', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useRtl(name?: string = getCurrentInstanceName()): { isRtl: Ref<boolean, boolean>; rtlClasses: ComputedRef<string>; }', NULL, NULL, 'packages/ds/src/composables/Commons/rtl.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8bc706a2-5ee2-45a0-afea-48a91fc86751', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-scope-id', 'useScopeId', NULL, 'Commons', 'mdi-identifier', '', 'Reads the Vue SFC scope ID from the current component instance and returns it as an attribute object. Used to ensure that teleported or dynamically-created DOM nodes receive the same scoped-CSS attribute as their parent component, so that scoped style rules continue to match across teleport boundaries.', NULL, 'function useScopeId(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('55f30436-1006-4ab2-ad13-a4838ca17881', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-scroll', 'useScroll', NULL, 'Commons', 'mdi-gesture-swipe-vertical', '', 'Tracks scroll position and direction on a configurable target element (or window). Returns reactive flags for scroll direction, activity state, threshold crossing, and a scroll ratio useful for progressive UI transitions. Also exposes useScrollStrategies (apply named scroll behaviours like block, close, or reposition to floating overlays) and useScrolling (keyboard + scroll helpers for virtualised list + search-field combos).', NULL, 'function useScroll(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('9b581a9c-8763-41e1-a046-87626400504d', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-scroll-strategies', 'useScrollStrategies', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useScrollStrategies(props: IScrollStrategyProps, data: IScrollStrategyData): void', NULL, NULL, 'packages/ds/src/composables/Commons/scrollStrategies.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('00f79098-9b1c-46f4-b14d-ba708e9a071a', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-select', 'useSelection', NULL, 'DataTable', 'mdi-checkbox-multiple-marked-outline', '', 'Inject accessor for the row-selection context provided by provideSelection inside OrigamDataTable. Returns the reactive selected Set and the select / toggleSelect / selectAll helpers plus status flags (someSelected, allSelected, showSelectAll). Used by checkbox columns and the header select-all control.', NULL, 'function useSelection(): IDataTableProvideSelection', NULL, NULL, 'packages/ds/src/composables/DataTable/select.composable.ts', NULL, NULL, 'useSelection throws when called outside a DataTable context (no inject match for ORIGAM_DATA_TABLE_SELECT_KEY). It must be used inside a component tree where provideSelection() was called by the parent table.', NULL, NULL, NULL, '{"consumedInterfaces": ["IDataTableProvideSelection", "IDataTableSelectableItem", "IDataTableSelectProps"]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('08053972-87e3-4a3b-9991-b8c7031c13a1', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-select-link', 'useSelectLink', NULL, 'Commons', 'mdi-link-variant', '', 'Bridges a router link and a group selection: when the link becomes active (current route matches), it automatically selects its group item. Used internally by navigation components (NavList, BottomNav, Tabs) so that a hard navigation or a programmatic router push keeps the selected state in sync without a manual v-model update.', NULL, 'function useSelectLink(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f0ed23d1-0c1a-4ab7-9981-519ecd40a982', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-sheet-swipe', 'useSheetSwipe', NULL, 'Sheet', 'mdi-gesture-swipe-up', '', 'Encapsulates bottom-sheet swipe gesture logic using Pointer Events (covers both mouse and touch). Tracks pointerdown → pointermove → pointerup on a dedicated handle element, resolves the target snap point on release via velocity (fast flick = step one snap) or absolute distance (slow drag = nearest snap), and exposes reactive drag state for 1:1 finger tracking during the gesture.', NULL, 'function useSheetSwipe(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0d2eeafe-72e4-4245-b8e8-ff2dffbf1831', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-size', 'useSize', NULL, 'Commons', 'mdi-magnify-plus-outline', '', 'Resolves the `size` prop to component-local modifier classes and optional width/height inline styles. Named presets (x-small/small/default/large/x-large) emit BEM modifier classes; custom values emit pixel dimensions.', NULL, 'function useSize(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('6cd7d968-b235-4269-b3ce-58e717b56d83', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-slider-field', 'useSteps', NULL, 'SliderField', 'mdi-tune-variant', '', 'Pure-function stepping math for OrigamSliderField. Computes reactive min / max / step / decimals values from the component props and exposes a roundValue helper that snaps any raw number to the nearest valid step (clamped to [min, max]). After the migration to a native <input type="range">, this is the only remaining logic layer for the slider — the browser now owns drag tracking.', NULL, 'function useSteps(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c036988a-96db-496e-8ee7-d336fe654f05', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-snackbar', 'useCountdown', NULL, 'Snackbar', 'mdi-timer-sand', '', 'Internal countdown timer used by OrigamSnackbar to drive the auto-dismiss progress indicator. Counts down from a given millisecond value using setInterval, ticking at the CSS transition duration of the host element so the progress bar remains visually synchronised. Exposes clear / reset / start controls and a reactive time ref.', NULL, 'function useCountdown(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b5e381e1-8528-483a-9597-89fa8a80315f', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-snackbar-group', 'useSnackbarGroup', NULL, 'Snackbar', 'mdi-bell-outline', '', 'Module-level singleton store for a named snackbar stack. Push notifications via notify(), dismiss them by id or all at once. Each call sharing the same id option reads and writes the same reactive items list — the composable and the matching <OrigamSnackbarGroup id="…"> component share live state with no event bus required.', NULL, 'function useSnackbarGroup(
