INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c575d56d-5246-409c-9431-f19c8f10d971', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-ssr-boot', 'useSsrBoot', NULL, 'Commons', 'mdi-server', '', 'Defers CSS transitions until after the first browser paint to prevent flash-of-transition on SSR hydration. Returns an isBooted flag (false during SSR and the first rAF frame, then true) and a ssrBootStyles computed that injects `transition: none !important` while booting, suppressing unwanted entry animations during hydration.', NULL, 'function useSsrBoot(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('12b07632-6550-4ffa-a371-ac78792471f0', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-stack', 'useStack', NULL, 'Commons', 'mdi-layers-outline', '', 'Manages z-index stacking order for overlay components (Dialog, Menu, Tooltip, Drawer, …). Registers the component in the global GLOBAL_STACK array when it becomes active and auto-computes a z-index 10 units above the current topmost overlay. Exposes globalTop (is this the topmost overlay worldwide?) and localTop (does this overlay have no active child overlays?) for pointer-event and close-on-outside-click decisions.', NULL, 'function useStack(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('064e39f8-d2ff-434a-a7d1-9cede93539af', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-state-effect', 'useStateEffect', NULL, 'Commons', 'mdi-palette-swatch-variant', '', 'Unified composable that consolidates eight visual axes (color, bgColor, border, rounded, elevation, padding, margin, gap) into a single state-aware layer. Reads the hover / active state and their override objects (IHoverState / IActiveState) and emits per-axis classes + styles for each axis. Replaces the prior chain of useColorEffect + useBorder + useRounded + useElevation + usePadding + useMargin that every visual component had to repeat.', NULL, 'function useStateEffect(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('06c82e56-05b0-42e1-8745-e41c21787b67', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-state-flag', 'useStateFlag', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useStateFlag(props: object, options: IStateFlagOptions<S>): IStateFlagReturn', NULL, NULL, 'packages/ds/src/composables/Commons/stateFlag.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7a74a5b1-1bd6-4d5f-a20c-28e234747481', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-status', 'useStatus', NULL, 'Commons', 'mdi-alert-circle-outline', '', 'Resolves semantic status props (success, info, warning, error) into icon slots, status classes, and a forced intent color. The status intent overrides any color / bgColor the consumer passed — a status colour is non-negotiable by design. Also manages icon routing across prepend / append / replace slots based on statusIconPosition.', NULL, 'function useStatus(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('89b20543-b996-4090-bec5-7ea319a59591', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-sticky', 'useSticky', NULL, 'Commons', 'mdi-pin-outline', '', 'Implements the "sticky-while-scrolling" pattern for taller-than-viewport navigation drawers. Tracks scroll direction and element bounding rect to decide whether the sidebar is stuck at the top, stuck at the bottom, or free-floating mid-page. Returns stickyStyles with the appropriate top/bottom offset so the sidebar scrolls naturally through long content without jumping.', NULL, 'function useSticky(options: ISticky): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('db9825c4-7546-4444-b90a-a347a07d45c1', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'const', 'blockquote-variants', 'BLOCKQUOTE_VARIANTS', 'Typography', NULL, NULL, 'consts.catalog.blockquote_variants.description', 'Closed list of valid variant values for OrigamBlockquote. Exposed so stories and consumers can iterate the full visual matrix without duplicating string literals.', 'export const BLOCKQUOTE_VARIANTS: ReadonlyArray<TBlockquoteVariant> = Object.values(BLOCKQUOTE_VARIANT)', NULL, NULL, 'Object.values(BLOCKQUOTE_VARIANT)', 'packages/ds/src/consts/Blockquote/blockquote.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2d271f78-579d-43f8-914f-a7c70a030187', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-style', 'useStyle', NULL, 'Commons', 'mdi-code-tags', '', 'Injects a dynamic <style> tag into document.head scoped to a generated element id, allowing components to apply per-instance CSS that cannot be expressed as inline styles (e.g. pseudo-element rules, :hover selectors, @keyframes). Also exposes the lower-level useStyleTag for raw CSS string injection. Both composables manage their own lifecycle: they load on mount and unload on scope dispose.', NULL, 'function useStyle(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fa5afd9a-a113-414b-9307-44257fc2f4b2', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-style-tag', 'useStyleTag', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useStyleTag(css: MaybeRef<string>, options?: IStyleTagOptions = {}): { id: string; css: Ref<string, string> | ShallowRef<string, string> | WritableComputedRef<string, string>; unload: () => void; load: () => void; isLoaded: Readonly<...>; }', NULL, NULL, 'packages/ds/src/composables/Commons/styleTag.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f427d255-535a-4048-a24b-03d68adf6c28', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-teleport', 'useTeleport', NULL, 'Commons', 'mdi-arrow-top-right-bold-box-outline', '', 'Resolves the Vue Teleport target for overlay components. Accepts true (disable teleport — render inline), false (teleport to document.body), a CSS selector string (teleport to the matched element), or a raw Element. Creates an .origam-overlay-container div inside the target when one does not already exist, so multiple overlays sharing the same target stack correctly without polluting the host''s direct children.', NULL, 'function useTeleport(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e6e528c9-44d1-46f3-95eb-723667649992', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-teleport-typography', 'useTeleportTypography', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useTeleportTypography(fieldRef: Ref<{ $el?: HTMLElement } | undefined>, isOpen: Ref<boolean>, extraVars: (fontSize: string) => Record<string, string>, measureSelector?: string = TELEPORT_TYPOGRAPHY_MEASURE_SELECTOR, neutralFontSize?: string = TELEPORT_TYPOGRAPHY_NEUTRAL_FONT_SIZE): { typographyStyles: Ref<Record<string, string>, Record<string, string>>; }', NULL, NULL, 'packages/ds/src/composables/Commons/teleport-typography.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
