INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('af9533cc-a128-491e-b6ab-0dc41bcfbcf5', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-textarea-field-rich', 'useTextareaRich', 'TextareaField', 'TextareaField', NULL, NULL, NULL, NULL, 'function useTextareaRich(options: IUseTextareaRichOptions): { hostRef: Ref<HTMLElement, HTMLElement>; active: { bold: boolean; italic: boolean; underline: boolean; code: boolean; link: boolean; listBullet: boolean; listOrdered: boolean; heading: 0 | ... 2 more ... | 3; }; ... 5 more ...; onPaste: (event: ClipboardEvent) => void; }', NULL, NULL, 'packages/ds/src/composables/TextareaField/textarea-field-rich.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4621a670-bc0d-495b-a8de-71a6861fa2c2', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-textarea-rich', 'useTextareaRich', NULL, 'Textarea', 'mdi-format-text', '', 'Owns the runtime contract of the rich-text textarea (OrigamTextareaRich). Mounts a contenteditable host, applies formatting commands via document.execCommand, tracks active formatting state at the caret for toolbar UI feedback, and sanitises every emit so the consumer v-model never carries XSS payloads. Registers Cmd/Ctrl keyboard shortcuts for the common formatting commands.', NULL, 'function useTextareaRich(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1ed718d9-aed0-4820-9cf7-a650d7d89b13', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-theme', 'useTheme', NULL, 'Theme', 'mdi-theme-light-dark', '', 'Module-level singleton managing the brand theme axis (data-theme attribute) and the color-mode axis (data-mode attribute). Persists both axes to localStorage and reacts to prefers-color-scheme. Every call to useTheme() shares the same refs.', NULL, 'function useTheme(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('30bb4f63-96c5-467a-8a89-5e9108669c76', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'composable', 'use-throttle', 'useThrottleFn', NULL, 'Commons', 'mdi-timer-outline', '', 'Wraps a function so it executes at most once per wait milliseconds. The first call fires immediately; subsequent calls within the wait window are silently discarded. After the window expires the next call fires again immediately. Designed for scroll, resize, and pointer-move handlers where firing on every frame would be prohibitively expensive.', NULL, 'function useThrottleFn<T extends any[], R = void>(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1de590aa-6ee5-465c-bff3-ea3cc3e4d905', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'const', 'chart-bar-slot-fill-ratio', 'CHART_BAR_SLOT_FILL_RATIO', 'Chart', NULL, NULL, NULL, NULL, 'export const CHART_BAR_SLOT_FILL_RATIO = 0.7', NULL, NULL, '0.7', 'packages/ds/src/consts/Chart/chart.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
