INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('5b9dd6c1-f4a5-45d1-b67a-9dab5e682b74', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'interface', 'i-chart-sankey-props', 'IChartSankeyProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_props.description', 'Props for <OrigamChartSankey>. The component consumes series[0] only — each item in series[0].data must conform to IChartSankeyDatum ({ from, to, value }). Nodes are inferred automatically; columns are assigned by topological depth. Extends IChartBaseProps.', 'export interface IChartSankeyProps extends IChartBaseProps {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d22a36da-b213-43f2-af54-ce2ea43bedc6', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'interface', 'i-chart-sankey-slots', 'IChartSankeySlots', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_slots.description', 'Slot signatures exposed by <OrigamChartSankey>. Extends IChartBaseSlots with a node-label slot that replaces the label rendered beside each node, receiving the node name, value, formatted value, resolved colour and column index.', 'export interface IChartSankeySlots extends IChartBaseSlots {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a1392699-15de-4d91-bd0f-473cf85dc80f', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'interface', 'i-chart-scales', 'IChartScales', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_scales.description', 'Pair of pixel-mapping functions produced by useChart from the data range and viewBox size. Pure functions — safe to call from computed refs. x maps a value or category index to an SVG horizontal coordinate; y maps a numeric value to an SVG vertical coordinate.', 'export interface IChartScales {
