INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('250ff8e8-f3d0-48eb-9ce9-eeefe8a9ab19', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'interface', 'i-chart-slots', 'IChartSlots', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_slots.description', 'Slot signatures for the universal OrigamChart component. Replace the default tooltip card, a legend entry, the title block, or the empty state without losing the rest of the chart chrome.', 'export interface IChartSlots {
