INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3ee7f096-9e84-4497-bcd6-4478097c1202', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'fd250285-364a-42c3-b559-d724ad96bfa8', 'props', 'IActivatorProps', true, NULL, '', 'Props controlling how the overlay is triggered. Includes activator selector/element, open-on strategy (click, hover, focus, context-menu), close-on-content-click, delay settings inherited from IDelayProps, and an optional target override.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('477fdde9-2f63-455b-8e11-57388ff40a24', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'fd250285-364a-42c3-b559-d724ad96bfa8', 'isActive', 'Ref<boolean>', true, NULL, '', 'Reactive flag representing the open/closed state of the overlay. useActivator reads and writes this ref to toggle the overlay on user interaction.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('588dd5f7-fe50-49fa-b7c0-17c28d84f84b', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'fd250285-364a-42c3-b559-d724ad96bfa8', 'isTop', 'Ref<boolean>', true, NULL, '', 'Reactive flag set by the overlay stack manager. When true, this overlay is the topmost one; when it becomes false while hover/focus-triggered, the composable auto-closes the overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('622a70ac-ae5c-43a8-bbb8-d0335a17dc8a', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'afb2891b-61d8-485f-aa2e-572f58a19fc6', 'props', 'IActiveProps & Record<string, any>', true, NULL, '', 'Component props. Reads `props[prop]` (default: `props.active`).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('daef48c3-35d4-4645-89d6-b10bd192c88a', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'afb2891b-61d8-485f-aa2e-572f58a19fc6', 'prop', 'string', false, '''active''', '', 'The prop key to read for the active value. Use "modelValue" for components with a v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3280357a-36fa-4156-9825-f69f7d7368a3', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'afb2891b-61d8-485f-aa2e-572f58a19fc6', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--active` class.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d4c1a3a3-31f6-435e-be8b-e2ffdcd161ff', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'b3a46833-3c61-4b6d-bdda-f665cd692d81', 'props', 'IAdjacentProps', true, NULL, '', 'Props carrying prependIcon, appendIcon, prependAvatar, and appendAvatar values. The composable reads these to determine whether the outer prepend/append regions should render.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('247b594e-9c26-45ba-b06c-5e3b05e207a4', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'b3a46833-3c61-4b6d-bdda-f665cd692d81', 'prependIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the prepend slot. When provided, takes precedence over props.prependIcon, enabling status-aware icon swapping without prop mutation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('45f2322b-9f43-4333-b8c0-0d891472daf0', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'b3a46833-3c61-4b6d-bdda-f665cd692d81', 'appendIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the append slot. Same semantics as prependIcon but for the trailing position.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4d4a875e-a17e-4dc4-8074-f45bc48e0e9b', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '75e9796e-b1f0-4c13-887a-54d83018cdb0', 'props', 'IAdjacentInnerProps', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f8789235-2060-4402-a56c-88fb033d33da', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '7a3d443f-58ab-4910-97aa-0ed31a38a8fd', 'props', '{ aspectRatio?: string | number }', true, NULL, '', 'Object carrying an optional aspectRatio value. Accepts a numeric ratio (1.777 for 16:9), a division expression string ("16/9"), or is left undefined to use window.innerWidth / window.innerHeight as the ratio.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('40f320fb-41f9-46de-bd15-adcf8c713666', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '2a0e2686-7078-49a3-99bf-411164c37f18', 'props', 'IUseAudioProps', true, NULL, '', 'Props object with audio (URL of the audio source) and playAudio (boolean flag). When playAudio changes to true the composable calls onPlay(); when it changes to false it calls onStop(). When audio changes, wasPlayed and isPlaying are reset.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('229828d2-c0d4-4df4-a1a1-89f5ccaf0c46', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '611f3fc6-8ca7-4f1f-aea4-9c4b76a557e7', 'options', 'IUseOrigamAudioPlayerOptions', false, '{}', '', 'Optional configuration. Accepts `audioRef` (bring your own ref), `autoplay`, `muted`, `loop`, and `preload`. All fields are optional.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a7cd04a3-f83f-4c16-aa1c-eb188f68b722', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '9a5b7bf2-f488-4954-a9f9-05144f800d13', 'router', 'Router | undefined', true, NULL, NULL, NULL, 0, false, NULL, NULL);
