INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('34593b57-56c4-43e5-b946-d1e48737dec7', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'a19015f9-5f19-4ca8-b05f-687fe7da2e7e', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "bgColor". Omit when passing a plain Ref.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1707e1a3-652d-4471-b0d2-0408544a38a1', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '2bf56692-11e4-4422-b6bb-2fe0f7a5476b', 'props', 'IBorderProps | Ref<boolean | number | string | TDirectionBoth | Array<TDirectionBoth> | null | undefined>', true, NULL, '', 'Either the component props object (reads border, borderColor, borderStyle) or a plain Ref for the border shorthand only.', 0, false, NULL, NULL);
