INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b0ea475b-68d0-4d15-9dc6-8d4d11eb76e5', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'dcdf873a-6f83-4b36-b571-df2158c4d8ff', 'options', 'IUseCalendarOptions', true, NULL, '', 'Configuration thunks. All fields are getter functions so the composable reacts to reactive sources without re-instantiation. Includes events, view, currentDate, firstDayOfWeek, slotDuration, dayStartHour, dayEndHour, and optional minDate/maxDate/locale.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1df59a79-83fa-4420-98b6-bd27ee27a529', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'dcdf873a-6f83-4b36-b571-df2158c4d8ff', 'setView', '(view: TCalendarView) => void', false, NULL, '', 'Optional callback invoked by the returned setView proxy. Bind to a v-model:view setter to keep the parent state in sync when the calendar switches views.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('91fe5d74-9a6b-4732-b79c-99887363b9d7', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'dcdf873a-6f83-4b36-b571-df2158c4d8ff', 'setCurrentDate', '(date: Date) => void', false, NULL, '', 'Optional callback invoked by navigate(). Bind to a v-model:currentDate setter. If omitted, navigation calls have no effect on the parent state.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d4d0c544-765d-432c-87e6-430df4a52deb', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '48cd93b2-fc80-48f3-b7ed-e364be2db51f', 'options', 'IUseChartOptions', true, NULL, '', 'Configuration object with getter thunks for type, series, categories, stacked, stacking, donutHoleSize, colorScheme, smoothing, yMin, yMax, width, height, padding, and optional hiddenLabels and secondaryYAxis. All values are () => T functions so the composable reacts to any reactive source.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('21621d67-c0b8-4843-96a9-dec734396662', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'ca671e59-201d-4882-8115-16028983a562', 'props', 'Pick<IChartBaseProps, ''animationDuration''>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('49cda7f5-488e-40a0-b012-631575a78475', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'fb60babb-37ff-43bf-8bfa-97f61d3376d6', 'options', 'IUseChartGaugeOptions', true, NULL, '', 'Configuration thunks. Required: value, min, max, width, height, padding. Optional: thickness (arc ring width, default 18px), startAngle (radians, default -3π/4), endAngle (radians, default 3π/4). All values are () => T getters so the composable reacts to reactive sources.', 0, false, NULL, NULL);
