INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('def93184-3a15-492d-8b37-9dd1e9170b26', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '08053972-87e3-4a3b-9991-b8c7031c13a1', 'link', 'IUseLink', true, NULL, '', 'The link object returned by useRouter/useLink. Exposes isLink (whether an href/to prop is present) and isActive (whether the current route matches the link target). Watched by the composable to trigger selection.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('83b40230-437c-49ca-8326-c3ca5c0f0c5b', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '08053972-87e3-4a3b-9991-b8c7031c13a1', 'select', '(value: boolean, e?: Event) => void', false, NULL, '', 'The group selection callback injected by useGroup. When the link becomes active, this is called with value=true on the next tick. When undefined, the composable becomes a no-op.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('077520a9-0173-4545-abf7-a1ea979e897b', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'f0ed23d1-0c1a-4ab7-9981-519ecd40a982', 'options', 'ISheetSwipeOptions', true, NULL, '', 'Configuration object. Includes el (sheet root element ref), handle (drag handle element ref), snapPoints (reactive array of TSheetSnapPoint), defaultSnap (initial snap id), disabled (Ref<boolean> to suspend gesture), and persistent (Ref<boolean> to block the closed snap).', 0, false, NULL, NULL);
