INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1dcad097-e248-465e-9bfb-c20f0b0c41a9', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '0d2eeafe-72e4-4245-b8e8-ff2dffbf1831', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--size-{value}` class.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b7655d8e-d8ff-43cd-bc41-d80c02df4d92', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '6cd7d968-b235-4269-b3ce-58e717b56d83', 'props', 'ISliderFieldProps', true, NULL, '', 'Component props. Reads min (default 0), max (default 100), and step (default 0 = no stepping). All three accept string or number — they are parsed with parseFloat internally.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('47ebefc3-e526-4fc7-9d0a-f1eb7a074d32', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c036988a-96db-496e-8ee7-d336fe654f05', 'milliseconds', 'number', true, NULL, '', 'Total countdown duration in milliseconds. This is the initial value of time and the value it resets to on reset().', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f868d283-4ef9-4dd8-b049-79db76060059', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'b5e381e1-8528-483a-9597-89fa8a80315f', 'options', 'IUseSnackbarGroupOptions', false, '{}', '', 'Optional configuration. id (string) namespaces the stack so multiple independent stacks can coexist on the same page (default: SNACKBAR_GROUP_DEFAULT_ID). max (number) caps the stack size with FIFO eviction. defaultDuration (ms) is the fallback auto-dismiss delay for items that omit their own (default: 5000 ms).', 0, false, NULL, NULL);
