INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('694c3061-a24b-4af6-a080-65261ed78ab2', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '12b07632-6550-4ffa-a371-ac78792471f0', 'isActive', 'Readonly<Ref<boolean>>', true, NULL, '', 'Reactive open/closed state. When it flips to true, useStack registers the component in the global stack and computes a new z-index. When false, the entry is removed and z-index is released.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('887eaff0-6562-4d19-b23f-2f955e667b1c', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '12b07632-6550-4ffa-a371-ac78792471f0', 'zIndex', 'Readonly<Ref<string | number>>', true, NULL, '', 'Base z-index to start from when no other overlays are open. Typically comes from the component props (e.g. zIndex="200").', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f5604bde-13af-421b-8b50-5d5aea416ae5', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '12b07632-6550-4ffa-a371-ac78792471f0', 'disableGlobalStack', 'Readonly<Ref<boolean>>', true, NULL, '', 'When true, skips registration in GLOBAL_STACK. Use for overlays that manage their own z-index independently (e.g. nested teleport roots) and should not compete with the global stacking order.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5ad8252a-c283-4a54-bd53-65a5363836b5', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '064e39f8-d2ff-434a-a7d1-9cede93539af', 'props', 'TStateEffectProps', true, NULL, '', 'Component props implementing all eight axes: IColorProps & IBgColorProps & IBorderProps & IRoundedProps & IElevationProps & IPaddingProps & IMarginProps & { gap? }. Also reads props.status when present to force the matching semantic intent (overrides color/bgColor).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6e6af2bb-0af2-4f8d-83f7-636c113ba430', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '064e39f8-d2ff-434a-a7d1-9cede93539af', 'isHover', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive hover state from useHover. When true, the composable applies the override values from hoverState for each axis.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('351c77f6-ccb0-4a6f-bf39-d18cb09099e8', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '064e39f8-d2ff-434a-a7d1-9cede93539af', 'isActive', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive active/selected state from useActive. When true (and isHover is false), override values from activeState are applied. Hover takes priority when both are engaged simultaneously.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6bc11f23-dc65-418f-a7d0-194c8262bb30', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'a4d937e2-c926-4e63-9dbc-ca9c775d623c', 'amount', 'number', true, NULL, 'utils.detail.add_minutes.param_amount', 'Number of minutes to add. Negative values subtract minutes.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('842109f5-fad9-46ec-9eda-768f0c2f73ad', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '064e39f8-d2ff-434a-a7d1-9cede93539af', 'hoverState', 'ComputedRef<IHoverState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useHover. Contains per-axis override values (color, bgColor, border, rounded, elevation, padding, margin, gap) to apply while hovered.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7e08de91-ed28-499f-896b-8e3a4a37f2ef', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '064e39f8-d2ff-434a-a7d1-9cede93539af', 'activeState', 'ComputedRef<IActiveState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useActive. Same shape as IHoverState — per-axis overrides applied while the item is selected/active.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('aa207983-5f8d-4370-bd4f-5634e6139909', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '064e39f8-d2ff-434a-a7d1-9cede93539af', 'isDisabled', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, colorClasses is emptied (utility classes suppressed) so the disabled opacity veil is not overridden by a tokenised background.', 5, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('986155de-6995-44cb-9b3d-08d4342b1ecf', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '064e39f8-d2ff-434a-a7d1-9cede93539af', 'flat', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, elevationClasses and elevationStyles resolve to empty. Bridges the flat prop of Btn / Card without requiring a separate useElevation call.', 6, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bffbfd71-b647-4a9e-a191-44aca5525250', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '06c82e56-05b0-42e1-8745-e41c21787b67', 'props', 'object', true, NULL, NULL, NULL, 0, false, NULL, NULL);
