INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5e7f8132-3bf1-460a-b35e-a88d22eb0f47', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '7a74a5b1-1bd6-4d5f-a20c-28e234747481', 'props', 'IStatusProps & IAdjacentProps', true, NULL, '', 'Component props. Reads status (TStatus: success | info | warning | error), statusIconPosition (prepend | append | both | replace), prependIcon, appendIcon, and icon. When status is set and statusIconPosition is replace, the status icon overwrites props.icon; when prepend/append/both, it fills the matching slot only if no explicit icon prop was passed.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6aec8a70-c854-41dd-b2c9-1de06cb4bd80', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '7a74a5b1-1bd6-4d5f-a20c-28e234747481', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name used to build the BEM modifier class `{name}--{status}` (e.g. origam-alert--success). Defaults to the current Vue instance name.', 1, false, NULL, NULL);
