INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5f1d0b22-01b1-4b2b-aa72-0896546641db', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '95d912fd-6a27-486a-a11d-e574c2c21175', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "color". Omit when passing a plain Ref.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f0a3c809-04f6-4ecb-8889-772b419f0d7d', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'af9533cc-a128-491e-b6ab-0dc41bcfbcf5', 'options', 'IUseTextareaRichOptions', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('54d92a1b-1dea-43f3-9eeb-f80e4c5a2c18', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '4621a670-bc0d-495b-a8de-71a6861fa2c2', 'options', 'IUseTextareaRichOptions', true, NULL, '', 'Configuration object. value: () => string — getter for the initial HTML content (bound to the parent v-model). onUpdate: (html: string) => void — called with sanitised HTML on every change. onFormat: (command, value?) => void — called after each format command (lets the host open a link popover on Cmd+K). disabled: () => boolean — suppresses all commands and keyboard shortcuts when true.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e55826cf-1e58-42c1-b31c-da331af4d5ed', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '30bb4f63-96c5-467a-8a89-5e9108669c76', 'fn', '(...args: T) => R', true, NULL, '', 'The function to throttle. Called immediately on the first invocation within each window. The return value is discarded — the wrapper always returns void.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('59a68fb7-4ef1-4230-a579-cf0d1c25d182', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '30bb4f63-96c5-467a-8a89-5e9108669c76', 'wait', 'number', true, NULL, '', 'Throttle window in milliseconds. No call will execute within wait ms of the previous execution.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('94cbe565-d70b-4710-8e10-df1707358721', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'ca6007fc-59b5-4eb2-9353-36df2b5db76a', 'source', 'WatchSource<boolean>', true, NULL, '', 'Reactive boolean source (ref, computed, or getter). When it evaluates to true the scope is started; when false the scope is stopped.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a3e6d549-40c5-4d2e-ab56-4c928bbe118c', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'ca6007fc-59b5-4eb2-9353-36df2b5db76a', 'fn', '(reset: () => void) => void', true, NULL, '', 'Callback run inside the new effectScope. Receives a `reset()` function that can be called from inside the scope to stop the current scope and immediately restart it — useful for subscriptions that need to re-initialise when an inner condition changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('829150af-6231-483b-bd73-1da2913ae1ae', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '71882269-86fe-442f-b7c3-5ca44d82585d', 'isActive', 'Ref<boolean>', true, NULL, '', 'Whether the drawer is currently open. The composable writes to this ref when a fling gesture settles.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('317724ea-64d4-4ee4-a1ce-22ebf12738a8', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '71882269-86fe-442f-b7c3-5ca44d82585d', 'isTemporary', 'Ref<boolean>', true, NULL, '', 'When true the drawer is temporary (modal overlay). The touch zone logic also activates for touches anywhere inside the element body, not only at the edge.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b6dfbe97-7c52-4fff-8ba7-b7f78ff84044', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '71882269-86fe-442f-b7c3-5ca44d82585d', 'width', 'Ref<number>', true, NULL, '', 'Pixel width (or height for top/bottom positions) of the drawer. Used to compute drag progress as a fraction in [0, 1].', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ce81b2c0-4023-44ca-a5b1-14cab7c25f85', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '71882269-86fe-442f-b7c3-5ca44d82585d', 'touchless', 'Ref<boolean>', true, NULL, '', 'When true all touch handling is disabled. Lets the consumer disable swipe gestures without unmounting the composable.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7f8de031-a72f-4e77-bec8-803e1d157f46', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '71882269-86fe-442f-b7c3-5ca44d82585d', 'position', 'Ref<''left'' | ''right'' | ''top'' | ''bottom''>', true, NULL, '', 'The edge from which the drawer slides in. Determines the touch zone, coordinate axis, and transform direction.', 4, false, NULL, NULL);
