INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a0d76680-2152-4cf8-b9e2-0c67dac4ff7a', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '5f0147d5-077c-44fb-bce6-8b4cc85fca82', 'prop', 'Prop', true, NULL, '', 'The prop key to observe, e.g. `"modelValue"` for a standard v-model binding.', 1, false, NULL, NULL);
