INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('68c03337-1494-4353-8e5d-69f91c57a480', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '5f0147d5-077c-44fb-bce6-8b4cc85fca82', 'transformIn', '(value?: Props[Prop]) => Inner', false, '(v?: Props[Prop]) => v as Inner', '', 'Optional transform applied to the external prop value before exposing it to the component. Useful for converting a string to a number, or normalising null / undefined.', 3, false, NULL, NULL);
