INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('91f83583-3fc9-4333-ae14-1ca7a3510042', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '7d7f6b56-cba0-4d28-8439-8c7bd91a4736', 'props', 'IValidationProps', true, NULL, '', 'Props read: modelValue, validationValue, rules, error, errorMessages, maxErrors, disabled, readonly, focused, validateOn, name.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8afae6b7-be64-40b3-a460-34aa4e04fb93', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '7d7f6b56-cba0-4d28-8439-8c7bd91a4736', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for validation CSS class names (e.g. `origam-text-field--error`).', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c07afef0-4feb-40ff-bde0-88841e0e63df', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '7d7f6b56-cba0-4d28-8439-8c7bd91a4736', 'id', 'MaybeRef<string | number>', false, 'getUid()', '', 'Unique field ID used to register with the parent form. Defaults to an auto-generated UID.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4b357818-3d0b-42ee-af1d-dcf678036a09', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'a44b09ff-f681-48f8-85cb-a9481f8333b7', 'props', 'IVariantProps | Ref<TVariant | TVariantInput | string | undefined>', true, NULL, '', 'Either the component props object (reads `props.variant`) or a bare reactive ref / computed to the variant string. The composable detects which form is passed via `isRef`.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0e272518-afc1-4364-be77-f9e01fcdcf45', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'a44b09ff-f681-48f8-85cb-a9481f8333b7', 'name', 'string', false, 'getCurrentInstanceName()', '', 'The BEM block prefix. Defaults to the current component name (e.g. `origam-btn`). The class produced will be `{name}--variant-{variant}`.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('838ecc86-2777-4365-8982-bf9042202659', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '6e48696c-cffc-4410-b29c-8be7b81918b6', 'options', 'IUseVideoPlayerOptions', false, '{}', '', 'Accepts `videoRef` (bring your own typed ref), `autoplay`, `muted`, `loop`, `preload`. All optional. Autoplay is suppressed when prefers-reduced-motion is active.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4684c587-f9ea-4b72-824c-fb0b414ef87b', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c00935ae-4b68-4f53-ab03-efb72a26eba7', 'props', 'IVirtualProps', true, NULL, '', 'Reads `itemHeight` (expected row height in px, used to estimate the initial window), `height` (container height as string / number), `scrollDuration` (ms, default 300), `scrollEasing` (easing name, default easeInOutCubic).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2112f906-70a1-4448-9ac0-b2475ac3bb55', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c00935ae-4b68-4f53-ab03-efb72a26eba7', 'items', 'Ref<readonly T[]>', true, NULL, '', 'The full dataset ref. The composable slices this array to produce `computedItems`. Changing the ref triggers an offset recalculation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d10843f2-6a99-4722-9ce0-d49736a0d0b3', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '25a4518f-e331-4cda-8657-0c94c88457c7', 'options', 'MaybeRefOrGetter<IUseWatermarkOptions>', false, '{}', '', 'Options bag (static object, reactive ref, or getter function). Reads: `text`, `image` (URL), `opacity` (default 0.15), `angle` (degrees, default -30), `gap` (tile spacing in px, default 100), `fontSize` (px, default 16), `fontFamily`, `color`, `fontWeight`, `pointerEvents` ("none" | "auto"), `zIndex`, `antiTamper` (enable MutationObserver re-injection). Passing a ref makes patternUrl update reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('401ff482-d40a-4b23-b7c9-dc47e35e6ad0', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'cddffbdf-210f-425b-a0fd-b2780257bfca', 'srcRef', 'Ref<string | undefined | null>', true, NULL, '', 'Reactive reference to the audio file URL. The composable watches this ref and re-triggers computation whenever the value changes. null / undefined clears the peaks array.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d0300265-5bb2-4bf5-b769-73d6542ae034', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'cddffbdf-210f-425b-a0fd-b2780257bfca', 'options', 'IUseWaveformOptions', false, '{}', '', 'Optional: `bins` (number of peaks to produce, default 200) and `crossOrigin` ("use-credentials" | undefined) for the fetch credentials policy.', 1, false, NULL, NULL);
