INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cc66bd7a-0f62-4344-832f-9b944d20af9e', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', 'a11430a0-3e8f-4da7-8f3e-8cded7a6303f', 'locationStrategy', 'TLocationStrategy | TLocationStrategyFn', NULL, NULL, true, NULL, NULL, NULL, 'Named strategy ("connected" | "static") or a custom strategy function. The connected strategy aligns the floating panel to the activator; static keeps it in place.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0f0f41fe-98c4-4ce7-ad60-1c583bdebd34', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', 'a11430a0-3e8f-4da7-8f3e-8cded7a6303f', 'location', 'TAnchor', NULL, NULL, true, NULL, NULL, NULL, 'Side and alignment where the floating content appears relative to the activator (e.g. "bottom start", "top end").', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('69436de2-1dd6-41f2-8ca1-e850931de4fe', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '334fcee7-2102-4f67-83cf-243b6663adc3', 'year', 'number', NULL, NULL, false, NULL, NULL, NULL, 'Four-digit year of this cell.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('36fceb3f-1cee-4e37-8fa7-4c6eb1a7a90f', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', 'a11430a0-3e8f-4da7-8f3e-8cded7a6303f', 'origin', 'TAnchor | ''auto'' | ''overlap''', NULL, NULL, true, NULL, NULL, NULL, 'The anchor point on the floating content itself. "auto" mirrors the location; "overlap" places the panel over the activator.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4dc76eda-8b9a-4576-8e88-7b6c1018ca39', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', 'a11430a0-3e8f-4da7-8f3e-8cded7a6303f', 'offset', 'number | string | Array<number>', NULL, NULL, true, NULL, NULL, NULL, 'Gap in pixels between the activator and the floating content. An array of two values sets [main-axis, cross-axis] offsets independently.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9e40530f-128e-491c-ab78-b7fb16dcc86e', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', 'a11430a0-3e8f-4da7-8f3e-8cded7a6303f', 'viewportMargin', 'number', NULL, NULL, true, NULL, '12', NULL, 'Minimum breathing room in pixels between the floating content and each viewport edge. Defaults to 12 so panels never overlap browser chrome.', 4, false, NULL, NULL);
