INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c8954727-3850-4820-a6e6-7d5bd731410a', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '7158a587-500c-485d-9aed-415f4f541561', 'target', 'Ref<HTMLElement | [x: number, y: number] | undefined>', NULL, NULL, false, NULL, NULL, NULL, 'Reactive reference to the anchor element or an [x, y] pixel coordinate. When set to coordinates, the floating panel anchors to a virtual point (used by context menus).', 1, false, NULL, NULL);
