INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7e766cbb-e6f5-4d49-a24f-b1ceba006834', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '191e2623-b938-4d31-a32d-bc12c2908468', 'disabled', 'boolean', NULL, NULL, true, NULL, 'false', NULL, 'Disables pointer + keyboard interaction. The element drops out of the tab order and pointer events become no-ops.', 6, false, NULL, NULL);
