INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('49c1cb6d-4805-4190-8654-167b4500e337', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '3ebb6c2d-a2ff-42bd-a83f-f5f26f10b995', 'lang', 'TCodeLang', 'code-lang', 'type', NULL, false, '''plaintext''', 'components.code.props.lang.description', 'Language grammar to apply. Supported: ''plaintext'' | ''vue'' | ''ts'' | ''js'' | ''tsx'' | ''jsx'' | ''scss'' | ''css'' | ''json'' | ''bash'' | ''html'' | ''xml'' | ''yaml'' | ''md''. Unknown values fall back to plaintext.', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f60deb55-f811-4750-811c-850648436ec1', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '3ebb6c2d-a2ff-42bd-a83f-f5f26f10b995', 'lineNumbers', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.line_numbers.description', 'Shows a left gutter with line numbers. Pure CSS counter — no JS layout work.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dc2a9ed7-4bd6-4795-9182-b1b4264f91c4', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '3ebb6c2d-a2ff-42bd-a83f-f5f26f10b995', 'highlightLines', 'number[] | string | null', '', 'primitive', NULL, false, 'null', 'components.code.props.highlight_lines.description', 'Lines to highlight. Accepts a 1-based array ([2, 5, 6]) or a range string (''2,5-7''). Null/empty disables.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ee270aa5-f83a-4477-a494-682928e2cf17', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '3ebb6c2d-a2ff-42bd-a83f-f5f26f10b995', 'copyable', 'boolean', '', 'primitive', NULL, false, 'true', 'components.code.props.copyable.description', 'Shows the copy-to-clipboard button. True by default — most code blocks benefit from it.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ff72bbd9-bbe8-4ee0-9d3f-633dd9bcf383', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '3ebb6c2d-a2ff-42bd-a83f-f5f26f10b995', 'format', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.format.description', 'Auto-format the code before highlighting. Reserved — currently a no-op that warns in dev mode. Prettier is not bundled at runtime to keep the tarball small.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('60cf4b6d-6c1b-4c4c-8607-d66113329bb5', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '3ebb6c2d-a2ff-42bd-a83f-f5f26f10b995', 'wrap', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.wrap.description', 'Wraps long lines instead of scrolling horizontally.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d8f084f0-4922-4c34-bc4e-0898857b5b73', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '3ebb6c2d-a2ff-42bd-a83f-f5f26f10b995', 'filename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.code.props.filename.description', 'Optional filename rendered in the header bar (e.g. ''App.vue''). When present AND copyable=true, the header hosts the copy button; otherwise the copy button floats in the top-right corner.', 7, false, NULL, NULL);
