INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d5d54beb-60ef-4079-a67a-0e01868c233a', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '7bd8f4c5-405a-42ac-9532-59703fb74e3e', 'state', 'IMediaPlayerState', '', 'primitive', NULL, true, '—', 'components.media_controller.props.state.description', 'Reactive media state from useMediaPlayer() (or a specialisation: useVideoPlayer, useAudioPlayer). Contains refs for playing, currentTime, duration, volume, muted, buffered, playbackRate, remoteAvailable, remoteState.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('214d28b1-237b-4e96-8699-5b78b2725297', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '7bd8f4c5-405a-42ac-9532-59703fb74e3e', 'methods', 'IMediaPlayerMethods', '', 'primitive', NULL, true, '—', 'components.media_controller.props.methods.description', 'Imperative methods from useMediaPlayer(). Provides play(), pause(), seek(), setVolume(), toggleMute(), setPlaybackRate(), requestRemotePlayback().', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a562df3d-08c4-4b14-97cc-395aaa8ef9af', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '7bd8f4c5-405a-42ac-9532-59703fb74e3e', 'inset', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.inset.description', 'YouTube-style overlay mode: the shell sits on top of the media surface with a dark gradient and auto-hides on visible=false. When false, renders as a regular always-on toolbar.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('314a68ce-d418-4cf2-9896-e2ec2d20277b', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '7bd8f4c5-405a-42ac-9532-59703fb74e3e', 'visible', 'boolean', '', 'primitive', NULL, false, 'true', 'components.media_controller.props.visible.description', 'Visibility flag driven by the parent autohide logic. Only meaningful when inset=true. When false, the shell is opacity: 0 and pointer-events: none.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0b5da43e-a16f-463b-832a-1012a9e54302', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '7bd8f4c5-405a-42ac-9532-59703fb74e3e', 'playbackRates', 'ReadonlyArray<number>', '', 'primitive', NULL, false, '[0.5, 0.75, 1, 1.25, 1.5, 2]', 'components.media_controller.props.playback_rates.description', 'Available playback rates exposed via the config cog menu. When the array has more than 1 entry, a "Playback speed" drill-down appears.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2992b049-8357-4ac6-a80a-8f864121849e', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '7bd8f4c5-405a-42ac-9532-59703fb74e3e', 'allowRemotePlayback', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.allow_remote_playback.description', 'Enable the Cast / AirPlay button (Remote Playback API). The button only appears when this flag is true AND state.remoteAvailable is true at runtime.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d0d8c3e4-4df2-457a-b839-6fba6997a556', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '7bd8f4c5-405a-42ac-9532-59703fb74e3e', 'downloadable', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.downloadable.description', 'Adds a "Download" row to the config cog menu when true. Requires downloadUrl to be set.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('51b01cec-702e-4df3-b020-8a89da7861ef', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '7bd8f4c5-405a-42ac-9532-59703fb74e3e', 'downloadUrl', 'string | null', '', 'primitive', NULL, false, 'null', 'components.media_controller.props.download_url.description', 'URL surfaced to the consumer when the Download menu item is clicked. Supports same-origin, data: and blob: URLs natively; cross-origin URLs are routed through a fetch → blob pipeline.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4b6b48ef-dde0-478e-a01f-87c0426b81d0', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '7bd8f4c5-405a-42ac-9532-59703fb74e3e', 'downloadFilename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.media_controller.props.download_filename.description', 'Suggested filename for the downloaded file (<a download="…"> attribute).', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('541da856-8517-4a87-a44f-8a42fc115580', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '7bd8f4c5-405a-42ac-9532-59703fb74e3e', 'qualityOptions', 'ReadonlyArray<TQualityOption>', '', 'primitive', NULL, false, '[]', 'components.media_controller.props.quality_options.description', 'Optional list of quality variants. When ≥ 2 entries are present, a "Quality" drill-down appears in the config menu. Each entry is { quality: string; label: string }.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b258cae3-8d25-41a1-a2a6-6fad39b494ae', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '7bd8f4c5-405a-42ac-9532-59703fb74e3e', 'currentQuality', 'string | null', '', 'primitive', NULL, false, 'null', 'components.media_controller.props.current_quality.description', 'Currently-active quality identifier displayed as the appendText in the Quality menu row.', 10, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('332ec1f5-83f2-4f59-a736-6e35d7ee0416', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '7bd8f4c5-405a-42ac-9532-59703fb74e3e', 'showPrevious', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_previous.description', 'Show the "previous track" transport button. The parent listens to the previous emit and decides the action (skip back 10s or jump to the previous playlist track).', 11, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e765539a-1b7a-46a0-b516-ed5e64a00ac9', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:34.870753+00', '7bd8f4c5-405a-42ac-9532-59703fb74e3e', 'showNext', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_next.description', 'Show the "next track" transport button. The parent owns the action.', 12, false, NULL, NULL);
