INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6f9437c4-0517-4628-8035-6b463f30cb41', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '6cd7d968-b235-4269-b3ce-58e717b56d83', 'step', 'ComputedRef<number>', '', 'Parsed step value. 0 means no stepping (any value between min and max is valid). Positive values define the snap grid.', 2, false, NULL, NULL);
