INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b021ad37-ec88-4358-8dda-0e9e51b0e9cb', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '6cd7d968-b235-4269-b3ce-58e717b56d83', 'roundValue', '(value: string | number) => number', '', 'Snap a raw value to the nearest valid step, clamped to [min, max]. Handles the min-offset edge case so that a step=5 min=3 grid snaps to 3, 8, 13, … rather than 0, 5, 10, ….', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('85b4fd29-7eba-482f-9265-12888ec77ea5', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c036988a-96db-496e-8ee7-d336fe654f05', 'time', 'ShallowRef<number>', '', 'Remaining milliseconds. Starts at the initial milliseconds value, decrements on each tick, and bottoms out at 0. Bind to a progress bar width to visualise the countdown.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1fbab6e6-ef49-4950-bcaf-574105dcadf2', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c036988a-96db-496e-8ee7-d336fe654f05', 'clear', '() => void', '', 'Stops the interval without resetting time. Use to pause the countdown (e.g. while the user is hovering the snackbar).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f0e6d938-126f-4e5c-987d-30b53388fabb', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c036988a-96db-496e-8ee7-d336fe654f05', 'reset', '() => void', '', 'Clears the interval and resets time to the initial milliseconds value on the next tick. Use when the snackbar content changes and the countdown should restart.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c79dbec2-e8fb-418e-8b2d-afe0f7393ece', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c036988a-96db-496e-8ee7-d336fe654f05', 'start', '(el?: HTMLElement) => void', '', 'Start (or resume) the countdown. Reads the CSS transitionDuration of el to synchronise tick frequency with the progress bar animation. Falls back to 200 ms when no element is provided or no transition is set. Clears any existing interval before starting.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6da8653f-f4fb-422f-a30b-015ca9ec0921', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'b5e381e1-8528-483a-9597-89fa8a80315f', 'items', 'Readonly<Ref<ReadonlyArray<ISnackbarGroupItem>>>', '', 'Reactive read-only snapshot of the current stack. Mutate only through notify / dismiss / dismissAll — direct writes are blocked at the TypeScript level.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('44bd10c9-5f85-410d-8f0f-191b63ff4db7', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'b5e381e1-8528-483a-9597-89fa8a80315f', 'notify', '(opts: ISnackbarGroupItemOptions) => string', '', 'Push a new item onto the stack. Accepts ISnackbarGroupItemOptions (message, variant, icon, duration, onDismiss callback…). Returns the generated item id so the caller can dismiss it early.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('06fd214f-f1dd-44c6-b9c0-71f4589055e6', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'b5e381e1-8528-483a-9597-89fa8a80315f', 'dismiss', '(itemId: string) => void', '', 'Remove the item with the given id from the stack, cancel its auto-dismiss timer, and invoke its onDismiss callback if any.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b037a5d6-1af5-4d49-9dab-f3c5767990a5', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'b5e381e1-8528-483a-9597-89fa8a80315f', 'dismissAll', '() => void', '', 'Dismiss every item in the stack in one call. Iterates a snapshot of the ids so mid-loop mutations are safe.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('de72da5e-ceb5-42c8-9d54-8b3877043c68', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'fe3937b3-6228-407b-bc98-04adf0d4ae5a', 'sortBy', 'Ref<Array<IDataTableSortItem>>', '', 'Reactive array of active sort descriptors, each with a key (column key) and an order (asc | desc). Driven by useVModel against the host table props.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a5767c97-55f6-4dd4-a6c0-37d48206418c', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'fe3937b3-6228-407b-bc98-04adf0d4ae5a', 'toggleSort', '(column: IInternalDataTableHeader) => void', '', 'Cycle the sort state for a column: none → asc → desc → none (or asc when mustSort=true). Respects multiSort — when false, replaces the entire sortBy array with a single entry.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b653189f-3f25-45a6-b6f5-3791b51d0244', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'fe3937b3-6228-407b-bc98-04adf0d4ae5a', 'isSorted', '(column: IInternalDataTableHeader) => boolean', '', 'Returns true when the column has an active sort entry in sortBy. Used by header cells to show the sort icon.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d75cc54f-a393-4477-aaa6-36e7fd0ef78b', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c575d56d-5246-409c-9431-f19c8f10d971', 'ssrBootStyles', 'ComputedRef<CSSProperties | []>', '', 'An object `{ transition: "none !important" }` when the component has not yet booted, or an empty array after the first animation frame. Spread onto the root element via :style to suppress hydration-flash transitions.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6e6e50f9-3009-435c-afaa-7f2f35266cc8', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c575d56d-5246-409c-9431-f19c8f10d971', 'isBooted', 'Readonly<ShallowRef<boolean>>', '', 'False on the server and during the first rAF after mount, true thereafter. Useful as a guard before running DOM-dependent logic that assumes the component is fully hydrated.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a20b3393-d67f-4999-8b79-8294c50be2af', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '4a82095e-6bfa-4e94-a3c7-2ecbf6753f70', NULL, 'Animation | { finished: Promise<void>; }', 'utils.detail.animate.returns', 'The native Animation object, or a stub with a resolved finished promise when the API is unavailable.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('538f16d3-38b8-4479-9e62-c25cef9f87ec', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '12b07632-6550-4ffa-a371-ac78792471f0', 'globalTop', 'Readonly<ShallowRef<boolean>>', '', 'True when this component is the last entry in GLOBAL_STACK (topmost overlay on the page). Updated asynchronously via setTimeout to avoid synchronous circular reads during stack registration.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('54140b78-54a0-4568-a805-1df8b499158d', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '12b07632-6550-4ffa-a371-ac78792471f0', 'localTop', 'ComputedRef<boolean>', '', 'True when this overlay has no active child overlays (nothing opened on top of it within its own sub-tree). Used to decide whether clicks on the backdrop should close this overlay.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('84d58179-cf8d-4fa8-a904-bb7338e7af1e', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '12b07632-6550-4ffa-a371-ac78792471f0', 'stackStyles', 'ComputedRef<{ zIndex: number }>', '', 'Style object containing the computed zIndex. Spread onto the overlay root element so it automatically rises above the previous topmost overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('214cf8b0-2366-4cc5-afda-739e44d5a08d', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '064e39f8-d2ff-434a-a7d1-9cede93539af', 'colorClasses / colorStyles', 'ComputedRef<string[]>', '', 'Tokenised intent values emit a utility class (origam--bg-primary); custom CSS colors emit an inline style. Both are empty when disabled/hover/active is true (state-inline path takes over).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('274f6669-35db-4595-80f9-fe82524f0321', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '064e39f8-d2ff-434a-a7d1-9cede93539af', 'borderClasses / borderStyles', 'ComputedRef<string[]>', '', 'Delegated to useBorder with a reactive proxy that swaps to hoverState/activeState.border when the state is engaged.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b5959b9c-825d-44a0-be92-60e345502ae6', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '064e39f8-d2ff-434a-a7d1-9cede93539af', 'roundedClasses / roundedStyles', 'ComputedRef<string[]>', '', 'Delegated to useRounded. State-aware: applies hoverState/activeState.rounded when engaged.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('56c0a959-52c2-42c0-8161-000a101ad3e0', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '064e39f8-d2ff-434a-a7d1-9cede93539af', 'elevationClasses / elevationStyles', 'ComputedRef<string[]>', '', 'Delegated to useElevation. Cleared when flat=true. State-aware via the pickEffective resolver.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1fa3b5b4-4708-4b3e-9c10-27ebcad59b82', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '064e39f8-d2ff-434a-a7d1-9cede93539af', 'paddingClasses / paddingStyles', 'ComputedRef<string[]>', '', 'Delegated to usePadding via a reactive getter proxy to preserve dependency tracking across state swaps.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3a3114b7-04ea-4457-b017-28e8f8c0a0b5', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '064e39f8-d2ff-434a-a7d1-9cede93539af', 'marginClasses / marginStyles', 'ComputedRef<string[]>', '', 'Delegated to useMargin via a reactive getter proxy.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9eeb1b8d-bf17-4d75-a30d-ffcc27fb73d4', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '064e39f8-d2ff-434a-a7d1-9cede93539af', 'gapClasses / gapStyles', 'ComputedRef<string[]>', '', 'Gap has no dedicated composable. Emits an inline style (gap: Npx or gap: <value>) when a gap override is present. gapClasses is always empty.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('78fb3fb4-2d27-48bc-96b5-a5466094739d', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '7a74a5b1-1bd6-4d5f-a20c-28e234747481', 'icon', 'ComputedRef<string | undefined>', '', 'Resolved center/replace icon. Returns the status icon when statusIconPosition="replace" and no explicit props.icon was provided, otherwise passes through props.icon.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8d547f10-e550-4cfa-a21d-5f1443793246', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '7a74a5b1-1bd6-4d5f-a20c-28e234747481', 'prependIcon', 'ComputedRef<string | undefined>', '', 'Resolved prepend-slot icon. Injects the status icon when statusIconPosition is prepend or both and props.prependIcon is unset.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('20f25e3c-3597-4e14-9b53-238f1e92b1f9', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '7a74a5b1-1bd6-4d5f-a20c-28e234747481', 'appendIcon', 'ComputedRef<string | undefined>', '', 'Resolved append-slot icon. Injects the status icon when statusIconPosition is append or both and props.appendIcon is unset.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dc3220d4-a97b-483e-adba-1f5dfffc084d', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '7a74a5b1-1bd6-4d5f-a20c-28e234747481', 'statusClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--{status}` when a status is set, empty otherwise. Bind to the root element for SCSS state selectors.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('57e49cfa-9e42-4ce5-869f-c88f0c6d74a6', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '7a74a5b1-1bd6-4d5f-a20c-28e234747481', 'statusIntent', 'ComputedRef<TColor | undefined>', '', 'The resolved TColor intent for the current status (success→success, info→info, warning→warning, error→danger). Undefined when no status is set. Consumed by useStateEffect to force the semantic surface color.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2fcc2784-3406-49c9-aa54-59c19eb95ca0', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '89b20543-b996-4090-bec5-7ea319a59591', 'isStuck', 'ShallowRef<boolean | "top" | "bottom">', '', 'Current stuck state. "top" = anchored at the top of the viewport (sidebar shorter than viewport or scrolled to top), "bottom" = anchored at the bottom edge, true = stuck mid-page (sidebar taller than viewport, user scrolled past the top edge), false = not sticky (isSticky prop is false).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d3718d21-ee5a-475a-8126-8a04fb202dfd', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '89b20543-b996-4090-bec5-7ea319a59591', 'stickyStyles', 'ComputedRef<Array<CSSProperties | undefined>>', '', 'Two-element style array to spread on the element. The first resets top/bottom/height when isSticky is enabled. The second applies the computed positional offset: the layoutItem top when not yet stuck, or the scrolled stuckPosition when stuck mid-page or at the bottom.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f9d8039e-98e6-4780-b339-4f270415b754', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '2d271f78-579d-43f8-914f-a7c70a030187', 'id', 'ComputedRef<string>', '', 'The element id used as the CSS scope selector (#id). Apply this id to the root element of the component so the injected styles target only this instance.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a8b907ea-de76-4dae-b9f6-d93123ae4de0', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '2d271f78-579d-43f8-914f-a7c70a030187', 'css', 'ShallowRef<string>', '', 'The current generated CSS string. Reactive — updates whenever the styles ComputedRef changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9b3a2a90-19e4-4412-88b9-4d1229f5bc6a', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '2d271f78-579d-43f8-914f-a7c70a030187', 'load / unload', '() => void', '', 'Manually control style tag injection. Normally called automatically on mount / scope dispose. Call load() to re-inject after an explicit unload().', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('be852c54-81d3-40d0-b59e-f0066c2c6c8c', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '2d271f78-579d-43f8-914f-a7c70a030187', 'isLoaded', 'Readonly<ShallowRef<boolean>>', '', 'True when the <style> tag is currently present in document.head.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9274031d-8838-4525-85de-e925724702c4', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'f427d255-535a-4048-a24b-03d68adf6c28', 'teleportTarget', 'ComputedRef<Element | undefined>', '', 'The resolved .origam-overlay-container element inside the target, or undefined when teleport is disabled (target=true) or the app is running on the server (SSR). Pass directly to <Teleport :to="teleportTarget">.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6ff74c0e-4d8d-4337-9746-474240c841f4', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '95d912fd-6a27-486a-a11d-e574c2c21175', 'textColorClasses', 'ComputedRef<string[]>', '', 'Utility class names (e.g. ["origam--color-primary"]) to bind via :class.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('aea58515-2fa3-4abc-9428-fa38a312ee83', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '95d912fd-6a27-486a-a11d-e574c2c21175', 'textColorStyles', 'ComputedRef<string[]>', '', 'Inline CSS declarations (e.g. ["color: #6d28d9"]) to bind via :style. For gradients, includes background-image + background-clip: text.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4671e513-369e-48f7-a54e-060dffa3fc1c', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '4621a670-bc0d-495b-a8de-71a6861fa2c2', 'hostRef', 'Ref<HTMLElement | undefined>', '', 'Template ref to assign to the contenteditable element. The composable uses it to read and write innerHTML, attach the selectionchange listener, and focus the element before applying a format command.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5d4b74a8-11a2-4ee4-8189-a5c8232a57f2', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '4621a670-bc0d-495b-a8de-71a6861fa2c2', 'active', 'ITextareaRichActiveState', '', 'Reactive object tracking the formatting state at the current caret position. Properties: bold, italic, underline, code, link (booleans), listBullet, listOrdered (booleans), heading (0 | 1 | 2 | 3). Bind to toolbar button :active props.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('231053cb-cf36-4e89-aa20-ad3c7d106e21', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '4621a670-bc0d-495b-a8de-71a6861fa2c2', 'format', '(command: TTextareaToolbarCommand, value?: string) => void', '', 'Apply a formatting command. Delegates to document.execCommand for bold, italic, underline, lists, and headings. Handles link creation (value = URL) and inline code toggling (insertHTML). Calls onFormat and onUpdate after every change.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3334ba41-c801-4f29-bb78-99fa8c6f38ec', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '4621a670-bc0d-495b-a8de-71a6861fa2c2', 'isFormatActive', '(command: TTextareaToolbarCommand) => boolean', '', 'Returns whether the given command is active at the current caret position. Reads from the reactive active object — a convenience wrapper for toolbar binding.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a070c105-7aac-48d1-8d4c-dae390a1fe96', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '4621a670-bc0d-495b-a8de-71a6861fa2c2', 'setValue', '(html: string) => void', '', 'Imperatively update the contenteditable innerHTML with sanitised HTML. No-ops when hostRef is unset or when the content is already identical (avoids cursor jump).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('34871aaa-30ad-45bd-a4ba-176727af6a56', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '4621a670-bc0d-495b-a8de-71a6861fa2c2', 'onInput / onKeydown / onPaste', '(event) => void', '', 'Event handlers to bind on the host element. onInput emits sanitised HTML. onKeydown intercepts Cmd/Ctrl+B/I/U/E/K and Cmd+Shift+7/8 for list shortcuts. onPaste strips HTML to sanitised form (or escapes plain text) before inserting.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('21ded569-78ef-4d50-91c3-5ec30dd079f5', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '1ed718d9-aed0-4820-9cf7-a650d7d89b13', 'theme', 'Readonly<Ref<TTheme>>', '', 'The current brand theme value: ''auto'' | ''light'' | ''dark'' | string (custom brand). Read-only reactive ref.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e7de2376-7742-4966-abb8-75a157644bab', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '1ed718d9-aed0-4820-9cf7-a650d7d89b13', 'resolved', 'Readonly<ComputedRef<TThemeResolved>>', '', 'Effective theme after resolving ''auto'' against prefers-color-scheme. Always ''light'' or ''dark''.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bfb12f93-26f8-4fbb-b0ce-0dc9fb6efb38', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '1ed718d9-aed0-4820-9cf7-a650d7d89b13', 'setTheme', '(next: TTheme) => void', '', 'Sets the brand theme, applies data-theme to <html> and persists to localStorage.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('205e5995-f832-4069-8037-11ff166735c0', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '1ed718d9-aed0-4820-9cf7-a650d7d89b13', 'toggle', '() => void', '', 'Convenience: flips the brand light ↔ dark. Treats ''auto'' as light.', 3, false, NULL, NULL);
