INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e0b1ccf7-318c-49d0-bc47-014a27ed59ea', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '1ed718d9-aed0-4820-9cf7-a650d7d89b13', 'setMode', '(next: TMode) => void', '', 'Sets the color mode, applies data-mode to <html> and persists to localStorage.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('775d8d61-ae1d-4c51-879b-55410666c8cc', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '1ed718d9-aed0-4820-9cf7-a650d7d89b13', 'toggleMode', '() => void', '', 'Flips the color mode light ↔ dark. Treats ''auto'' as the current system preference.', 7, false, NULL, NULL);
