INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('727c73bd-c8ff-4918-a897-66ce98cbe86d', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '71882269-86fe-442f-b7c3-5ca44d82585d', 'isDragging', 'ShallowRef<boolean>', '', 'True while a confirmed drag is in progress (threshold of 3px perpendicular movement must be exceeded before dragging starts).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('62a91bc1-2d6f-4193-b61e-61ff45723a3c', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '71882269-86fe-442f-b7c3-5ca44d82585d', 'dragProgress', 'ShallowRef<number>', '', 'Fraction in [0, 1] representing how open the drawer is during a drag. 0 = fully closed, 1 = fully open.', 1, false, NULL, NULL);
