INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b42366d3-2aed-4de3-91c9-e6267b9d8d54', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '522cf7c2-8066-43c1-acb2-e877f9c32fb0', 'name', 'ComputedRef<string | undefined>', '', 'The resolved transition name. Empty string when disabled (tells Vue not to apply CSS classes).', 0, false, NULL, NULL);
