INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('19d13a10-c365-4802-8afc-c5b90cc2482b', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '522cf7c2-8066-43c1-acb2-e877f9c32fb0', 'tag', 'ShallowRef<Component>', '', '`TransitionGroup` when `props.group` is true, `Transition` otherwise. Bind to `<component :is="tag">` in the consumer template.', 2, false, NULL, NULL);
