INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0cf0ac92-f18f-4509-8475-a6bca95d264a', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '6e48696c-cffc-4410-b29c-8be7b81918b6', 'state', 'IVideoPlayerState', '', 'All IMediaPlayerState fields (playing, paused, currentTime, duration, buffered, volume, muted, ready, loading, error, playbackRate, remoteAvailable, remoteState) plus `fullscreen: Ref<boolean>` and `pip: Ref<boolean>`.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('209947e7-03f4-4a6e-8682-fa041b4a1874', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', '6e48696c-cffc-4410-b29c-8be7b81918b6', 'methods', 'IVideoPlayerMethods', '', 'All IMediaPlayerMethods (play, pause, toggle, seek, setVolume, toggleMute, load, skipBackward, skipForward, setPlaybackRate, requestRemotePlayback, stopRemotePlayback) plus `enterFullscreen`, `exitFullscreen`, `toggleFullscreen`, `requestPip`, `exitPip`, `togglePip`.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4cba7ff9-0207-4b48-b053-dfd834844d73', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c00935ae-4b68-4f53-ab03-efb72a26eba7', 'containerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to the scrollable container element. The composable reads `scrollTop` from it and listens to `handleScroll` / `handleScrollend`.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b2090bf6-2632-4fea-8173-75f91b5acb82', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c00935ae-4b68-4f53-ab03-efb72a26eba7', 'markerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to a zero-height element at the top of the list content area. Its `offsetTop` is used to compute an offset if there is padding or a header above the virtual list.', 1, false, NULL, NULL);
