INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('da794f0c-3ef1-4cbf-8db2-0e8b7197a596', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c00935ae-4b68-4f53-ab03-efb72a26eba7', 'paddingTop', 'ShallowRef<number>', '', 'Pixel padding to add above the first rendered item to preserve the scroll height.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('de7142d1-700f-4ee9-a981-4d583e3d769b', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c00935ae-4b68-4f53-ab03-efb72a26eba7', 'paddingBottom', 'ShallowRef<number>', '', 'Pixel padding to add below the last rendered item to preserve the scroll height.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e2887ab8-ce1e-498c-892d-c524f1faf84c', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c00935ae-4b68-4f53-ab03-efb72a26eba7', 'scrollToIndex', '(index: number, options?: Partial<IGoToOptions>) => void', '', 'Programmatically scroll the container to a specific item index. Defers the scroll if the list has not yet measured (first render not complete). Pass `{ duration: 0 }` for instant scroll.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5e4e0d86-a133-44fb-b7ec-54e07063bb7d', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c00935ae-4b68-4f53-ab03-efb72a26eba7', 'handleScroll', '() => void', '', 'Bind to the `scroll` event of the container element. Computes scroll velocity and triggers visible-items recalculation.', 6, false, NULL, NULL);
