INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0aeaff6d-0252-49f0-b77a-e55206d7a66c', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'c00935ae-4b68-4f53-ab03-efb72a26eba7', 'handleItemResize', '(index: number, height: number) => void', '', 'Call when a rendered item changes its measured height. Updates the size cache and triggers an offset recalculation. Wire via a ResizeObserver on each rendered row.', 8, false, NULL, NULL);
