INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('61e1c1b0-baed-4abc-9d24-1ec2963de2f1', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'cefdb628-ed2e-4b7d-bd69-bdea9b0e0e8f', 'list', 'types.detail.file_field_display.list', 'Default. Renders each selected file as a card in a vertical stack below the field. Suitable when filenames and per-file actions (remove, download, progress) need to be visible.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fa3d07ac-852e-4b9b-9482-4fdbb03037d4', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'cefdb628-ed2e-4b7d-bd69-bdea9b0e0e8f', 'chips', 'types.detail.file_field_display.chips', 'Renders each selected file as a closable <OrigamChip> inline inside the field. Compact mode — best for forms where many files can be selected but vertical space is limited.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('70526d1e-b948-4c91-ba4f-36f07b7ce49c', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'cefdb628-ed2e-4b7d-bd69-bdea9b0e0e8f', 'counter', 'types.detail.file_field_display.counter', 'Shows a single "N files selected" line with an <OrigamCounter>. Most compact mode — use when the file names are irrelevant to the user after selection.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1484c748-d1c0-4077-af18-a229bc07e3d3', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'eba5b419-458c-4a6e-88ad-68d314a32eb2', 'false', 'types.detail.file_size.false', 'File sizes are not displayed. This is the default behaviour when the showSize prop is omitted.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('09c0831c-489a-4473-93a1-284df0e439fd', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'eba5b419-458c-4a6e-88ad-68d314a32eb2', 'true', 'types.detail.file_size.true', 'File sizes are displayed using the SI divisor (1 000) — KB, MB, GB.', 1, false, NULL, NULL);
