INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7f65347e-6ede-45e6-974f-3e5e335df52b', '2026-10-01 13:28:07.167959+00', '2026-10-01 13:28:07.167959+00', 'eba5b419-458c-4a6e-88ad-68d314a32eb2', '1024', 'types.detail.file_size.1024', 'Binary / IEC units: 1 KiB = 1 024 bytes, 1 MiB = 1 048 576 bytes. Traditional computing convention; more accurate for OS-reported file sizes.', 3, false, NULL, NULL);
